<h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">Глава 10. Собрание гатх (Sagāthakam)</h4>
<h5 class="text-center text-blue-700 font-semibold text-lg sm:text-lg md:text-lg mt-2 mb-6">Гатхи 1-62</h5>
<!— Гатхи 1-62 —>
<div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">

     <p>Затем бодхисаттва-махасаттва Махамати обратился к Благословенному:</p>

    <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>1. Мир (<em>lokaḥ</em>) свободен от возникновения и разрушения</li>
            <li>(<em>utpāda-bhaṅga-rahita</em>), подобен цветку в небе (<em>khapuṣpa-saṃnibha</em>).</li>
            <li>Он не устанавливается ни как существующий, ни как несуществующий —</li>
            <li>через Твои мудрость (<em>prajñā</em>) и сострадание (<em>kṛpā</em>).<a href="#citation-496" id="ref-496" class="citation-mark"><sup>496</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>2. Мир свободен от крайностей вечности и уничтожения,</li>
            <li>всегда подобен сновидению,</li>
            <li>Он не устанавливается ни как существующий, ни как несуществующий —</li>
            <li>через Твои мудрость (<em>prajñā</em>) и сострадание (<em>kṛpā</em>).<a href="#citation-497" id="ref-497" class="citation-mark"><sup>497</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>3. Все дхармы подобны магической иллюзии (<em>māyā</em>),</li>
            <li>не удерживаются в категориях ума (<em>citta</em>)</li>
            <li>и различающего сознания (<em>vijñāna</em>).</li>
            <li>Они не устанавливаются ни как существующие, ни как несуществующие —</li>
            <li>через Твои мудрость (<em>prajñā</em>) и сострадание (<em>kṛpā</em>).<a href="#citation-498" id="ref-498" class="citation-mark"><sup>498</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>4. Отсутствие «я» дхарм и личности (<em>dharmapudgalanairātmya</em>),</li>
            <li>завесы клеш и познаваемого (<em>kleśajñeya</em>) —</li>
            <li>всегда прояснено Тобой через без-признаковость (<em>animitta</em>),</li>
            <li>через Твои мудрость (<em>prajñā</em>) и сострадание (<em>kṛpā</em>).<a href="#citation-499" id="ref-499" class="citation-mark"><sup>499</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>5. Ты не угасаешь в нирване, ибо нирвана в Тебе пребывает.</li>
            <li>Свободен Ты от различения познающего и познаваемого,</li>
            <li>вне крайностей бытия и небытия.<a href="#citation-500" id="ref-500" class="citation-mark"><sup>500</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>6. Те, кто зрят Мудреца умиротворённым,</li>
            <li>свободным от возникновения такого рода,</li>
            <li>становятся свободными от цепляния (<em>nirupādānāḥ</em>),</li>
            <li>незапятнанными — здесь и там.<a href="#citation-501" id="ref-501" class="citation-mark"><sup>501</sup></a></li>
        </ul>
    </blockquote>

    <p>[Благословенный молвил:]</p>

    <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>7. Как марево (<em>mṛgatṛṣṇā</em>) в летний зной дрожит,</li>
            <li>вводя ум в заблуждение (<em>citta-mohanī</em>), и олени</li>
            <li>принимают его за воду —</li>
            <li>хотя никакого объекта (<em>vastu</em>) там нет,</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>8. так и это семя сознания (<em>vijñāna-bīja</em>) колеблется (<em>spandate</em>)</li>
            <li>в поле восприятия (<em>dṛṣṭi-gocara</em>).</li>
            <li>Невежды (<em>bāla</em>) хватаются за возникающее [как за реальное],</li>
            <li>как страдающие глазной болезнью (<em>taimirā</em>)</li>
            <li>видят мнимые пятна (<em>timira</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>9. Медитирующий (<em>dhyātā</em>), медитация (<em>dhyāna</em>)</li>
            <li>и объект медитации (<em>dhyeya</em>), устранение [омрачений] (<em>prahāṇa</em>)</li>
            <li>и видение истины (<em>satya-darśanam</em>) —</li>
            <li>всё это лишь воображение (<em>kalpanā-mātra</em>).</li>
            <li>Кто осознаёт (<em>budhyati</em>) это — тот освобождается (<em>mucyati</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>10. Эти дхармы лишены сущности (<em>asāraka</em>),</li>
            <li>возникли из домысливания (<em>manyanā</em>).</li>
            <li>Но и само это домысливание здесь — <em>шунья</em> (<em>śūnya</em>).</li>
            <li>Даже то, посредством чего мыслится</li>
            <li>«это <em>шунья</em>» — также лишено реальности.<a href="#citation-502" id="ref-502" class="citation-mark"><sup>502</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>11. Пять <em>скандх</em>, из которых сознание — пятая,</li>
            <li>подобны отражению деревьев в воде.</li>
            <li>Видимое (<em>dṛśya</em>) подобно иллюзии (<em>māyā</em>) и сну;</li>
            <li>его не следует домысливать  (<em>vikalpa</em>) [как реальность]</li>
            <li>через представления (<em>vijñapti</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>12. [Мир] всегда подобен иллюзии (<em>māyā</em>),</li>
            <li>механической кукле веталы (<em>vetāla-yantra</em>),</li>
            <li>сну, молнии и облаку (<em>vidyu-dhana</em>).</li>
            <li>Тот, кто видит мир, пресекающий</li>
            <li>три преемственности (<em>tri-saṃtati</em>), — освобождается.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>13. Из-за неправильного внимания (<em>ayoniśas</em>) и</li>
            <li>различающего воображения (<em>vikalpa</em>)</li>
            <li>сознание приводится в действие.</li>
            <li>Восьмеричное или девятиричное,<a href="#citation-503" id="ref-503" class="citation-mark"><sup>503</sup></a></li>
            <li>оно многообразно — как волны в великом океане.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>14. Всегда взращиваемое отпечатками (<em>vāsanā</em>),</li>
            <li>укоренённое в основании (<em>mūla</em>) посредством интеллекта (<em>buddhi</em>),</li>
            <li>имеющее устойчивую опору, оно блуждает в поле объектов,</li>
            <li>как железо (<em>ayas</em>), влекомое магнитом (<em>kānta</em>).<a href="#citation-504" id="ref-504" class="citation-mark"><sup>504</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>15. Пребывающая во всех существах,</li>
            <li>основа духовного рода (<em>gotrabhū</em>)</li>
            <li>свободна от логического умствования (<em>tarka</em>).</li>
            <li>Обратившись (<em>nivartate</em>), она свободна от действия (<em>kriyā</em>)</li>
            <li>и от разделения на познающего и познаваемое (<em>jñāna-jñeya</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>16. В <em>самадхи</em>, подобном иллюзии,</li>
            <li>выйдя за пределы десяти ступеней пути,</li>
            <li>узрите Царя-Ума — чистую природу,</li>
            <li>свободную от понятий и различающего сознания.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>17. Когда ум (<em>citta</em>) претерпевает обращение (<em>parāvṛtta</em>),</li>
            <li>тогда он пребывает непреходяще (<em>śāśvatam</em>) во дворце (<em>vimāna</em>),</li>
            <li>подобном лотосу (<em>padma-saṃkāśe</em>),</li>
            <li>рождённом из сферы иллюзии (<em>māyā-gocara-saṃbhava</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>18. Утвердившись в этом, бодхисаттва действует</li>
            <li>без усилия (<em>anābhoga-caryā</em>) и</li>
            <li>совершает дела на благо существ (<em>sattva-kāryāṇi</em>),</li>
            <li>подобно драгоценному камню (<em>maṇi</em>),</li>
            <li>отражающему все формы (<em>viśva-rūpa</em>).<a href="#citation-505" id="ref-505" class="citation-mark"><sup>505</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>19. Нет ни обусловленного (<em>saṃskṛta</em>),</li>
            <li>ни необусловленного (<em>asaṃskṛta</em>) —</li>
            <li>вне различения (<em>vikalpanā</em>) их не существует.</li>
            <li>Невежды цепляются за них — о, позор глупцам! —</li>
            <li>подобно бесплодной женщине (<em>vandhyā</em>), видящей сына во сне.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>20. Отсутствие собственной природы (<em>naiḥsvābhāvyam</em>),</li>
            <li>невозникновение (<em>anutpāda</em>), личность (<em>pudgala</em>), <em>скандха</em>,</li>
            <li>поток (<em>saṃtati</em>), условия (<em>pratyaya</em>), элементы (<em>dhātu</em>),</li>
            <li>познаваемое (<em>jñeya</em>), <em>шуньята</em> (<em>śūnyatā</em>),</li>
            <li>а также бытие и небытие (<em>bhava-abhava</em>) —</li>
            <li>[всё это лишь построения различения].<a href="#citation-506" id="ref-506" class="citation-mark"><sup>506</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>21. Моё учение — лишь искусное средство (<em>upāya</em>);</li>
            <li>я не проповедую признаки (<em>lakṣaṇa</em>) (как реально существующие).</li>
            <li>Невежды же цепляются за признак и за обозначаемое (<em>lakṣya</em>)</li>
            <li>как за имеющие сущность (<em>bhāvena</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>22. Я знаю всё (<em>sarvasya vettā</em>), но Я не всеведущий (<em>sarvavettā</em>);</li>
            <li>Я пребываю среди всего, но всего [этого как сущности] нет.</li>
            <li>Невежды и мудрецы мира строят различения (<em>vikalpana</em>) —</li>
            <li>Я же не познаю и не поучаю (<em>na budhyāmi na bodhayāmi</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>23. Обозначение (<em>prajñapti</em>) — лишь имя (<em>nāma-mātra</em>),</li>
            <li>признака (<em>lakṣaṇa</em>) как такового не существует.</li>
            <li><em>Скандхи</em> подобны комку волос (<em>keśoṇḍuka</em>),</li>
            <li>который измышляется (<em>vikalpyate</em>) невеждами.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>24. Ничто не возникает из небытия (<em>abhūtvā</em>) и</li>
            <li>не уничтожается условиями (<em>pratyaya</em>).</li>
            <li>Когда обусловленный мир (<em>saṃskṛta</em>) видится</li>
            <li>подобным сыну бесплодной женщины (<em>vandhyā-suta</em>)</li>
            <li>или цветку в небе (<em>ākāśa-puṣpa</em>) —</li>
            <li>тогда схватывающий (<em>grāha</em>) и схватываемое (<em>grāhya</em>)</li>
            <li>через распознавание заблуждения (<em>bhrānti</em>) обращаются вспять.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>25. Я не достигаю нирваны (<em>na nirvāsi</em>) ни через бытие (<em>bhāva</em>),</li>
            <li>ни через действие (<em>kriyā</em>), ни через признак (<em>lakṣaṇa</em>).</li>
            <li>Я освобождён (<em>nirvṛta</em>) благодаря прекращению (<em>nivṛtti</em>) сознания,</li>
            <li>которое служит причиной (<em>hetu</em>) различения (<em>vikalpa</em>).</li>
            <li>(Не исчезает признак (<em>lakṣaṇa</em>),</li>
            <li>который различается (<em>vikalpyate</em>) невеждами).<a href="#citation-507" id="ref-507" class="citation-mark"><sup>507</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>26. Как при иссякании великого потока</li>
            <li>волны более не возникают,</li>
            <li>так и многообразие сознаний,</li>
            <li>будучи прекращённым,</li>
            <li>больше не разворачивается.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>27. Эти явления пусты (<em>śūnya</em>) и лишены собственной природы,</li>
            <li>подобны иллюзии и нерождённы (<em>ajāta</em>).</li>
            <li>Они не обнаруживаются (<em>vidyante</em>)</li>
            <li>ни как существующие, ни как несуществующие (<em>sadasat</em>);</li>
            <li>эти явления (<em>bhāva</em>) подобны сновидению.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>28. Я излагаю единственную природу (<em>svabhāvam ekaṃ</em>),</li>
            <li>свободную от логических рассуждений (<em>tarka</em>)</li>
            <li>и представлений (<em>vijñapti</em>) —</li>
            <li>божественную область (<em>divya-gocara</em>) Благородных,</li>
            <li>свободную от двойственности</li>
            <li>собственных природ (<em>svabhāva-dvaya</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>29. Как страдающему расстройством</li>
            <li>[зрения или ума] видятся светлячки —</li>
            <li>разнообразные, хотя их нет (<em>na santi</em>),</li>
            <li>так из-за возмущения элементов (<em>dhātu-saṃkṣobha</em>)</li>
            <li>мир представляется имеющим</li>
            <li>собственную природу (<em>svabhāvataḥ</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>30. Как среди травы, дерева и черепков</li>
            <li>может видится иллюзия,</li>
            <li>хотя самой иллюзии нет,</li>
            <li>так и дхармы по своей природе не существуют.<a href="#citation-508" id="ref-508" class="citation-mark"><sup>508</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>31. Нет ни схватывающего (<em>grāhaka</em>), ни схватываемого (<em>grāhya</em>);</li>
            <li>нет ни связанного (<em>bandhya</em>), ни самого связывания (<em>bandhana</em>).</li>
            <li>Всё это подобно иллюзии, миражу,</li>
            <li>сновидению и глазному недугу (<em>timira</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>32. Когда стремящийся к истине (<em>tattvārthī</em>) зрит,</li>
            <li>будучи свободным от различений (<em>nirvikalpa</em>)</li>
            <li>и незапятнанным (<em>nirañjana</em>),</li>
            <li>тогда он, утвердившись в йоге (сосредоточении) (<em>yoga-samāpanna</em>),</li>
            <li>без сомнения, узрит Меня (то есть Дхармакаю).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>33. Здесь нет никакого представления (<em>vijñapti</em>),</li>
            <li>как в небе нет миражей.</li>
            <li>Так постигающий дхармы</li>
            <li>[мудрец] ничего не утверждает.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>34. Дхармы не возникают ни из существования,</li>
            <li>ни из не-существования.</li>
            <li>Именно потому, что ум блуждает в трёх мирах,</li>
            <li>это многообразие и кажется видимым.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>35. Сновидение и мир имеют одну природу (<em>sama-svabhāva</em>).</li>
            <li>И там и здесь видятся разнообразные формы,</li>
            <li>переживаются наслаждения и прикосновения,</li>
            <li>тело, Учитель мира и действие — [всё это едино по природе].<a href="#citation-509" id="ref-509" class="citation-mark"><sup>509</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>36. Ибо ум — источник трёх миров,</li>
            <li>заблуждаясь, он видится здесь и там.</li>
            <li>Познав такой ход мира,</li>
            <li>не следует измышлять мир как несуществующий.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>37. Глупцы из-за неведения видят</li>
            <li>возникновение (<em>saṃbhava</em>) и исчезновение (<em>vibhava</em>).</li>
            <li>Тот, кто наделён мудростью (<em>prajñā</em>)</li>
            <li>не видит ни возникновения, ни исчезновения.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>38. В божественной обители Акаништха,</li>
            <li>свободной от всякого зла,</li>
            <li>[Пробуждённые] всегда пребывают в сосредоточении,</li>
            <li>свободные от различений (<em>nirvikalpa</em>),</li>
            <li>двойственного ума и его факторов (<em>citta-caitta</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>39. Обладая <em>силами</em> (<em>bala</em>), <em>сверхзнаниями</em> (<em>abhijñā</em>)</li>
            <li>и <em>властью</em> (<em>vaśitā</em>),</li>
            <li>они достигают того самого <em>самадхи</em>.</li>
            <li>Там пребывают полностью пробуждённые,</li>
            <li>здесь же проявляется лишь их явленное тело (<em>nirmita</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>40. Бесчисленные десятки миллионов</li>
            <li>явленных тел исходят от Будд.</li>
            <li>Пребывающие в невежестве слышат повсюду</li>
            <li>от них Дхарму и внимают ей.<a href="#citation-510" id="ref-510" class="citation-mark"><sup>510</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>41. Свободная от начала, середины и конца,</li>
            <li>лишённая бытия и небытия;</li>
            <li>всепроникающая, неподвижная, чистая,</li>
            <li>неразличённая (<em>acitra</em>),</li>
            <li>но порождающая многообразие (<em>citra-saṃbhava</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>42. Скрытая покровом представлений (<em>vijñapti</em>),</li>
            <li>она пребывает во всех воплощённых существах.</li>
            <li>Из-за заблуждения возникает иллюзия,</li>
            <li>но сама иллюзия не является причиной заблуждения.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>43. Всё, что кажется существующим,</li>
            <li>существует лишь из-за заблуждения ума.</li>
            <li>Мир, созданный <em>Алайя-виджняной</em>,</li>
            <li>связан двойственностью природ;</li>
            <li>он — лишь представление (<em>vijñapti-mātra</em>),</li>
            <li>поток ложных воззрений о дхармах и личности.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>44. Постигнув мир таким образом,</li>
            <li>когда происходит обращение основы,</li>
            <li>он становится моим сыном —</li>
            <li>действующим в совершённой</li>
            <li>природе дхарм (<em>niṣpanna-dharma</em>).<a href="#citation-511" id="ref-511" class="citation-mark"><sup>511</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>45. Тепло, текучесть, движение и твёрдость —</li>
            <li>[четыре первичных элемента (<em>mahābhūta</em>)] —</li>
            <li>невежды воображают как дхармы.</li>
            <li>Это наложение (<em>samāropa</em>)</li>
            <li>несуществующего на существующее;</li>
            <li>нет ни обозначаемого (<em>lakṣya</em>), ни признака (<em>lakṣaṇa</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>46. Эту восьмисоставную телесную структуру</li>
            <li>и органы чувств</li>
            <li>невежды принимают как «форму» (<em>rūpa</em>),</li>
            <li>заблуждаясь в клетке сансары.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>47. Из совокупности причин и условий (<em>hetu-pratyaya</em>)</li>
            <li>невежды воображают возникновение.</li>
            <li>Не зная этого учения,</li>
            <li>они блуждают в обители трёх миров.<a href="#citation-512" id="ref-512" class="citation-mark"><sup>512</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>48. И даже «отсутствие</li>
            <li>собственной природы всех явлений» —</li>
            <li>лишь слова людей.</li>
            <li>Проявление возникает из воображения;</li>
            <li>существование подобно сну.</li>
            <li>Исследовав это, [мудрый]</li>
            <li>не пребывает ни в сансаре, ни в нирване.<a href="#citation-513" id="ref-513" class="citation-mark"><sup>513</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>49. Ум, называемый семенем, проявляется как многообразие,</li>
            <li>в сфере самого ума.</li>
            <li>Невежды же, видя это проявление</li>
            <li>и цепляясь за двойственность воображения,</li>
            <li>измышляют возникновение.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>50. Невежество, жажда и карма,</li>
            <li>а также ум и его факторы —</li>
            <li>это не [внешний губитель] Мара.</li>
            <li>Они действуют таким образом,</li>
            <li>поскольку имеют зависимую природу (<em>pāratantrya</em>) —</li>
            <li>таково моё учение.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>51. И они (невежи) воображают некий объект,</li>
            <li>который является лишь</li>
            <li>обманчивым заблуждением (<em>vibhrama</em>)</li>
            <li>в сфере (<em>gocara</em>) ума (<em>citta</em>).</li>
            <li>[Этот объект] не существует даже в самом воображении —</li>
            <li>он ложно выстроен заблуждающимся различением.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>52. Ум воплощённых существ развёртывается</li>
            <li>лишь в неразрывной связи с условиями (<em>pratyaya</em>).</li>
            <li>Я заявляю: я не нахожу никакого ума,</li>
            <li>существующего самого по себе, отдельно от этих условий.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>53. То, что полностью освобождено от условий</li>
            <li>и лишено собственных признаков (<em>svalakṣaṇa</em>),</li>
            <li>не пребывает в теле — и потому</li>
            <li>недостижимо как объект для восприятия (<em>agocaram</em>).<a href="#citation-514" id="ref-514" class="citation-mark"><sup>514</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>54. Подобно тому как царь или богатый купец</li>
            <li>забавляет своих сыновей в доме</li>
            <li>разнообразными игрушками, подобными зверям,</li>
            <li>суля им встречу с настоящими зверями в лесу, —</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>55. так и Я, через разнообразные признаки (<em>lakṣaṇa</em>),</li>
            <li>которые суть лишь отражения (<em>pratibimba</em>) дхарм,</li>
            <li>веду своих сыновей к <em>Пределу истинности</em> (<em>bhūtakoṭi</em>) —</li>
            <li>которая постигается</li>
            <li>каждым в себе самом (<em>pratyātmavedyā</em>).<a href="#citation-515" id="ref-515" class="citation-mark"><sup>515</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>56. Подобно тому как волны океана,</li>
            <li>поднятые ветром условий (<em>pavana-pratyaya</em>),</li>
            <li>движутся в непрестанном танце —</li>
            <li>и их течение не прерывается —</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>57. так и поток <em>Алайи</em> (<em>ālaya-ogha</em>),</li>
            <li>вечно гонимый ветром объектов (<em>viṣaya-pavana</em>),</li>
            <li>разворачивается, танцуя,</li>
            <li>в виде многообразных волн-сознаний (<em>taraṃga-vijñāna</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>58. Ум воплощённых существ склоняется-искривляется</li>
            <li>к разделению на познаваемое и познающего (<em>grāhya-grāhaka</em>).</li>
            <li>Но у видимого мира нет тех признаков (<em>lakṣaṇa</em>),</li>
            <li>которые измышляются невеждами.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>59. Высшая <em>Алайя-виджняна</em> — это представление (<em>vijñapti</em>),</li>
            <li>и это представление — снова <em>Алайя</em>.</li>
            <li>Когда исчезает двойственность познаваемого и познающего,</li>
            <li>Я проповедую это как Таковость (<em>tathatā</em>).<a href="#citation-516" id="ref-516" class="citation-mark"><sup>516</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>60. В <em>скандхах</em> нет ни «я» (<em>ātman</em>),</li>
            <li>ни существа (<em>sattva</em>), ни личности (<em>pudgala</em>).</li>
            <li>Возникает лишь сознание —</li>
            <li>и оно же прекращается.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>61. Подобно тому как на картине</li>
            <li>видятся впадины и выпуклости,</li>
            <li>которых на самом деле нет, —</li>
            <li>так и в явлениях видится их «сущность» (<em>bhāvatvaṃ</em>),</li>
            <li>которой в действительности не существует.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>62. Подобно городу гандхарвов или мареву в пустыне,</li>
            <li>видимый мир постоянно проявляется,</li>
            <li>но в свете мудрости (<em>prajñā</em>) он</li>
            <li>не обнаруживается как реальность.<a href="#citation-517" id="ref-517" class="citation-mark"><sup>517</sup></a></li>
        </ul>
    </blockquote>
</div>

<!— Гатхи 63-130 —>
<div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
    <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>63. [Истинная природа] не зависит</li>
            <li>ни от средств познания (<em>pramāṇa</em>),</li>
            <li>ни от органов чувств (<em>indriya</em>).</li>
            <li>Она не является ни причиной, ни следствием,</li>
            <li>лишена познающего и познаваемого (<em>buddhi-boddhavya</em>),</li>
            <li>свободна от признака (<em>lakṣaṇa</em>) и обозначаемого (<em>lakṣya</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>64. Истинный Будда (<em>saṃbuddha</em>), [рассматриваемый]</li>
            <li>в зависимости от <em>скандх</em>, не был обнаружен нигде и никем.</li>
            <li>Того, кто нигде и никем не может быть найден,</li>
            <li>как возможно определить?<a href="#citation-518" id="ref-518" class="citation-mark"><sup>518</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>65. Через условия (<em>pratyaya</em>), причины (<em>hetu</em>)</li>
            <li>и примеры (<em>dṛṣṭānta</em>),</li>
            <li>через тезисы (<em>pratijñā</em>) и логические основания (<em>kāraṇa</em>),</li>
            <li>через [образы] сна (<em>svapna</em>), города гандхарвов</li>
            <li>и огненного колеса (<em>cakra</em>),</li>
            <li>через мираж (<em>marīcī</em>), луну (<em>soma</em>) и солнце (<em>bhāskara</em>) —</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>66. примерами гончара (<em>kulāla</em>) и прочими сравнениями</li>
            <li>Я объясняю возникновение того, что невидимо [как объект].</li>
            <li>Этот мир пуст (<em>śūnya</em>) и воображаем (<em>kalpita</em>) —</li>
            <li>его называют сном, заблуждением и магической иллюзией.<a href="#citation-519" id="ref-519" class="citation-mark"><sup>519</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>67. [Истинная природа] не имеет опоры</li>
            <li>ни в Трёх Мирах (<em>trailokya</em>),</li>
            <li>ни во внутреннем (<em>adhyātma</em>), ни во внешнем.</li>
            <li>Узрев, что бытие нерождено (<em>anutpanna</em>), [йогин] обретает</li>
            <li>стойкость в постижении невозникновения (<em>anutpatti-kṣānti</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>68. [Тогда он обретает] <em>самадхи,</li>
            <li>подобное иллюзии</em> (<em>māyopama-samādhi</em>),</li>
            <li>и <em>тело, рожденное из ума</em> (<em>manomaya-kāya</em>).</li>
            <li>Его <em>сверхзнания</em> (<em>abhijñā</em>), <em>власть</em> (<em>vaśitā</em>) и <em>силы</em> (<em>bala</em>) —</li>
            <li>это лишь многообразное [естественное] проявление его ума.<a href="#citation-520" id="ref-520" class="citation-mark"><sup>520</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>69. Даже у тех, для кого явления нерождённы,</li>
            <li>пусты и лишены собственной природы,</li>
            <li>может возникать заблуждение,</li>
            <li>но оно прекращается благодаря условиям.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>70. Ум проявляется как ум;</li>
            <li>он же проявляется вовне как обладающий формой (<em>rūpin</em>).</li>
            <li>Иного видимого (<em>dṛśya</em>) не существует, кроме того,</li>
            <li>что измышляется (<em>vikalpyate</em>) невеждами.<a href="#citation-521" id="ref-521" class="citation-mark"><sup>521</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>71. Истинно, хорошо обученные [бодхисаттвы]</li>
            <li>удерживают намерение (<em>saṃkalā</em>), образ Будды (<em>buddha-bimba</em>)</li>
            <li>и проявление многообразия существ (<em>bhūtānāṃ vidāraṇam</em>) —</li>
            <li>утверждая этим пёстрый мир (jagac-citram)</li>
            <li>как условную реальность (<em>prajñapti</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>72. Тело (<em>deha</em>), основа (<em>pratiṣṭhā</em>) и наслаждение (<em>bhoga</em>) —</li>
            <li>три вида схватываемого (<em>grāhyavijñapti</em>).</li>
            <li><em>Манас</em> (<em>manas</em>), восприятие (<em>udgraha-vijñapti</em>)</li>
            <li>и различение (<em>vikalpa</em>) —</li>
            <li>три проявления схватывающего (<em>grāhaka</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>73. Пока различение (<em>vikalpa</em>) и различаемое (<em>vikalpya</em>)</li>
            <li>находятся в сфере знаков и слов (<em>akṣara-gocara</em>),</li>
            <li>до тех пор Истину (<em>tattva</em>) не видят, особенно логики (<em>tārkikāḥ</em>),</li>
            <li>которые заблуждаются, полагаясь на рассудок (<em>tarka-vibhrama</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>74. Когда мудростью (<em>prajñā</em>) постигается отсутствие</li>
            <li>собственной природы (<em>naiḥsvabhāvya</em>) всех явлений (<em>bhāvānām</em>),</li>
            <li>тогда йогин (<em>yogī</em>) покоится (<em>viśramati</em>),</li>
            <li>утвердившись в беспризнаковом (<em>ānimitta-pratiṣṭhita</em>).<a href="#citation-522" id="ref-522" class="citation-mark"><sup>522</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>75. Как петух, покрытый сажей (<em>masimrakṣitaka</em>),</li>
            <li>принимается невеждами [за иное],</li>
            <li>так же и три колесницы (<em>yāna-traya</em>)</li>
            <li>воспринимаются неведающими глупцами как различные.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>76. Ибо здесь нет никаких шраваков,</li>
            <li>нет последователей колесницы пратьекабудд.</li>
            <li>То, что видится как форма шраваки и Победителя (<em>jina</em>), —</li>
            <li>это лишь проявление (<em>nirmāṇa</em>), которое</li>
            <li>сострадательные бодхисаттвы являют как наставление.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>77. Три мира (<em>tribhava</em>) — лишь представление (<em>vijñapti-mātra</em>),</li>
            <li>измышленное через двойственную природу (<em>svabhāva-dvaya</em>)</li>
            <li>[воображаемую и зависимую].</li>
            <li>Таковость (<em>tathatā</em>) же раскрывается через обращение (<em>parāvṛtta</em>),</li>
            <li>возникающее из прекращения колебания между</li>
            <li>цеплянием за дхармы и личность  (<em>dharma-pudgala</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>78. Луна (<em>soma</em>), солнце (<em>bhāskara</em>), светильник (<em>dīpa</em>),</li>
            <li>пламя (<em>arci</em>) и драгоценные камни (<em>maṇi</em>) </li>
            <li>действуют без различения (<em>nirvikalpa</em>).</li>
            <li>Так же действует и природа Будды (<em>buddhatā</em>).<a href="#citation-523" id="ref-523" class="citation-mark"><sup>523</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>79. Как волосяной комок ложно воспринимается</li>
            <li>людьми с больными глазами,</li>
            <li>так и это различение явлений (<em>bhāva-vikalpa</em>)</li>
            <li>ложно воображается невеждами.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>80. Явления (<em>bhāva</em>) лишены пребывания,</li>
            <li>разрушения и возникновения (<em>sthiti-bhaṅga-utpatti</em>)</li>
            <li>и свободны от вечности и непостоянства (<em>nitya-anitya</em>).</li>
            <li>То, что называется «омрачением» (<em>saṃkleśa</em>)</li>
            <li>и «очищением» (<em>vyavadāna</em>), —</li>
            <li>подобно волосяному комку.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>81. Как некий человек,</li>
            <li>увидев куклу с золотым блеском,</li>
            <li>принимает её за золото —</li>
            <li>хотя на самом деле там нет золота:</li>
            <li>и даже её основу он домысливает как золото,</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>82. так и невежды, осквернённые</li>
            <li>безначальными умом и умственными факторами,</li>
            <li>принимают за действительное явления,</li>
            <li>возникшее как иллюзия и мираж.<a href="#citation-524" id="ref-524" class="citation-mark"><sup>524</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>83. Единое семя (<em>eka-bīja</em>) и бессемянный (<em>abīja</em>),</li>
            <li>единый океан (<em>samudra-eka</em>) и семя-источник (<em>bījaka</em>),</li>
            <li>а также всесемянный (<em>sarva-bījaka</em>) —</li>
            <li>так созерцайте этот многообразный ум (<em>citta-citraka</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>84. Когда единое семя (<em>eka-bīja</em>) очищено (<em>śuddha</em>)</li>
            <li>и обращено (<em>parāvṛtta</em>),</li>
            <li>оно становится бессемянным (<em>abījaka</em>).</li>
            <li>Оно равно (<em>sama</em>) благодаря</li>
            <li>отсутствию различений (<em>nirvikalpatva</em>).</li>
            <li>Но из-за избытка [омрачений] (<em>udreka</em>)</li>
            <li>возникает смешение рождений (<em>janma-saṃkara</em>).</li>
            <li>Семя становится многообразным (<em>citra</em>),</li>
            <li>и потому называется всесемянным (<em>sarva-bīja</em>).<a href="#citation-525" id="ref-525" class="citation-mark"><sup>525</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>85. Здесь ничто не возникает из условий (<em>pratyaya</em>)</li>
            <li>и не прекращается через условия.</li>
            <li>Возникновение и прекращение</li>
            <li>относятся лишь к воображаемым (<em>kalpita</em>) условиям.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>86. Три мира (<em>tribhava</em>) —</li>
            <li>лишь условные обозначения (<em>prajñapti-mātra</em>),</li>
            <li>они не обладают собственной природой (<em>svabhāvataḥ</em>).</li>
            <li>Логики (<em>tārkika</em>) воображают действительность,</li>
            <li>принимая обозначение (<em>prajñapti</em>) за явление (<em>vastu</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>87. Исследованием (<em>jijñāsā</em>) собственной природы явлений</li>
            <li>заблуждение (<em>bhrānti</em>) не прекращается.</li>
            <li>Лишь узрев невозникновение (<em>anutpatti</em>)</li>
            <li>собственной природы явлений, [человек] освобождается.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>88. Не потому бытие дхарм провозглашается</li>
            <li>[подобным магии], что они не существуют (<em>nāsti</em>).</li>
            <li>А потому, что их бытие ложно (<em>vitatha</em>)</li>
            <li>и подобно вспышке молнии (<em>aśu-vidyut</em>),</li>
            <li>они называются подобными магии (<em>māyopama</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>89. Они не будут возникать, не возникали,</li>
            <li>и нигде не обнаруживаются даже условия (<em>pratyaya</em>)</li>
            <li>[их нынешнего возникновения].</li>
            <li>Но для повседневного общения (<em>vyavahāra</em>) так говорится.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>90. Нельзя устранить ни разрушение (<em>bhaṅga</em>),</li>
            <li>ни возникновение (<em>utpāda</em>),</li>
            <li>ни омрачённость (<em>saṃkleśa</em>) [тех] условий.</li>
            <li>Но то, что невежды измышляют (<em>vikalpenti</em>) о них —</li>
            <li>именно это и устраняется.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>91. Нет ни собственной природы (<em>svabhāva</em>),</li>
            <li>ни представлений (<em>vijñapti</em>), ни объектов (<em>vastu</em>),</li>
            <li>ни <em>Алайи</em>. Всё это измышлено невеждами,</li>
            <li>ставшими рабами (<em>vaśa-bhūta</em>) дурной логики (<em>kutārkika</em>).<a href="#citation-526" id="ref-526" class="citation-mark"><sup>526</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>92. Когда сыны Победителя (<em>jinātmaja</em>) видят мир</li>
            <li>как «только-ум» (<em>citta-mātra</em>),</li>
            <li>тогда они обретают тело нирваны (<em>nairvāṇika-kāya</em>),</li>
            <li>свободное от действий и</li>
            <li>обусловленных построений (<em>kriyā-saṃskāra</em>),</li>
            <li>соединённое с <em>силами</em> (<em>bala</em>), <em>сверхзнаниями</em> (<em>abhijñā</em>)</li>
            <li>и <em>властями</em> (<em>vaśitā</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>93. Хотя ум разворачивается (<em>pravartate</em>)</li>
            <li>как явление всех форм (<em>sarva-rūpa-avabhāsa</em>),</li>
            <li>здесь нет ни ума, ни форм [как самостоятельных сущностей];</li>
            <li>есть лишь безначальное (<em>anādika</em>)</li>
            <li>заблуждение (<em>bhrānta</em>) ума.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>94. Тогда йогин мудростью (<em>prajñā</em>) видит мир</li>
            <li>как лишённый признаков (<em>anābhāsa</em>).</li>
            <li>Превзойдя (<em>atikramya</em>) признаки (<em>nimitta</em>),</li>
            <li>вещность (<em>vastu</em>), представления (<em>vijñapti</em>)</li>
            <li>и колебания ума (<em>mano-vispandita</em>),</li>
            <li>мои сыновья пребывают без различений (<em>nirvikalpa</em>).<a href="#citation-527" id="ref-527" class="citation-mark"><sup>527</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>95. Город гандхарвов (<em>gandharva-nagara</em>), магия (<em>māyā</em>),</li>
            <li>волосяной комок (<em>keśoṇḍuka</em>) и мираж (<em>marīcikā</em>) —</li>
            <li>ложны, но кажутся истинными (<em>asatyāḥ satyataḥ khyānti</em>).</li>
            <li>Таково и мысленное построение явлений (<em>bhāva</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>96. Все явления нерождённы (<em>anutpanna sarva-bhāva</em>).</li>
            <li>Видится лишь одно заблуждение (<em>bhrānti-mātra</em>).</li>
            <li>Невежды, привязанные</li>
            <li>к двойственному построению (<em>kalpa-dvaya</em>),</li>
            <li>воображают это заблуждение как возникшее (<em>utpanna</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>97. Ум, связанный с возникновением рождения (<em>aupapattya-aṅgika citta</em>),</li>
            <li>многообразен (<em>vicitra</em>) и возникает</li>
            <li>из отпечатков (<em>vāsanā-saṃbhava</em>).</li>
            <li>Он разворачивается подобно потоку волн (<em>taraṅga-ogha</em>),</li>
            <li>но при отсечении [этих причин] (<em>taccheda</em>)</li>
            <li>более не проявляется.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>98. Если многообразные объекты (<em>vicitra-ālambana</em>)</li>
            <li>возникают в уме благодаря внешним опорам,</li>
            <li>то почему же они не возникают</li>
            <li>в пустом пространстве (<em>ākāśa</em>) или на голой стене (<em>kuḍya</em>)?</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>99. Если бы ум возникал, опираясь (<em>ālambya</em>)</li>
            <li>на внешний признак (<em>nimitta</em>),</li>
            <li>то он был бы порождённым условиями (<em>pratyaya-janita</em>),</li>
            <li>и тогда положение «только-ум» (<em>citta-mātra</em>)</li>
            <li>было бы неверным.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>100. Ум воспринимает ум (<em>cittena gṛhyate citta</em>).</li>
            <li>Нет ничего внешнего, имеющего причинную силу (<em>sahetuka</em>).</li>
            <li>Истинная природа ума (<em>citta-dharmatā</em>) чиста (<em>śuddhā</em>).</li>
            <li>В небе (<em>gagana</em>) нет никаких отпечатков (<em>vāsanā</em>).<a href="#citation-528" id="ref-528" class="citation-mark"><sup>528</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>101. Именно из-за привязанности к</li>
            <li>собственному уму (<em>sva-citta-abhiniveśa</em>)</li>
            <li>ум разворачивается.</li>
            <li>Вовне не существует никакого видимого (<em>dṛśya</em>).</li>
            <li>Поэтому [говорится, что всё есть] </li>
            <li>«только-ум» (<em>citta-mātra</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>102. Ум (<em>citta</em>) — это <em>Алайя-виджняна</em>.</li>
            <li><em>Манас</em> — то, что по своей природе</li>
            <li>есть воображение «я» (<em>manyanā</em>).</li>
            <li>А то, посредством чего схватываются объекты (<em>viṣaya</em>),</li>
            <li>называется различающим сознанием (<em>vijñāna</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>103. Сознание [<em>Алайя</em>] всегда нейтрально.</li>
            <li><em>Манас</em> же движется в обоих направлениях (<em>ubhaya-saṃcara</em>).</li>
            <li>А действующее сознание (<em>vartamāna vijñāna</em>)</li>
            <li>бывает благим и неблагим (<em>kuśala-akuśala</em>).<a href="#citation-529" id="ref-529" class="citation-mark"><sup>529</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>104. Врата высшей истины (<em>paramārtha-dvāra</em>)</li>
            <li>свободны от двойственности представлений (<em>vijñapti-dvaya</em>).</li>
            <li>Когда установлено состояние без проявлений (<em>nirābhāsa</em>),</li>
            <li>как может там оставаться деление на три колесницы?</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>105. «Только-ум (<em>citta-mātra</em>)</li>
            <li>и состояние «без проявлений» (<em>nirābhāsa</em>),</li>
            <li>[духовные] обители (<em>vihāra</em>) и ступени Будды (<em>buddha-bhūmi</em>) —</li>
            <li>об этом возвещали Будды, возвещают и будут возвещать.<a href="#citation-530" id="ref-530" class="citation-mark"><sup>530</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>106. Семь ступеней относятся к сфере ума (<em>citta</em>);</li>
            <li>восьмая же — состояние «без образов» (<em>nirābhāsa</em>).</li>
            <li>Две [следующие] ступени и высшая обитель (<em>vihāra</em>) —</li>
            <li>оставшаяся ступень принадлежит</li>
            <li>Моей собственной природе (<em>mamātmikā</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>107. Чистая ступень,</li>
            <li>постигаемая внутри себя (<em>pratyātmavedyā</em>),</li>
            <li>также принадлежит Моей собственной природе.</li>
            <li>Она сияет в высшей обители Великого Владыки (<em>māheśvara</em>),</li>
            <li>в небе Акаништха.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>108. Подобно тому как от пламени (<em>hutāśana</em>)</li>
            <li>исходят его лучи (<em>raśmi</em>),</li>
            <li>так возникают многообразные (<em>citra</em>),</li>
            <li>прекрасные (<em>manohara</em>) и благие (<em>saumya</em>) проявления,</li>
            <li>создающие Трёхмирье (<em>tribhava</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>109. Проявив некое Трёхмирье</li>
            <li>или используя то, что было проявлено прежде (<em>pūrva-nirmita</em>),</li>
            <li>[Будды] проповедуют там различные колесницы.</li>
            <li>Такова ступень,</li>
            <li>принадлежащая Моей природе (<em>mamātmikā bhūmi</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>110. Нет времени (<em>kāla</em>) в постижении ступеней,</li>
            <li>как нет его в столкновении воинов (<em>kṣatra-saṃkrama</em>).</li>
            <li>Превзойдя «только-ум (<em>citta-mātra</em>),</li>
            <li>обретают плод — утверждение</li>
            <li>в состоянии «без образов» (<em>nirābhāsa</em>).<a href="#citation-531" id="ref-531" class="citation-mark"><sup>531</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>111. Небытие (<em>asattā</em>) и бытие (<em>sattā</em>),</li>
            <li>и видимое многообразие (<em>vicitratā</em>) —</li>
            <li>так воспринимают невежды</li>
            <li>с извращёнными схватываниями (<em>grāha-viparyasta</em>),</li>
            <li>ибо само многообразие есть заблуждение (<em>viparyāsa</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>112. Если мудрость (<em>jñāna</em>) свободна от различений (<em>nirvikalpa</em>),</li>
            <li>то утверждение «объект существует» неуместно.</li>
            <li>Поскольку ум не есть формы (<em>rūpa</em>),</li>
            <li>он по своей природе свободен от различений.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>113. Органы чувств (<em>indriya</em>) подобны магии (<em>māyā</em>);</li>
            <li>объекты (<em>viṣaya</em>) — подобны сновидениям (<em>svapna</em>).</li>
            <li>Деятель (<em>kartṛ</em>), действие (<em>karman</em>)</li>
            <li>и сам акт действия (<em>kriyā</em>)</li>
            <li>в действительности вовсе не обнаруживаются.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>114. Стадии созерцания (<em>dhyāna</em>)</li>
            <li>и безмерные состояния (<em>apramāṇa</em>),</li>
            <li><em>самадхи</em> миров без форм (<em>ārūpya</em>),</li>
            <li>даже полное прекращение восприятия (<em>saṃjñā-nirodha</em>) —</li>
            <li>ничего этого нет в «только-уме (<em>citta-mātra</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>115. Плод <em>Вступившего в поток</em> (<em>srotāpatti-phala</em>),</li>
            <li>плод <em>Однажды-возвращающегося</em> (<em>sakṛdāgāmi-phala</em>),</li>
            <li>плод <em>Невозвращающегося</em> (<em>anāgāmi-phala</em>)</li>
            <li>и само состояние <em>Архата</em> (<em>arhatva</em>) —</li>
            <li>всё это лишь заблуждение ума (<em>citta-vibhrama</em>).<a href="#citation-532" id="ref-532" class="citation-mark"><sup>532</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>116. <em>Шунью</em> (<em>śūnya</em>), непостоянство (<em>anitya</em>)</li>
            <li>и мгновенность (<em>kṣaṇika</em>) невежды воображают</li>
            <li>[как свойства] обусловленного (<em>saṃskṛta</em>).</li>
            <li>С помощью примеров реки (<em>nadī</em>), светильника (<em>dīpa</em>) и прочих</li>
            <li>смысл мгновенности ложно воображается (<em>vikalpyate</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>117. Но [истинная] мгновенность (<em>kṣaṇika</em>) —</li>
            <li>это отсутствие деятельности (<em>nirvyāpāra</em>),</li>
            <li>уединённость (<em>vivikta</em>) и свобода от действия (<em>kriyā-varjita</em>).</li>
            <li>Невозникновение всех дхарм (<em>anutpatti</em>) —</li>
            <li>вот что Я называю</li>
            <li>истинным смыслом мгновенности (<em>kṣaṇikārtha</em>).<a href="#citation-533" id="ref-533" class="citation-mark"><sup>533</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>118. Невозникновение (<em>anutpāda</em>) существующего (<em>sat</em>)</li>
            <li>или несуществующего (<em>asat</em>)</li>
            <li>провозглашалось последователями <strong>Санкхьи</strong> и <strong>Вайшешики</strong>;</li>
            <li>всё это ими объявлялось «неопределённым» (<em>avyākṛta</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>119. [Существуют] четыре вида ответов (<em>vyākaraṇa</em>):</li>
            <li>прямой ответ (<em>ekāṃśa</em>), встречный вопрос (<em>paripṛcchana</em>),</li>
            <li>ответ с различением (<em>vibhajya</em>)</li>
            <li>и оставление без ответа (<em>sthāpanīya</em>), —</li>
            <li>[последнее] применяется для пресечения</li>
            <li>ложных воззрений иноверцев (<em>tīrtha-vāda</em>).<a href="#citation-534" id="ref-534" class="citation-mark"><sup>534</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>120. Всё существует в условной истине (<em>saṃvṛti</em>);</li>
            <li>в высшей истине (<em>paramārtha</em>) не существует.</li>
            <li>Но даже в высшей истине усматривается</li>
            <li>отсутствие собственной природы дхарм (<em>niḥsvabhāvatva</em>).</li>
            <li>Поскольку условность есть восприятие того,</li>
            <li>что лишено собственной природы,</li>
            <li>она так и именуется.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>121. Если бы явления (<em>bhāva</em>) и их</li>
            <li>собственная природа (<em>svabhāva</em>) существовали,</li>
            <li>имея причиной речь (<em>abhilāpa</em>),</li>
            <li>то явления возникали бы из слов.</li>
            <li>Но этого не бывает —</li>
            <li>[их] собственная природа не обнаруживается.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>122. Речь (<em>abhilāpa</em>) лишена реального объекта (<em>nirvastu</em>);</li>
            <li>даже в условной истине она</li>
            <li>не обнаруживается как нечто вещественное.</li>
            <li>Поскольку заблуждение (<em>viparyāsa</em>)</li>
            <li>не является чем-то реальным (<em>vastu</em>),</li>
            <li>то и [его] восприятие (<em>upalabdhi</em>) не обнаруживается.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>123. Если бы заблуждение действительно существовало,</li>
            <li>то отсутствие собственной природы (<em>naiḥsvābhāvya</em>)</li>
            <li>не могло бы быть обнаружено.</li>
            <li>Если бы заблуждение было реальным,</li>
            <li>то всё воспринимаемое было бы истинным.</li>
            <li>Но то, что лишено собственной природы,</li>
            <li>в действительности вовсе не обнаруживается.<a href="#citation-535" id="ref-535" class="citation-mark"><sup>535</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>124. Всё это видимое многообразие (<em>citra</em>) — ум (<em>citta</em>),</li>
            <li>пропитанный грубыми отпечатками (<em>dauṣṭhulya-vāsita</em>).</li>
            <li>Схватывание видимых форм (<em>rūpāvabhāsa-grahaṇa</em>) —</li>
            <li>это заблуждение ума (<em>citta-vibhrama</em>),</li>
            <li>которое воспринимает их как нечто «внешнее» (<em>bahirdhā</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>125. Через различение (<em>vikalpa</em>)</li>
            <li>или через не-различение (<em>avikalpa</em>)</li>
            <li>различение должно быть оставлено.</li>
            <li>Через различение или через не-различение</li>
            <li>[приходят к] созерцанию</li>
            <li>подлинной сути <em>Шуньяты</em> (<em>śūnyatā-tattva-darśana</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>126. Подобно магическому слону (<em>māyā-hastin</em>),</li>
            <li>подобно картине (<em>citra</em>) или золоту,</li>
            <li>сделанному из [окрашенных] листьев (<em>patrāṇi kanaka</em>),</li>
            <li>так и этот мир является людям,</li>
            <li>чьё сознание пропитано неведением (<em>ajñāna-vāsita</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>127. Благородный (<em>ārya</em>) не видит заблуждения (<em>bhrānti</em>),</li>
            <li>но он не видит и «истины» (<em>tattva</em>) внутри него.</li>
            <li>Если бы истина находилась внутри заблуждения,</li>
            <li>то само заблуждение было бы истиной.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>128. Если же, оставив всякое заблуждение,</li>
            <li>[человек вновь] порождает какой-либо образ (<em>nimitta</em>),</li>
            <li>то именно этот образ становится новым заблуждением —</li>
            <li>подобно помутнению зрения при болезни глаз (<em>timira</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>129. Как человек, страдающий болезнью глаз (<em>taimirika</em>),</li>
            <li>из-за помутнения зрения (<em>vibhrama</em>)</li>
            <li>принимает волосяной комок (<em>keśoṇḍuka</em>) за реальность,</li>
            <li>так же происходит и схватывание (<em>grahaṇa</em>)</li>
            <li>объектов (<em>viṣaya</em>) невежественными людьми.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>130. Подобно волосяному комку,</li>
            <li>подобно миражу (<em>marīcī</em>) или обману с водой,</li>
            <li>Трёхмирье — подобно сну (<em>svapna</em>) и иллюзии (<em>māyā</em>).</li>
            <li>Созерцая его таким образом (<em>vibhāventa</em>),</li>
            <li>человек освобождается (<em>vimucyate</em>).<a href="#citation-536" id="ref-536" class="citation-mark"><sup>536</sup></a></li>
        </ul>
    </blockquote>

</div>

<!— Гатхи 131-210 —>
<div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">

    <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>131. Различение (<em>vikalpa</em>), объект различения (<em>vikalpya</em>)</li>
            <li>и сам процесс различения;</li>
            <li>а также узы (<em>bandha</em>), тот, кто скован (<em>bandhya</em>),</li>
            <li>и состояние скованности (<em>baddha</em>) —</li>
            <li>эти шесть суть причины</li>
            <li>для освобождения (<em>mokṣa-hetavaḥ</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>132. Нет ни ступеней (<em>bhūmi</em>), ни истин (<em>satya</em>),</li>
            <li>ни миров (<em>kṣetra</em>), ни явленных форм (<em>nirmita</em>).</li>
            <li>Будды, Пратьекабудды и Шраваки —</li>
            <li>всё это лишь воображаемое (<em>kalpita</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>133. Личность (<em>pudgala</em>), поток (<em>saṃtati</em>), <em>скандхи</em>,</li>
            <li>условия (<em>pratyaya</em>) и даже атомы (<em>aṇu</em>),</li>
            <li>первоматерия (<em>pradhāna</em>), Ишвара и деятель (<em>kartṛ</em>) —</li>
            <li>всё это строится различением</li>
            <li>в поле «только-ума (<em>citta-mātra</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>134. Поистине, ум (<em>citta</em>) есть всё;</li>
            <li>он пребывает везде и во всех телах.</li>
            <li>Невежественные воспринимают его</li>
            <li>как многообразный (<em>vicitra</em>),</li>
            <li>тогда как «только-ум»</li>
            <li>лишен признаков (<em>alakṣaṇa</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>135. Нет «я» (<em>ātman</em>) в <em>скандхах</em>,</li>
            <li>и <em>скандхи</em> не пребывают в «я».</li>
            <li>Они не таковы, как воображаются (<em>vikalpyante</em>),</li>
            <li>но и нельзя сказать, что их вовсе нет.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>136. Если бы существование (<em>astitva</em>)</li>
            <li>всех явлений (<em>sarva-bhāva</em>)</li>
            <li>было таким, как его воображают невежественные,</li>
            <li>то все они были бы видящими истину (<em>tattva-darśin</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>137. Поскольку все дхармы лишены бытия (<em>abhāva</em>),</li>
            <li>нет ни омрачения (<em>saṃkleśa</em>), ни очищения (<em>śuddhi</em>).</li>
            <li>Они не таковы, как они воспринимаются,</li>
            <li>но и нельзя сказать, что их вовсе нет.<a href="#citation-537" id="ref-537" class="citation-mark"><sup>537</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>138. Заблуждение (<em>bhrānti</em>), образ (<em>nimitta</em>)</li>
            <li>и построение умозрений (<em>saṃkalpa</em>) —</li>
            <li>таков признак зависимой природы (<em>paratantra-lakṣaṇa</em>).</li>
            <li>А то именование (<em>nāma</em>),</li>
            <li>которое относится к этому признаку, —</li>
            <li>это признак воображаемой природы (<em>vikalpita-lakṣaṇa</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>139. Когда имя (<em>nāma</em>), образ (<em>nimitta</em>)</li>
            <li>и умозрительное построение (<em>saṃkalpa</em>) не возникают,</li>
            <li>то остаётся лишь</li>
            <li>обозначение зависимости (<em>pratyaya-saṃketa</em>),</li>
            <li>не являющееся чем-то (<em>avastu</em>) —</li>
            <li>это признак совершенной природы (<em>pariniṣpanna</em>).<a href="#citation-538" id="ref-538" class="citation-mark"><sup>538</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>140. Будды Воздаяния (<em>vaipākika</em>), Победители (<em>jina</em>),</li>
            <li>Будды Воплощения (<em>nairmāṇika</em>),</li>
            <li>существа (<em>sattva</em>) и бодхисаттвы,</li>
            <li>а также миры (<em>kṣetra</em>) во всех направлениях —</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>141. Будды излияния (<em>nisyanda</em>), Будды Дхармы (<em>dharma</em>),</li>
            <li>и Будды Воплощения (<em>nirmāṇa</em>), Победители —</li>
            <li>все они исходят из Амитабхи (<em>amitābha</em>),</li>
            <li>из Сукхавати (<em>sukhāvatī</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>142. То, что провозглашено Буддами Воплощения (<em>nairmāṇika</em>),</li>
            <li>и то, что провозглашено Буддами Воздаяния (<em>vipākaja</em>), —</li>
            <li>имеет скрытый смысл (<em>saṃdhi</em>);</li>
            <li>постигайте его через метод</li>
            <li>обширных сутр (<em>sūtrānta-vaipulya-naya</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>143. То, что провозглашено сынами Победителя (<em>jina-suta</em>),</li>
            <li>и то, что провозглашают Проводники (<em>nāyaka</em>), —</li>
            <li>всё это провозглашается Буддами Воплощения (<em>nairmāṇika</em>),</li>
            <li>но не Буддами Воздаяния (<em>vaipākika</em>).<a href="#citation-539" id="ref-539" class="citation-mark"><sup>539</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>144. Поистине, эти дхармы не рождены (<em>anutpannāḥ</em>),</li>
            <li>но нельзя сказать, что их вовсе нет.</li>
            <li>Они подобны городу гандхарвов,</li>
            <li>сновидению, магии и призрачному творению (<em>nirmāṇa</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>145. Ум (<em>citta</em>) разворачивается [в сансару],</li>
            <li>Ум же и освобождается.</li>
            <li>Ум воистину возникает, и ничто иное;</li>
            <li>Ум же и прекращается.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>146. Ум людей проявляется как видимость объектов (<em>arthābhāsa</em>);</li>
            <li>именно ум является как воображаемое (<em>kalpita</em>).</li>
            <li>Объектов не существует, всё это — «только-ум» (<em>citta-mātra</em>).</li>
            <li>Свободный от различений (<em>nirvikalpa</em>) освобождается.<a href="#citation-540" id="ref-540" class="citation-mark"><sup>540</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>147. Пагубная склонность (<em>dauṣṭhulya</em>)</li>
            <li>к разрастанию умопостроений (<em>prapañca</em>)</li>
            <li>накопленная с безначальных времён, укоренилась [в уме].</li>
            <li>Этим взращивается различение,</li>
            <li>и через него разворачивается ложное проявление (<em>mithyābhāsa</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>148. В то время как сознание (<em>vijñāna</em>)</li>
            <li>занято видимостью объектов,</li>
            <li>мудрость (<em>jñāna</em>) имеет своей сферой Таковость (<em>tathatā</em>).</li>
            <li>Она [мудрость] преображена (<em>parāvṛtta</em>) и свободна от образов;</li>
            <li>именно она является сферой опыта Благородных (<em>ārya</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>149. [Существуют разные виды созерцания]:</li>
            <li><em>дхьяна</em> как исследование объектов,</li>
            <li><em>дхьяна</em> как практика для начинающих (<em>bāla-upacārika</em>),</li>
            <li><em>дхьяна</em>, опирающаяся на Таковость,</li>
            <li>и благая <em>дхьяна</em> Татхагаты.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>150. По своей воображаемой природе (<em>parikalpita</em>)</li>
            <li>все дхармы не рождены (<em>ajāta</em>).</li>
            <li>Опираясь же на зависимую природу (<em>paratantra</em>),</li>
            <li>различающее мышление людей блуждает.<a href="#citation-541" id="ref-541" class="citation-mark"><sup>541</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>151. Когда <em>зависимая природа</em> (<em>paratantra</em>) очищена</li>
            <li>и полностью свободна от различающего мышления (<em>vikalpa</em>),</li>
            <li>то, что преображено (<em>parāvṛtti</em>), есть Таковость (<em>tathatā</em>) —</li>
            <li>пребывание, свободное от воображения.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>152. Не порождайте различений!</li>
            <li>Различение не существует как истина.</li>
            <li>У того, кто воображает заблуждение,</li>
            <li>нет [действительного] познаваемого и познающего —</li>
            <li>видение внешних объектов —</li>
            <li><em>воображаемая природа</em> (<em>parikalpita</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>153. Тем воображением (<em>kalpanā</em>),</li>
            <li>которым [люди] строят [мир], —</li>
            <li>является природа,</li>
            <li>возникающая из условий (<em>pratyayodbhava-svabhāva</em>).</li>
            <li>Но видение внешних объектов (<em>bāhyārtha-darśana</em>) ложно:</li>
            <li>объектов нет, есть только Ум (<em>citta</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>154. У тех, кто созерцает посредством</li>
            <li>правильного рассуждения (<em>yuktyā</em>),</li>
            <li>угасает двойственность познающего и познаваемого.</li>
            <li>Внешних объектов не существует так,</li>
            <li>как их измышляют невежественные люди.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>155. Ум, взволнованный отпечатками (<em>vāsanā</em>)</li>
            <li>разворачивается как видимость объектов.</li>
            <li>С прекращением двух видов воображения (<em>kalpa-dvaya</em>)</li>
            <li>возникает знание, чья сфера — Таковость.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>156. Возникает состояние «без проявлений» (<em>anābhāsa</em>),</li>
            <li>непостижимая сфера Благородных.</li>
            <li>Имя, образ,</li>
            <li>умозрительное построение (<em>nāma-nimitta-saṃkalpa</em>)—</li>
            <li>характеристика (<em>lakṣaṇam</em>)</li>
            <li>двойственной природы (<em>svabhāva-dvaya</em>);</li>
            <li>истинное знание (<em>samyak-jñānam</em>) и Таковость —</li>
            <li>свойства <em>совершенной природы</em> (<em>pariniṣpanna</em>).<a href="#citation-542" id="ref-542" class="citation-mark"><sup>542</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>157. Из соединения матери и отца,</li>
            <li>будучи связанным с <em>Алайя-виджняной</em> и <em>манасом</em>,</li>
            <li>[зародыш] растёт вместе с семенем,</li>
            <li>подобно мыши в сосуде с топлёным маслом.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>158. Плод кармы разворачивается</li>
            <li>в виде [стадий зародыша]:</li>
            <li>сгустка (<em>peśī</em>), плотной массы (<em>ghana</em>),</li>
            <li>пузыря (<em>arbuda</em>) и опухоли (<em>piṭaka</em>) —</li>
            <li>этого нечистого скопления,</li>
            <li>оформленного кармой и</li>
            <li>движимого ветрами первоэлементов.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>159. [Возникают] пять пятериц</li>
            <li>и также девять отверстий;</li>
            <li>покрытый ногтями, зубами и волосами,</li>
            <li>трепещущий, он рождается.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>160. Едва родившись, человек подобен червю в нечистотах,</li>
            <li>словно с ещё спящим сознанием;</li>
            <li>формы начинают мерцать пред глазами,</li>
            <li>и через воображение они разрастаются.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>161. Через соприкосновение нёба и губ,</li>
            <li>под воздействием различающего мышления (<em>vikalpa</em>),</li>
            <li>у людей рождается речь —</li>
            <li>это лишь игра воображения</li>
            <li>подобная [подражанию] попугая.<a href="#citation-543" id="ref-543" class="citation-mark"><sup>543</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>162. Учения тиртхиков определённы (<em>niścitāḥ</em>),</li>
            <li>Тогда как Махаяна — свободна от догм (<em>aniścitam</em>).</li>
            <li>Она направлена на прибежище для существ,</li>
            <li>но недоступна тем, кто держится ложных воззрений.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>163. Моя Колесница —</li>
            <li>это путь, постигаемый лично (<em>pratyātmavedya</em>),</li>
            <li>недоступный логикам (<em>tārkikā</em>).</li>
            <li>[Махамати спросил]:</li>
            <li>«Скажи, когда Владыка уйдет, кто в будущие времена </li>
            <li>станет хранителем этого [учения]?»</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>164. [Будда ответил]:</li>
            <li>«Когда Сугата уйдет в нирвану</li>
            <li>и время его минует, —</li>
            <li>о Махамати, знай,</li>
            <li>кто станет хранителем этого пути:</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>165. В южной стране Ведалья явится</li>
            <li>славный и высокочтимый монах по имени Нага,</li>
            <li>сокрушитель крайностей бытия и небытия.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>166. Провозгласив в мире людей Мою Колесницу —</li>
            <li>непревзойденную Махаяну, он [Нагарджуна]</li>
            <li>достигнет <em>Ступени Радости</em> (<em>muditā-bhūmi</em>)</li>
            <li>и уйдет в [обитель] Сукхавати».</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>167. Когда дхармы исследуются рассудком,</li>
            <li>их собственная природа не устанавливается;</li>
            <li>поэтому они объявлены невыразимыми речью</li>
            <li>и лишёнными собственной природы.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>168. В том, что возникает из условий,</li>
            <li>не устанавливается ни «есть», ни «нет».</li>
            <li>Те, кто воображают «бытие» или «небытие»</li>
            <li>относительно того, что включено в условия, —</li>
            <li>те, полагаю, далеки от Учения</li>
            <li>и придерживаются взглядов тиртхиков.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>169. Именование всех явлений</li>
            <li>укоренялось и укреплялось</li>
            <li>на протяжении сотен рождений</li>
            <li>через взаимное понятийное различение.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>170. Если бы не происходило называние,</li>
            <li>весь мир погрузился бы в путаницу.</li>
            <li>Поэтому устанавливаются имена —</li>
            <li>лишь ради устранения этой путаницы.<a href="#citation-544" id="ref-544" class="citation-mark"><sup>544</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>171. Невежественные выстраивают явления</li>
            <li>посредством трёх видов различающего мышления:</li>
            <li>через заблуждение, через именование</li>
            <li>и через [выстраивание], возникающее из условий.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>172. Поистине, [дхармы] не прекращающиеся (<em>aniruddha</em>)</li>
            <li>и не возникающие (<em>anutpanna</em>);</li>
            <li>по своей природе они подобны пространству.</li>
            <li>Те же, чья природа — небытие, —</li>
            <li>имеют признак воображаемого (<em>vikalpita-lakṣaṇa</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>173. [Они] подобны мерцанию, отражению,</li>
            <li>магии, миражу и сновидению;</li>
            <li>они ложно возникают,</li>
            <li>подобно огненному колесу, городу гандхарвов и эху.<a href="#citation-545" id="ref-545" class="citation-mark"><sup>545</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>174. Недвойственность, Таковость, <em>Шунья</em>, <em>Предел истинности</em>,</li>
            <li>Дхармата и отсутствие понятийного различения —</li>
            <li>так Я излагаю признаки <em>совершенной природы</em>.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>175. То, что относится к сфере речи и ума, — обманчиво;</li>
            <li>«истина», постигаемая мыслью, — вымышлена.</li>
            <li>Ум впадает в крайности двойственности;</li>
            <li>потому <em>праджня</em> не является вымышленной.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>176. «Есть» и «нет» — две крайности,</li>
            <li>пока длится сфера ума (<em>cittasya gocaraḥ</em>).</li>
            <li>Когда эта сфера очищена (<em>gocareṇa vidhūtena</em>),</li>
            <li>ум истинно успокаивается (<em>samyak cittaṃ nirudhyate)</em>.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>177. При отсутствии схватывания объектов</li>
            <li>и благодаря прекращению этого процесса</li>
            <li>раскрывается состояние Таковости —</li>
            <li>как сфера опыта Благородных.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>178. Мир не является для невежд таким,</li>
            <li>каким он является мудрецам.</li>
            <li>Для мудрецов же все дхармы</li>
            <li>не имеют определимых признаков.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>179. Подобно тому как глупцы</li>
            <li>принимают за золото сплав харакута,</li>
            <li>который золотом не является,</li>
            <li>хотя и выглядит как золото, —</li>
            <li>так и заблуждающиеся логики воображают дхармы.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>180. Те, кто полагают, что нечто возникает,</li>
            <li>не существовав прежде,</li>
            <li>или что, существовав, оно затем уничтожается,</li>
            <li>а также мыслят в категориях бытия и небытия, —</li>
            <li>те не пребывают в Моём Учении.<a href="#citation-546" id="ref-546" class="citation-mark"><sup>546</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>181. Поскольку у дхарм нет ни начала, ни конца,</li>
            <li>они пребывают в подлинном признаке истинного (<em>bhūtalakṣaṇa</em>).</li>
            <li>Но логики этого мира, мыслящие</li>
            <li>как ремесленники-причинники (<em>kāraṇakārava</em>),</li>
            <li>этого не постигают.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>182. Прошлое существует, существует и будущее,</li>
            <li>настоящее воспринимается непосредственно;</li>
            <li>поэтому все дхармы нерождены.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>183. Те, кто воображают превращение, время,</li>
            <li>устройство элементов и органов чувств,</li>
            <li>а также промежуточное состояние, —</li>
            <li>те не являются мудрецами.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>184. Победители не описывают мир как зависимо возникший;</li>
            <li>они указывают, что это лишь поток условий,</li>
            <li>подобный городу гандхарвов.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>185. Всё это есть лишь условное обозначение дхарм;</li>
            <li>в его пределах говорится: «это есть то».</li>
            <li>То же, что отделено от обозначения,</li>
            <li>не рождается и не прекращается.<a href="#citation-547" id="ref-547" class="citation-mark"><sup>547</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>186. В зеркале, в воде, в глазу,</li>
            <li>в сосудах и в драгоценных камнях</li>
            <li>видится отражение;</li>
            <li>но этого отражения нигде нет.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>187. Так и ум проявляется как видимость —</li>
            <li>подобно мареву в небе,</li>
            <li>как многообразные образы во сне,</li>
            <li>как [видение] сына бесплодной женщины.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>188. Моя Колесница — не [внешняя] Махаяна,</li>
            <li>это не звуки и не буквы,</li>
            <li>не истины и не освобождения,</li>
            <li>и даже не сфера «без образов» (<em>nirābhāsa</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>189. Но Махаяна — это владычество над <em>самадхи</em>,</li>
            <li>это многогранное «тело,</li>
            <li>рожденное из ума» (<em>manomaya-kāya</em>),</li>
            <li>украшенное цветами владычества (<em>vaśitā</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>190. Ни как единое, ни как раздельное</li>
            <li>явление не обнаруживается в условиях.</li>
            <li>«Рождение» — лишь совпадение условий,</li>
            <li>«прекращение» — лишь их распад.<a href="#citation-548" id="ref-548" class="citation-mark"><sup>548</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>191. «<em>Шуньята</em> <em>нерождённого</em>» — одно,</li>
            <li>а «<em>шуньята</em> <em>возникшего</em>» — другое.</li>
            <li><em>Шуньята</em> <em>нерождённого</em> — высшая;</li>
            <li><em>шуньята</em> <em>возникшего</em> исчезает.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>192. Таковость, <em>Шуньята</em>, <em>Предел истинности</em>,</li>
            <li>Нирвана и Дхармадхату,</li>
            <li>а также многообразное <em>тело, рождённое из ума</em>, —</li>
            <li>всё это Я излагаю различными синонимами.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>193. Те, кто полагают очищение через</li>
            <li>Сутры, Винаю и Абхидхарму,</li>
            <li>следуя букве (<em>granthato</em>), а не смыслу (<em>arthena</em>), —</li>
            <li>те не утвердились в учении об отсутствии «я».</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>194. Ни тиртхиками, ни Буддами,</li>
            <li>ни Мной, ни кем-либо</li>
            <li>не установлено бытие через условия;</li>
            <li>как же тогда может быть небытие?</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>195. Кем было обосновано бытие,</li>
            <li>чтобы затем возникло его небытие из условий?</li>
            <li>Из-за ложного взгляда, утверждающего возникновение,</li>
            <li>воображают «есть» и «нет».</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>196. Для того, у кого ничто не возникает</li>
            <li>и ничто не прекращается,</li>
            <li>не возникает «есть» или «нет»,</li>
            <li>когда он видит мир в уединённости (<em>vivikta</em>).<a href="#citation-549" id="ref-549" class="citation-mark"><sup>549</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>197. У людей возникает представление того,</li>
            <li>что называется «рогами зайца».</li>
            <li>Те же, кто принимают это воображаемое (как действительное),</li>
            <li>заблуждаются, подобно оленям, [бегущим за] миражом.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>198. Из-за привязанности к воображаемому</li>
            <li>само воображение продолжает разворачиваться.</li>
            <li>Но если воображение без причины,</li>
            <li>то само воображение не может быть обосновано.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>199. Подобно тому как в безводном месте</li>
            <li>видится вода, как мираж в небе,</li>
            <li>так и невежественным являются объекты.</li>
            <li>Для Благородных же здесь нет различий.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>200. Видение Благородных чисто;</li>
            <li>оно рождается из трех [врат] освобождения.</li>
            <li>Оно свободно от рождения и распада</li>
            <li>и пребывает в состоянии «без образов» (<em>nirābhāsa</em>).<a href="#citation-550" id="ref-550" class="citation-mark"><sup>550</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>201. Глубину, величие и обширность [Учения],</li>
            <li>знание и великолепие чистых земель</li>
            <li>Я провозглашаю сыновьям Победителей (бодхисаттвам);</li>
            <li>шравакам же — непостоянство.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>202. Непостоянство трех миров, <em>шуньяту</em>,</li>
            <li>отсутствие «я» и «моего» —</li>
            <li>Это Я провозглашаю шравакам,</li>
            <li>а также [учу их] общим признакам [дхарм].</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>203. Непривязанность ко всем дхармам,</li>
            <li>уединение и одиночное странствие —</li>
            <li>Это плод для пратьекабудд;</li>
            <li>Я провозглашаю [его] за пределами логики.<a href="#citation-551" id="ref-551" class="citation-mark"><sup>551</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>204. Пока обладающий телом,</li>
            <li>воображая внешнее как имеющее собственную природу</li>
            <li>и принимая <em>зависимую природу</em> за реальную,</li>
            <li>не увидит заблуждения о «я»,</li>
            <li>его ум продолжает разворачиваться.<a href="#citation-552" id="ref-552" class="citation-mark"><sup>552</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>205. Десятая [ступень] становится первой,</li>
            <li>а первая — восьмой;</li>
            <li>девятая — седьмой,</li>
            <li>а седьмая — восьмой.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>206. Вторая становится третьей,</li>
            <li>четвертая — пятой,</li>
            <li>А третья — шестой.</li>
            <li>В [состоянии] отсутствия образов</li>
            <li>откуда взяться порядку?<a href="#citation-553" id="ref-553" class="citation-mark"><sup>553</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>207. Ведь в состоянии отсутствия образов</li>
            <li>небытие не существует для йогинов.</li>
            <li>Из равенства бытия и небытия</li>
            <li>рождается плод Благородных.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>208. — Как может небытие явлений</li>
            <li>установить равенство?</li>
            <li>— Когда ум не распознаёт</li>
            <li>колебания во внешнем и внутреннем,</li>
            <li>тогда угасает [заблуждение]</li>
            <li>благодаря видению равного ума.<a href="#citation-554" id="ref-554" class="citation-mark"><sup>554</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>209. В безначальной сансаре,</li>
            <li>охваченной цеплянием за бытие,</li>
            <li>посредством невежд,</li>
            <li>подобно тому как клин выбивается клином,</li>
            <li>[ум], будучи увлечён [одним],</li>
            <li>отводится [от другого].</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>210. Имея это своей причиной,</li>
            <li>беря это как объект</li>
            <li>и опираясь на движение ума,</li>
            <li>оно даёт причину уму,</li>
            <li>и сознание на этом основывается.<a href="#citation-555" id="ref-555" class="citation-mark"><sup>555</sup></a></li>
        </ul>
        </blockquote>
</div>
<!— Гатхи 211-260 —>
<div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
    <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl"></blockquote>
      <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>211. Благодаря кармическому созреванию,</li>
            <li>благодаря <em>благословению</em></li>
            <li>и вследствие рождения в телах и уделах,</li>
            <li>во сне обретаются четыре вида <em>сверхзнания</em>.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>212. И то, что обретается во сне,</li>
            <li>и то, что [возникает] благодаря <em>благосклонности</em> Будды, —</li>
            <li>всё это относится к тем,</li>
            <li>чьё существование в телах, уделах и родах</li>
            <li>есть плод созревания сознания.<a href="#citation-556" id="ref-556" class="citation-mark"><sup>556</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>213. Ум, сформированный отпечатками,</li>
            <li>разворачивается как видимость явлений.</li>
            <li>Когда невежды этого не понимают,</li>
            <li>тогда излагается учение о возникновении.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>214. Пока речь выстраивает явление,</li>
            <li>наделяя его признаками,</li>
            <li>до тех пор ум постигает [это],</li>
            <li>не видя собственного заблуждения.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>215. — Почему говорится о возникновении?</li>
            <li>Почему не говорится о видимом?</li>
            <li>Ведь видимое по своей природе невидимо —</li>
            <li>чьё оно, что именно описывается и откуда [исходит]?<a href="#citation-557" id="ref-557" class="citation-mark"><sup>557</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>216. — Ум по своей природе ясен,</li>
            <li>но <em>манас</em> производит омрачение.</li>
            <li><em>Манас</em> вместе с сознаниями</li>
            <li>постоянно вбрасывает отпечатки.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>217. Когда <em>Алайя</em> покидает тело,</li>
            <li><em>манас</em> устремляется к новому становлению.</li>
            <li>Сознание, видя явленность объектов,</li>
            <li>увлекается заблуждением.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>218. Всё воспринимаемое есть ум;</li>
            <li>внешнего не существует.</li>
            <li>Так следует ясно распознавать заблуждение</li>
            <li>и удерживать в памяти Таковость.<a href="#citation-558" id="ref-558" class="citation-mark"><sup>558</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>219. Область созерцающих (<em>dhyāyināṃ viṣayaḥ</em>),</li>
            <li>карма и величие Будды —</li>
            <li>эти три непостижимы; и это</li>
            <li>непостижимое относится к сфере сознания.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>220. Будущее и прошлое, нирвану, личность и речь</li>
            <li>Я излагаю условно;</li>
            <li>высшая же истина — вне всякого выражения.<a href="#citation-559" id="ref-559" class="citation-mark"><sup>559</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>221. Последователи различных направлений и тиртхики,</li>
            <li>опираясь на односторонние воззрения,</li>
            <li>полностью заблуждаются в отношении «только-ума»</li>
            <li>и воображают внешнее бытие.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>222. «Пробуждение для себя» (<em>pratyekabodhi</em>),</li>
            <li>«состояние Будды» (<em>buddhatva</em>),</li>
            <li>архатство, лицезрение Будды —</li>
            <li>то, что во сне кажется достижением,</li>
            <li>в пробуждении раскрывается как скрытое семя.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>223. — Где? Для кого? Как? Почему?</li>
            <li>С какой целью? — поведай мне!</li>
            <li>— Моё учение — ум, совершенно умиротворённый,</li>
            <li>вне сторон бытия и небытия.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>224. Для тех, кто заблуждается относительно «только-ума»,</li>
            <li>Я излагаю учение, в котором [говорится] «есть» и «нет»,</li>
            <li>связанное с возникновением и распадом,</li>
            <li>лишённое определяемого и признака.<a href="#citation-560" id="ref-560" class="citation-mark"><sup>560</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>225. Различение — это <em>манас</em> вместе с пятью сознаниями;</li>
            <li>семя ума приходит в движение,</li>
            <li>подобно отражению в текущей воде.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>226. Когда ум, <em>манас</em> и сознание не приходят в движение,</li>
            <li>тогда обретается <em>тело, рождённое умом</em>,</li>
            <li>и ступень Будды.<a href="#citation-561" id="ref-561" class="citation-mark"><sup>561</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>227. Условия (<em>pratyayāḥ</em>), элементы (<em>dhātavaḥ</em>), <em>скандхи</em></li>
            <li>и собственные признаки дхарм (<em>svalakṣaṇam dharmāṇām</em>),</li>
            <li>условные обозначения (<em>prajñaptiḥ</em>), личность (<em>pudgala</em>) и ум (<em>citta</em>) —</li>
            <li>подобны сну и волоскам перед глазами.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>228. Увидев мир подобным иллюзии и сну,</li>
            <li>следует опереться на истинную природу (<em>tattva</em>).</li>
            <li>Ибо истинная природа свободна от характеристик (<em>lakṣaṇair muktam</em>)</li>
            <li>и не устанавливается ни доводами (<em>yukti</em>), ни причинами (<em>hetu</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>229. Следует всегда памятовать</li>
            <li>о состоянии Благородных (<em>āryāṇāṃ vihāraḥ</em>),</li>
            <li>постигаемом лично (<em>pratyātma-vedya</em>).</li>
            <li>Мир, заблуждающийся в доводах (<em>yukti</em>) и причинах (<em>hetu</em>),</li>
            <li>следует направить к истинной природе (<em>tattva</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>230. Благодаря затиханию</li>
            <li>всех умопостроений (<em>sarvaprapañcopaśamāt</em>)</li>
            <li>заблуждение более не разворачивается.</li>
            <li>Пока различение принимается как «мудрость» (<em>prajñā yāvat vikalpante</em>),</li>
            <li>до тех пор продолжается заблуждение (<em>bhrāntiḥ pravartate</em>).<a href="#citation-562" id="ref-562" class="citation-mark"><sup>562</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>231. Отсутствие собственной природы, бытие, <em>Шуньята</em>,</li>
            <li>а также постоянство и непостоянство —</li>
            <li>всё это воззрения тех, кто утверждает возникновение,</li>
            <li>но не тех, кто утверждает невозникновение.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>232. Единство, различие, оба сразу,</li>
            <li>[возникновение] от Творца или самопроизвольно,</li>
            <li>из времени, первоматерии или иных условий —</li>
            <li>так измышляется мир.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>233. Сознание — семя сансары;</li>
            <li>оно разворачивается при наличии видимого,</li>
            <li>как картина существует при наличии стены.</li>
            <li>Потому через полное распознавание того,</li>
            <li>что видимое — лишь проявление ума,</li>
            <li>[сансара] прекращается.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>234. Подобно иллюзорному человеку,</li>
            <li>у людей разворачиваются смерть и рождение.</li>
            <li>Так же из-за омрачения</li>
            <li>у невежд разворачиваются узы и освобождение.<a href="#citation-563" id="ref-563" class="citation-mark"><sup>563</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>235. Внутреннее и внешнее — двояко;</li>
            <li>[так же как] дхармы и условия.</li>
            <li>Ясно различая это, йогин утверждается</li>
            <li> в состоянии «без образов» (<em>nirābhāsa</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>236. Ум не разделим с отпечатками (<em>vāsanā</em>),</li>
            <li>и не образует с ними единого целого.</li>
            <li>Он неразличим по признаку,</li>
            <li>хотя окутан отпечатками.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>237. Отпечатки, возникшие из <em>мано-виджняны</em>,</li>
            <li>подобны грязи;</li>
            <li>ум, подобный белой ткани,</li>
            <li>из-за них не проявляет своего сияния.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>238. Как Я говорю: небо —</li>
            <li>ни бытие, ни небытие (<em>na bhāvo nābhāvo</em>),</li>
            <li>так и <em>Алая</em> в Теле —</li>
            <li>свободна от бытия и небытия.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>239. Когда <em>мано-виджняна</em> преобразована (обращена),</li>
            <li>ум свободен от загрязнений.</li>
            <li>Через полное постижение всех дхарм</li>
            <li>Я называю такой ум — Буддой.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>240. С пресечением трёх потоков</li>
            <li>[оно] свободно от бытия и небытия,</li>
            <li>освобождено от четырёх крайностей —</li>
            <li>таково становление (<em>bhava</em>),</li>
            <li>всегда подобное иллюзии.<a href="#citation-564" id="ref-564" class="citation-mark"><sup>564</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>241. Две природы и семь ступеней</li>
            <li>возникают из ума;</li>
            <li>остальные ступени и ступень Будды —</li>
            <li><em>совершенная природа</em>.<a href="#citation-565" id="ref-565" class="citation-mark"><sup>565</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>242. Мир форм, мир без форм,</li>
            <li>мир желаний и нирвана —</li>
            <li>всё это провозглашено</li>
            <li>как сфера ума в этом самом теле.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>243. Пока что-либо воспринимается [как нечто внешнее],</li>
            <li>до тех пор разворачивается заблуждение.</li>
            <li>При полном пробуждении собственного ума</li>
            <li>заблуждение более не разворачивается и не прекращается.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>244. В не-возникновении (<em>anutpāda</em>) отсутствует причинность;</li>
            <li>в утверждении «есть» — вовлечение в сансару.</li>
            <li>Видя всё подобным иллюзии,</li>
            <li>не измышляй признаков.<a href="#citation-566" id="ref-566" class="citation-mark"><sup>566</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>245. Я учу о трёх колесницах, единой колеснице</li>
            <li>и отсутствии колесницы —</li>
            <li>это — для невежд со слабым разумом</li>
            <li>и для отделённости Благородных.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>246. Двояко излагаю возникновение —</li>
            <li>через признаки и через постижение.</li>
            <li>Метод наставления четырёхчастен:</li>
            <li>установление и разъяснение через доводы.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>247. Видя особенности форм и очертаний,</li>
            <li>ум вовлекается в различение.</li>
            <li>В отсутствии имён и структуры постигается</li>
            <li>собственная природа — сфера Благородных.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>248. Пока существует различение,</li>
            <li>до тех пор существует воображаемый признак.</li>
            <li>При отсутствии различения и воображения</li>
            <li>постигается собственная природа —</li>
            <li>сфера Благородных.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>249. Истинность (<em>tattva</em>) постоянна и неизменна;</li>
            <li>готра (<em>gotra</em>) — имеющая природу основы (<em>vastu</em>).</li>
            <li>Таковость (<em>tathatā</em>) свободна от ума</li>
            <li>и лишена всяких измышлений.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>250. Если бы не было основы (<em>vastu</em>),</li>
            <li>не было бы ни омрачения (<em>saṃkleśa</em>), ни очищения (<em>śuddhi</em>).</li>
            <li>Но поскольку ум очищается и омрачение наблюдается,</li>
            <li>следовательно, [есть] чистое основание (<em>viśuddha-vastu</em>),</li>
            <li>сфера Благородных (<em>ārya-gocara</em>).<a href="#citation-567" id="ref-567" class="citation-mark"><sup>567</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>251. Мир, возникший из условий</li>
            <li>и свободный от различений,</li>
            <li>подобен иллюзии и сну —</li>
            <li>узрев его так, практик освобождается.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>252. Отпечатки — пёстрые,</li>
            <li>пропитанные скверной — сплетены с умом,</li>
            <li>видятся как внешнее —</li>
            <li>но это не есть природа ума.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>253. Природа ума чиста;</li>
            <li>ум не рождён из заблуждения.</li>
            <li>Заблуждение, будучи омрачающим,</li>
            <li>делает [истинный] ум невидимым.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>254. То, что принимается за заблуждение, —</li>
            <li>именно это и есть истина; иной истины нет.</li>
            <li>Она не в обусловленном (<em>saṃskāra</em>) и не вне него,</li>
            <li>но постигается через видение обусловленного.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>255. Когда [йогин] видит обусловленное</li>
            <li>свободным от [двойственности] обозначаемого и признака,</li>
            <li>тогда для него мир оказывается очищенным,</li>
            <li>[и он] видит [в нем лишь] собственный ум.<a href="#citation-568" id="ref-568" class="citation-mark"><sup>568</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>256. Утвердившись в [понимании] «только-ума»,</li>
            <li>не следует измышлять внешние объекты.</li>
            <li>Пребывая в опоре на Таковость,</li>
            <li>следует превзойти и [само понятие] «только-ума».</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>257. Превзойдя «только-ум», следует превзойти</li>
            <li>и состояние «отсутствия образов».</li>
            <li>Йогин, утвердившийся в состоянии «без образов»,</li>
            <li>истинно зрит Махаяну.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>258. Путь без усилия, умиротворённый,</li>
            <li>очищенный посредством обетов (<em>praṇidhāna</em>), —</li>
            <li>высшее знание, свободное от «я»,</li>
            <li>не видит даже состояние «без образов».</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>259. Пусть распознаёт сферу ума,</li>
            <li>пусть видит сферу знания,</li>
            <li>пусть распознаёт сферу мудрости —</li>
            <li>тогда не заблудится в признаках.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>260. Истина страдания — сфера ума;</li>
            <li>истина возникновения — сфера знания;</li>
            <li>две высшие истины и ступень Будды —</li>
            <li>в сфере мудрости.<a href="#citation-569" id="ref-569" class="citation-mark"><sup>569</sup></a></li>
        </ul>
    </blockquote>

</div>

<!— Гатхи 261-310 —>

<div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">

    <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>261. Достижение плода, нирвана и восьмеричный путь —</li>
            <li>через постижение всех дхарм очищается знание Будды.<a href="#citation-570" id="ref-570" class="citation-mark"><sup>570</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>262. Глаз, форма, освещение, пространство, а также <em>манас</em> —</li>
            <li>при их сочетании возникает у людей</li>
            <li>сознание, рождённое из <em>Алаи</em>.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>263. Схватываемое, схватывание и схватывающий —</li>
            <li>не имеют собственной основы (<em>avastuka</em>).</li>
            <li>Те, кто полагают, что различение (<em>vikalpa</em>)</li>
            <li>возникает без причины, — не мудры.<a href="#citation-571" id="ref-571" class="citation-mark"><sup>571</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>264. В объекте имя не возникло,</li>
            <li>и в имени объект не возник.</li>
            <li>Различение, возникающее из причин и не-причин,</li>
            <li>не следует развёртывать.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>265. У всех явлений нет собственной природы,</li>
            <li>и высказывание о них также не имеет основы.</li>
            <li>Не узрев ни <em>шуньяты</em>, ни её смысла, невежда блуждает.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>266. Когда «пребывание истины» усматривают</li>
            <li>через домысливание,</li>
            <li>учение остаётся лишь условным обозначением.</li>
            <li>Единство, установленное пятью способами, —</li>
            <li>такую «истину» следует отбросить.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>267. Разрастание понятий, уязвимое для Мары,</li>
            <li>следует превзойти, выйдя за пределы «есть» и «нет».</li>
            <li>Стремление к небытию — ложное представление,</li>
            <li>проистекающее из [неверного понимания] видения отсутствия «я».</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>268. Вечность и существование творца —</li>
            <li>лишь развёртывания на уровне рассуждений.</li>
            <li>Высшая истина невыразима;</li>
            <li>в угасании — видение дхарм.<a href="#citation-572" id="ref-572" class="citation-mark"><sup>572</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>269. Опираясь на <em>Алаю</em>, разворачивается <em>манас</em>.<a href="#citation-573" id="ref-573" class="citation-mark"><sup>573</sup></a></li>
            <li>Опираясь на ум (<em>citta</em>) и <em>манас</em>, разворачивается сознание.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>270. Распознав наложение как наложение (<em>samāropa</em>), йогин видит,</li>
            <li>что Таковость — это природа ума (<em>citta-dharmatā</em>).</li>
            <li>Так постигая, он обретает знание «только-ума».<a href="#citation-574" id="ref-574" class="citation-mark"><sup>574</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>271. <em>Манас</em>, признаки и то, что принимается за объект,</li>
            <li>йогин не полагает ни как вечные, ни как невечные.</li>
            <li>В йоге он не измышляет</li>
            <li>ни возникновения, ни невозникновения.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>272. Двойственность объекта не воображается [мудрыми],</li>
            <li>ибо сознание рождается из <em>Алаи</em>.</li>
            <li>Единый смысл не постигается двойственным умом —</li>
            <li>не познаётся и происхождение.<a href="#citation-575" id="ref-575" class="citation-mark"><sup>575</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>273. Нет ни говорящего, ни изрекаемого;</li>
            <li>нет и «шуньяты» при видении самого ума.</li>
            <li>Из-за невидения собственного ума</li>
            <li>разворачивается сеть воззрений.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>274. Нет возникновения из условий (<em>pratyaya</em>),</li>
            <li>нет никаких органов чувств (<em>indriya</em>);</li>
            <li>ни элементов (<em>dhātu</em>), ни <em>скандх</em>;</li>
            <li>ни страсти, ни обусловленного (<em>saṃskṛta</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>275. Нет изначального огня кармы;<a href="#citation-576" id="ref-576" class="citation-mark"><sup>576</sup></a></li>
            <li>нет ни сотворённого (<em>kṛta</em>), ни обусловленного (<em>saṃskṛta</em>).</li>
            <li>Нет ни предела (<em>koṭi</em>), ни силы,</li>
            <li>ни освобождения, ни связующих уз.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>276. Нет неопределенного (<em>avyākṛta</em>), нет и бытия;</li>
            <li>воистину, нет ни дхармы, ни адхармы.</li>
            <li>Нет ни времени, ни нирваны;</li>
            <li>даже «природа дхарм» (<em>dharmatā</em>) не обнаруживается.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>277. Нет ни Будды, ни истин;</li>
            <li>ни плода, ни причин.</li>
            <li>Нет ни заблуждения (<em>viparyaya</em>), ни нирваны;</li>
            <li>нет ни уничтожения (<em>vibhava</em>), ни становления (<em>saṃbhava</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>278. Нет и двенадцати звеньев [зависимого возникновения];</li>
            <li>нет ни конечного (<em>anta</em>), ни бесконечного (<em>ananta</em>).</li>
            <li>Для устранения всех воззрений</li>
            <li>Я провозглашаю «только-ум».<a href="#citation-577" id="ref-577" class="citation-mark"><sup>577</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>279. Клеши, пути кармы, тела,</li>
            <li>деятели и плоды —</li>
            <li>подобны миражу и сну,</li>
            <li>подобны городу гандхарвов.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>280. При установлении в «только-уме»</li>
            <li>прекращается двойственность — признак бытия (<em>bhāvalakṣaṇa</em>).</li>
            <li>При утверждении в «только-уме» устраняются воззрения</li>
            <li>о вечности и уничтожении (<em>śāśvata-uccheda-darśana</em>).<a href="#citation-578" id="ref-578" class="citation-mark"><sup>578</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>281. В нирване нет ни <em>скандх</em>, ни «я», ни признаков (<em>lakṣaṇa</em>).</li>
            <li>Благодаря вхождению в «только-ум»</li>
            <li>прекращается цепляние за освобождение (<em>mokṣagrāha</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>282. Изъян, обусловленный принятием видимого за существующее,</li>
            <li>людям представляется внешним.</li>
            <li>Но ум возник из неявленного (<em>adṛśya</em>),</li>
            <li>поэтому сам ум не видится.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>283. Отпечатки людям видятся как тело,</li>
            <li>объекты наслаждения и место пребывания.</li>
            <li>Ум — ни бытие, ни небытие;</li>
            <li>в отпечатках он не являет своей природы.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>284. Пятно видно на белом,</li>
            <li>но белизна не видна в пятне.</li>
            <li>Как небо [скрыто] в облаках,</li>
            <li>так ум [в своей чистоте] не виден.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>285. Умом накапливается карма,</li>
            <li>знанием (<em>jñāna</em>) же она рассеивается.</li>
            <li>Через мудрость (<em>prajñā</em>) достигается</li>
            <li>состояние без образов (<em>nirābhāsa</em>)</li>
            <li>и [истинная] сила (<em>prabhāva</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>286. Ум связан с объектами,</li>
            <li>знание вовлечено в рассуждение (<em>tarka</em>).</li>
            <li>В состоянии без образов и в высшем [постижении]</li>
            <li>разворачивается [истинное] знание.<a href="#citation-579" id="ref-579" class="citation-mark"><sup>579</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>287. Достигнув природы дхарм</li>
            <li>вне измышлений (<em>avikalpa-dharmatā</em>),</li>
            <li>шраваки обрели ум (<em>citta</em>), <em>манас</em> (<em>manas</em>),</li>
            <li>различающее сознание (<em>vijñāna</em>) и распознавание (<em>saṃjñā</em>),</li>
            <li>свободные от измышлений.</li>
            <li>Но они — не сыны Победителя.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>288. В каждом терпении (<em>kṣānti</em>), в каждой высшей ступени терпения</li>
            <li>рождается знание Татхагаты — во благо высшего смысла,</li>
            <li>вне всякого предписанного действия.<a href="#citation-580" id="ref-580" class="citation-mark"><sup>580</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>289. Воображаемая природа существует [как приписывание];</li>
            <li>зависимая не существует [как независимая от ума].</li>
            <li>Воображаемое схватывается в заблуждении;</li>
            <li>зависимое не следует воображать [как независимое].<a href="#citation-581" id="ref-581" class="citation-mark"><sup>581</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>290. Ум возник из невозникшего (<em>abhūta</em>);</li>
            <li>сам ум нигде не воспринимается.</li>
            <li>Тело, объекты наслаждения и опора мира —</li>
            <li>так предстают людям их отпечатки.<a href="#citation-582" id="ref-582" class="citation-mark"><sup>582</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>291. Нет формы, полностью состоящей из элементов (<em>bhautika</em>);</li>
            <li>есть форма, не состоящая из элементов (<em>abhautika</em>).</li>
            <li>Град гандхарвов, сон, иллюзия, мираж —</li>
            <li>всё это формы не из элементов (<em>abhautika</em>).<a href="#citation-583" id="ref-583" class="citation-mark"><sup>583</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>292. У Меня тройственная мудрость,<a href="#citation-584" id="ref-584" class="citation-mark"><sup>584</sup></a></li>
            <li>которой достигается сфера Благородных.</li>
            <li>Но ум возник из невидимого —</li>
            <li>потому сам ум не видим.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>293. Отпечатки видятся людям как тело,</li>
            <li>объекты наслаждения и опора.</li>
            <li>Через них измышляются признаки,</li>
            <li>и те же отпечатки скрывают <em>природы</em>.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>294. Мудрость, лишённая образов,</li>
            <li>несвязанная с обеими колесницами,</li>
            <li>у шраваков разворачивается</li>
            <li>через привязанность к становлению.</li>
            <li>Через вхождение в «только-ум»</li>
            <li>[возникает] незапятнанная мудрость Татхагат.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>295. Если утверждают, что нечто возникает</li>
            <li>из существующего или из несуществующего</li>
            <li>в зависимости от условий,</li>
            <li>то неизбежно возникают воззрения</li>
            <li>о единстве или различии.<a href="#citation-585" id="ref-585" class="citation-mark"><sup>585</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>296. Разнообразные проявления развёртываются,</li>
            <li>но, как иллюзия, не утверждаются [как реальные].</li>
            <li>Так и многообразные, пёстрые признаки,</li>
            <li>измышляемые умом, не устанавливаются.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>297. Связывание, возникающее из ума,</li>
            <li>имеет природу искажённых образов (<em>nimitta-dauṣṭhulya</em>).</li>
            <li>Те, кто не распознают воображаемое</li>
            <li>как воображаемое (<em>parikalpita</em>),</li>
            <li>измышляют зависимое (<em>paratantra</em>).<a href="#citation-586" id="ref-586" class="citation-mark"><sup>586</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>298. То, что принимается за воображаемое,</li>
            <li>и есть именно зависимое.</li>
            <li>Зависимое, проявляющееся в многообразии,</li>
            <li>измышляется как воображаемое.<a href="#citation-587" id="ref-587" class="citation-mark"><sup>587</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>299. Есть условная истина (<em>saṃvṛti</em>) и высшая истина (<em>paramārtha</em>),</li>
            <li>третьего [основания] не существует.<a href="#citation-588" id="ref-588" class="citation-mark"><sup>588</sup></a></li>
            <li>Воображаемое названо условным;</li>
            <li>с его устранением открывается сфера Благородных (<em>āryagocaraḥ</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>300. Подобно тому как один объект</li>
            <li>является йогинам как многообразный,</li>
            <li>хотя в нём нет многообразия, —</li>
            <li>таковы и признаки воображаемого.<a href="#citation-589" id="ref-589" class="citation-mark"><sup>589</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>301. Подобно тому как у страдающих глазной болезнью</li>
            <li>воображается многообразие форм,</li>
            <li>хотя сама болезнь — ни форма, ни не-форма, —</li>
            <li>так мудрые понимают зависимое.<a href="#citation-590" id="ref-590" class="citation-mark"><sup>590</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>302. Подобно чистому золоту,</li>
            <li>воде без мути или небу без облаков —</li>
            <li>так при устранении воображаемого</li>
            <li>[раскрывается <em>совершенная природа</em>].<a href="#citation-591" id="ref-591" class="citation-mark"><sup>591</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>303. Шраваки Мои бывают трёх видов:</li>
            <li>сотворённые [мною], рождённые из обета,</li>
            <li>и шраваки, рождённые из Дхармы —</li>
            <li>свободные от страсти и ненависти.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>304. И бодхисаттва также трёх видов.</li>
            <li>У Будд же нет признаков; но в уме,</li>
            <li>в уме каждого существа (<em>citte citte tu sattvānāṃ</em>)</li>
            <li>видится отражение Будды.<a href="#citation-592" id="ref-592" class="citation-mark"><sup>592</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>305. Истинно, воображённой сущности (<em>kalpito bhāvaḥ</em>) нет,</li>
            <li>но зависимое (<em>paratantra</em>) имеет место.</li>
            <li>Из-за различения —</li>
            <li>приписывания (<em>samāropa</em>) и отрицания (<em>apavāda</em>), —</li>
            <li>различение не угасает.<a href="#citation-593" id="ref-593" class="citation-mark"><sup>593</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>306. Если бы воображаемое было лишь отсутствием (<em>abhāva</em>)</li>
            <li>по отношению к зависимой природе,</li>
            <li>тогда бытие существовало бы независимо от небытия,</li>
            <li>и бытие возникало бы из небытия.<a href="#citation-594" id="ref-594" class="citation-mark"><sup>594</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>307. Опираясь на воображаемое (<em>parikalpita</em>),</li>
            <li>постигается зависимое (<em>paratantra</em>).</li>
            <li>Из связи образа (<em>nimitta</em>) и имени (<em>nāma</em>)</li>
            <li>рождается воображаемое.<a href="#citation-595" id="ref-595" class="citation-mark"><sup>595</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>308. Когда воображаемое полностью прекращает</li>
            <li>порождать видимость «иного», тогда постигается</li>
            <li>чистая <em>совершенная природа</em> (<em>pāramārthika-svabhāva</em>).<a href="#citation-596" id="ref-596" class="citation-mark"><sup>596</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>309. Воображаемое — десяти видов,</li>
            <li>зависимое — шести видов.</li>
            <li>Таковость (<em>tathatā</em>) же — это сфера личного постижения,</li>
            <li>в ней нет определений.<a href="#citation-597" id="ref-597" class="citation-mark"><sup>597</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>310. <em>Пять дхарм</em> составляют истину (<em>tattva</em>),</li>
            <li>и <em>три природы</em> (<em>svabhāva</em>) — также.</li>
            <li>Глубоко постигая их,</li>
            <li>йогин не отступает от Таковости (<em>tathatā</em>).<a href="#citation-598" id="ref-598" class="citation-mark"><sup>598</sup></a></li>
        </ul>
    </blockquote>

</div>

<!— Гатхи 311-370 —>

<div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">

    <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>311. Принимая облик звезд и облаков,</li>
            <li>сияя как луна и солнце,</li>
            <li>является людям их ум</li>
            <li>как видимый мир, возникший из отпечатков.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>312. Эти [формы] не обладают природой элементов;</li>
            <li>в них нет ни обозначаемого (<em>lakṣya</em>), ни признаков (<em>lakṣaṇa</em>).</li>
            <li>Если бы форма была материальной (<em>bhautika</em>),</li>
            <li>то и сами элементы были бы составными.<a href="#citation-599" id="ref-599" class="citation-mark"><sup>599</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>313. Великие элементы не возникли;</li>
            <li>в самих элементах нет ничего «материального».</li>
            <li>Великие элементы — причина,</li>
            <li>а земля, вода и прочее — их следствие.<a href="#citation-600" id="ref-600" class="citation-mark"><sup>600</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>314. «Вещественная» форма —</li>
            <li>лишь условное обозначение (<em>prajñapti</em>);</li>
            <li>таковы и формы, порождённые магией,</li>
            <li>образы сна и град гандхарвов, и, пятое, — мираж.<a href="#citation-601" id="ref-601" class="citation-mark"><sup>601</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>315. Пять видов иччхантиков,</li>
            <li>пять родов (<em>gotra</em>);</li>
            <li>пять колесниц и «не-колесница»;</li>
            <li>шесть видов нирваны.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>316. Двадцать четыре деления <em>скандх</em>,</li>
            <li>восемь видов формы;</li>
            <li>двадцать четыре Будды,</li>
            <li>два вида сынов Победителя.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>317. Сто восемь методов</li>
            <li>и три вида шраваков;</li>
            <li>одно поле у Будд,</li>
            <li>и Будда — воистину един.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>318. Три вида освобождения,</li>
            <li>четыре потока ума;</li>
            <li>шесть видов отсутствия «я»,</li>
            <li>познаваемое — также четырёх видов.<a href="#citation-602" id="ref-602" class="citation-mark"><sup>602</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>319. Не связанная с причинностью,</li>
            <li>свободная от ошибок воззрений,</li>
            <li>постигаемая непосредственно лично, неколебимая —</li>
            <li>такова непревзойдённая Великая Колесница (<em>Mahāyāna</em>).<a href="#citation-603" id="ref-603" class="citation-mark"><sup>603</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>320. Учения о возникновении и невозникновении</li>
            <li>развёртываются восьми- или девятикратно;</li>
            <li>но принцип последовательного наставления — один,</li>
            <li>и окончательный смысл — также один.<a href="#citation-604" id="ref-604" class="citation-mark"><sup>604</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>321. Мир без форм (<em>ārūpya-dhātu</em>) — восьми видов,</li>
            <li>разделение <em>дхьян</em> — шести видов,</li>
            <li>выход [к освобождению] для пратьекабудд</li>
            <li>и сынов Победителя — семи видов.<a href="#citation-605" id="ref-605" class="citation-mark"><sup>605</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>322. Нет трёх времён, нет ни вечного, ни невечного.</li>
            <li>Действие, карма и её плод —</li>
            <li>воистину подобны происходящему во сне.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>323. Будды, шраваки и сыны Победителя</li>
            <li>не имеют ни начала, ни конца.</li>
            <li>Ум же, свободный от видимого,</li>
            <li>всегда подобен магическим дхармам.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>324. Пребывание в чреве, рождение,</li>
            <li>уход из мира и пребывание в Тушита —</li>
            <li>[Будды] проявлены во всех мирах,</li>
            <li>но не рождены из утробы.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>325. Переход, странствие существ,</li>
            <li>проповедь и нирвана,</li>
            <li>истины и постижение земель будд —</li>
            <li>всё это движимо условиями (<em>pratyaya</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>326. Миры, могучие деревья («владыка леса»), острова;</li>
            <li>учение об отсутствии «я» и движение по этим путям,</li>
            <li><em>дхьяны</em>, колесницы, <em>Алая</em> и её достижение, —</li>
            <li>всё это относится к сфере непостижимого плода.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>327. Роды Луны и бесчисленные звёзды,</li>
            <li>царские роды, обители богов,</li>
            <li>роды якшей и гандхарвов —</li>
            <li>всё это порождено кармой</li>
            <li>и возникает из жажды (<em>tṛṣṇā</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>328. Переход (<em>cyuti</em>), непостижимый и</li>
            <li>непрерывно изменяющийся,</li>
            <li>связан с отпечатками.</li>
            <li>Когда этот переход пресекается, сеть клеш угасает.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>329. Богатство, зерно, золото и земли —</li>
            <li>всё это лишь измышляется (<em>vikalpyate</em>).</li>
            <li>Так же — скот, слуги, кони и слоны.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>330. Не следует спать на высоких ложах,</li>
            <li>не следует украшать [жилище].</li>
            <li>Не должно использовать сосуды</li>
            <li>из золота, серебра, бронзы или меди.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>331. Шерстяные накидки — синие и красные,</li>
            <li>а монашеские одеяния — цвета навоза;</li>
            <li>Пусть йогин всегда окрашивает белые одежды</li>
            <li>глиной, плодами и листьями.<a href="#citation-606" id="ref-606" class="citation-mark"><sup>606</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>332. Каменную, глиняную, железную,</li>
            <li>или сделанную из раковины или хрусталя —</li>
            <li>такую чашу [для подаяний] следует носить йогину,</li>
            <li>наполняя её [мерой] Магадхи.<a href="#citation-607" id="ref-607" class="citation-mark"><sup>607</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>333. [Должно иметь] нож в четыре пальца [длиной],</li>
            <li>изогнутый, для обрезания ткани.</li>
            <li>Йогину, преданному йоге,</li>
            <li>не следует обучаться мирским ремеслам (<em>śilpavidyā</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>334. Торговля и обмен не должны совершаться</li>
            <li>йогином, пребывающем в йоге.</li>
            <li>[Уход за] садами и прочее [хозяйство] — дело [мирян].</li>
            <li>Так Я провозглашаю Дхарму.<a href="#citation-608" id="ref-608" class="citation-mark"><sup>608</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>335. Того, чьи чувства обузданы,</li>
            <li>кто знает истинный смысл (<em>arthajña</em>),</li>
            <li>кто сведущ в Сутрах и Винае,</li>
            <li>кто не смешивается с домохозяевами —</li>
            <li>того Я называю йогином.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>336. В пустом доме, на кладбище,</li>
            <li>под сенью дерева или в пещерах,</li>
            <li>на соломе или под открытым небом —</li>
            <li>там йогину следует устраивать свое жилище.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>337. Всегда облачен в три одеяния,</li>
            <li>[пребывая хоть] на кладбище или где придется.</li>
            <li>Одежду следует ему принимать [лишь ту],</li>
            <li>что дается добровольно и с радостью.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>338. Взгляд пусть быть устремлен</li>
            <li>[пред собой] на расстояние ярма;</li>
            <li>и пусть будет умерен в принятии пищи.</li>
            <li>Подобно пчеле, [собирающей нектар] с цветов,</li>
            <li>пусть он собирает подаяние.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>339. [Пребывание] в толпе и общение с толпой,</li>
            <li>а также с монахинями —</li>
            <li>всё это связано с [неправильным] образом жизни;</li>
            <li>это не подобает йогинам.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>340. Царям, царевичам, советникам</li>
            <li>и богатым людям</li>
            <li>йогин не должен проповедовать</li>
            <li>ради получения подаяния.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>341. Пища из домов, где было рождение или смерть,</li>
            <li>и та, что дана из дружеской приязни,</li>
            <li>и та, что готовили вместе монахи с монахинями, —</li>
            <li>не подобает она йогинам.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>342. В обители, где постоянно вьётся дым</li>
            <li>и по сроку варится еда,</li>
            <li>а также то, что приготовлено специально, —</li>
            <li>всё это не подобает принимать йогинам.<a href="#citation-609" id="ref-609" class="citation-mark"><sup>609</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>343. Свободным от возникновения и разрушения,</li>
            <li>вне крайностей «есть» и «нет»,</li>
            <li>предстающим как связка обозначаемого и признака —</li>
            <li>таковым пусть йогин созерцает мир.<a href="#citation-610" id="ref-610" class="citation-mark"><sup>610</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>344. Йогин станет без промедления наделенным</li>
            <li>силой <em>самадхи</em>, <em>сверхзнаниями</em> и <em>властью</em>,</li>
            <li>если только не будет измышлять возникновение.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>345. Не следует измышлять мир как возникший</li>
            <li>из атомов, времени или первоосновы.</li>
            <li>И мир, якобы возникший из причин и условий,</li>
            <li>йогину не следует измышлять.<a href="#citation-611" id="ref-611" class="citation-mark"><sup>611</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>346. Йогину всегда следует воспринимать</li>
            <li>этот пёстрый, яркий мир,</li>
            <li>воображённый собственными измышлениями,</li>
            <li>возникший из отпечатков,</li>
            <li>подобным магии и сну.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>347. Всегда придерживаясь видения,</li>
            <li>свободного от отрицания и наложения,</li>
            <li>не следует измышлять три мира,</li>
            <li>которые предстают как тело, объекты и опора.<a href="#citation-612" id="ref-612" class="citation-mark"><sup>612</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>348. Приняв пищу, пусть йогин установит тело</li>
            <li>прямо и устойчиво, снова и снова выражая</li>
            <li>почтение Буддам и Бодхисаттвам.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>349. Опираясь на Винаю, Сутры и рассуждение,</li>
            <li>сведя [учение] к его сути, знаток йоги</li>
            <li>пусть созерцает <em>пять дхарм</em>,</li>
            <li>собственный ум и отсутствие «я».</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>350. Чистоту собственной природы дхарм,</li>
            <li>ступени и Землю Будды —</li>
            <li>пусть созерцает это йогин; тогда</li>
            <li>он получает посвящение на великом лотосе.<a href="#citation-613" id="ref-613" class="citation-mark"><sup>613</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>351. Пройдя через все состояния существования</li>
            <li>с умом, встревоженным бытием,</li>
            <li>он приступает к чудесной йоге,</li>
            <li>вступая на благой и мирный путь.<a href="#citation-614" id="ref-614" class="citation-mark"><sup>614</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>352. Подобно луне и солнцу,</li>
            <li>подобно сиянию лепестков лотоса,</li>
            <li>йогин зрит совокупности</li>
            <li>как огонь в небе или пёстрый узор.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>353. Эти многообразные образы (<em>nimitta</em>)</li>
            <li>ведут на пути тиртиков;</li>
            <li>они низводят к состоянию шраваков</li>
            <li>или к сфере пратьекабудд.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>354. Когда, развеяв все эти [образы],</li>
            <li>йогин становится свободным от образов,</li>
            <li>тогда руки Будд, сияющие как солнца,</li>
            <li>собравшиеся из всех миров, очищают его голову,</li>
            <li>устраняя последний знак, —</li>
            <li>ибо они пребывают в Таковости.<a href="#citation-615" id="ref-615" class="citation-mark"><sup>615</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>355. Оно есть — вне форм,</li>
            <li>свободное от вечности и уничтожения.</li>
            <li>Те, кто вышли за пределы «есть» и «нет»,</li>
            <li>будут мыслить «срединное».</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>356. В учении о беспричинности</li>
            <li>возникают воззрения о случайности и уничтожении.</li>
            <li>Из-за непонимания внешних объектов</li>
            <li>они разрушают Срединный путь.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>357. Они не освобождаются от цепляния за бытие,</li>
            <li>[полагая:] «пусть не будет воззрения об уничтожении».</li>
            <li>И потому проповедуют Срединное</li>
            <li>через наложение и отрицание.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>358. Через постижение «только-ума»</li>
            <li>внешние объекты лишаются опоры.</li>
            <li>Прекращение различения —</li>
            <li>это и есть реализация Срединного пути.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>359. Они не видят «только-ум»</li>
            <li>и полагают, что при отсутствии объекта</li>
            <li>ничто не возникает.</li>
            <li>Срединный же путь — иной:</li>
            <li>он преподан мною и другими Буддами.<a href="#citation-616" id="ref-616" class="citation-mark"><sup>616</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>360. Возникновение и не-возникновение,</li>
            <li>бытие и небытие,</li>
            <li><em>шуньята</em> и отсутствие собственной природы явлений —</li>
            <li>эту двойственность не следует измышлять.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>361. Увлечённые различающим мышлением,</li>
            <li>глупцы принимают [обычное] бытие за освобождение.</li>
            <li>Но пока не постигнута деятельность ума,</li>
            <li>схватывание двойственности не исчезает.<a href="#citation-617" id="ref-617" class="citation-mark"><sup>617</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>362. Когда осознано, что всё видимое —</li>
            <li>лишь собственный ум,</li>
            <li>захват двойственности исчезает.</li>
            <li>Оставление — это полное постижение того,</li>
            <li>что измышляется, а не его уничтожение.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>363. Через полное постижение того,</li>
            <li>что всё воспринимаемое — это ум,</li>
            <li>различение перестаёт возникать.</li>
            <li>Прекращение различения — и есть Таковость,</li>
            <li>свободная от двойственного ума.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>364. Если видна деятельность, свободная от пороков тиртхиков,</li>
            <li>мудрые признают её достойной принятия:</li>
            <li>она есть прекращение (<em>nivṛtti</em>) [заблуждения],</li>
            <li>возникающее из неуничтожимости (<em>avināśataḥ</em>) [истинной природы].</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>365. Состояние Будды через это постижение</li>
            <li>было проповедано мною и всеми Буддами.</li>
            <li>Ведь если трактовать это иначе,</li>
            <li>учение неизбежно превращается в воззрения иноверцев.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>366. Нерождённые, они кажутся рождёнными;</li>
            <li>непоколебимые, они кажутся уходящими.</li>
            <li>Подобно луне, отражённой в воде,</li>
            <li>они видятся одновременно в миллионах миров.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>367. Став единым и множественным</li>
            <li>они проливаются дождём и пылают огнём.<a href="#citation-618" id="ref-618" class="citation-mark"><sup>618</sup></a></li>
            <li>Проявляясь как формы, созданные умом,</li>
            <li>они возвещают «только-ум».</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>368. В [различных] умах — лишь «только-ум»,</li>
            <li>и даже то, что не обладает</li>
            <li>сознанием, возникло из ума.</li>
            <li>Принимая многообразные облики,</li>
            <li>всё это сводится к «только-уму».<a href="#citation-619" id="ref-619" class="citation-mark"><sup>619</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>369. В обликах пратьекабудд и шраваков,</li>
            <li>и в формах, подобных пратьекабуддам,</li>
            <li>и во множестве иных форм</li>
            <li>они проповедуют «только-ум».</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>370. Для не имеющих формы</li>
            <li>они принимают бесформенный облик,</li>
            <li>а для обитателей ада — адский.</li>
            <li>Они являют существам соответствующий облик</li>
            <li>чтобы те постигли «только-ум».</li>
        </ul>

    </blockquote>

</div>

<!— Гатхи 371-406 —>

<div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">

    <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>371. <em>Самадхи, подобное иллюзии</em> (<em>māyopama</em>),</li>
            <li><em>тело, созданное умом</em> (<em>manomaya</em>),</li>
            <li>десять ступеней и <em>власть</em> (<em>vaśitā</em>)</li>
            <li>обретают совершившие поворот (<em>parāvṛttāḥ</em>) основы.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>372. Искажениями собственных различений</li>
            <li>(<em>svavikalpa-viparyāsa</em>)</li>
            <li>и колебаниями разрастания умопостроений (<em>prapañca</em>)</li>
            <li>невежды связываются распознаванием (<em>saṃjñā</em>)</li>
            <li>в увиденном, услышанном, помысленном и познанном.<a href="#citation-620" id="ref-620" class="citation-mark"><sup>620</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>373. Образ (<em>nimitta</em>) есть зависимое (<em>paratantra</em>),</li>
            <li>а имя (<em>nāma</em>) в нём лишь воображается (<em>kalpita</em>).</li>
            <li>Так воображаемый образ (<em>parikalpita-nimitta</em>)</li>
            <li>возникает из зависимого.<a href="#citation-621" id="ref-621" class="citation-mark"><sup>621</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>374. При рассмотрении умом (<em>buddhi</em>)</li>
            <li>не обнаруживается ни зависимого (<em>paratantra</em>),</li>
            <li>ни воображаемого (<em>kalpita</em>).</li>
            <li>Совершенного нет как чего-либо (<em>bhāva</em>);</li>
            <li>как же оно может быть измышлено?<a href="#citation-622" id="ref-622" class="citation-mark"><sup>622</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>375. <em>Совершенная природа</em> — свободна от «есть» и «нет».</li>
            <li>[Но] если она совершенно свободна от «есть» и «нет»,</li>
            <li>как могут быть две [иные] природы?</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>376. В <em>воображаемой природе</em> устанавливаются две природы.</li>
            <li>Воображаемое видится и как пёстрое многообразие,</li>
            <li>и как совершенно чистая сфера Благородных (<em>āryagocara</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>377. Ведь воображаемое, имеющее пёструю видимость,</li>
            <li>измышляется в зависимом (<em>paratantra</em>).</li>
            <li>Если же это измышляется иначе,</li>
            <li>это приводит к учениям иноверцев.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>378. То, что называют «измышлением»,</li>
            <li>возникает из причин вследствие видения.</li>
            <li>Лишь то, что свободно от двойственности различения,</li>
            <li>и есть <em>совершенная природа</em> (<em>niṣpanna</em>).<a href="#citation-623" id="ref-623" class="citation-mark"><sup>623</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>379. Поле (<em>kṣetra</em>), Будды и их проявления (<em>nirmāṇa</em>),</li>
            <li>единая колесница и три [колесницы] —</li>
            <li>Я не нирвана;</li>
            <li>всё это пусто и лишено возникновения.<a href="#citation-624" id="ref-624" class="citation-mark"><sup>624</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>380. Тридцать шесть видов Будд</li>
            <li>и десять — по отдельности;</li>
            <li>потоки сознания живых существ —</li>
            <li>всё это не земли и не вместилища.<a href="#citation-625" id="ref-625" class="citation-mark"><sup>625</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>381. Как воображаемое</li>
            <li>кажется пёстрым зрелищем,</li>
            <li>хотя пестроты там нет, —</li>
            <li>так же Дхарма Будды и мир.<a href="#citation-626" id="ref-626" class="citation-mark"><sup>626</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>382. Будда Дхармы (<em>Dharmabuddha</em>) и есть Будда;</li>
            <li>остальные — лишь его сотворённые формы (<em>nirmita</em>).</li>
            <li>Существа видят поток собственных семян (<em>svabīja-saṃtāna</em>)</li>
            <li>через видения Будды.<a href="#citation-627" id="ref-627" class="citation-mark"><sup>627</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>383. Вследствие связи с ложными образами (<em>bhrānti-nimitta</em>)</li>
            <li>возникает различение (<em>vikalpa</em>).</li>
            <li>Таковость (<em>tathatā</em>) не отлична от различения;</li>
            <li>само же измышление не имеет образов.<a href="#citation-628" id="ref-628" class="citation-mark"><sup>628</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>384. Естественный, Блаженства,</li>
            <li>Явленный и пять Проявленных и</li>
            <li>весь сонм тридцати шести Будд</li>
            <li>есть Естественный Будда.<a href="#citation-629" id="ref-629" class="citation-mark"><sup>629</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>385. Подобно тому как синева, краснота, солёность,</li>
            <li>белизна раковины, белизна молока, сладость сахара,</li>
            <li>ароматы плодов и цветов, лучи солнца —</li>
            <li>неотделимы от своей основы,</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>386. и как волны океана не считаются</li>
            <li>ни отличными от него, ни тождественными ему,</li>
            <li>так и семь сознаний соединены с Умом.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>387. Изменчивость (<em>pariṇāma</em>) океана</li>
            <li>проявляет многообразие волн;</li>
            <li>точно так же и <em>Алайя</em></li>
            <li>разворачивается в многообразии того,</li>
            <li>что зовётся «сознаниями».</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>388. Ум (<em>citta</em>), <em>манас</em> (<em>manas</em>)</li>
            <li>и сознание (<em>vijñāna</em>)</li>
            <li>различаются лишь ради указания признаков.</li>
            <li>Восемь [сознаний] неразделимы по признакам:</li>
            <li>нет ни определяемого (<em>lakṣya</em>), ни признака (<em>lakṣaṇa</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>389. Как между океаном и волнами</li>
            <li>нет качественного различия,</li>
            <li>так в Уме не найти</li>
            <li>реального видоизменения (<em>pariṇāma</em>)</li>
            <li>в виде [отдельных] сознаний.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>390. Умом (<em>citta</em>) накапливается карма,</li>
            <li><em>манасом</em> — различается,</li>
            <li>[умственной] виджняной познаётся [объект],</li>
            <li>а пятью [чувственными сознаниями]</li>
            <li>выстраивается воспринимаемое.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>[Махамати спросил:]</li>
            <li>391. — Ум людям видится в цветах —</li>
            <li>то синим, то красным.</li>
            <li>О Великий Мудрец! Почему же Ты говоришь</li>
            <li>о сходстве между волнами и умом?</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>[Благословенный ответил:]</li>
            <li>392. — Воистину, в самих волнах</li>
            <li>нет синевы или красноты!</li>
            <li>Деятельность же ума описывается [через них]</li>
            <li>лишь ради [пояснения] признаков для неразумных.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>393. Сам же ум (<em>svacitta</em>, <em>Алайя</em>) — без деятельности (<em>vṛtti</em>),</li>
            <li>ибо он свободен от схватываемого (<em>grāhya</em>).</li>
            <li>Если бы было схватываемое,</li>
            <li>тогда возникло бы и схватывающее (<em>grāha</em>) —</li>
            <li>подобно волнам [и океану].</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>394. Виджняна проявляется людям</li>
            <li>как «тело», «объекты восприятия» и «мир-вместилище».</li>
            <li>Поэтому его деятельность видится</li>
            <li>подобной волнам [океана].</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>[Махамати спросил:]</li>
            <li>395. — Океан видится танцующим в облике волн.</li>
            <li>Почему же подобная динамика (<em>vṛtti</em>) <em>Алайи</em></li>
            <li>не постигается разумом (<em>buddhi</em>)?</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>[Благословенный ответил:]</li>
            <li>396. — У невежд (<em>bāla</em>) разум слаб.</li>
            <li>Потому сходство <em>Алайи</em> с океаном</li>
            <li>и её динамики с волнами</li>
            <li>разъясняется им через это сравнение.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>[Махамати продолжил:]</li>
            <li>397. — Как солнце восходит над миром,</li>
            <li>светя одинаково низшим и высшим,</li>
            <li>так и Ты, Светоч мира,</li>
            <li>излагаешь истину (<em>tattva</em>) невеждам.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>398. Но утвердив их в дхармах,</li>
            <li>почему не излагаешь истину?</li>
            <li>Ведь если Ты говоришь истину,</li>
            <li>то истина в уме не обнаруживается.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>[Благословенный ответил:]</li>
            <li>399. — Как волны в океане, отражения в зеркале,</li>
            <li>образы во сне видятся одновременно (<em>yugapad</em>),</li>
            <li>так и ум в своей собственной сфере (<em>svagocara</em>)</li>
            <li>проявляется в одно и то же время.</li>
            <li>Но из-за неполноты (отсутствия) объектов [восприятия]</li>
            <li>он разворачивается последовательно.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>400. Виджняна распознаёт, <em>манас</em> мыслит,</li>
            <li>пяти [сознаниям] является воспринимаемое;</li>
            <li>но в сосредоточении (<em>samāhita</em>) нет последовательности.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>401. Как опытный живописец или его ученик</li>
            <li>наносит те или иные краски ради создания картины —</li>
            <li>так и Я излагаю Учение.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>402. [Суть] самой картины не обнаруживается</li>
            <li>ни в красках, ни в холсте, ни в сосуде [с красками];</li>
            <li>но ради привлечения существ</li>
            <li>картина изображается при помощи тех или иных красок.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>403. Проповедь не отклоняется от сути,</li>
            <li>истина (<em>tattva</em>) же — воистину вне знаков.</li>
            <li>Утвердив [учеников] в дхарме,</li>
            <li>Я указываю йогинам истину (<em>tattva</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>404. Истина (<em>tattva</em>) — сфера личного постижения</li>
            <li>(<em>pratyātmagatikam</em>),</li>
            <li>она свободна от измышляемого (<em>kalpya</em>) и измышления (<em>kalpana</em>).</li>
            <li>Её Я излагаю сынам Победителя;</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>405. Подобно тому как многообразная иллюзия (<em>māyā</em>) видима,</li>
            <li>но не обнаруживается,</li>
            <li>так и проповедь [Будды] видится многообразной,</li>
            <li>хотя [в своей сути] не отклоняется [от Таковости].</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>406. Ведь то, что является наставлением для одного,</li>
            <li>не является наставлением для другого.</li>
            <li>Как врач назначает лекарство</li>
            <li>каждому больному сообразно его недугу,</li>
            <li>так и Будды провозглашают существам: «только-ум».</li>
        </ul>

    </blockquote>

</div>

<!— Гатхи 407-471 —>

<div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">

    <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>407. Из семени внешних отпечатков возникает различение (<em>vikalpa</em>).</li>
            <li>То, посредством чего происходит схватывание — зависимое (<em>tantra</em>);</li>
            <li>то, что схватывается — воображаемое (<em>kalpita</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>408. Схватываемое как внешняя опора</li>
            <li>возникает, опираясь на сознание;</li>
            <li>заблуждение разворачивается двояко —</li>
            <li>третьей причины нет.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>409. То, из чего возникает заблуждение,</li>
            <li>и то, на чём оно основано —</li>
            <li>будь то шесть, двенадцать или восемнадцать, —</li>
            <li>я утверждаю: всё это только ум.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>410. Через [постижение] связи</li>
            <li>между собственными семенами и схватываемым объектом</li>
            <li>прекращается цепляние за «я».</li>
            <li>Посредством распознавания умственного измышления</li>
            <li>прекращается цепляние за дхармы.<a href="#citation-630" id="ref-630" class="citation-mark"><sup>630</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>411. То, что [называют] сознанием-сокровищницей (<em>ālaya-vijñāna</em>),</li>
            <li>разворачивается как различающие сознания.</li>
            <li>Внутренние основы восприятия (<em>āyatana</em>)</li>
            <li>становятся «внешними» вследствие кажимости двойственности.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>412. Подобно тому как неразумные схватывают</li>
            <li>«волоски» перед глазами или образы во сне, —</li>
            <li>так воображаются обусловленное и необусловленное</li>
            <li>как постоянные, хотя их не существует.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>413. Как город гандхарвов,</li>
            <li>майя или вода в мираже —</li>
            <li>не существуют, но видятся,</li>
            <li>такова и <em>зависимая природа</em> (<em>paratantra</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>414. Через условное обозначение «я»</li>
            <li>и способностей восприятия (<em>indriya</em>)</li>
            <li>Я указываю на три ума (<em>tricitta</em>) —</li>
            <li>ум (<em>citta</em>), <em>манас</em> (<em>manas</em>) и <em>сознание</em> (<em>vijñāna</em>), —</li>
            <li>свободные от собственных признаков.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>415. Ум (<em>citta</em>), <em>манас</em> (<em>manas</em>) и сознание (<em>vijñāna</em>),</li>
            <li>двойное отсутствие «я»,</li>
            <li><em>пять дхарм</em> и <em>три природы</em> —</li>
            <li>такова сфера опыта Будд.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>416. По признакам они троичны,</li>
            <li>но основание их одно — обусловленное отпечатками (<em>vāsana</em>).</li>
            <li>Как краска едина, но на стене видится пёстрой картиной.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>417. Отсутствие «я», недвойственность,</li>
            <li>ум, <em>манас</em> и сознание,</li>
            <li><em>пять дхарм</em> и <em>три природы</em> —</li>
            <li>в Моём роде они отсутствуют.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>418. Свободный от признаков ума,</li>
            <li>свободный от <em>манаса</em> и сознания,</li>
            <li>пребывающий вне дхарм и их природ —</li>
            <li>входит в род Татхагаты.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>419. Ни телом, ни речью, ни мыслью</li>
            <li>не совершает благих действий преднамеренно;</li>
            <li>чист род Татхагаты,</li>
            <li>свободен от кармических проявлений.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>420. Очищен <em>властью</em> (<em>vaśita</em>) и <em>высшим знанием</em> (<em>abhijñā</em>),</li>
            <li><em>силами</em> (<em>bala</em>) и <em>самадхи</em> украшен,</li>
            <li>с <em>телом, созданным из ума</em> (<em>manomaya-kāya</em>), —</li>
            <li>таков чистый род Татхагаты.<a href="#citation-631" id="ref-631" class="citation-mark"><sup>631</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>421. Безупречное, постигаемое лично (<em>pratyātma-vedyaṃ</em>),</li>
            <li>свободное от причин (<em>hetu</em>) и признаков (<em>lakṣaṇa</em>) —</li>
            <li>восьмая будда-ступень (<em>aṣṭamī buddha-bhūmi</em>)</li>
            <li>и есть род Татхагаты (<em>gotraṃ tāthāgataṃ</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>422. [Ступени] «Далеко идущая» (<em>dūraṃgamā</em>),</li>
            <li>«Благая мудрость» (<em>sādhumatī</em>), «Облако Дхармы» (<em>dharmameghā</em>)</li>
            <li>и ступень Татхагаты — таков род Будд;</li>
            <li>всё прочее ведет лишь к двум колесницам.<a href="#citation-632" id="ref-632" class="citation-mark"><sup>632</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>423. Сообразно различиям в потоках существ</li>
            <li>и ради разъяснения признаков незрелым</li>
            <li>Будды, обретшие власть над умом,</li>
            <li>преподают семь ступеней.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>424. На седьмой ступени более не проявляется</li>
            <li>косность (<em>dauṣṭhulya</em>) речи, тела и ума;</li>
            <li>на восьмой же преображается сама основа (<em>āśrayaḥ</em>),</li>
            <li>подобно пробуждению ото сна или [спасению] от наводнения.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>425. На восьмой и на пятой ступенях</li>
            <li>сыновья Победителей постигают</li>
            <li>искусства, науки и ремесла,</li>
            <li>и принимают царское достоинство</li>
            <li>в обителях бытия ради блага других.<a href="#citation-633" id="ref-633" class="citation-mark"><sup>633</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>426. Ни возникновение, ни не-возникновение;</li>
            <li>ни <em>шуньяту</em>, ни не-<em>шуньяту</em> не следует измышлять.</li>
            <li>Ни собственной природы, ни отсутствия собственной природы</li>
            <li>не обнаруживается в «только-уме».</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>427. Тот, кто измышляет:</li>
            <li>«Это — истинно, это — истинно, а то — ложно», —</li>
            <li>это изложение для шраваков и пратьекабудд,</li>
            <li>но это не [учение] для сыновей Победителя.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>428. Ни существования, ни не-существования,</li>
            <li>ни мгновенности, ни признаков,</li>
            <li>ни обозначения (<em>prajñapti</em>), ни вещественности (<em>dravya</em>)</li>
            <li>не обнаруживается в «только-уме».</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>429. Явления допускаются существующими</li>
            <li>в рамках относительной истины (<em>saṃvṛtyā</em>),</li>
            <li>но в высшем смысле — никаких явлений нет.</li>
            <li>Заблуждение относительно того,</li>
            <li>что лишено собственной природы, —</li>
            <li>это и есть относительная истина.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>430. Хотя [в истинном смысле] все дхармы не существуют,</li>
            <li>Мною устанавливаются их обозначения.</li>
            <li>Но эти наименования и мирские условности —</li>
            <li>для незрелых; они лишены реальности.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>431. Ведь то, что возникает из наименования,</li>
            <li>кажется существующим в сфере опыта (<em>artha-gocara</em>).</li>
            <li>Но, увидев это, понимают,</li>
            <li>что возникшее из наименования не существует.<a href="#citation-634" id="ref-634" class="citation-mark"><sup>634</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>432. Как при отсутствии основы не возникает картина,</li>
            <li>и тень — при отсутствии столба,</li>
            <li>так и чистая <em>Алайя</em> не разворачивается в волны.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>433. Ум (<em>citta</em>) пребывает подобно актёру,</li>
            <li><em>манас</em> (<em>manas</em>) — подобен шуту;</li>
            <li>вместе с пятью [чувственными] сознаниями</li>
            <li>они разыгрывают воспринимаемое, подобное сцене (<em>raṅga</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>434. Излияние Дхармы проповеди (<em>deśanā-dharma-niṣyanda</em>)</li>
            <li>и то, что из этого излияния проявлено (<em>niṣyanda-nirmita</em>), —</li>
            <li>это и есть изначальные Будды (<em>paurāḥ</em>);</li>
            <li>прочие — лишь явленные формы (<em>nirmāṇa-vigraha</em>).<a href="#citation-635" id="ref-635" class="citation-mark"><sup>635</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>435. Воспринимаемого не обнаруживается;</li>
            <li>ум же вводится в заблуждение воспринимаемым.</li>
            <li>То, что предстаёт существам</li>
            <li>как тело, [объекты] наслаждения и обитель,</li>
            <li>именуется <em>Алайя</em>.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>436. Ум (<em>citta</em>), <em>манас</em> (<em>manas</em>) и сознание (<em>vijñāna</em>),</li>
            <li><em>три природы</em>, <em>пять дхарм</em> и двойное отсутствие «я» —</li>
            <li>вот что провозглашают Владыки как чистое [учение].</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>437. То, что Владыки излагают как сферу личного постижения,</li>
            <li>не является областью для рассудочных логиков</li>
            <li>и не доступно шравакам.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>438. Подобно [понятиям] «длинное» и «короткое»,</li>
            <li>всё возникает лишь во взаимной зависимости.</li>
            <li>Нет доказательства бытия самого по себе;</li>
            <li>бытие устанавливается лишь в противоположности небытия.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>439. Если разлагать форму до мельчайших частиц,</li>
            <li>то в конце концов нельзя будет вообразить никакую форму.</li>
            <li>Учение о «только-уме» не принимается теми,</li>
            <li>кто придерживается ложных воззрений.<a href="#citation-636" id="ref-636" class="citation-mark"><sup>636</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>440. Не измышляй «шуньяту» (<em>śūnyatā</em>),</li>
            <li>и «не-шуньяту» также не измышляй.</li>
            <li>«Есть» и «нет» — лишь умопостроения;</li>
            <li>воображаемого нет.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>441. Невежды воображают форму</li>
            <li>как совокупность качеств (<em>guṇa</em>), атомов (<em>aṇu</em>)</li>
            <li>и того, что принимают за вещь (<em>dravya</em>).</li>
            <li>Но ни один атом по отдельности не существует,</li>
            <li>следовательно, и [ничего целостного] не обнаруживается.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>442. Собственный ум, принявший облик видимого,</li>
            <li>предстает людям как нечто внешнее.</li>
            <li>Внешнего видимого нет;</li>
            <li>потому [ничего внешнего] не обнаруживается.<a href="#citation-637" id="ref-637" class="citation-mark"><sup>637</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>443. Подобно волоскам в глазу, иллюзии, сну,</li>
            <li>городу гандхарвов, огненному колесу и миражу</li>
            <li>является ум людям, хотя и не существует.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>444. Вечное и невечное, единство и множественность,</li>
            <li>и то, и другое, и ни то, ни другое —</li>
            <li>всё это невежды, опутанные безначальными пороками,</li>
            <li>воображают в своём ослеплении.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>445. Установления колесниц вовсе не существует —</li>
            <li>Единую колесницу Я провозглашаю.</li>
            <li>Лишь ради привлечения невежд</li>
            <li>Я говорю о различии колесниц.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>446. Также существуют три вида освобождения</li>
            <li>и отсутствие «я» дхарм.</li>
            <li>Однако [шраваки] лишены того освобождения,</li>
            <li>которое именуется мудростью равенства и свободой от клеш.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>447. Подобно тому, как бревно в океане уносится волнами,</li>
            <li>так и глупый шравака увлекается признаками.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>448. Они не достигают окончательного предела,</li>
            <li>но и не возвращаются вновь.</li>
            <li>Достигнув <em>тела самадхи</em>,</li>
            <li>они не пробуждаются вплоть до [конца] кальпы.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>449. Связанные привычными тенденциями и <em>клешами</em>,</li>
            <li>но свободные от активных проявлений [<em>клеш</em>],</li>
            <li>опьянённые <em>самадхи</em>,</li>
            <li>они пребывают в <em>сфере без притока</em> (<em>dhātau tiṣṭhanty-anāsrave</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>450. Подобно тому, как пьяный человек трезвеет,</li>
            <li>когда проходит действие хмеля,</li>
            <li>так и они обретут моё Тело,</li>
            <li>именуемое Буддадхармой (<em>buddhadharma</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>451. Подобно тому, как слон, увязший в трясине,</li>
            <li>не может двинуться вперёд,</li>
            <li>так и шраваки, воистину, пребывают неподвижно,</li>
            <li>увязнув в хмеле <em>самадхи</em> (<em>samādhimadamagnāḥ</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>452. Поддержка (<em>adhiṣṭhāna</em>) Владык Людей, очищенная их обетами,</li>
            <li>проявляется в посвящении (<em>abhiṣeka</em>), <em>самадхи</em> и прочем —</li>
            <li>от первой и до десятой ступени.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>453. О пространстве, о рогах зайца</li>
            <li>и о сыне бесплодной женщины говорят, хотя их нет;</li>
            <li>точно так же воображают явления.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>454. Мир, обусловленный (<em>hetu</em>) отпечатками (<em>vāsana</em>),</li>
            <li>не является ни несуществующим,</li>
            <li>ни существующим-и-несуществующим где бы то ни было.</li>
            <li>Те, кто видит его таким образом, освобождаются,</li>
            <li>будучи знатоками отсутствия «я» дхарм (<em>dharma-nairātmya</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>455. Воображённое как собственная природа (<em>svabhāva-kalpita</em>) — лишь имя;</li>
            <li>зависимое (<em>paratantra</em>) возникает из основы (<em>tantra</em>);</li>
            <li>совершенно установленное (<em>niṣpanna</em>) именуется Таковостью (<em>tathatā</em>) —</li>
            <li>так Я неизменно провозглашаю в каждой сутре.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>456. В буквах, в совокупности слов и особенно в именах</li>
            <li>вязнут скудоумные невежды —</li>
            <li>подобно тому как великие слоны увязают в трясине.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>457. Я провозглашаю колесницу богов, колесницу Брахмы,</li>
            <li>колесницу шраваков, колесницу пратьекабудд</li>
            <li>и колесницу Татхагаты.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>458. У колесниц воистину нет предела, пока действует ум.</li>
            <li>Когда же в уме происходит поворот основы (<em>parāvṛtti</em>),</li>
            <li>нет ни колесницы, ни того, кто по ней движется.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>459. Ум (<em>citta</em>), различение (<em>vikalpa</em>), представление (<em>vijñapti</em>),</li>
            <li><em>манас</em> (<em>manas</em>) и сознание (<em>vijñāna</em>),</li>
            <li><em>Алая</em>, три мира и [его] деятельность —</li>
            <li>всё это обозначения (<em>paryayāḥ</em>) одного и того же ума.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>460. Продолжительность жизни, тепло, сознание, <em>Алая</em>,</li>
            <li>жизненная способность, <em>манас</em> и <em>мано-виджняна</em> —</li>
            <li>всё это различные определения различения (<em>vikalpa</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>461. Умом (<em>citta</em>) удерживается тело;</li>
            <li><em>манас</em> (<em>manas</em>) всегда (<em>sadā</em>) мыслит;</li>
            <li>сознание (<em>vijñāna</em>) рассекает область ума на объекты</li>
            <li>вместе с другими видами сознания.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>462. Жажда (<em>tṛṣṇā</em>) названа матерью,</li>
            <li>а неведение (<em>avidyā</em>) — отцом.</li>
            <li>Сознание (<em>vijñāna</em>), постигающее объекты,</li>
            <li>именуется в учении «Буддой».</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>463. Архаты — это спящие склонности (<em>anuśayāḥ</em>),</li>
            <li>а Сангха — это пучок <em>скандх</em>.</li>
            <li>Через разрыв их непрерывности</li>
            <li>карма становится немедленной.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>464. Благодаря [познанию] двух видов отсутствия «я»,</li>
            <li>[отбрасыванию] омрачений, двух видов завес,</li>
            <li>и благодаря обретению выхода (<em>cyuti</em>)</li>
            <li>из непостижимого превращения — является Татхагата.<a href="#citation-638" id="ref-638" class="citation-mark"><sup>638</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>465. Те, кто знают различие между высшей истиной (<em>siddhānta</em>),</li>
            <li>методом (<em>naya</em>) и учением личного постижения (<em>pratyātmaśāsana</em>),</li>
            <li>не попадают под власть рассуждений (<em>tarka</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>466. Бытие не существует так, как его воображают невежды.</li>
            <li>Почему же логики не желают освобождения через небытие?</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>467. Те, кто зрят сотворённое (<em>saṃskṛta</em>)</li>
            <li>как связанное с возникновением и распадом,</li>
            <li>лишь питают две крайние [двойственности],</li>
            <li>не видя истины из-за своего извращённого [восприятия].</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>468. Есть лишь одна Истина — Нирвана,</li>
            <li>свободная от <em>манаса</em> (<em>manavarjitam</em>).</li>
            <li>Следует зреть воображённый мир подобным магии</li>
            <li>и стволу бананового дерева (<em>kadalīskandha</em>) — пустому внутри.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>469. Нет ни страсти, ни гнева, ни неведения, ни личности.</li>
            <li><em>Скандхи</em>, возникшие из жажды,</li>
            <li>существуют, но подобно сновидениям.<a href="#citation-639" id="ref-639" class="citation-mark"><sup>639</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>470. В промежутке между ночью постижения</li>
            <li>и ночью ухода в паринирвану</li>
            <li>Мною не было провозглашено ни единого слова.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>471. Исходя из установленности</li>
            <li>личной природы реальности, Я изрёк это.</li>
            <li>Между теми Буддами и Мною</li>
            <li>нет ни малейшего различия.<a href="#citation-640" id="ref-640" class="citation-mark"><sup>640</sup></a></li>
        </ul>

    </blockquote>

</div>

<!— Гатхи 472-540 —>

<div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">

    <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>472. [Невеждам кажется, что] «я» (<em>atman</em>) существует как вещь (<em>dravya</em>),</li>
            <li>а <em>скандхи</em> лишены [собственных] признаков.</li>
            <li>[Но] <em>скандхи</em> наличествуют как явленность (<em>bhāvena</em>),</li>
            <li>и «я» (<em>atman</em>) в них не обнаруживается.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>473. Взращивая понимание (<em>pratipatti</em>) [истины]</li>
            <li>среди <em>клеш</em> и людской суеты,</li>
            <li>освобождается от всех страданий тот,</li>
            <li>кто видит мир (<em>jagat</em>) как собственный ум (<em>svacittaṃ</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>474. Те, для кого мир развёртывается через</li>
            <li>причины (<em>kāraṇa</em>) и условия (<em>pratyaya</em>),</li>
            <li>и кто связан четырьмя крайностями (<em>catuṣkoṭika</em>), —</li>
            <li>те не сведущи в Моём методе (<em>mannaya</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>475. Мир не рождается ни как несуществующий,</li>
            <li>ни как существующий,</li>
            <li>ни как одновременно существующий и несуществующий,</li>
            <li>[ни как ни существующий и ни несуществующий].</li>
            <li>Как же невежды измышляют его через причины и условия?</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>476. Когда мир зрят ни как существующий,</li>
            <li>ни как несуществующий,</li>
            <li>ни как существующий-и-несуществующий [одновременно],</li>
            <li>тогда ум поворачивается вспять (<em>vyāvartate cittam</em>)</li>
            <li>и постигается отсутствие «я» (<em>nairātmya</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>477. Все явления не рождены (<em>anutpanna</em>),</li>
            <li>поскольку возникают лишь в силу условий.</li>
            <li>Ибо все условия сами являются следствием иных причин,</li>
            <li>но из следствия бытие (<em>bhava</em>) не рождается.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>478. Одно следствие не рождает другое следствие —</li>
            <li>иначе возникла бы двойственность в следствии.</li>
            <li>Но даже при допущении этой двойственности</li>
            <li>отсутствие следствия не обнаруживается.<a href="#citation-641" id="ref-641" class="citation-mark"><sup>641</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>479. Когда созерцается обусловленное (<em>saṃskṛta</em>) как свободное</li>
            <li>от опоры (<em>ālamba</em>, объекта) и опирающегося (<em>ālambya</em>, субъекта),</li>
            <li>то любой образ (<em>nimitta</em>) — это лишь «только-ум».</li>
            <li>Такой «только-ум» Я и провозглашаю.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>480. Только (<em>mātra</em>) — это пребывание</li>
            <li>в собственной природе (<em>svabhāva-saṃsthāna</em>),</li>
            <li>свободной от внешних условий и бытия.</li>
            <li>Это — конечное состояние, наивысшее;</li>
            <li>это Я называю «только» (<em>mātra</em>).<a href="#citation-642" id="ref-642" class="citation-mark"><sup>642</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>481. «Я» (<em>ātman</em>) существует лишь как условное обозначение (<em>prajñapti</em>),</li>
            <li>но не как нечто реально существующее (<em>dravya</em>).</li>
            <li>Подобно этому и <em>скандхи</em> суть «скандхи»</li>
            <li>лишь по наименованию, но не по своей сути (<em>dravya</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>482. Существует четыре вида равенства (<em>samatā</em>):</li>
            <li>равенство признаков (<em>lakṣaṇa</em>), равенство причин (<em>hetu</em>),</li>
            <li>равенство основ-вместилищ (<em>bhājana</em>) [миров]</li>
            <li>и четвёртое — равенство в отсутствии «я» — для практикующих йогу.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>483. Отбрасывание всех воззрений,</li>
            <li>свобода от воображаемого и воображающего,</li>
            <li>не-обнаружение [объектов] и не-возникновение —</li>
            <li>это Я называю «только-ум».</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>484. Ни бытие, ни небытие, свободное от бытия и небытия,</li>
            <li>Таковость, свободная [даже] от [идеи] ума, —</li>
            <li>это Я называю «только-ум».</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>485. Таковость (<em>tathatā</em>), <em>шуньята</em> (<em>śūnyatā</em>),</li>
            <li><em>Предел истинности</em> (<em>koṭi</em>), нирвана, <em>дхармадхату</em>,</li>
            <li><em>тело, созданное умом</em> (<em>manomaya-kāya</em>), и само сознание —</li>
            <li>всё это Я называю «только-ум».</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>486. Связанный отпечатками различений (<em>vikalpavāsanā</em>),</li>
            <li>многообразие, возникающее из ума,</li>
            <li>являющийся людям как внешнее —</li>
            <li>таков мирской «только-ум».</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>487. Внешних видимых объектов не существует —</li>
            <li>видится лишь пёстрота ума.</li>
            <li>Тело, объекты наслаждения и опора-обитель —</li>
            <li>всё это Я называю «только-ум».<a href="#citation-643" id="ref-643" class="citation-mark"><sup>643</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>488. У шраваков — знание уничтожения [<em>клеш</em>],</li>
            <li>у Будд — знание, возникающее из их рождения [в мире],</li>
            <li>у пратьекабудд и сыновей Победителей —</li>
            <li>оно проистекает из неосквернённости (<em>asaṃkleśā</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>489. Воистину, вовне нет формы —</li>
            <li>собственный ум видится как внешнее.</li>
            <li>Из-за непонимания собственного ума</li>
            <li>неразумные измышляют обусловленное (<em>saṃskṛta</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>490. Не зная, что внешнего объекта нет,</li>
            <li>видя пёстроту собственного ума,</li>
            <li>невежи, связанные четырьмя крайностями,</li>
            <li>пытаются обосновать [мир] причинами.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>491. Нет ни причин, ни логических пределов (<em>koṭi</em>),</li>
            <li>ни примеров (<em>dṛṣṭānta</em>), ни членов [силлогизма].</li>
            <li>Мудрецы знают: это лишь собственный ум (<em>svacittaṃ</em>),</li>
            <li>являющийся как объект (<em>arthasaṃkrānta</em>).<a href="#citation-644" id="ref-644" class="citation-mark"><sup>644</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>492. Не следует различением различать (<em>vikalpa</em>)</li>
            <li>то, признак чего — само различение.</li>
            <li>Ведь различение (<em>vikalpa</em>) разворачивается,</li>
            <li>лишь опираясь на воображаемое (<em>kalpita</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>493. Из-за их нераздельной взаимосвязанности друг с другом</li>
            <li>и единой причины — отпечатков (<em>vāsanā</em>),</li>
            <li>эта двойственность [<em>grāhya</em>/<em>grāhaka</em>] является привнесённой (<em>āgantuka</em>),<a href="#citation-645" id="ref-645" class="citation-mark"><sup>645</sup></a></li>
            <li>поэтому ум (<em>citta</em>) у людей не рождается [сам по себе].</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>494. Различение (<em>vikalpa</em>), направленное на ум (<em>citta</em>),</li>
            <li>ментальные факторы (<em>caitta</em>) и объекты (<em>artha</em>),</li>
            <li>утверждается в трёх мирах.</li>
            <li>То, что проявляется как подобие объектов (<em>arthābhāḥ</em>),</li>
            <li>и есть <em>воображаемая природа</em> (<em>svabhāva-kalpito</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>495. Из соединения семян (<em>bīja</em>) и их проявлений (<em>ābhāsa</em>)</li>
            <li>разворачиваются двенадцать опор восприятия (<em>āyatana</em>).</li>
            <li>Это взаимодействие между основой (<em>āśraya</em>)</li>
            <li>и воспринимаемым (<em>ālambya</em>) и есть</li>
            <li>тот процесс (<em>prakriyā</em>), который Я описываю.<a href="#citation-646" id="ref-646" class="citation-mark"><sup>646</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>496. Подобно отражению в зеркале</li>
            <li>или волоскам при болезни глаз —</li>
            <li>так неразумные видят ум,</li>
            <li>покрытый отпечатками (<em>vāsanā</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>497. Различение (<em>vikalpa</em>) разворачивается</li>
            <li>опираясь на объект (<em>artha</em>), им же воображённый.</li>
            <li>Внешнего объекта не существует</li>
            <li>так, как его измышляют тиртики.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>498. Подобно тому как неразумные,</li>
            <li>не распознав верёвку, принимают её за змею,</li>
            <li>так и [люди], не зная, что объект —</li>
            <li>это собственный ум, воображают его внешним.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>499. Веревка в своей «верёвочности»</li>
            <li>свободна от тождества и отличия.</li>
            <li>Это лишь изъян собственного ума,</li>
            <li>вследствие которого верёвка измышляется иным.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>500. Если нечто, воображаемое в том или ином виде,</li>
            <li>не обнаруживается [таким],</li>
            <li>не следует считать, что его вовсе нет.</li>
            <li>Такова истинная природа (<em>dharmatā</em>) всех явлений (<em>dharma</em>).<a href="#citation-647" id="ref-647" class="citation-mark"><sup>647</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>501. «Нет» предваряется «есть»,</li>
            <li>«есть» предваряется «нет».</li>
            <li>Поэтому не следует приходить к «нет»</li>
            <li>и не следует измышлять «есть».</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>502. [Махамати:] — Воистину, то, что воображается (<em>kalpita</em>)</li>
            <li>и сам процесс воображения (<em>kalpyamāna</em>),</li>
            <li>не обладают той природой [которую им приписывают].</li>
            <li>Как же может различение (<em>vikalpa</em>)</li>
            <li>продолжать разворачиваться,</li>
            <li>когда [человек] увидел их отсутствие «я» (<em>anātmaka</em>)?</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>503. Форма (<em>rūpa</em>) не существует как сущность формы (<em>rūpātman</em>);</li>
            <li>так же и кувшин, одежда и прочее.</li>
            <li>Хотя видимое (<em>dṛśya</em>) не обнаруживается,</li>
            <li>именно из-за этого и возникает различение (<em>vikalpa</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>504. Если различение (<em>vikalpa</em>) пребывает</li>
            <li>в этом безначальном заблуждении (<em>bhrānti</em>),</li>
            <li>посредством чего возникла</li>
            <li>сущностность явлений (<em>bhāvānāṃ bhāvatā</em>)?</li>
            <li>Скажи мне, о Муни!</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>505. [Будда:] — У явлений (<em>bhāva</em>) нет сущностности (<em>bhāvatā</em>) —</li>
            <li>видится лишь «только-ум» (<em>cittamātra</em>).</li>
            <li>Но не видя своего собственного ума (<em>svacitta</em>),</li>
            <li>[человек] разворачивает различения (<em>vikalpa</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>506. Если воображаемое (<em>kalpita</em>) не существует так,</li>
            <li>как его воображает глупец (<em>bāliśa</em>),</li>
            <li>то, даже если оно и существует иначе (<em>anyathā</em>),</li>
            <li>оно не постигается разумом (<em>buddhi</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>507. Если оно существует для Благородных (<em>ārya</em>),</li>
            <li>то оно не таково, как его измыслили неразумные (<em>bāla</em>).</li>
            <li>А если оно ложно и для Благородных,</li>
            <li>тогда Благородные ничем не отличаются от неразумных.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>508. Для Благородных (<em>ārya</em>) воистину нет заблуждения (<em>bhrānti</em>),</li>
            <li>ибо их ум (<em>citta</em>) очищен (<em>viśodhita</em>).</li>
            <li>Неразумные же (<em>bāla</em>), чьи потоки ума (<em>cittasaṃtāna</em>) нечисты (<em>aśuddha</em>),</li>
            <li>измышляют воображаемое (<em>kalpitam</em>).<a href="#citation-648" id="ref-648" class="citation-mark"><sup>648</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>509. Подобно тому как мать, желая успокоить ребёнка,</li>
            <li>делает вид, будто извлекает плод из воздуха,</li>
            <li>[говоря]: «Вот, не плачь — возьми этот чудесный плод!»</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>510. Так и Я для всех существ предлагаю</li>
            <li>многообразные воображаемые «плоды»:</li>
            <li>увлекая ими, указываю метод,</li>
            <li>свободный от крайностей «есть» и «нет».</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>511. [То], чьё бытие (<em>bhāva</em>) мыслится как возникшее</li>
            <li>из небытия (<em>abhūtvā</em>) и не связанное с условиями (<em>pratyaya</em>), —</li>
            <li>такое «рождённое» на самом деле не рождалось прежде</li>
            <li>и вовсе лишено собственной сути (<em>alabdhātmaka</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>512. Ибо то, что лишено собственной сути (<em>alabdhātmaka</em>)</li>
            <li>и не рождено (<em>ajāta</em>),</li>
            <li>никогда не существует без условий (<em>pratyaya</em>);</li>
            <li>даже то, что кажется возникшим (<em>utpanna</em>) — это «бытие» (<em>bhāva</em>) —</li>
            <li>нигде не бывает вне условий (<em>pratyaya</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>513. Видя так вкратце, мудрец понимает:</li>
            <li>нигде нет ни бытия (<em>sat</em>), ни небытия (<em>asat</em>), ни их совместного (<em>sadasat</em>).</li>
            <li>То, что возникает через условия (<em>pratyaya</em>),</li>
            <li>не является для мудрецов предметом различения (<em>vikalpa</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>514. О тождестве (<em>ekatva</em>) или отличии (<em>anyatva</em>) рассуждают</li>
            <li>ложные тиртхики (<em>kutīrthya</em>) и глупцы (<em>bāla</em>);</li>
            <li>они не знают, что мир (<em>jagat</em>), возникающий через условия (<em>pratyaya</em>),</li>
            <li>подобен иллюзии (<em>māyā</em>) и сну (<em>svapna</em>).<a href="#citation-649" id="ref-649" class="citation-mark"><sup>649</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>515. Высшая Великая Колесница —</li>
            <li>это колесница за пределами сферы наименований.<a href="#citation-650" id="ref-650" class="citation-mark"><sup>650</sup></a></li>
            <li>Мною воистину указан верный смысл,<a href="#citation-651" id="ref-651" class="citation-mark"><sup>651</sup></a></li>
            <li>но неразумные его не постигают.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>516. Те [учения], что изложены из привязанности</li>
            <li>[к своим воззрениям] шраваками и тиртхиками, —</li>
            <li>они воистину искажают смысл,<a href="#citation-652" id="ref-652" class="citation-mark"><sup>652</sup></a></li>
            <li>ибо проповедуют через рациональную логику (<em>tarka</em>).<a href="#citation-653" id="ref-653" class="citation-mark"><sup>653</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>517. Признак (<em>lakṣaṇa</em>), бытие (<em>bhāva</em>),</li>
            <li>форма (<em>saṃsthāna</em>) и имя (<em>nāma</em>) —</li>
            <li>[это] четыре [основания].</li>
            <li>Приняв их за опоры (<em>ālambana</em>) восприятия,</li>
            <li>воображение (<em>kalpanā</em>) приходит в движение.<a href="#citation-654" id="ref-654" class="citation-mark"><sup>654</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>518. Те, кто утверждают «единое» или «многое»,</li>
            <li>подпав под власть представления о высшей реальности (<em>brahmakāya</em>),</li>
            <li>или приверженные Луне и Солнцу как основам [бытия],<a href="#citation-655" id="ref-655" class="citation-mark"><sup>655</sup></a> —</li>
            <li>они утрачивают [смысл Учения] и не являются Моими сыновьями.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>519. Наделённые видением Благородных,</li>
            <li>достигшие понимания «как оно есть»,</li>
            <li>искусные в растворении механизмов обозначения (<em>saṃjñā</em>),<a href="#citation-656" id="ref-656" class="citation-mark"><sup>656</sup></a></li>
            <li>и исчерпавшие различающее сознание (<em>vijñāna</em>), —</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>520. такова печать подлинности (<em>mudrā</em>) освобождённых,</li>
            <li>Моих сыновей в этом учении:</li>
            <li>они свободны от бытия и небытия,</li>
            <li>свободны от понятий прихода и ухода.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>521. Если бы карма уничтожалась</li>
            <li>при прекращении сознания формы (<em>rūpavijñāna</em>),</li>
            <li>не устанавливалось бы ни постоянство (<em>nityā</em>), ни непостоянство (<em>anityā</em>) —</li>
            <li>и сансара не имела бы места.<a href="#citation-657" id="ref-657" class="citation-mark"><sup>657</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>522. В момент угасания форма прекращается</li>
            <li>в своей области проявления,</li>
            <li>но карма, свободная от крайностей «есть» и «нет»,</li>
            <li>продолжает пребывать в <em>Алайе</em>.<a href="#citation-658" id="ref-658" class="citation-mark"><sup>658</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>523. Форма разрушена и отпала [от потока],</li>
            <li>но сознание пребывает в основании становления (<em>bhavālaya</em>).</li>
            <li>Карма, связанная с формой и сознанием,</li>
            <li>не уничтожается.<a href="#citation-659" id="ref-659" class="citation-mark"><sup>659</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>524. Если бы карма уничтожалась вместе с ними,</li>
            <li>то при разрушении кармической связи</li>
            <li>не было бы ни сансары, ни нирваны.<a href="#citation-660" id="ref-660" class="citation-mark"><sup>660</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>525. Если же [карма], разрушившись вместе с ними,</li>
            <li>всё же рождается в сансаре вновь,</li>
            <li>то форма окажется связанной с ней —</li>
            <li>в силу их нераздельности (<em>abhinnatva</em>).<a href="#citation-661" id="ref-661" class="citation-mark"><sup>661</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>526. Ум и форма воистину</li>
            <li>не являются ни тождественными, ни различными —</li>
            <li>их разделённость есть лишь различение (<em>vikalpa</em>).</li>
            <li>У явлений разрушение (<em>pradhvaṃsa</em>) не устанавливается,</li>
            <li>ибо здесь отброшены крайности «есть» и «нет».<a href="#citation-662" id="ref-662" class="citation-mark"><sup>662</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>527. Воображаемое (<em>kalpita</em>) и зависимое (<em>paratantra</em>)</li>
            <li>нераздельны по своим характеристикам,</li>
            <li>подобно тому как форма и её непостоянство</li>
            <li>взаимно порождают (<em>janaka</em>) друг друга.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>528. Свободное от тождества и различия,</li>
            <li>воображаемое само по себе не устанавливается.</li>
            <li>Как же здесь может быть «есть» или «нет»?</li>
            <li>Как это видно на примере непостоянства формы.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>529. При правильном видении воображаемого</li>
            <li>зависимое более не возникает.</li>
            <li>При видении же зависимого как оно есть</li>
            <li>воображаемое предстает как Таковость (<em>tathatā</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>530. Когда воображаемое уничтожается [как просто несуществующее],</li>
            <li>разрушается само Моё наставление.</li>
            <li>Те, кто так поступает, впадают в крайности</li>
            <li>приписывания и отрицания в Моём учении.<a href="#citation-663" id="ref-663" class="citation-mark"><sup>663</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>531. Когда бы ни появились такие искажающие Дхарму,</li>
            <li>все они — те, с кем не следует даже разговаривать,</li>
            <li>ибо они разрушают Моё наставление.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>532. Мудрым не следует с ними разговаривать;</li>
            <li>следует полностью избегать с ними монашеских дел (<em>bhikṣukārya</em>),</li>
            <li>с теми, кто уничтожает воображаемое,<a href="#citation-664" id="ref-664" class="citation-mark"><sup>664</sup></a></li>
            <li>впадая в крайности приписывания (<em>samāropa</em>) и отрицания (<em>apavāda</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>533. [Мир] подобен пучку волос перед глазами,</li>
            <li>магии (<em>māyā</em>), сну и городу гандхарвов, подобен мареву —</li>
            <li>но те, чьё видение основано на [противопоставлении]</li>
            <li>«есть» и «нет», этого не видят.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>534. Тот, кто примыкает к их обществу (<em>saṃgraha</em>),</li>
            <li>не следует учению Будд.</li>
            <li>Воистину, такие люди пали в крайности двойственности</li>
            <li>и несут погибель другим.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>535. С теми йогинами, которые видят воображаемое (<em>kalpita</em>)</li>
            <li>как обособленное (<em>vivikta</em>) [от ложного приписывания],</li>
            <li>свободное от бытия и небытия (<em>bhāvābhāva</em>), —</li>
            <li>с ними воистину следует пребывать вместе (<em>saṃgraha</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>536. Подобно тому как в мире существуют рудники,</li>
            <li>в которых находятся золото, драгоценные камни и жемчуг, —</li>
            <li>они многообразны, не имеют кармы своей причиной</li>
            <li>и служат средством существования для неразумных.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>537. Так и роды существ (<em>sattvagotrāṇi</em>) многообразны</li>
            <li>и свободны от кармы [в своей основе].</li>
            <li>Поскольку нет реально видимого [объекта],</li>
            <li>нет и кармы, и нет перерождений, рождённых кармой.<a href="#citation-665" id="ref-665" class="citation-mark"><sup>665</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>538. У явлений нет сущностности (<em>bhāvatā</em>) —</li>
            <li>так созерцают Благородные.</li>
            <li>Однако явления «существуют» [лишь] так,</li>
            <li>как их измышляют неразумные.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>539. Если бы явления действительно существовали так,</li>
            <li>как их измышляют неразумные,</li>
            <li>то, будь эти «сущности» реальными,</li>
            <li>не было бы омрачения ни у кого.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>540. Из омрачения, вызванного многообразием явлений,</li>
            <li>сансара разворачивается у воплощённых существ,</li>
            <li>устремлённых к [объектам] через органы чувств,</li>
            <li>связанных неведением и жаждой.<a href="#citation-665.0" id="ref-665.0" class="citation-mark"><sup>665.0</sup></a></li>
        </ul>

    </blockquote>

</div>

<!— Гатхи 541-610 —>

<div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">

    <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>541. У тех, кто не признаёт за явлениями</li>
            <li>того бытия, какое им приписывают неразумные,</li>
            <li>прекращается обычная работа органов чувств —</li>
            <li>но это ещё не путь йогинов.<a href="#citation-667" id="ref-667" class="citation-mark"><sup>667</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>542. Если бы то, что считают причинами сансары,</li>
            <li>вовсе не существовало,</li>
            <li>то и неразумные были бы освобождены —</li>
            <li>без всякой практики (<em>kriyā</em>).<a href="#citation-668" id="ref-668" class="citation-mark"><sup>668</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>543. Тогда в чём было бы различие</li>
            <li>между неразумными и Благородными,</li>
            <li>если бы оно основывалось лишь на бытии и небытии (<em>bhāva / abhāva</em>)?</li>
            <li>Воистину, у Благородных,</li>
            <li>следующих трём вратам освобождения (<em>vimokṣa-traya</em>),</li>
            <li>не устанавливается никакое бытие (<em>bhāva</em>).<a href="#citation-669" id="ref-669" class="citation-mark"><sup>669</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>544. <em>Скандхи</em>, «личность» (<em>pudgala</em>), дхармы,</li>
            <li>их собственные и общие характеристики (<em>sva-sāmānya</em>),</li>
            <li>а также отсутствие [у них] собственных признаков (<em>alakṣaṇa</em>),<a href="#citation-670" id="ref-670" class="citation-mark"><sup>670</sup></a></li>
            <li>условия (<em>pratyaya</em>) и органы чувств (<em>indriya</em>) —</li>
            <li>всё это я разъясняю для шраваков (<em>śrāvaka</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>545. «Только-ум» (<em>cittamātra</em>), не имеющий [внешней] причины (<em>ahetu</em>),</li>
            <li><em>блистательные проявления</em> (<em>vibhūti</em>)<a href="#citation-671" id="ref-671" class="citation-mark"><sup>671</sup></a> и <em>ступени</em> (<em>bhūmi</em>),</li>
            <li>а также чистую Таковость (<em>tathatā</em>),</li>
            <li>постигаемую в непосредственном опыте (<em>pratyātma</em>), —</li>
            <li>это я указываю Сыновьям Победителя (<em>jina-aurasa</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>546. В будущем появятся</li>
            <li>осквернители моего Учения (<em>śāsana-dūṣaka</em>),</li>
            <li>в монашеских одеждах (<em>kāṣāya</em>),</li>
            <li>проповедующие «есть» и «нет»</li>
            <li>и утверждающие реальность следствия (<em>kārya</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>547. Хотя явления (<em>bhāva</em>) сами по себе не существуют (<em>asat</em>),</li>
            <li>они проявляются через условия (<em>pratyaya</em>) —</li>
            <li>такова сфера видения Благородных (<em>ārya-gocara</em>).</li>
            <li>Воображаемого бытия (<em>kalpita-bhāva</em>) воистину нет,</li>
            <li>но логики (<em>tārkika</em>) будут его измышлять.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>548. В будущем появятся последователи Канабхуга (<em>Kaṇabhuk</em>)<a href="#citation-672" id="ref-672" class="citation-mark"><sup>672</sup></a> —</li>
            <li>глупцы от рождения (<em>bālajātikāḥ</em>),</li>
            <li>которые, придерживаясь ложного воззрения</li>
            <li>о возникновении следствия из несуществующего (<em>asatkāryavāda</em>),<a href="#citation-673" id="ref-673" class="citation-mark"><sup>673</sup></a></li>
            <li>будут вводить людей в заблуждение.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>549. Они будут утверждать, что мир возникает из атомов (<em>aṇu</em>),</li>
            <li>сами же атомы беспричинны (<em>ahetuka</em>),</li>
            <li>и станут проповедовать о</li>
            <li>девяти вечных первоэлементах (<em>nava dravyāṇi nityāni</em>)<a href="#citation-674" id="ref-674" class="citation-mark"><sup>674</sup></a></li>
            <li>вследствие ложного видения.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>550. «Элемент (<em>dravya</em>) порождает элемент (<em>dravya</em>),</li>
            <li>Качество (<em>guṇa</em>) — качество (<em>guṇa</em>)», — так они будут учить<a href="#citation-675" id="ref-675" class="citation-mark"><sup>675</sup></a></li>
            <li>и тем самым уничтожат [истинное понимание]</li>
            <li>сущностности явлений (<em>bhāvatā</em>), [утверждая] иную,</li>
            <li>[ложно полагаемую, как] существующую.<a href="#citation-676" id="ref-676" class="citation-mark"><sup>676</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>551. Ведь мир имел бы начало,</li>
            <li>если бы возникал, не существовав прежде.</li>
            <li>Но Я возглашаю:</li>
            <li>у сансары воистину нет начала (<em>pūrvā koṭiḥ</em>).<a href="#citation-677" id="ref-677" class="citation-mark"><sup>677</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>552. Если бы всё возникало, не существовав прежде,</li>
            <li>то, без сомнения, появились бы</li>
            <li>рога у собак, верблюдов и ослов.<a href="#citation-678" id="ref-678" class="citation-mark"><sup>678</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>553. Если бы глаз, форма и зрительное сознание</li>
            <li>возникали, не существовав прежде,</li>
            <li>то из кома глины могли бы рождаться</li>
            <li>циновки, короны, одежды и прочее.<a href="#citation-679" id="ref-679" class="citation-mark"><sup>679</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>554. Из ткани не возникает циновка,</li>
            <li>как и из травы — ткань.</li>
            <li>Если одно возникает из условий в одном [случае],</li>
            <li>почему не возникает [всё] [из любых условий]?<a href="#citation-680" id="ref-680" class="citation-mark"><sup>680</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>555. Учение о том, что душа (<em>jīva</em>) и тело (<em>charīra</em>)</li>
            <li>тождественны или различны,</li>
            <li>а также [взгляд], что нечто возникает,</li>
            <li>не существовав прежде, —</li>
            <li>всё это чужие доктрины;</li>
            <li>я привёл их лишь для опровержения.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>556. Изложив взгляды оппонентов,</li>
            <li>я отбрасываю их убеждения;</li>
            <li>отбросив же эти мнения,</li>
            <li>указываю собственный путь.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>557. Именно поэтому Мною</li>
            <li>были изложены учения иноверцев —</li>
            <li>чтобы Мой собор учеников,</li>
            <li>не впал в заблуждение,</li>
            <li>прибегая к крайностям бытия или небытия.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>558. Даже дурномыслящий Капила</li>
            <li>говорит своим ученикам:</li>
            <li>«Мир возник из Первоматерии» (<em>pradhāna</em>)</li>
            <li>и учит их превращению гунн (<em>guṇa</em>).<a href="#citation-681" id="ref-681" class="citation-mark"><sup>681</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>559. [Явления] — ни существующие, ни несуществующие;</li>
            <li>ни условия, ни то, что ими обусловлено,</li>
            <li>не имеют собственной природы.</li>
            <li>Поскольку условия лишены собственного бытия (<em>asadbhāva</em>),</li>
            <li>несуществующее (<em>abhūta</em>) не возникает.<a href="#citation-682" id="ref-682" class="citation-mark"><sup>682</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>560. Свободная от (<em>vigata</em>) крайностей «есть» и «нет»,</li>
            <li>свободная от (<em>varjita</em>) причин и условий,</li>
            <li>лишённая (<em>rahita</em>) рождения и прекращения —</li>
            <li>такова Моя позиция (<em>svapakṣaḥ</em>),</li>
            <li>свободная от (<em>varjita</em>) объекта установления (<em>lakṣya</em>).<a href="#citation-683" id="ref-683" class="citation-mark"><sup>683</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>561. Кто всегда (<em>sadā</em>) видит мир</li>
            <li>подобным миражу и сну,</li>
            <li>свободным от причин и условий,</li>
            <li>по своей природе беспричинным (<em>ahetukam</em>), —</li>
            <li>у того различение не разворачивается.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>562. Всегда видя становление</li>
            <li>подобным призрачному городу, миражу,</li>
            <li>волоскам перед глазами,</li>
            <li>свободным от крайностей «есть» и «нет»,</li>
            <li>лишённым причин и условий,</li>
            <li>по своей природе беспричинным,</li>
            <li>поток ума очищается.<a href="#citation-684" id="ref-684" class="citation-mark"><sup>684</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>563. Видя, что объект (<em>vastu</em>) не обнаруживается,</li>
            <li>не обнаруживается и «только-ум» (<em>cittamātra</em>).</li>
            <li>Как может ум быть без объекта?</li>
            <li>В таком случае «только-ум»</li>
            <li>невозможно утверждать (<em>na yujyate</em>).<a href="#citation-685" id="ref-685" class="citation-mark"><sup>685</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>564. Приняв объект (<em>vastu</em>) за опору (<em>ālambana</em>),</li>
            <li>у людей возникает ум.</li>
            <li>Как может ум быть беспричинным?</li>
            <li>В таком случае «только-ум» невозможно утверждать.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>565. Таковость (<em>tathatā</em>) и «только-ум»</li>
            <li>в учении Благородных о подлинном —</li>
            <li>и устанавливаются, и не устанавливаются.</li>
            <li>Те, кто пытаются их так установить,</li>
            <li>не сведущи в Моём методе (<em>naya</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>566. Если ум разворачивается</li>
            <li>как схватывающий и схватываемое,</li>
            <li>то это воистину мирской ум —</li>
            <li>в таком случае «только-ум» невозможно утверждать.<a href="#citation-686" id="ref-686" class="citation-mark"><sup>686</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>567. Если бы тело, переживаемое и опора</li>
            <li>Возникали [в уме] подобно сну,</li>
            <li>то возникла бы двойственность ума (<em>dvicittatā</em>);</li>
            <li>но ум не имеет двойственной природы (<em>na dvilakṣaṇam</em>).<a href="#citation-687" id="ref-687" class="citation-mark"><sup>687</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>568. Подобно тому как меч не режет сам своё лезвие,</li>
            <li>а палец не касается самого своего кончика, —</li>
            <li>так и ум не видит себя в собственном созерцании.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>569. Ни внешнего (<em>na paraṃ</em>), ни <em>зависимой природы</em> (<em>tantra</em>),</li>
            <li>ни воображаемого объекта (<em>parikalpita-vastu</em>),</li>
            <li>ни <em>пяти дхарм</em>, ни двойственного ума —</li>
            <li>в состоянии без-образности (<em>nirābhāsa</em>) этого воистину нет.<a href="#citation-688" id="ref-688" class="citation-mark"><sup>688</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>570. Порождающее и порождаемое —</li>
            <li>вот двоякий признак становления.</li>
            <li>Говоря о порождающем, Я тем самым</li>
            <li>утверждаю отсутствие собственной природы.<a href="#citation-689" id="ref-689" class="citation-mark"><sup>689</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>571. Если бы представление</li>
            <li>о многообразии форм возникало само по себе,</li>
            <li>то в небе и «в рогах зайца»</li>
            <li>появились бы видимости объектов.<a href="#citation-690" id="ref-690" class="citation-mark"><sup>690</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>572. Если бы ум становился видимостью объекта,</li>
            <li>тогда сам объект был бы не-воображённым.</li>
            <li>Но воображаемый объект</li>
            <li>не признаётся чем-то иным, нежели ум.<a href="#citation-691" id="ref-691" class="citation-mark"><sup>691</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>573. В безначальной сансаре объект нигде не обнаруживается.</li>
            <li>Как же тогда ум, не подкреплённый ничем,</li>
            <li>разворачивается как видимость объектов?<a href="#citation-692" id="ref-692" class="citation-mark"><sup>692</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>574. Если бы подкрепление происходило из отсутствия (<em>abhāva</em>),</li>
            <li>оно было бы и в «рогах зайца».</li>
            <li>Но различение не разворачивается,</li>
            <li>будучи подкрепляемым отсутствием.<a href="#citation-693" id="ref-693" class="citation-mark"><sup>693</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>575. Как его нет сейчас, так не было и прежде.</li>
            <li>Как же ум может разворачиваться,</li>
            <li>связываясь с тем, чего нет?<a href="#citation-694" id="ref-694" class="citation-mark"><sup>694</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>576. Таковость (<em>tathatā</em>), <em>шуньята</em> (<em>śūnyatā</em>),</li>
            <li><em>Предел истинности</em>, нирвана,</li>
            <li><em>дхармадхату</em>, не-возникновение дхарм —</li>
            <li>вот высшая <em>собственная природа</em>.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>577. Неразумные пали в крайности «нет» и «есть»</li>
            <li>из-за измышлений о причинах и условиях,</li>
            <li>ибо они не знают становления (<em>bhava</em>)</li>
            <li>как беспричинного (<em>ahetuka</em>) и нерожденного (<em>anutpāda</em>).<a href="#citation-695" id="ref-695" class="citation-mark"><sup>695</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>578. Ум проявляется, но видимого объекта нет — [всё же]</li>
            <li>это различие полагают как имеющее безначальную причину.</li>
            <li>Но если даже в <em>безначальном</em> объекта нет,</li>
            <li>чем же порождается это различие?<a href="#citation-696" id="ref-696" class="citation-mark"><sup>696</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>579. Если бы подкрепление приходило из отсутствия,</li>
            <li>то бедняк стал бы богачом.<a href="#citation-697" id="ref-697" class="citation-mark"><sup>697</sup></a></li>
            <li>[Махамати:] — О Мудрец, скажи мне:</li>
            <li>при отсутствии объекта как же возникает ум?</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>580. [Будда:] — Всё это беспричинно:</li>
            <li>нет ни ума, ни его поля деятельности.</li>
            <li>Ум воистину не подкрепляется;</li>
            <li>три мира лишены собственной деятельности.<a href="#citation-698" id="ref-698" class="citation-mark"><sup>698</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>581. Ради устранения представления о возникновении</li>
            <li>Я учу учению о беспричинности (<em>ahetuvāda</em>),</li>
            <li>устанавливающему не-возникновение (<em>anutpāda</em>), —</li>
            <li>однако неразумные не способны его постичь.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>582. Всё это нерождённо; явления (<em>bhāva</em>)</li>
            <li>нельзя назвать ни существующими, ни несуществующими.</li>
            <li>Подобно городу гандхарвов, сну и магической иллюзии,</li>
            <li>явления видятся, хотя и беспричинны.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>583. [Махамати:]</li>
            <li>— Скажи мне, на каком основании явления</li>
            <li>называются нерождёнными по своей природе</li>
            <li>и пустыми (<em>śūnya</em>)?</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>584. [Будда:]</li>
            <li>— Явление не схватывается мыслью</li>
            <li>как существующее отдельно от сочетания (<em>samavāya</em>).<a href="#citation-699" id="ref-699" class="citation-mark"><sup>699</sup></a></li>
            <li>Поэтому Я называю его пустым, нерождённым</li>
            <li>и лишённым собственной природы (<em>asvabhāva</em>).<a href="#citation-700" id="ref-700" class="citation-mark"><sup>700</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>585. Ни само сочетание (<em>samavāya</em>),</li>
            <li>ни каждая его часть по отдельности</li>
            <li>не обнаруживаются вследствие отсутствия воспринимаемого.</li>
            <li>Сочетание не обнаруживается —</li>
            <li>однако не [в силу того] уничтожения (<em>pralaya</em>),</li>
            <li>которое утверждают воззрения тиртхиков.<a href="#citation-701" id="ref-701" class="citation-mark"><sup>701</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>586. Подобно сну, мушкам перед глазами, магической иллюзии,</li>
            <li>городу гандхарвов и мареву воды в пустыне —</li>
            <li>явления мира видятся, хотя и беспричинны.</li>
            <li>Таково многообразие мира.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>587. Опровергнув посредством учения о беспричинности</li>
            <li>[воззрение о] возникновении,</li>
            <li>следует утвердить не-возникновение.</li>
            <li>Когда не-возникновение утверждено должным образом,</li>
            <li>Моё Наставление (<em>netrī</em>) не исчезает.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>588. Когда же преподаётся учение о беспричинности,</li>
            <li>у тиртхиков возникает страх.</li>
            <li>«Как? Кем? Откуда? Где</li>
            <li>может быть беспричинное возникновение?»</li>
            <li>Но когда обусловленное (<em>saṃskṛta</em>)</li>
            <li>видится как не возникающее</li>
            <li>ни беспричинно, ни из причин,</li>
            <li>тогда прекращается воззрение,</li>
            <li>утверждающее возникновение и уничтожение.<a href="#citation-702" id="ref-702" class="citation-mark"><sup>702</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>589. [Махамати:]</li>
            <li>— Является ли не-возникновение (<em>anutpāda</em>) небытием (<em>abhāva</em>)?</li>
            <li>Или же — рассмотрением условий (<em>pratyaya-vīkṣaṇa</em>)?</li>
            <li>Или это лишь имя для явления (<em>bhāva</em>)?</li>
            <li>Или пустое слово? Скажи мне.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>590. [Будда:]</li>
            <li>— Не-возникновение — не небытие;</li>
            <li>не рассмотрение условий;</li>
            <li>не имя для явления;</li>
            <li>и не бессмысленное имя.<a href="#citation-703" id="ref-703" class="citation-mark"><sup>703</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>591. То, что недоступно (<em>agocara</em>)</li>
            <li>ни шравакам, ни пратьекабуддам, ни тиртхикам,</li>
            <li>ни [бодхисаттвам], пребывающим</li>
            <li>на [первых] семи ступенях (<em>saptabhūmigata</em>), —</li>
            <li>таков признак не-возникновения (<em>anutpāda-lakṣaṇa</em>).<a href="#citation-704" id="ref-704" class="citation-mark"><sup>704</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>592. Устранение причин и условий (<em>hetu-pratyaya-vyāvṛtti</em>),</li>
            <li>прекращение причины (<em>kāraṇa-nirodhana</em>)</li>
            <li>и установление «только-ума» (<em>cittamātra-vyavasthāna</em>) —</li>
            <li>вот что Я называю не-возникновением.<a href="#citation-705" id="ref-705" class="citation-mark"><sup>705</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>593. Беспричинное разворачивание явлений (<em>ahetu-vṛtti</em>),</li>
            <li>свободное от воображаемого</li>
            <li>и самого выстраивания понятий (<em>kalpya-kalpanā-varjita</em>),</li>
            <li>свободное от крайностей «есть» и «нет» (<em>sadasat-pakṣa-nirmukta</em>) —</li>
            <li>вот что Я называю не-возникновением.<a href="#citation-706" id="ref-706" class="citation-mark"><sup>706</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>594. Ум, свободный от воспринимаемого (<em>citta-dṛśya-vinirmuktam</em>);</li>
            <li>свобода от двух природ (<em>svabhāva-dvaya-varjitam</em>)</li>
            <li>[воображаемой и зависимой];</li>
            <li>поворот основы (<em>āśrayasya parāvṛttim</em>) —</li>
            <li>вот что Я называю не-возникновением.<a href="#citation-707" id="ref-707" class="citation-mark"><sup>707</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>595. Ни внешнее явление (<em>bāhya-bhāva</em>),</li>
            <li>ни его отсутствие (<em>abhāva</em>),</li>
            <li>ни присвоение умом (<em>citta-parigraha</em>);</li>
            <li>[видение всего] как сна, волосков перед глазами,</li>
            <li>магической иллюзии, города гандхарвов и миража,</li>
            <li>а также оставление всех воззрений</li>
            <li>(<em>sarva-dṛṣṭi-prahāṇa</em>) —</li>
            <li>таков признак не-возникновения (<em>anutpāda-lakṣaṇa</em>).<a href="#citation-708" id="ref-708" class="citation-mark"><sup>708</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>596. Так следует понимать все эти обозначения —</li>
            <li><em>шуньяту</em>, отсутствие собственной природы</li>
            <li>(<em>asvabhāva</em>) и прочие.</li>
            <li>Они не устанавливают <em>шуньяту</em> посредством самой <em>шуньяты</em></li>
            <li>(<em>śūnyayā śūnyā</em>),</li>
            <li>но раскрывают её через <em>шуньяту</em> не-возникновения</li>
            <li>(<em>anutpāda-śūnyatā</em>).<a href="#citation-709" id="ref-709" class="citation-mark"><sup>709</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>597. Совокупность условий (<em>kalāpa</em>)</li>
            <li>разворачивается и прекращается.</li>
            <li>То, что мыслится отдельно от совокупности,</li>
            <li>не рождается и не прекращается.<a href="#citation-710" id="ref-710" class="citation-mark"><sup>710</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>598. Нигде не обнаруживается никакое явление,</li>
            <li>отделённое от совокупности условий.</li>
            <li>Представления о единстве или разделённости —</li>
            <li>таково суждение тиртхиков (<em>tīrthyair-vikalpyate</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>599. Явление не рождается ни из существующего,</li>
            <li>ни из несуществующего,</li>
            <li>ни из существующего-и-несуществующего.</li>
            <li>Именно эта совокупность разворачивается и прекращается,</li>
            <li>и нигде иначе.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>600. Всё это — лишь условное обозначение (<em>saṃketa-mātram</em>),</li>
            <li>для взаимозависимого сцепления (<em>anyonyāpekṣa-saṃkalāt</em>).</li>
            <li>Никакого иного смысла не существует</li>
            <li>отдельно от сцепления условий (<em>pṛthak-pratyaya-saṃkalāt</em>).<a href="#citation-711" id="ref-711" class="citation-mark"><sup>711</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>601. Поскольку отсутствует самостоятельно порождаемое,</li>
            <li>Я учу не-возникновению (<em>anutpāda</em>),</li>
            <li>свободному от ошибок тиртхиков.</li>
            <li>Я учу лишь сцеплению (<em>saṃkalā-mātra</em>),</li>
            <li>но неразумные не способны этого постичь.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>602. Тот, для кого порождаемое явление (<em>janyo bhāvaḥ</em>)</li>
            <li>существовало бы где-либо отдельно</li>
            <li>от сцепления (<em>saṃkalā</em>), —</li>
            <li>должен быть признан сторонником беспричинности (<em>ahetuvādī</em>),</li>
            <li>разрушающим само сцепление.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>603. Сцепление (<em>saṃkalā</em>) подобно светильнику:</li>
            <li>оно делает различимыми виды явлений (<em>dravya-jātīnāṃ vyañjakā</em>).</li>
            <li>Если же кто-либо полагает, что какое-либо явление</li>
            <li>существует отдельно от сцепления, —</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>604. то то, что неразумными воображается</li>
            <li>как отделённое от сцепления, —</li>
            <li>лишено собственной природы (<em>asvabhāva</em>),</li>
            <li>нерождённо (<em>anutpanna</em>) и подобно пространству (<em>gaganopama</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>605. Это и есть «иное» не-возникновение —</li>
            <li>дхармата достижения Благородных (<em>āryāṇāṃ prāpti-dharmatā</em>).</li>
            <li>Для того, кто познал не-возникновение [<em>saṃkalā-mātra</em>],</li>
            <li>возникает стойкость в не-возникновении (<em>anutpāda-kṣānti</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>606. Когда весь этот мир видится</li>
            <li>как лишь сцепление (<em>saṃkalā-mātra</em>),</li>
            <li>когда видится: «всё это — лишь сцепление», —</li>
            <li>тогда ум входит в <em>самадхи</em>.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>607. Неведение, жажда, карма и прочее —</li>
            <li>это внутреннее сцепление (<em>adhyātmikā saṃkalā</em>).</li>
            <li>Глина, палка, гончарный круг, семя, элементы и прочее —</li>
            <li>это внешнее (<em>bāhiraṃ</em>) сцепление.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>608. Тот, для кого бытие возникает как нечто иное,</li>
            <li>из условий (<em>parataḥ pratyayaiḥ jāyate</em>), —</li>
            <li>для того это не есть лишь сцепление;</li>
            <li>такие не утверждены ни в правильном методе (<em>yukti</em>),</li>
            <li>ни в Учении (<em>āgama</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>609. [Махамати:] — Если нет порождаемого явления,</li>
            <li>то благодаря какому условию возникает познание (<em>buddhi</em>)?</li>
            <li>[Будда:] — Они взаимно порождают друг друга;</li>
            <li>поэтому и называются условиями (<em>pratyaya</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>610. Тепло, текучесть, движение, твёрдость —</li>
            <li>так неразумные измышляют «дхармы».</li>
            <li>Но это лишь совокупность условий (<em>kalāpa</em>), а не дхармы;</li>
            <li>потому воистину [всё] лишено собственной природы (<em>niḥsvabhāvatā</em>).<a href="#citation-712" id="ref-712" class="citation-mark"><sup>712</sup></a></li>
        </ul>

    </blockquote>

</div>

<!— Гатхи 611-680 —>
<div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">

    <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>611. Подобно тому как врачи, сообразуясь с недугом больного,</li>
            <li>применяют различные способы лечения,</li>
            <li>сама наука (<em>śāstra</em>) не разделяется —</li>
            <li>различие существует лишь в недугах (<em>doṣa-bheda</em>),</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>612. так и Я, [видя] потоки существ (<em>sattva-saṃtāna</em>),</li>
            <li>глубоко поражённые омрачениями (<em>kleśa-doṣa</em>),</li>
            <li>зная силу их способностей (<em>indriya-bala</em>),</li>
            <li>проповедую метод (<em>naya</em>) живым существам.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>613. Из-за различия омрачений (<em>kleśa</em>) и способностей</li>
            <li>Моё учение (<em>śāsana</em>) не разделяется.</li>
            <li>Единой является Колесница (<em>yānam ekam</em>) —</li>
            <li>Благой Восьмеричный Путь (<em>aṣṭāṅgika-mārga</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>614. Ты полагаешь существование горшка, ткани,</li>
            <li>короны, рога как причинно обусловленное,</li>
            <li>даже «рога зайца» [мыслятся так же].</li>
            <li>Но то, что считается возникшим из причин,</li>
            <li>не существует — это тебе следует понять.<a href="#citation-713" id="ref-713" class="citation-mark"><sup>713</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>615. Нет доказательства существования;</li>
            <li>утверждать «нет, нет» также неуместно.</li>
            <li>Ведь «существование» не существует само по себе —</li>
            <li>оно обусловлено взаимозависимыми причинами.<a href="#citation-714" id="ref-714" class="citation-mark"><sup>714</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>616. Кто утверждает: «Одно проявляется, опираясь на другое»,</li>
            <li>принимая это другое как беспричинное, —</li>
            <li>тот делает проявленное одновременно</li>
            <li>беспричинным [по основе]</li>
            <li>и не-беспричинным [по зависимости].<a href="#citation-715" id="ref-715" class="citation-mark"><sup>715</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>617. Если же одно опирается на другое, а то — ещё на иное,</li>
            <li>возникает бесконечная цепь зависимости (<em>anavasthā</em>),</li>
            <li>и не было бы ни чего-либо, ни чего бы то ни было.<a href="#citation-716" id="ref-716" class="citation-mark"><sup>716</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>618. Подобно тому как, опираясь на листья и щепки,</li>
            <li>разворачивается иллюзия, —</li>
            <li>так и, опираясь на принимаемое за реальное (<em>vastu</em>),</li>
            <li>многообразие становится видимым для людей.<a href="#citation-717" id="ref-717" class="citation-mark"><sup>717</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>619. Иллюзия — это не листья,</li>
            <li>не щепки и не камешки.</li>
            <li>Неразумные видят лишь саму иллюзию,</li>
            <li>и сама их опора (<em>āśraya</em>) — лишь её образ.<a href="#citation-718" id="ref-718" class="citation-mark"><sup>718</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>620. Подобным образом, если, опираясь</li>
            <li>на принимаемое за реальное (<em>vastu</em>), нечто исчезает,</li>
            <li>то в момент видения нет двойственности;</li>
            <li>как же тогда возможно какое-либо различение (<em>vikalpa</em>)?<a href="#citation-719" id="ref-719" class="citation-mark"><sup>719</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>621. То, что измышляется через различение (<em>vikalpa</em>), не существует;</li>
            <li>и самого различения нет.</li>
            <li>Когда различение не обнаруживается,</li>
            <li>нет ни сансары (<em>saṃsṛti</em>), ни нирваны (<em>nirvṛti</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>622. Когда различение не обнаруживается,</li>
            <li>различение не разворачивается.</li>
            <li>Как может ум не разворачиваться?</li>
            <li>«Только-ум» тогда невозможно утверждать.<a href="#citation-720" id="ref-720" class="citation-mark"><sup>720</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>623. Из-за раздробленности множеством мнений</li>
            <li>в Учении не остаётся сути (<em>sāratā</em>)</li>
            <li>А при отсутствии сути нет освобождения</li>
            <li>и не раскрывается способ проявления многообразия мира.<a href="#citation-721" id="ref-721" class="citation-mark"><sup>721</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>624. Внешнее видимое не обнаруживается</li>
            <li>так, как его воображают неразумные.</li>
            <li>Ум проявляется подобно отражению,</li>
            <li>приведённый в кружение отпечатками.<a href="#citation-722" id="ref-722" class="citation-mark"><sup>722</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>625. Все явления (<em>bhāva</em>)  воистину не рождены (<em>anutpannā</em>),</li>
            <li>они не возникают ни из не-существования, ни из существования.</li>
            <li>Всё это — «только-ум» (<em>citta-mātram</em>),</li>
            <li>свободный от воображаемых построений (<em>kalpanābhiśca varjitam</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>626. Неразумные объявляют явления (<em>bhāva</em>) [реальными]</li>
            <li>через условия (<em>pratyaya</em>), мудрые же — нет.</li>
            <li>Ум, доступный Благородным, — благой,</li>
            <li>свободный от собственной природы (<em>svabhāva</em>)</li>
            <li>и от [обычного] ума (<em>citta</em>).<a href="#citation-723" id="ref-723" class="citation-mark"><sup>723</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>627. Последователи Санкхьи, Вайшешики,</li>
            <li>нагие аскеты, ведические мыслители и пашупаты —</li>
            <li>все они пали в воззрения о «есть» и «нет»</li>
            <li>и лишены понимания подлинного смысла.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>628. [Махамати:] — Если все явления</li>
            <li>лишены собственной природы (<em>niḥsvabhāvāḥ</em>),</li>
            <li>не возникли (<em>anutpannāḥ</em>), пусты (<em>śūnyā</em>),</li>
            <li>подобны иллюзии (<em>māyopamāḥ</em>) и чисты (<em>amalāḥ</em>), —</li>
            <li>то кому же это было преподано Буддами</li>
            <li>и разъяснено Тобой?<a href="#citation-724" id="ref-724" class="citation-mark"><sup>724</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>629. [Будда:] — Для йогинов с чистым умом</li>
            <li>Будды проповедуют йогу,</li>
            <li>свободную от воззрений и рассудочных построений;</li>
            <li>её же разъясняю и Я.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>630. [Махамати:] — Если всё это — лишь ум, то на чём утверждён этот мир?</li>
            <li>На основе чего людям видится приход и уход на этой земле?<a href="#citation-725" id="ref-725" class="citation-mark"><sup>725</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>631. [Будда:] — Как птица (<em>śakuni</em>) в небе, движимая различением,</li>
            <li>не имея опоры и ни на что не опираясь,</li>
            <li>движется — словно имея основание,</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>632. так и все воплощённые существа,</li>
            <li>движимые различением (<em>vikalpa</em>),</li>
            <li>перемещаются в собственном уме,</li>
            <li>подобно птице в небе.<a href="#citation-726" id="ref-726" class="citation-mark"><sup>726</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>633. [Махамати:] — Ум проявляется как имеющий вид</li>
            <li>тела, объектов и опоры — скажи: как он разворачивается?</li>
            <li>Как и посредством чего возникают его проявление и деятельность?</li>
            <li>Разъясни мне учение «только-ум».<a href="#citation-727" id="ref-727" class="citation-mark"><sup>727</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>634. [Будда:] — Тело, объекты и опора, а также проявление и деятельность —</li>
            <li>возникают посредством отпечатков (<em>vāsanā</em>).</li>
            <li>У не сведущих же проявление и деятельность</li>
            <li>порождаются различением (<em>vikalpanaiḥ</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>635. Объект есть воображённое явление;</li>
            <li>ум [полагается] возникающим из объекта.</li>
            <li>Но при совершенном постижении (<em>parijñāna</em>) видимого и ума</li>
            <li>различение (<em>vikalpa</em>) не разворачивается.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>636. Когда воображённое распознаётся как имя,</li>
            <li>не связанное с тем, что именуется,</li>
            <li>и как свободное от познающего (<em>buddhi</em>) и познаваемого (<em>boddhavya</em>),</li>
            <li>тогда происходит освобождение от обусловленного (<em>saṃskṛta</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>637. Это познание (<em>buddhi</em>) и есть подлежащее постижению (<em>bodhya</em>):</li>
            <li>отличие (<em>vibhāvana</em>) имени (<em>nāma</em>) от именуемого (<em>nāmni</em>).</li>
            <li>Кто понимает иначе — не являются ни Буддами, ни наставниками.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>638. <em>Пять дхарм, три природы,</em></li>
            <li>восемь сознаний и два вида отсутствие «я» —</li>
            <li>в этом заключается весь охват Махаяны.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>639. Когда мир видится свободным от (<em>vivikta</em>) [двойственности]</li>
            <li>познающего (<em>buddhi</em>) и познаваемого (<em>boddhavya</em>),</li>
            <li>тогда ни имя, ни различение больше не разворачиваются.<a href="#citation-728" id="ref-728" class="citation-mark"><sup>728</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>640. Прекращение действий, обозначений и различений</li>
            <li>происходит через в<em>и</em>дение ума.</li>
            <li>Из-за нев<em>и</em>дения собственного ума</li>
            <li>различение вновь приходит в движение.<a href="#citation-729" id="ref-729" class="citation-mark"><sup>729</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>641. Четыре бесформенные <em>скандхи</em> —</li>
            <li>они не поддаются исчислению.</li>
            <li>Если форма отлична от элементов,</li>
            <li>как возможно многообразие форм?<a href="#citation-730" id="ref-730" class="citation-mark"><sup>730</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>642. При устранении признаков (<em>lakṣaṇa</em>)</li>
            <li>нет ни элементов, ни производного от них.</li>
            <li>Если же форма мыслится обладающей иными признаками,</li>
            <li>почему она возникает из <em>скандх</em>?<a href="#citation-731" id="ref-731" class="citation-mark"><sup>731</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>643. Когда <em>скандхи</em> и <em>аятаны</em> видятся</li>
            <li>как лишённые признаков, тогда ум обращается вспять</li>
            <li>благодаря видению отсутствие «я» дхарм (<em>dharma-nairātmya</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>644. Из-за разделения объекта и органов чувств</li>
            <li>сознание возникает как восьмеричное.</li>
            <li>По признакам оно становится тройственным;</li>
            <li>в состоянии «без-образности» — прекращается.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>645. <em>Алая</em> в <em>манасе</em> принимается за «я»,</li>
            <li>а познание — за «моё».</li>
            <li>Из-за схватывания двойственности это разворачивается,</li>
            <li>а при полном постижении (<em>parijñāna</em>) — прекращается.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>646. Когда видится то, что свободно от «иного» и «тождественного»,</li>
            <li>как не вовлечённое в движение,</li>
            <li>тогда не измышляется двойственность —</li>
            <li>ни «я», ни «моё».</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>647. Неразвёрнувшееся не поддерживает</li>
            <li>и не является причиной сознания.</li>
            <li>Свободное от причины и следствия,</li>
            <li>прекращённое — не разворачивается.<a href="#citation-732" id="ref-732" class="citation-mark"><sup>732</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>648. [Махамати]: — Скажи мне, каким образом (<em>kena</em>)</li>
            <li>различение, «только-ум» и мир оказываются</li>
            <li>лишёнными причин и свободными</li>
            <li>от объекта определения (<em>lakṣya</em>) и признака (<em>lakṣaṇa</em>)?</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>649. [Будда]: — Собственный ум предстаёт как многообразный,</li>
            <li>в виде образа видимого, возникшего из различения.</li>
            <li>Из-за непостижения ума и видимого возникает «иное» —</li>
            <li>как нечто отличное, вследствие схватывания объекта ума.<a href="#citation-733" id="ref-733" class="citation-mark"><sup>733</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>650. [Махамати]: — Воззрение на небытие возникает,</li>
            <li>когда не видят посредством понимания.</li>
            <li>Но как может быть существование у этого,</li>
            <li>если оно не возникает даже из схватывания умом?</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>651. [Будда:] — Различение (<em>vikalpa</em>) — не бытие и не небытие;</li>
            <li>поэтому из него не возникает существование.</li>
            <li>Благодаря полному постижению (<em>parijñānāt</em>) ума и видимого</li>
            <li>различение (<em>vikalpa</em>) не разворачивается (<em>na pravartate</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>652. Прекращение разворачивания различения —</li>
            <li>это поворот без [установления какой-либо] опоры.</li>
            <li>Если отвергнуть четыре позиции</li>
            <li>и при этом считать, что явления имеют причины,</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>653. то это оказывается лишь различием в ином обозначении (<em>saṃjñā</em>)</li>
            <li>— кем это установлено? Оно не доказано.</li>
            <li>Либо принимается по предположению (<em>arthāpatti</em>),</li>
            <li>либо разворачивается из представления о причине.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>654. Из-за соединения причин (<em>hetu</em>) и условий (<em>pratyaya</em>)</li>
            <li>и отрицания независимой причины (<em>kāraṇa-pratiṣedhataḥ</em>)</li>
            <li>устраняется крайность вечности (<em>nitya-doṣo nivāryate</em>) —</li>
            <li>поскольку условия непостоянны (<em>anityā yadi pratyayāḥ</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>655. Тогда у неразумных не оказывается</li>
            <li>ни возникновения (<em>saṃbhava</em>), ни прекращения (<em>vibhava</em>) —</li>
            <li>ведь всё непостоянно (<em>anityatvāt</em>).</li>
            <li>Ведь то, что разрушается</li>
            <li>не может быть увидено как причина.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>656. Как может возникать становление (<em>bhavaḥ</em>),</li>
            <li>претендующее на то, чтобы не быть непостоянным (<em>na anityaḥ</em>),</li>
            <li>если оно никак не обнаруживается?</li>
            <li>«Существ следует направлять средствами привлечения</li>
            <li>и удерживать нравственной дисциплиной.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>657. Мудростью (<em>prajñā</em>) следует разрушать воззрения,</li>
            <li>а посредством освобождений (<em>vimokṣa</em>) — развивать [путь]».</li>
            <li>Всё это — мирское учение (<em>lokāyata</em>),</li>
            <li>что ложно проповедуют иноверцы.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>658. Из-за воззрения о реальности причины и следствия</li>
            <li>их собственное учение не имеет основания.</li>
            <li>Я же проповедую единое учение,</li>
            <li>свободное от причины и следствия.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>659. Я излагаю это собранию учеников,</li>
            <li>будучи свободным от мирского учения:</li>
            <li>«Всё — только ум; видимого нет.</li>
            <li>Ум представляется двояко —</li>
            <li>как схватывающее и схватываемое,</li>
            <li>свободное от вечности и уничтожения».</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>660. Пока разворачивается ум,</li>
            <li>сохраняется мирское видение (<em>lokāyata</em>).</li>
            <li>Прекращение различения —</li>
            <li>у того, кто видит мир как собственный ум.<a href="#citation-734" id="ref-734" class="citation-mark"><sup>734</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>661. Приход (<em>āya</em>) — это возникновение явленного,</li>
            <li>уход (<em>vyaya</em>) — его исчезновение.</li>
            <li>Благодаря постижению (<em>parijñāna</em>) прихода и ухода</li>
            <li>различение (<em>vikalpa</em>) не разворачивается.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>662. Вечное и непостоянное, сотворённое и несотворённое,</li>
            <li>высшее и низшее — всё это относится</li>
            <li>к мирскому мышлению (<em>lokāyata</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>663. Боги, асуры, люди,</li>
            <li>животные, преты и обитатели мира Ямы —</li>
            <li>таковы шесть уделов существования,</li>
            <li>где рождаются воплощённые существа.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>664. В силу низких, высших и средних деяний</li>
            <li>рождаются в них. Сохраняя всё благое,</li>
            <li>достигают либо лучшего удела, либо освобождения.<a href="#citation-735" id="ref-735" class="citation-mark"><sup>735</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>665. [Махамати:] — Учение о возникновении и угасании</li>
            <li>в каждое мгновение (<em>kṣaṇe kṣaṇe</em>),</li>
            <li>которое Ты проповедуешь собранию монахов, —</li>
            <li>открой мне его смысл!</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>666. [Будда:] — Подобно тому как от одной формы возникает другая,</li>
            <li>так и ум, возникнув, распадается.</li>
            <li>Потому Я указываю ученикам</li>
            <li>на последовательность мгновенных рождений.<a href="#citation-736" id="ref-736" class="citation-mark"><sup>736</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>667. В каждой форме — возникновение и исчезновение различения.</li>
            <li>Ведь «существо» — это лишь различение; иного существа нет.<a href="#citation-737" id="ref-737" class="citation-mark"><sup>737</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>668. Учение о мгновениях — не является окончательным,</li>
            <li>это лишь речь об условиях.</li>
            <li>Когда освобождаются от схватывания формы,</li>
            <li>нет ни рождения, ни распада.<a href="#citation-738" id="ref-738" class="citation-mark"><sup>738</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>669. Условия, возникшие из условий —</li>
            <li>неведение, Таковость и прочее —</li>
            <li>действуют как двойственность дхарм;</li>
            <li>но Таковость — недвойственна.<a href="#citation-739" id="ref-739" class="citation-mark"><sup>739</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>670. Если условия, возникшие из условий,</li>
            <li>определяются как дхармы,</li>
            <li>тогда возникают представления о вечности и прочем,</li>
            <li>и устанавливаются следствие, причина и условие.<a href="#citation-740" id="ref-740" class="citation-mark"><sup>740</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>671. [Махамати:] — Если принимать причину и следствие,</li>
            <li>[учение] стало бы неотличимым от учений иноверцев;</li>
            <li>тогда и твоё учение, и учение Будд,</li>
            <li>о Великий Мудрец, не было бы учением Благородных!</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>672. [Будда:] — В этом самом теле, высотой всего в одну сажень,</li>
            <li>Я указываю сынам Победителя</li>
            <li>мир (<em>loka</em>) и возникновение мира,</li>
            <li>а также путь, ведущий к его прекращению.<a href="#citation-741" id="ref-741" class="citation-mark"><sup>741</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>673. Цепляясь за [учение о] <em>трех природах</em></li>
            <li>и видя схватывающего и схватываемое,</li>
            <li>обычные люди измышляют мирские и надмирские дхармы.<a href="#citation-742" id="ref-742" class="citation-mark"><sup>742</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>674. Поэтому принятие [понятия] «собственной природы»</li>
            <li>приводится лишь как предварительный тезис (<em>pūrvapakṣa</em>);</li>
            <li>ради устранения [ложных] воззрений</li>
            <li>не следует измышлять «собственную природу».<a href="#citation-743" id="ref-743" class="citation-mark"><sup>743</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>675. Из-за изъяна разрыва (<em>chidra-doṣa</em>)</li>
            <li>нет устойчивого установления (<em>niyama</em>),</li>
            <li>и ум не разворачивается.</li>
            <li>И при схватывании двойственности разворачивания</li>
            <li>Таковость всегда недвойственна.<a href="#citation-744" id="ref-744" class="citation-mark"><sup>744</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>676. Неведение, жажда, карма, сознание и прочее —</li>
            <li>не имеют источника (<em>ayonijāḥ</em>).</li>
            <li>Следовательно, становление (<em>bhava</em>) не возникает,</li>
            <li>потому что не является ни «падением в бесконечность» (<em>anavasthā</em>),</li>
            <li>ни «сотворённостью» (<em>kṛtakatva</em>).<a href="#citation-745" id="ref-745" class="citation-mark"><sup>745</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>677. Неразумные говорят о четырёх видах разрушения явлений.</li>
            <li>[Но] в различении с двойственным разворачиванием</li>
            <li>не обнаруживается ни бытие, ни небытие —</li>
            <li>оно свободно от четырёх крайностей</li>
            <li>и лишено двойственных воззрений.<a href="#citation-746" id="ref-746" class="citation-mark"><sup>746</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>678. Когда видишь, что различение —</li>
            <li>лишь двойственное разворачивание,</li>
            <li>оно более не разворачивается.</li>
            <li>Ведь в нерождённых явлениях</li>
            <li>разум уже находится вне потока.<a href="#citation-747" id="ref-747" class="citation-mark"><sup>747</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>679. [Махамати:] — Даже в возникших явлениях —</li>
            <li>поскольку они воображаемы —</li>
            <li>не следует ничего измышлять.</li>
            <li>О Владыка, открой мне рассуждение,</li>
            <li>что устраняет двойственные воззрения!</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>680. Чтобы я и другие всегда не впадали в «есть» и «нет»,</li>
            <li>не соприкасались с учениями иноверцев,</li>
            <li>отличались от шраваков</li>
            <li>и сохраняли практику постижения Победителей</li>
            <li>не отпадая от пути сыновей Победителя.<a href="#citation-748" id="ref-748" class="citation-mark"><sup>748</sup></a></li>
        </ul>
    </blockquote>

</div>

<!— Гатхи 681-732 —>
<div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">

    <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>681. [Будда]: — Освобождение (<em>vimokṣa</em>), причина (<em>hetu</em>)</li>
            <li>и беспричинность (<em>ahetu</em>) — всё это, когда сводится</li>
            <li>к единому признаку не-возникновения (<em>anutpāda-eka-lakṣaṇa</em>),</li>
            <li>вводит в заблуждение множеством способов выражения (<em>paryāya</em>);</li>
            <li>мудрым следует этого избегать.<a href="#citation-749" id="ref-749" class="citation-mark"><sup>749</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>682. Подобны облакам, грозовым тучам, сиянию радуги,</li>
            <li>мареву, волоскам перед глазами и иллюзии —</li>
            <li>воистину, все явления возникают из собственного различения;</li>
            <li>иноверцы же измышляют мир через свои причины.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>683. Не-возникновение (<em>anutpāda</em>), Таковость (<em>tathatā</em>),</li>
            <li><em>Предел истинности</em> и <em>шуньята</em> (<em>śūnyatā</em>) —</li>
            <li>всё это — имена формы (<em>rūpa</em>);</li>
            <li>не следует измышлять их как небытие (<em>abhāva</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>684. Как «рука» и «кисть» в мире — одно,</li>
            <li>и Индра, Шакра, Пурандара — одно,</li>
            <li>так и относительно всех явлений</li>
            <li>не следует измышлять небытие.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>685. <em>Шуньята</em> неотлична от формы, так же как и не-возникновение.</li>
            <li>Не следует измышлять их как различное, поскольку они не отличны;</li>
            <li>иначе неизбежно возникает изъян воззрения.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>686. После схватывания (<em>saṃgraha</em>) признаков объектов (<em>vastu-lakṣaṇa</em>)</li>
            <li>возникают воображение (<em>saṃkalpa</em>) и различение (<em>vikalpa</em>).</li>
            <li>А из схватывания (<em>saṃgraha</em>) воображаемого (<em>parikalpa</em>) проистекают</li>
            <li>такие понятия, как «длинное», «короткое», «круглое» и прочие.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>687. Схватывание — это ум (<em>citta</em>), воображение — <em>манас</em> (<em>manas</em>),</li>
            <li>различение — ментальное сознание (<em>manovijñāna</em>);</li>
            <li>по своей природе всё это свободно от определяемого и признака.<a href="#citation-750" id="ref-750" class="citation-mark"><sup>750</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>688. Если полагать, что «не-возникновение» у тиртхиков</li>
            <li>и «не-возникновение», понимаемое как Моё учение,</li>
            <li>не различаются, возникает изъян воззрения.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>689. Цель [учения] — не-возникновение,</li>
            <li>и смысл его — не-возникновение.</li>
            <li>Те, кто понимают это через правильное рассуждение (<em>yukti</em>),</li>
            <li>постигают Моё учение.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>690. Цель — устранение воззрений,</li>
            <li>не-возникновение — лишено опоры (<em>anālayam</em>).</li>
            <li>Благодаря полному постижению (<em>parijñāna</em>)</li>
            <li>двойственности объекта (<em>artha-dvaya</em>) и воспринимающего</li>
            <li>Я и провозглашаю «не-возникновение».<a href="#citation-751" id="ref-751" class="citation-mark"><sup>751</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>691. [Махамати]: — Существуют ли явления</li>
            <li>как нерождённые (<em>anutpanna</em>) или нет?</li>
            <li>Скажи, о Великий Мудрец!</li>
            <li>Не сводится ли нерождённость (<em>anutpāda</em>)</li>
            <li>к учению о беспричинности (<em>ahetuvāda</em>)</li>
            <li>излагаемому иноверцами?</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>692. [Будда]: — Учение о беспричинности (<em>ahetuvāda</em>)</li>
            <li>и [их] «нерождённость» —</li>
            <li>искажённое воззрение (<em>viṣama-darśana</em>) иноверцев;</li>
            <li>я же провозглашаю «только-ум» (<em>cittamātra</em>),</li>
            <li>свободный от «есть» (<em>asti</em>) и «нет» (<em>nāsti</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>693. Следует отвергнуть «возникновение» (<em>utpāda</em>)</li>
            <li>и «нерождённость» (<em>anutpāda</em>),</li>
            <li>когда они основаны на воззрениях (<em>dṛṣṭi-hetuka</em>);</li>
            <li>ибо даже в учениях о беспричинности (<em>ahetuvāda</em>)</li>
            <li>и «нерождённости» (<em>anutpāda</em>)</li>
            <li>«возникновение» опирается на причину (<em>kāraṇāśraya</em>).<a href="#citation-752" id="ref-752" class="citation-mark"><sup>752</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>694. [Махамати]: — Если нет действия без усилия (<em>anābhoga-kriyā</em>),</li>
            <li>то при наличии действия (<em>kriyā</em>)</li>
            <li>возникает смешение воззрений (<em>dṛṣṭi-saṃkara</em>),</li>
            <li>разъясни мне это с точки зрения</li>
            <li>искусных средств (<em>upāya</em>), обетов (<em>praṇidhāna</em>) и прочего.</li>
            <li>Если все дхармы лишены сущности (<em>asattva</em>),</li>
            <li>как возникает эта целостность (<em>maṇḍala</em>)?</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>695. [Будда]: — При отсутствии связи (<em>visaṃyoga</em>)</li>
            <li>между схватываемым (<em>grāhya</em>) и схватывающим (<em>grāhaka</em>)</li>
            <li>нет ни разворачивания (<em>pravṛtti</em>), ни прекращения (<em>nivṛtti</em>).</li>
            <li>Представление о переходе из одного состояния в другое —</li>
            <li>поистине, порождение ума (<em>citta-samutthita</em>).<a href="#citation-753" id="ref-753" class="citation-mark"><sup>753</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>696. [Махамати]: — Объясни мне:</li>
            <li>как понимать не-возникновение (<em>anutpāda</em>) дхарм?</li>
            <li>Ведь если существа этого не постигают,</li>
            <li>то ради них это и должно быть разъяснено.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>697. О Великий Мудрец! Изложи всё это</li>
            <li>без противоречия между предыдущим и последующим,</li>
            <li>свободное от изъянов иноверцев</li>
            <li>и лишённое искажённого учения о беспричинности.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>698. О Лучший из проповедников!</li>
            <li>Скажи мне о не-разворачивании (<em>apravṛtti</em>) и прекращении (<em>nivṛtti</em>),</li>
            <li>свободных от «есть» (<em>asti</em>) и «нет» (<em>nāsti</em>)</li>
            <li>и не-разрушающих причину (<em>hetu</em>) и плод (<em>phala</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>699. Скажи мне о последовательности ступеней (<em>bhūmi-krama</em>)</li>
            <li>и о признаке дхарм (<em>dharma-lakṣaṇa</em>).</li>
            <li>Мир пал в крайности двойственности</li>
            <li>и приведён в смятение воззрениями (<em>dṛṣṭi</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>700. [Будда]: — Через «нерождённость» (<em>anutpāda</em>),</li>
            <li>«возникновение» (<em>utpāda</em>) и прочее</li>
            <li>не постигается причина умиротворения (<em>śama-hetu</em>).</li>
            <li>Воистину, у Меня нет никакой системы (<em>maṇḍala</em>),</li>
            <li>и Я не проповедую никакой «природы дхарм» (<em>dharmatā</em>).<a href="#citation-754" id="ref-754" class="citation-mark"><sup>754</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>701-702. [Махамати]: — Там, где есть двойственность, возникает изъян;</li>
            <li>[говорится, что] двойственность очищена Буддами.</li>
            <li>[Утверждается:] «Явления — пусты (<em>śūnyā</em>), мгновенны (<em>kṣaṇikā</em>),</li>
            <li>лишены собственной природы (<em>niḥsvabhāvā</em>) и нерождены (<em>ajātikā</em>)», —</li>
            <li>но всё это измышляется теми, кто окутан ложными воззрениями,</li>
            <li>а не Татхагатами.</li>
            <li>Объясни мне разворачивание и прекращение различения!<a href="#citation-755" id="ref-755" class="citation-mark"><sup>755</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>703. [Будда]: — Так объект возникает как явленность (<em>mukha</em>):</li>
            <li>он формируется из сочетания цветов и форм</li>
            <li>и развёртывается множащимися умопостроениями (<em>prapañca</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>704. Когда форма (<em>rūpa</em>) воспринимается как внешняя,</li>
            <li>возникает различение (<em>vikalpa</em>).</li>
            <li>Но благодаря полному постижению (<em>parijñāna</em>) именно этого</li>
            <li>и видению действительности такой, какова она есть (<em>yathābhūtam</em>),</li>
            <li>ум (<em>citta</em>), соответствующий роду Благородных (<em>āryagotra</em>),</li>
            <li>не вовлекается в разворачивание (<em>pravṛtti</em>).<a href="#citation-756" id="ref-756" class="citation-mark"><sup>756</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>705. Отвергнув элементы (<em>bhūta</em>) [как нечто внешнее],</li>
            <li>не обнаруживается возникновение существования (<em>bhāva-utpatti</em>).</li>
            <li>Следует постоянно созерцать ум</li>
            <li>как проявляющийся в форме объектов (<em>bhūtākāra</em>)</li>
            <li>и [при этом] нерождённый (<em>anutpanna</em>).<a href="#citation-757" id="ref-757" class="citation-mark"><sup>757</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>706. Не порождай различения (<em>vikalpa</em>)!</li>
            <li>Воистину, мудрецы свободны от различения (<em>nirvikalpāḥ</em>).</li>
            <li>Тот, кто измышляет различение,</li>
            <li>имеет лишь двойственность (<em>dvaya</em>) — не прекращение (<em>nirvṛtti</em>).<a href="#citation-758" id="ref-758" class="citation-mark"><sup>758</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>707. Для того, кто утверждает не-возникновение (<em>anutpāda</em>),</li>
            <li>иллюзия (<em>māyā</em>) используется как способ объяснения (<em>naya</em>).</li>
            <li>Но [считать] иллюзию возникшей без причины (<em>anirhetu</em>) —</li>
            <li>признак утраты (<em>hāni</em>) [верной] позиции (<em>siddhānta</em>).<a href="#citation-759" id="ref-759" class="citation-mark"><sup>759</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>708. Ум (<em>citta</em>) видится подобным отражению (<em>bimba</em>),</li>
            <li>сформированным безначальными представлениями (<em>anādi-mati</em>).</li>
            <li>Он принимает форму объекта (<em>arthākāra</em>),</li>
            <li>но самого объекта (<em>artha</em>) не существует;</li>
            <li>это следует созерцать таким, каково оно есть (<em>yathābhūtam</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>709. Подобно тому как в зеркале видится образ (<em>rūpa</em>),</li>
            <li>свободный от тождества (<em>ekatva</em>) и отличия (<em>anyatva</em>)</li>
            <li>и при этом не отсутствующий, —</li>
            <li>таков признак возникновения (<em>utpāda-lakṣaṇa</em>).<a href="#citation-760" id="ref-760" class="citation-mark"><sup>760</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>710. Как город гандхарвов, иллюзия и прочее</li>
            <li>описываются как возникающие в зависимости</li>
            <li>от причин (<em>hetu</em>) и условий (<em>pratyaya</em>),</li>
            <li>таково и проявление (<em>saṃbhava</em>) всех явлений (<em>bhāva</em>) —</li>
            <li>ведь это не есть не-возникновение (<em>asaṃbhava</em>).<a href="#citation-761" id="ref-761" class="citation-mark"><sup>761</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>711. Различение (<em>vikalpa</em>), облекаясь в образ человека (<em>puruṣākāra</em>),</li>
            <li>разворачивается в двойственном завихрении.</li>
            <li>Посредством условных обозначений «я» и «дхармы»</li>
            <li>оно остаётся нераспознанным для невежд.<a href="#citation-762" id="ref-762" class="citation-mark"><sup>762</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>712. Шравака и даже архат зависят от обширных условий.</li>
            <li>Того же, кто опирается на собственную силу</li>
            <li>и на Победителей, следует вести как пятого шраваку.<a href="#citation-763" id="ref-763" class="citation-mark"><sup>763</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>713. Разрушение со временем, полный распад,</li>
            <li>взаимное уничтожение в высшей истине,</li>
            <li>взаимное непостоянство — эти четыре вида непостоянства</li>
            <li>воображают невежды, лишённые мудрости.<a href="#citation-764" id="ref-764" class="citation-mark"><sup>764</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>714. Невежды, павшие в крайности двойственности,</li>
            <li>верят в гуны, атомы (<em>aṇu</em>), первоматерию (<em>prakṛti</em>), первопричину (<em>kāraṇa</em>).</li>
            <li>Они не знают пути к освобождению</li>
            <li>из-за цепляния (<em>saṃgraha</em>) за предвзятость «есть» (<em>sat</em>) / «нет» (<em>asat</em>).<a href="#citation-765" id="ref-765" class="citation-mark"><sup>765</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>715. Как невежды хватаются за кончик пальца,</li>
            <li>[указывающего на луну] вместо луны,</li>
            <li>так [поступают] и те, кто привязан к словам,</li>
            <li>не постигая Моей истины.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>716. То, что полагают первоэлементами (<em>bhūtāni</em>),</li>
            <li>различающимися по признакам,</li>
            <li>принимают как источники форм и явлений.</li>
            <li>Но всё это — лишь их взаимное расположение (<em>saṃniveśa</em>);</li>
            <li>производное (<em>bhautika</em>) не сотворено самими элементами.<a href="#citation-766" id="ref-766" class="citation-mark"><sup>766</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>717. Огонь сжигает форму, стихия воды — увлажняет,</li>
            <li>ветер — развеивает форму.</li>
            <li>Как же тогда форма может порождаться элементами?</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>718. Форма и сознание — это два, а не пять.</li>
            <li>Различия в способах обозначения <em>скандх</em></li>
            <li>Я излагаю сотнями способов.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>719. Через различие ума (<em>citta</em>) и ментальных факторов (<em>caitta</em>)</li>
            <li>разворачивается происходящее. Формы различны,</li>
            <li>но форма — это ум, не состоящий из элементов (<em>na bhautikam</em>).<a href="#citation-767" id="ref-767" class="citation-mark"><sup>767</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>720. Белое зависит от синего и прочего; синее — от белого.</li>
            <li>Выстроив в уме причину и следствие,</li>
            <li>[невежды] судят о шуньяте</li>
            <li>как о «существующей» и «несуществующей».<a href="#citation-768" id="ref-768" class="citation-mark"><sup>768</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>721. Средство установления (<em>sādhana</em>),</li>
            <li>устанавливающий (<em>sādhaka</em>) и устанавливаемое (<em>sādhya</em>);</li>
            <li>холод и жар; определяемое и его признак —</li>
            <li>всё это и подобное этому не может быть обосновано логиками (<em>tārkikaiḥ</em>).<a href="#citation-769" id="ref-769" class="citation-mark"><sup>769</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>722. Ум (<em>citta</em>), <em>манас</em> (<em>manas</em>) и шесть других сознаний,</li>
            <li>рассматриваемые как связанные с «я»,</li>
            <li>лишены как единства, так и различия —</li>
            <li>всё это есть разворачивание <em>Алаи</em>.<a href="#citation-770" id="ref-770" class="citation-mark"><sup>770</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>723. Последователи Санкхьи, Вайшешики, нагие аскеты (джайны) (<em>nagna</em>),</li>
            <li>логики (<em>tārkika</em>), проповедующие Ишвару (<em>īśvara-udita</em>) —</li>
            <li>все они впали в пристрастие (<em>pakṣa</em>) к бытию и небытию (<em>sat-asat</em>),</li>
            <li>и лишены (<em>vivarjita</em>) постижения уединённого смысла (<em>vivikta-artha</em>).<a href="#citation-771" id="ref-771" class="citation-mark"><sup>771</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>724. Ни расположение (<em>saṃsthāna</em>), ни очертания (<em>ākṛti</em>),</li>
            <li>ни особенности (<em>viśeṣa</em>) элементов (<em>bhūta</em>)</li>
            <li>не являются составленными из них (<em>bhautika</em>).</li>
            <li>Тиртхики же утверждают возникновение (<em>janma</em>) и элементов,</li>
            <li>и того, что из них составлено (<em>bhautika</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>725. Дхармы не возникают, но тиртхики,</li>
            <li>опираясь на [идею] причины, воображают возникновение.</li>
            <li>Будучи омрачёнными, они не понимают этого и потому</li>
            <li>придерживаются позиций «есть» и «нет».</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>726. Соединённое с умом (<em>citta</em>),</li>
            <li>разъединённое с <em>манасом</em> (<em>manas</em>) и прочими [сознаниями],</li>
            <li>[пробуждённое] существо (<em>sattva</em>),</li>
            <li>обладающее чистым признаком (<em>lakṣaṇa</em>),</li>
            <li>пребывает вместе с мудростью (<em>jñāna</em>).<a href="#citation-772" id="ref-772" class="citation-mark"><sup>772</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>727. Карма (<em>karma</em>) и то, что возникает как форма (<em>rūpa</em>),</li>
            <li>обусловлены <em>скандхами</em>, объектами (<em>viṣaya</em>) и причинами (<em>hetu</em>).</li>
            <li>[Пробуждённые] существа (<em>sattva</em>), свободные от цепляния (<em>nirupādāna</em>),</li>
            <li>не пребывают даже в мире без-форм (<em>ārūpya</em>).<a href="#citation-773" id="ref-773" class="citation-mark"><sup>773</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>728. Если [смешать] учение об отсутствии «я» (<em>nairātmya</em>)</li>
            <li>с утверждением существа (<em>sattva</em>),</li>
            <li>то из отсутствия существа (<em>sattvābhāva</em>) следует противоречие (<em>prasajyate</em>).</li>
            <li>Для утверждающего отсутствие «я» (<em>nairātmya-vādin</em>)</li>
            <li>возникает крайность уничтожения (<em>uccheda</em>),</li>
            <li>и даже сознание (<em>vijñāna</em>) становится невозможным (<em>asaṃbhava</em>).<a href="#citation-774" id="ref-774" class="citation-mark"><sup>774</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>729. Как могут устоять четыре [позиции] (<em>catvāraḥ sthitāḥ</em>) для него,</li>
            <li>если [отрицать] наличие формы (<em>rūpa</em>)?</li>
            <li>В силу отсутствия (<em>abhāva</em>) внутреннего (<em>adhyātma</em>) и внешнего (<em>bāhya</em>) —</li>
            <li>сознание (<em>vijñāna</em>) вовсе не развёртывается (<em>na pravartate</em>).<a href="#citation-775" id="ref-775" class="citation-mark"><sup>775</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>730. Логики (<em>tārkika</em>) утверждают <em>скандхи</em> [как опору]</li>
            <li>для промежуточного состояния (<em>antarābhava</em>),</li>
            <li>[но] разве не существует становления (<em>bhava</em>) без формы (<em>arūpa</em>)</li>
            <li>для рождённого (<em>upapanna</em>) в мире без-форм (<em>ārūpya</em>)?<a href="#citation-776" id="ref-776" class="citation-mark"><sup>776</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>731. Без существа (<em>sattva</em>) и сознания (<em>vijñāna</em>)</li>
            <li>освобождение (<em>mokṣa</em>) наступало бы без усилий (<em>aprayatnena</em>).</li>
            <li>Это, без сомнения, учение тиртхиков,</li>
            <li>[но] логики этого не осознают.<a href="#citation-777" id="ref-777" class="citation-mark"><sup>777</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>732. [Допустим,] форма (<em>rūpa</em>) существует там,</li>
            <li>но в мире без-форм (<em>ārūpya</em>) нет видения (<em>darśana</em>).</li>
            <li>Отсутствие того (<em>tad-abhāva</em>) —</li>
            <li>это не установленная позиция (<em>siddhānta</em>),</li>
            <li>ни Путь (<em>yāna</em>), ни Путник (<em>yāyin</em>).<a href="#citation-778" id="ref-778" class="citation-mark"><sup>778</sup></a></li>
        </ul>
    </blockquote>

</div>

<!— Гатхи 733-780 —>
<div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">

    <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>733. [Махамати]: — Связанное с органами чувств (<em>indriya</em>)</li>
            <li>и возникающее из отпечатков (<em>vāsanā</em>),</li>
            <li>восьмеричное [сознание] (<em>aṣṭavidha</em>), [взятое] как единое (<em>ekadeśa</em>),</li>
            <li>поистине не схватывается в одно мгновение времени.<a href="#citation-779" id="ref-779" class="citation-mark"><sup>779</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>734. Когда форма (<em>rūpa</em>) не проявляется, и органы [не действуют],</li>
            <li>и [действие] посредством органов отсутствует,—</li>
            <li>именно поэтому Благословенный учит:</li>
            <li>органы и прочее (<em>indriyādayaḥ</em>) мгновенны (<em>kṣaṇika</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>735. Если форма (<em>rūpa</em>) не установлена,</li>
            <li>как сознание (<em>vijñāna</em>) может развёртываться?</li>
            <li>Если знание (<em>jñāna</em>) не развёртывается,</li>
            <li>как оно породит сансару (<em>saṃsāra</em>)?<a href="#citation-780" id="ref-780" class="citation-mark"><sup>780</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>736. [Будда]: — Наставники (<em>vināyaka</em>) не учат,</li>
            <li>что разрушение (<em>bhaṅga</em>) следует</li>
            <li>непосредственно за возникновением (<em>utpatti</em>).</li>
            <li>У явлений (<em>bhāva</em>) нет непрерывности (<em>nairantarya</em>) в том процессе (<em>gati</em>),</li>
            <li>который представляет собой пульсацию различения (<em>vikalpa-spandita</em>).<a href="#citation-781" id="ref-781" class="citation-mark"><sup>781</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>737. Органы чувств (<em>indriya</em>) и их объекты (<em>indriyārtha</em>) —</li>
            <li>[утверждаются] у заблуждающихся (<em>mūḍha</em>), но не у мудрых (<em>paṇḍita</em>).</li>
            <li>Невежды (<em>bāla</em>) схватывают [всё] по именам (<em>nāma</em>);</li>
            <li>благородные (<em>ārya</em>) же — знатоки смысла (<em>artha-kovida</em>).<a href="#citation-782" id="ref-782" class="citation-mark"><sup>782</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>738. Шестое [сознание] поистине без присвоения (<em>upādāna</em>);</li>
            <li>оно не схватывается как имеющее присвоение.</li>
            <li>Благородные (<em>ārya</em>), свободные от ошибки «существования» (<em>asti-doṣa</em>),</li>
            <li>называют его неопределимым (<em>anirdhārya</em>).<a href="#citation-783" id="ref-783" class="citation-mark"><sup>783</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>739. Логики (<em>tārkika</em>), страшащиеся крайностей</li>
            <li>вечности (<em>śāśvata</em>) и уничтожения (<em>uccheda</em>) и лишённые знания (<em>jñāna</em>),</li>
            <li>не различают обусловленное (<em>saṃskṛta</em>)</li>
            <li>и необусловленное (<em>asaṃskṛta</em>) как таковые;</li>
            <li>они — глупцы (<em>bāliśa</em>).<a href="#citation-784" id="ref-784" class="citation-mark"><sup>784</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>740. Даяние (<em>dāna</em>) обнаруживается</li>
            <li>и как единое, и как отличное.</li>
            <li>Единство — с умом (<em>citta</em>), а различие —</li>
            <li>с <em>манасом</em> (<em>manas</em>) и прочими.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>741. Когда даяние определяется как «ум</li>
            <li>и так называемые ментальные факторы» (<em>caitta</em>),</li>
            <li>то как, вследствие присвоения (<em>upādāna</em>),</li>
            <li>там можно установить единство?<a href="#citation-785" id="ref-785" class="citation-mark"><sup>785</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>742. Установление [чего-либо] как наделённого присвоением (<em>sopādāna</em>)</li>
            <li>логики будут доказывать через карму, рождение, действие и прочее,</li>
            <li>по аналогии с огнём (<em>agni</em>),</li>
            <li>используя доводы сходства и различия (<em>sadṛśa-asadṛśa-naya</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>743. Подобно тому как огонь одновременно сжигаем и сжигает —</li>
            <li>сжигаемое и сжигающее (<em>dāhya-dāhaka</em>), —</li>
            <li>так же и «я» (<em>ātman</em>), наделённое присвоением, —</li>
            <li>почему же логики (<em>tārkika</em>) [этого] не принимают?<a href="#citation-786" id="ref-786" class="citation-mark"><sup>786</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>744. Независимо от возникновения или не-возникновения —</li>
            <li>ум (<em>citta</em>) поистине всегда сияющий (<em>bhāsvara</em>).</li>
            <li>Почему же логики (<em>tārkika</em>), стремящиеся доказать «я» (<em>ātman</em>),</li>
            <li>не приводят это в качестве примера (<em>dṛṣṭānta</em>)?<a href="#citation-787" id="ref-787" class="citation-mark"><sup>787</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>745. Запутавшиеся в дебрях сознания (<em>vijñāna-gahvara</em>),</li>
            <li>логики (<em>tārkika</em>), лишённые верного способа (<em>naya</em>),</li>
            <li>мечутся туда-сюда, желая обосновать</li>
            <li>учение о «я» (<em>ātma-vāda</em>).<a href="#citation-788" id="ref-788" class="citation-mark"><sup>788</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>746. «Я» (<em>ātman</em>) с признаком чистоты (<em>śuddhi-lakṣaṇa</em>),</li>
            <li>постигается лишь внутренним опытом (<em>pratyātma-gati-gamya</em>).</li>
            <li>Это — Лоно Татхагаты (<em>tathāgata-garbha</em>),</li>
            <li>недоступное пониманию логиков (<em>tārkika</em>).<a href="#citation-789" id="ref-789" class="citation-mark"><sup>789</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>747. Если различаются присваиваемое (<em>upādāna</em>)</li>
            <li>и присваивающий (<em>upādātṛ</em>),</li>
            <li>а также признак (<em>lakṣaṇa</em>) двух [аспектов] <em>скандх</em>, —</li>
            <li>рождается знание (<em>jñāna</em>) как верный способ видения (<em>naya</em>).<a href="#citation-790" id="ref-790" class="citation-mark"><sup>790</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>748. <em>Алая</em> (<em>ālaya</em>) в образе зародыша (<em>garbha</em>) —</li>
            <li>так её истолковывают тиртхики:</li>
            <li>соединяя её с «я» (<em>ātman</em>)</li>
            <li>и не провозглашая дхарм [как они есть].<a href="#citation-791" id="ref-791" class="citation-mark"><sup>791</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>749. Через различение этих [категорий] (<em>pravibhāga</em>) наступают</li>
            <li>освобождение (<em>vimokṣa</em>) и видение истины (<em>satyadarśana</em>),</li>
            <li>а также очищение (<em>viśodhana</em>) от омрачений (<em>kleśa</em>)</li>
            <li>и от явлений, подлежащих устранению на пути видения (<em>darśya-heya</em>).<a href="#citation-792" id="ref-792" class="citation-mark"><sup>792</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>750. Ум (<em>citta</em>), сияющий по природе (<em>prakṛti-prabhāsvara</em>), —</li>
            <li>благое Лоно Татхагаты (<em>tathāgata-garbha śubha</em>).</li>
            <li>Поистине, он выступает как основа (<em>upādāna</em>) для живых существа (<em>sattva</em>),</li>
            <li>свободный от крайностей конечности и бесконечности.<a href="#citation-793" id="ref-793" class="citation-mark"><sup>793</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>751. Подобно тому как сияние (<em>kānti</em>) золота —</li>
            <li>в самородном золоте (<em>jātarūpa</em>) и в песке (<em>śarkara</em>) —</li>
            <li>становится видно после очистки (<em>parikarma</em>),</li>
            <li>так и существо (<em>sattva</em>) распознаётся в совокупности <em>скандх</em>.<a href="#citation-794" id="ref-794" class="citation-mark"><sup>794</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>752. Будда — не личность (<em>pudgala</em>) и не <em>скандхи</em>;</li>
            <li>[он есть] незапятнанное знание (<em>anāsrava-jñāna</em>).</li>
            <li>Узрев постоянный покой (<em>sadāśānti</em>),</li>
            <li>поистине, я иду под прибежище.<a href="#citation-795" id="ref-795" class="citation-mark"><sup>795</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>753. Ум (<em>citta</em>), по природе сияющий (<em>prakṛti-prabhāsvara</em>),</li>
            <li>через вторичные омрачения (<em>upakleśa</em>) и <em>манас</em> (<em>manas</em>)</li>
            <li>и прочее выступает как связанный с «я» (<em>ātman</em>) —</li>
            <li>так учит Лучший из наставников.<a href="#citation-796" id="ref-796" class="citation-mark"><sup>796</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>754. Ум (<em>citta</em>) по природе сияющий;</li>
            <li><em>манас</em> (<em>manas</em>) и прочее выступают по отношению к нему как иное.</li>
            <li>Ими накапливаются кармы,</li>
            <li>и потому оба вовлекаются в омрачение.<a href="#citation-797" id="ref-797" class="citation-mark"><sup>797</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>755. «Я» (<em>ātman</em>) по природе сияющее (<em>prabhāsvara</em>)</li>
            <li>омрачается пришлыми (<em>āgantuka</em>) и безначальными (<em>anādi</em>) загрязнениями;</li>
            <li>будучи ими охвачено (<em>upeta</em>),</li>
            <li>оно очищается — подобно одежде.<a href="#citation-798" id="ref-798" class="citation-mark"><sup>798</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>756. Подобно тому как ткань без грязи или золото,</li>
            <li>свободное от примесей, остаются и не уничтожаются, —</li>
            <li>так и «я» (<em>ātman</em>) без омрачений</li>
            <li>остаётся и не уничтожается.<a href="#citation-799" id="ref-799" class="citation-mark"><sup>799</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>757. Как несведущий может искать</li>
            <li>сладость звука в лютне, раковине или барабане —</li>
            <li>так же [он ищет] «личность» (<em>pudgala</em>) в <em>скандхах</em>.<a href="#citation-800" id="ref-800" class="citation-mark"><sup>800</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>758. Подобно тому как клады, драгоценности</li>
            <li>и вода под землёй — присутствуют, но не видны, —</li>
            <li>так и «личность» (<em>pudgala</em>) не обнаруживается в <em>скандхах</em>.<a href="#citation-801" id="ref-801" class="citation-mark"><sup>801</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>759. Совокупность ума и ментальных факторов,</li>
            <li>обладающую собственными качествами (<em>guṇa</em>)</li>
            <li>и связанную со <em>скандхами</em>, несведущие не постигают —</li>
            <li>так же [они не постигают] «личность» в <em>скандхах</em>.<a href="#citation-802" id="ref-802" class="citation-mark"><sup>802</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>760. Подобно тому как плод во чреве существует, но не виден, —</li>
            <li>так и тот, кто не владеет правильным методом (<em>yukti</em>),</li>
            <li>не видит «я» (<em>ātman</em>) в <em>скандхах</em>.<a href="#citation-803" id="ref-803" class="citation-mark"><sup>803</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>761. Подобно тому как не знающие правильного метода (<em>ayuktijña</em>)</li>
            <li>не видят сути (<em>sāra</em>) в лекарственных травах (<em>auṣadhi</em>)</li>
            <li>или огня (<em>agni</em>) в дровах (<em>indhana</em>), —</li>
            <li>так же они не видят «личность» (<em>pudgala</em>) в <em>скандхах</em>.<a href="#citation-804" id="ref-804" class="citation-mark"><sup>804</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>762. Подобно тому как знающие (<em>budha</em>) не видят</li>
            <li>непостоянство (<em>anityatā</em>) во всех явлениях (<em>sarvabhāva</em>)</li>
            <li>и <em>шуньяту</em> (<em>śūnyatā</em>), хотя они и присутствуют, —</li>
            <li>точно так же не видят «личность» (<em>pudgala</em>) в <em>скандхах</em>.<a href="#citation-805" id="ref-805" class="citation-mark"><sup>805</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>763. Ступени (<em>bhūmi</em>), <em>владение [силами]</em> (<em>vaśitā</em>), <em>высшие знания</em> (<em>abhijñā</em>),</li>
            <li>а также высшее посвящение (<em>abhiṣeka</em>), <em>самадхи</em> и особые достижения —</li>
            <li>поистине, не существуют, если не признаётся «я» (<em>ātman</em>).<a href="#citation-806" id="ref-806" class="citation-mark"><sup>806</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>764. Когда утверждающий уничтожение (<em>vaināśika</em>), придя, скажет:</li>
            <li>«Если [оно] существует — покажи!»,</li>
            <li>— знающий (<em>vijña</em>) должен ответить:</li>
            <li>«Покажи собственное умопостроение (<em>svavikalpa</em>)».<a href="#citation-807" id="ref-807" class="citation-mark"><sup>807</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>765. С проповедниками [искажённого] отсутствия «я» (<em>nairātmyavādin</em>),</li>
            <li>отвергающими монашеские дела (<em>bhikṣukarman</em>),</li>
            <li>не следует вести беседы.</li>
            <li>Обладая воззрениями крайностей «есть» и «нет» (<em>sadasat-pakṣa-dṛṣṭi</em>),</li>
            <li>они являются препятствием для Учения Будды.<a href="#citation-808" id="ref-808" class="citation-mark"><sup>808</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>766. Свободное от пороков тиртхиков (<em>tīrtha-doṣa</em>),</li>
            <li>сжигающее лес [воззрений об] отсутствии «я» (<em>nairātmya-vana-dāhaka</em>), —</li>
            <li>это учение о «я» (<em>ātma-vāda</em>) пылает,</li>
            <li>подобно огню конца эпохи.<a href="#citation-809" id="ref-809" class="citation-mark"><sup>809</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>767. Подобно тому как в сахарном тростнике (<em>khaṇḍekṣu</em>),</li>
            <li>сахаре (<em>śarkarā</em>), мёде (<em>madhu</em>), твороге (<em>dadhi</em>),</li>
            <li>кунжуте (<em>tila</em>) и топлёном масле (<em>ghṛta</em>)</li>
            <li>присутствует их собственный вкус (<em>svarasa</em>), —</li>
            <li>не попробовав, он не воспринимается.<a href="#citation-810" id="ref-810" class="citation-mark"><sup>810</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>768. Хотя «я» (<em>ātman</em>) и схватывается пятью способами</li>
            <li>в совокупности <em>скандх</em> (<em>skandhasamucchraya</em>),</li>
            <li>— невежды (<em>avidvāṃsa</em>) его не видят;</li>
            <li>мудрый (<em>vidvān</em>), увидев, освобождается.<a href="#citation-811" id="ref-811" class="citation-mark"><sup>811</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>769. Даже с помощью примеров с магией (<em>vidyā</em>) и прочего</li>
            <li>ум (<em>citta</em>) не определяется.</li>
            <li>Ни где [он], ни откуда, ни зачем —</li>
            <li>и его совокупность (<em>samūha</em>) — всё это не постигается.<a href="#citation-812" id="ref-812" class="citation-mark"><sup>812</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>770. Поистине, явления (<em>dharma</em>) обладают различными признаками,</li>
            <li>но единый ум (<em>citta</em>) не схватывается.</li>
            <li>Для логиков (<em>tārkika</em>) отсюда неизбежно вытекают</li>
            <li>беспричинность (<em>ahetu</em>) и отсутствие развёртывания (<em>apravṛtti</em>).<a href="#citation-813" id="ref-813" class="citation-mark"><sup>813</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>771. Йогин, созерцающий ум (<em>cittānupaśyī</em>),</li>
            <li>не видит ума в уме.</li>
            <li>Видящий рождается из видимого;</li>
            <li>каково же происхождение видимого от причины?<a href="#citation-814" id="ref-814" class="citation-mark"><sup>814</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>772. Я — из рода Катьяяны,</li>
            <li>явившийся из Чистых Обителей (<em>śuddhāvāsa</em>).</li>
            <li>Я проповедую существам (<em>sattva</em>) Дхарму,</li>
            <li>ведущую в Град Нирваны (<em>nirvāṇa-pura-gāmin</em>).<a href="#citation-815" id="ref-815" class="citation-mark"><sup>815</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>773. Это — древний путь (<em>paurāṇika-vartman</em>);</li>
            <li>им шли Я и те Татхагаты. Тремя тысячами сутр</li>
            <li>они проповедовали Нирвану —</li>
            <li>превосходя (<em>atyadeśayan</em>) [обычное изложение].<a href="#citation-816" id="ref-816" class="citation-mark"><sup>816</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>774. Будда не пробуждается ни в Мире Страстей (<em>kāmadhātu</em>),</li>
            <li>ни в Мире Без Форм (<em>ārūpya</em>);</li>
            <li>он пробуждается в Акаништхе Мира Форм (<em>rūpadhātu</em>),</li>
            <li>[где пребывают] свободные от страсти (<em>vītarāga</em>).<a href="#citation-817" id="ref-817" class="citation-mark"><sup>817</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>775. Объекты (<em>viṣaya</em>) не суть причина рабства (<em>bandha-hetu</em>);</li>
            <li>причина — привязанность к объектам (<em>viṣaya-bandhana</em>).</li>
            <li>Омрачения (<em>kleśa</em>) преодолеваются Знанием (<em>jñāna</em>) —</li>
            <li>это, поистине, обет, подобный лезвию меча (<em>asidhārā-vrata</em>).<a href="#citation-818" id="ref-818" class="citation-mark"><sup>818</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>776. Если «я» (<em>ātman</em>) не признаётся —</li>
            <li>как вообще правомерно [говорить] «есть» или «нет» о явлениях,</li>
            <li>подобных иллюзии и прочему?</li>
            <li>Таковость (<em>tathatā</em>) проявляется неразумным —</li>
            <li>как же она может отсутствовать,</li>
            <li>будучи лишённой «я» (<em>nirātmikā</em>)?<a href="#citation-819" id="ref-819" class="citation-mark"><sup>819</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>777. Поистине, ввиду [природы] сотворённого и несотворённого</li>
            <li>не существует причины, приводящей в действие.</li>
            <li>Всё это — изначально невозникшее (<em>anutpanna</em>),</li>
            <li>но неразумные этого не усматривают.<a href="#citation-820" id="ref-820" class="citation-mark"><sup>820</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>778. Причины (<em>kāraṇa</em>) [по природе] невозникшие;</li>
            <li>условия (<em>pratyaya</em>), считающиеся произведёнными (<em>kṛtaka</em>), — также.</li>
            <li>Оба эти [вида] не являются порождающими —</li>
            <li>как же тогда возникновение мыслится через причины?<a href="#citation-821" id="ref-821" class="citation-mark"><sup>821</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>779. Логики (<em>tārkika</em>) описывают причину как предшествующую,</li>
            <li>последующую или одновременную [со следствием].</li>
            <li>Возникновение явлений объясняется ими на примерах</li>
            <li>светильника, горшка, ученика и прочего.<a href="#citation-822" id="ref-822" class="citation-mark"><sup>822</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>780. Будды не [определяются] через признаки (<em>lakṣaṇa</em>),</li>
            <li>[устанавливаемые] посредством накопленного усилия (<em>abhisaṃskāra</em>).</li>
            <li>Ибо таковы качества Чакравартина (<em>cakravartin</em>) —</li>
            <li>а не то, что провозглашено Буддой.<a href="#citation-823" id="ref-823" class="citation-mark"><sup>823</sup></a></li>
        </ul>
    </blockquote>

</div>

<!— Гатхи 781-831 —>
<div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">

    <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>781. Признак Будд — знание (<em>jñāna</em>),</li>
            <li>свободное от изъянов воззрений (<em>dṛṣṭi-doṣa</em>),</li>
            <li>имеющее своей областью</li>
            <li>прямое личное видение (<em>pratyātma-dṛṣṭi-gatika</em>),</li>
            <li>уничтожающее все изъяны.<a href="#citation-824" id="ref-824" class="citation-mark"><sup>824</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>782. Для глухих, слепых, немых,</li>
            <li>для дряхлых стариков, для живущих враждой,</li>
            <li>и особенно для духовно незрелых (<em>bāla</em>) —</li>
            <li>святая жизнь (<em>brahmacarya</em>) недоступна.<a href="#citation-825" id="ref-825" class="citation-mark"><sup>825</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>783. Некоторые уходят в отречение (<em>pravrajanti</em>),</li>
            <li>[привлечённые] скрытыми (<em>āvṛta</em>) божественными знаками</li>
            <li>и признаками Чакравартина;</li>
            <li>другие же проповедники (<em>pravādin</em>) этого не признают.<a href="#citation-826" id="ref-826" class="citation-mark"><sup>826</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>784. Вьяса, Канада, Ришабха, Капила,</li>
            <li>Наставник из рода Шакья (<em>śākya-nāyaka</em>) —</li>
            <li>после Моего ухода в Нирвану</li>
            <li>появятся и подобные им.<a href="#citation-827" id="ref-827" class="citation-mark"><sup>827</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>785. Когда пройдёт сто лет после Моей Нирваны,</li>
            <li>явятся Вьяса и Бхарата,</li>
            <li>затем — Пандавы, Кауравы и Рама,</li>
            <li>затем возникнет династия Маурьев.<a href="#citation-828" id="ref-828" class="citation-mark"><sup>828</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>786. За Маурьями последуют Нанды и Гупты,</li>
            <li>затем — варвары (<em>mleccha</em>), низшие среди царей.</li>
            <li>После варваров — смятение войн (<em>śastra-saṃkṣobha</em>),</li>
            <li>после войн — Кали-юга.</li>
            <li>В конце Кали-юги Истинная Дхарма (<em>saddharma</em>)</li>
            <li>людьми взращиваема не будет.<a href="#citation-829" id="ref-829" class="citation-mark"><sup>829</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>787. Всё это и подобное ему, прошедшее, —</li>
            <li>мир (<em>jagat</em>) вращается подобно колесу.</li>
            <li>От соединения огня и солнца</li>
            <li>разрушается Мир Желаний (<em>kāmadhātu</em>).<a href="#citation-830" id="ref-830" class="citation-mark"><sup>830</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>788. Затем вновь утвердится божественное,</li>
            <li>и в том мире развернётся [жизнь]:</li>
            <li>четыре варны (<em>cāturm-varṇa</em>), цари,</li>
            <li>мудрецы-риши (<em>ṛṣi</em>) и сама Дхарма.<a href="#citation-831" id="ref-831" class="citation-mark"><sup>831</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>789. Веды, жертвоприношения и даяния —</li>
            <li>как [части] устоя Дхармы (<em>dharma-sthā</em>) — продолжат существовать.</li>
            <li>Через сказания (<em>ākhyāyika</em>), исторические предания (<em>itihāsa</em>) и прочее,</li>
            <li>прозу, краткие заметки (<em>cūrṇikā</em>) и комментарии (<em>vārtika</em>) —</li>
            <li>мир поистине придёт в смятение</li>
            <li>из-за [передачи] услышанного от меня и подобного ему.<a href="#citation-832" id="ref-832" class="citation-mark"><sup>832</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>790. Доведя окраску до насыщенности,</li>
            <li>пусть затем нарушит равномерность её окраса:</li>
            <li>синей глиной и коровьим навозом</li>
            <li>пусть сделает ткань неравномерно пёстрой.</li>
            <li>Во всех одеяниях облик его остаётся необычным (<em>vicitrāṅga</em>),</li>
            <li>лишённым признаков иноверческих аскетов (<em>tīrthya-liṅga-vivarjita</em>).<a href="#citation-833" id="ref-833" class="citation-mark"><sup>833</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>791. Йогин должен проповедовать Учение (<em>śāsana</em>) —</li>
            <li>это воистину знамя (<em>dhvaja</em>) Будд.</li>
            <li>Следует пить воду, очищенную тканью (<em>vastrapūta</em>),</li>
            <li>носить поясной шнур (<em>kaṭisūtra</em>)</li>
            <li>и принимать подаяние, приходящее в своё время,</li>
            <li>свободное от недостойного (<em>nīca-varjita</em>).<a href="#citation-834" id="ref-834" class="citation-mark"><sup>834</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>792. Одно [рождение] — божественное, из небес (<em>svarga</em>),</li>
            <li>два других — из человеческого рождения.</li>
            <li>Наделённый признаками драгоценности (<em>ratna-lakṣaṇa</em>),</li>
            <li>является владыка мира, рождённый среди богов.<a href="#citation-835" id="ref-835" class="citation-mark"><sup>835</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>793. Он наслаждается небесами и четырьмя континентами (<em>dvīpa</em>),</li>
            <li>правя в согласии с Дхармой (<em>dharma-śāsana</em>).</li>
            <li>Но, долго наслаждаясь ими,</li>
            <li>он приходит в упадок из-за жажды (<em>tṛṣṇā</em>).<a href="#citation-836" id="ref-836" class="citation-mark"><sup>836</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>794. Крита-юга, Трета, Двапара и Кали —</li>
            <li>в Крита-юге являюсь Я и другие,</li>
            <li>а в Кали-юге — Шакьясимха.<a href="#citation-837" id="ref-837" class="citation-mark"><sup>837</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>795. Сиддхартха, сын Шакьев, Вишну, Вьяса и Махешвара —</li>
            <li>и подобные им — будут причислены</li>
            <li>к учениям иных школ (<em>tīrthya</em>) после Моего ухода.<a href="#citation-838" id="ref-838" class="citation-mark"><sup>838</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>796. «Так мною было услышано и прочее» —</li>
            <li>так будет начинаться проповедь Шакьясимхи.</li>
            <li>Затем это станет историческим преданием Вьясы.<a href="#citation-839" id="ref-839" class="citation-mark"><sup>839</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>797. Вишну и Махешвара будут проповедовать учение о творении.</li>
            <li>Всё это и подобное ему произойдёт после Моего ухода.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>798. Мать Моя — Васумати, отец — брахман Праджапати.</li>
            <li>Я буду из рода Катьяяны, по имени —</li>
            <li>Победитель, Свободный от Пыли (<em>Viraja</em>).<a href="#citation-840" id="ref-840" class="citation-mark"><sup>840</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>799. В Чампе Я буду рождён, там же — отец и дед.</li>
            <li>Дед Мой по имени Сомагупта</li>
            <li>будет происходить из Лунной династии.<a href="#citation-841" id="ref-841" class="citation-mark"><sup>841</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>800. Исполнив обеты и отрекшись от мира,</li>
            <li>Я укажу тысячу верных способов видения (<em>naya</em>).</li>
            <li>Дав Махамати посвящение и пророчество,</li>
            <li>Я войду в окончательную Нирвану.<a href="#citation-842" id="ref-842" class="citation-mark"><sup>842</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>801. Мати передаст [учение] Дхарме,</li>
            <li>Дхарма — Мекхале.</li>
            <li>Ученик Мекхалы, по причине слабости,</li>
            <li>в конце цикла разрушит её.<a href="#citation-843" id="ref-843" class="citation-mark"><sup>843</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>802. Кашьяпа, Кракуччханда, Канака и Винайака,</li>
            <li>и Я, Свободный от Пыли, и другие —</li>
            <li>все они Победители, свершившие своё дело.<a href="#citation-844" id="ref-844" class="citation-mark"><sup>844</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>803. В Крита-югу после этого</li>
            <li>появится лидер по имени Мати.</li>
            <li>Он будет Великим Героем (<em>Mahāvīra</em>),</li>
            <li>раскрывающим пять познаваемых.<a href="#citation-845" id="ref-845" class="citation-mark"><sup>845</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>804. Ни в Двапаре, ни в Трете, ни впоследствии в Кали-юге</li>
            <li>не появляются Владыки мира.</li>
            <li>Они пробуждаются в Крита-юге.<a href="#citation-846" id="ref-846" class="citation-mark"><sup>846</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>805. С помощью неотъемлемых признаков (<em>ahārya-lakṣaṇa</em>),</li>
            <li>вместе с десяткой непрерывных элементов (<em>acchinna-daśaka</em>),</li>
            <li>узорами в форме лунных пятен павлина (<em>mora-candra</em>)</li>
            <li>пусть [йогин] украсит верхнюю одежду (<em>uttarīya</em>).<a href="#citation-847" id="ref-847" class="citation-mark"><sup>847</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>806. В два или три пальца (<em>aṅgula</em>) должен быть узор,</li>
            <li>и таким же — расстояние между ними.</li>
            <li>Иначе украшение становится</li>
            <li>привлекательным (<em>lobhanīya</em>) для неразумных (<em>bāliśa</em>).<a href="#citation-848" id="ref-848" class="citation-mark"><sup>848</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>807. Пусть он всегда гасит огонь страсти (<em>rāga-agni</em>),</li>
            <li>пусть омывается водой знания (<em>jñāna-vāri</em>).</li>
            <li>Тройное Прибежище (<em>tri-śaraṇa</em>) йогину</li>
            <li>следует усердно принимать трижды в день (<em>tri-sandhyā</em>).<a href="#citation-849" id="ref-849" class="citation-mark"><sup>849</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>808. Подобно стреле, пучку травы или куску дерева,</li>
            <li>подброшенным вверх: одно, будучи брошено, летит,</li>
            <li>другое — падает; таковы же [последствия]</li>
            <li>благих и неблагих деяний (<em>kuśalākuśala</em>).<a href="#citation-850" id="ref-850" class="citation-mark"><sup>850</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>809. «Одного», [превращающегося] во «многое»,</li>
            <li>не существует нигде — вследствие различия признаков (<em>vailakṣaṇya</em>).</li>
            <li>Ветер и сияние — все [они] выступают</li>
            <li>как схватывающие условия (<em>grāhaka</em>)</li>
            <li>и действуют как дающие [проявление], подобно полю (<em>kṣetra</em>).<a href="#citation-851" id="ref-851" class="citation-mark"><sup>851</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>810. Если бы «одно» воистину становилось «многим»,</li>
            <li>всё было бы несотворённым (<em>akṛtaka</em>).</li>
            <li>Но сотворённое подвержено разрушению —</li>
            <li>таков ход рассуждения (<em>naya</em>) логиков.<a href="#citation-852" id="ref-852" class="citation-mark"><sup>852</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>811. Подобно светильнику и семени — [лишь] по сходству (<em>sādṛśya</em>);</li>
            <li>откуда же [возникает] множественность?</li>
            <li>«Одно» становится «многим» —</li>
            <li>таков ход рассуждения логиков.<a href="#citation-853" id="ref-853" class="citation-mark"><sup>853</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>812. Из кунжута не возникает боб мунг,</li>
            <li>ячмень не служит причиной рису.</li>
            <li>Пшеница и злаки дают [собственные] виды;</li>
            <li>как же «одно» [может стать] «многим»?<a href="#citation-854" id="ref-854" class="citation-mark"><sup>854</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>813. Панини, вождь речи (<em>śabda-netāra</em>), Акшапада,</li>
            <li>Брихаспати — [все они] основатели локаяты (<em>lokāyata-praṇetāra</em>) —</li>
            <li>и Брахмагарбха явятся [в будущем].<a href="#citation-855" id="ref-855" class="citation-mark"><sup>855</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>814. Катьяяна, составитель сутр (<em>sūtra-kartā</em>),</li>
            <li>Яджнявалкья, а также Бхудхука,</li>
            <li>джьотиша и прочее (<em>jyotiṣa-ādi</em>)</li>
            <li>появятся в Кали-юге.<a href="#citation-856" id="ref-856" class="citation-mark"><sup>856</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>815. Из мира совершивших заслуги (<em>puṇyakṛtām lokāt</em>),</li>
            <li>по благу подданных (<em>prajā-bhāgyāt</em>), явится Бали,</li>
            <li>защитник всех дхарм — царь Бали, владыка земли (<em>mahīpati</em>).<a href="#citation-857" id="ref-857" class="citation-mark"><sup>857</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>816. Вальмики, Масуракша, Каутилья и Ашвалаяна —</li>
            <li>эти великие риши появятся в грядущем (<em>anāgata</em>).<a href="#citation-858" id="ref-858" class="citation-mark"><sup>858</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>817. Сиддхартха, сын Шакьев (<em>śākya-tanaya</em>),</li>
            <li>Бхутанта (<em>bhūtānta</em>, «предел явлений») и Панчачудака,</li>
            <li>Вагбали и Медхавин —</li>
            <li>появятся в последующие времена (<em>paścāt-kāla</em>).<a href="#citation-859" id="ref-859" class="citation-mark"><sup>859</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>818. Шкуру антилопы (<em>ajina</em>), посох (<em>daṇḍa-kāṣṭha</em>),</li>
            <li>пояс и диск (<em>cakra-maṇḍala</em>) —</li>
            <li>Брахма и Махешвара даруют это</li>
            <li>[тому, кто] утвердился в лесной обители (<em>vana-bhūmi</em>).<a href="#citation-860" id="ref-860" class="citation-mark"><sup>860</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>819. Явится великий йогин по имени Вираджа (<em>viraja</em>),</li>
            <li>проповедник освобождения (<em>mokṣa-deśaka</em>), Учитель —</li>
            <li>он воистину знамя мудрецов (<em>muni-dhvaja</em>).<a href="#citation-861" id="ref-861" class="citation-mark"><sup>861</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>820. Брахма, вместе с сотнями брахм (<em>brahma-śata</em>)</li>
            <li>и множеством богов, сбросив с небес Мою шкуру антилопы,</li>
            <li>там же исчезает, обуздав себя (<em>vaśin</em>).<a href="#citation-862" id="ref-862" class="citation-mark"><sup>862</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>821. Многообразные одежды (<em>sarva-citra-vāsas</em>),</li>
            <li>чашу для подаяния (<em>bhaikṣya-pātra</em>) —</li>
            <li>Индра, Вирудхака и другие даруют Мне в лесной обители.<a href="#citation-863" id="ref-863" class="citation-mark"><sup>863</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>822. Тот, кто принимает учение</li>
            <li>о невозникновении (<em>anutpāda-vāda</em>) как основание (<em>hetu</em>), —</li>
            <li>может ли нерождённое (<em>ajāta</em>) возникнуть вновь?</li>
            <li>Пытаясь доказать невозникновение,</li>
            <li>он поистине провозглашает лишь слова (<em>vāṅmātra</em>).<a href="#citation-864" id="ref-864" class="citation-mark"><sup>864</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>823. [Говорят,] неведение (<em>avidyā</em>) есть причина развёртывания</li>
            <li>этих моментов ума (<em>citta</em>).</li>
            <li>Каково же то состояние (<em>avasthā</em>) в промежутке (<em>antarā</em>),</li>
            <li>пока форма (<em>rūpa</em>) ещё не возникла?</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>824. Когда непосредственно предшествующее</li>
            <li>полностью прекращено (<em>samanantara-pradhvasta</em>),</li>
            <li>возникает иной момент ума.</li>
            <li>Никакая форма не пребывает;</li>
            <li>опираясь на что, он будет развёртываться?</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>825. Поскольку [момент] ума, имеющий ложную причину (<em>vitatha-hetuka</em>),</li>
            <li>где бы ни развёртывался, сам не установлен (<em>na prasiddha</em>),</li>
            <li>как тогда можно утверждать</li>
            <li>его мгновенное разрушение (<em>kṣaṇabhaṅga</em>)?<a href="#citation-865" id="ref-865" class="citation-mark"><sup>865</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>826. Поистине, сосредоточения (<em>samāpatti</em>) йогинов,</li>
            <li>золотые реликвии Победителей (<em>suvarṇa-jina-dhātu</em>),</li>
            <li>а также сияющие небесные обители (<em>ābhāsvara-vimāna</em>)</li>
            <li>неразрушимы мирскими причинами (<em>loka-kāraṇa</em>).<a href="#citation-866" id="ref-866" class="citation-mark"><sup>866</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>827. Пребывания, обретение дхарм,</li>
            <li>совершенство знания Будд,</li>
            <li>состояние бхикшу и принятие обетов —</li>
            <li>будучи наблюдаемыми, как же они могут быть мгновенными?<a href="#citation-867" id="ref-867" class="citation-mark"><sup>867</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>828. Формы, подобные городу гандхарвов, магии и прочему, —</li>
            <li>как же они могут считаться мгновенными?</li>
            <li>Первоэлементы (<em>bhūta</em>) лишены [истинной]</li>
            <li>природы первоэлементов (<em>abhūtikāś ca bhūtāś ca</em>),</li>
            <li>разве они когда-либо и откуда-либо приходят?<a href="#citation-868" id="ref-868" class="citation-mark"><sup>868</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>829. Ум, имеющий причиной неведение (<em>avidyā-hetuka</em>),</li>
            <li>накопленный безначальными умственными</li>
            <li>построениями (<em>anādi-mati-saṃcita</em>),</li>
            <li>связанный с возникновением и разрушением (<em>utpāda-bhaṅga-saṃbaddha</em>),</li>
            <li>— так он выстраивается логиками</li>
            <li>через рассуждение (<em>tārkikaiḥ saṃprakalpyate</em>).<a href="#citation-869" id="ref-869" class="citation-mark"><sup>869</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>830. Учение санкхьи (<em>sāṃkhyavāda</em>) двояко:</li>
            <li>[оно излагает] учение о преобразовании</li>
            <li>из первопричины (<em>pradhānāt pariṇāmikam</em>).</li>
            <li>В первопричине существует следствие (<em>kārya</em>),</li>
            <li>и следствие утверждается</li>
            <li>через собственную природу (<em>svātma-prasādhitam</em>).<a href="#citation-870" id="ref-870" class="citation-mark"><sup>870</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>831. Первопричина вместе с проявлением (<em>bhāva</em>)</li>
            <li>провозглашается как различие качеств (<em>guṇa-bheda</em>).</li>
            <li>Многообразие причин и следствий (<em>kārya-kāraṇa-vaicitrya</em>)</li>
            <li>в самом преобразовании не обнаруживается.<a href="#citation-871" id="ref-871" class="citation-mark"><sup>871</sup></a></li>
        </ul>
    </blockquote>

</div>

<!— Гатхи 832-884 —>
<div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">

    <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>832. Как чистая ртуть (<em>pārada</em>) не затрагивается</li>
            <li>второстепенными омрачениями (<em>upakleśa</em>),</li>
            <li>так и <em>Алая</em> чиста — она есть основа (<em>āśraya</em>)</li>
            <li>всех воплощённых существ.<a href="#citation-872" id="ref-872" class="citation-mark"><sup>872</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>833. Запах асафетиды, [запах] лука,</li>
            <li>видение плода во чреве беременной,</li>
            <li>солёность [вкуса] от соли и прочего —</li>
            <li>разве всё это не пребывает [скрыто], подобно семени (<em>bījavat</em>)?<a href="#citation-873" id="ref-873" class="citation-mark"><sup>873</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>834. Ни в отличии, ни в неотличии,</li>
            <li>ни в том и другом, ни в отсутствии обоих.</li>
            <li>Присутствие (<em>astitva</em>), свободное от присвоения (<em>nirupādāna</em>),</li>
            <li>не отсутствует и не является обусловленным (<em>saṃskṛta</em>).<a href="#citation-874" id="ref-874" class="citation-mark"><sup>874</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>835. [Согласно этому взгляду,] Атман существует,</li>
            <li>подобно лошади, лишённой коровьей природы,</li>
            <li>будучи отличным от <em>скандх</em>.</li>
            <li>Его называют обусловленным и необусловленным,</li>
            <li>выразимым и невыразимым,</li>
            <li>обладающим собственной природой (<em>svabhāvakam</em>).<a href="#citation-875" id="ref-875" class="citation-mark"><sup>875</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>836. Загрязнённое ошибочным воззрением (<em>malīkṛtaṃ durdṛṣṭyā</em>),</li>
            <li>основанным на рассуждении (<em>yukti</em>), предании (<em>āgama</em>)</li>
            <li>и логических спекуляциях (<em>tarkadṛṣṭyā</em>),</li>
            <li>называют неопределимым «я» (<em>anirdhāryaṃ vadantyātmā</em>).</li>
            <li>Оно не обнаруживается ни в присвоении (<em>upādāne</em>), ни отдельно от него.<a href="#citation-876" id="ref-876" class="citation-mark"><sup>876</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>837. Их ошибка (<em>doṣa-nirdhāraṇā</em>) состоит в том,</li>
            <li>что через <em>скандху</em> рассматривается (<em>vibhāvyate</em>) «я» (<em>ātmā</em>) —</li>
            <li>либо как тождественное ей, либо как отличное от неё.</li>
            <li>Но логики (<em>tārkikā</em>) этого не понимают.<a href="#citation-877" id="ref-877" class="citation-mark"><sup>877</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>838. Подобно тому как в зеркале, в воде или в глазу</li>
            <li>видится (<em>pradṛśyate</em>) отражение (<em>bimba</em>),</li>
            <li>так и «личность» (<em>pudgala</em>) обнаруживается через <em>скандхи</em>,</li>
            <li>оставаясь свободной от тождества и различия с ними.<a href="#citation-878" id="ref-878" class="citation-mark"><sup>878</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>839. Созерцаемое (<em>bhāvya</em>), созерцание (<em>vibhāvanā</em>) и созерцающий (<em>adhyātā</em>) —</li>
            <li>таковы путь и видение истины (<em>satyā ca darśanam</em>).</li>
            <li>Развивая (<em>vibhāvento</em>) эту триаду,</li>
            <li>освобождаются от дурных воззрений (<em>kudarśanaiḥ</em>).<a href="#citation-879" id="ref-879" class="citation-mark"><sup>879</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>840. Подобно молнии (<em>vidyut</em>) —</li>
            <li>появившейся и [тут же] исчезнувшей (<em>dṛṣṭaṃ naṣṭaṃ</em>),</li>
            <li>или огненному колесу (<em>cakraṃ</em>) в доме с прорехами (<em>chidragṛhe</em>) —</li>
            <li>таково изменение (<em>pariṇāma</em>) всех явлений (<em>sarvadharmāṇā</em>).</li>
            <li>Не выстраивай о них понятий (<em>na kalpayet</em>),</li>
            <li>как это делают невежды (<em>bālairiva</em>).<a href="#citation-880" id="ref-880" class="citation-mark"><sup>880</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>841. Понимание нирваны через бытие и небытие (<em>bhāvābhāvena</em>) —</li>
            <li>лишь омрачение ума невежд (<em>bālānāṃ cittamohanam</em>).</li>
            <li>[Она открывается] благодаря подлинному наличию</li>
            <li>видения Благородных (<em>āryadarśanasadbhāvād</em>) и видению [всего]</li>
            <li>в его истинном пребывании (<em>yathāvasthānadarśanāt</em>).<a href="#citation-881" id="ref-881" class="citation-mark"><sup>881</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>842. Лишённым возникновения и распада (<em>utpādabhaṅgarahitaṃ</em>),</li>
            <li>свободным от бытия и небытия (<em>bhāvābhāvavivarjitam</em>),</li>
            <li>свободным от объекта и признака (<em>lakṣyalakṣaṇanirmuktaṃ</em>) —</li>
            <li>[таким] следует созерцать изменение (<em>pariṇāmaṃ vibhāvayet</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>843. Полностью освобождённым от учений тиртхиков (<em>tīrthyavādavinirmuktaṃ</em>),</li>
            <li>лишённым имени и очертания (<em>nāmasaṃsthānavarjitam</em>),</li>
            <li>покоящимся во внутреннем видении (<em>adhyātmadṛṣṭinilayaṃ</em>) —</li>
            <li>[таким] следует созерцать изменение (<em>pariṇāmaṃ vibhāvayet</em>).<a href="#citation-882" id="ref-882" class="citation-mark"><sup>882</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>844. Через соприкосновение и страдание</li>
            <li>разворачиваются состояния богов и адских существ.</li>
            <li>Промежуточное существование (<em>antarābhava</em>) не устанавливается —</li>
            <li>всё это развёртывается сознанием (<em>vijñānena pravartitā</em>).<a href="#citation-883" id="ref-883" class="citation-mark"><sup>883</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>845. Живорождённых, рождённых из яйца,</li>
            <li>из влаги и прочих (<em>jarajāṇḍajasaṃsvedādyā</em>), а также</li>
            <li>возникающих через промежуточное существование (<em>antarābhavasaṃbhavāḥ</em>) —</li>
            <li>эти разнообразные тела существ (<em>sattvakāyā yathā citrā</em>)</li>
            <li>следует созерцать в их приходе и уходе (<em>gatyāgatyāṃ vibhāvayet</em>).<a href="#citation-884" id="ref-884" class="citation-mark"><sup>884</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>846. Лишённые правильного метода</li>
            <li>и свидетельств традиции (<em>yuktyāgamavyapetāni</em>),</li>
            <li>ведущие к разрушению устремления</li>
            <li>к свободе от омрачений (<em>niḥkleśapakṣakṣayāvahā</em>) —</li>
            <li>пустословию воззрений тиртхиков (<em>tīrthyadṛṣṭipralāpāni</em>)</li>
            <li>мудрый не должен следовать (<em>matimān na samācaret</em>).<a href="#citation-885" id="ref-885" class="citation-mark"><sup>885</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>847. Прежде всего (<em>ādau</em>) устанавливается «я» (<em>ātmā</em>),</li>
            <li>[затем] его следует отличать от присвоения (<em>upādānād viśeṣayet</em>).</li>
            <li>Без [такого] установления (<em>anirdhārya</em>) наделять отличиями (<em>viśeṣanti</em>) —</li>
            <li>[всё равно что] наделять отличиями</li>
            <li>сына бесплодной женщины (<em>vandhyāputraṃ viśiṣyate</em>).<a href="#citation-886" id="ref-886" class="citation-mark"><sup>886</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>848. Вижу (<em>paśyāmi</em>) существ (<em>sattvān</em>) божественным [оком] (<em>divyena</em>) —</li>
            <li>[оком], лишённым [обычной] мудрости и плоти (<em>prajñāmāṃsavivarjitam</em>),</li>
            <li>свободным от <em>скандх</em> сансары (<em>saṃsāraskandhanirmuktaṃ</em>) —</li>
            <li>воплощённость (<em>mūrtimān</em>) всех обладающих телом (<em>sarvadehinām</em>).<a href="#citation-887" id="ref-887" class="citation-mark"><sup>887</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>849. Пребывающее в неочищенном и чистом золоте (<em>durvarṇasuvarṇagataṃ</em>),</li>
            <li>лишённое различий между освобождённым</li>
            <li>и неосвобождённым (<em>muktāmuktaviśeṣaṇam</em>) —</li>
            <li>божественное (<em>divyaṃ</em>), свободное от обусловленного (<em>saṃskāravigataṃ</em>),</li>
            <li>созерцается в [самом] обусловленном (<em>saṃskārasthaṃ prapaśyate</em>).<a href="#citation-888" id="ref-888" class="citation-mark"><sup>888</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>850. Воплощённость (<em>mūrtimān</em>) в переходе</li>
            <li>между состояниями существования (<em>gatisaṃdhau</em>)</li>
            <li>поистине недоступна логикам (<em>tārkikāṇām agocaram</em>).</li>
            <li>Превзошедшую человеческий удел (<em>atikrāntamānuṣyagatim</em>)</li>
            <li>[вижу] Я (ahaṃ), [но] не другие, дурные логики (<em>nānye kutārkikāḥ</em>).<a href="#citation-889" id="ref-889" class="citation-mark"><sup>889</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>851. Если «я» (<em>ātmā</em>) не существует (<em>nāsty</em>),</li>
            <li>то как возникает ум (<em>jāyate cittaṃ</em>).</li>
            <li>Откуда развёртывается это (<em>kasmād etat pravartate</em>)?</li>
            <li>Подобно реке, светильнику и семени (<em>nadīdīpabījavat</em>) —</li>
            <li>почему не объясняется его проявление из предшествующего (<em>nirgama</em>)?<a href="#citation-890" id="ref-890" class="citation-mark"><sup>890</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>852. Когда сознание не возникло (<em>anutpanne ca vijñāne</em>),</li>
            <li>не обнаруживается неведение и прочее (<em>ajñānādi na vidyate</em>).</li>
            <li>При его отсутствии (<em>tadabhāve</em>) нет и сознания —</li>
            <li>как же возникает непрерывность сознания (<em>saṃtatyā</em>)?<a href="#citation-891" id="ref-891" class="citation-mark"><sup>891</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>853. Триада времён (<em>adhvatrayam</em>), вневременное (<em>anadhva</em>)</li>
            <li>и неизрекаемое (<em>avaktavya</em>) как пятое —</li>
            <li>это познаваемое буддами (<em>jñeyam etad dhi buddhānām</em>),</li>
            <li>тогда как логиками лишь провозглашается (<em>tārkikaiḥ saṃprakīrtyate</em>).<a href="#citation-892" id="ref-892" class="citation-mark"><sup>892</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>854. Неизрекаемое (<em>avaktavya</em>) знание,</li>
            <li>имеющее обусловленное своей причиной (<em>saṃskārahetukam</em>),</li>
            <li>схватывает то, что пребывает в обусловленном (<em>saṃskāragataṃ</em>).</li>
            <li>Такое знание называется «обусловленным» (<em>saṃskāraśabditam</em>).<a href="#citation-893" id="ref-893" class="citation-mark"><sup>893</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>855. «При наличии этого возникает то» (<em>asmin satīdaṃ bhavati</em>) —</li>
            <li>так описываются условия (<em>pratyayā</em>),</li>
            <li>не имеющие независимой причины (<em>ahetukā</em>).</li>
            <li>Их разъясняют лишь посредством</li>
            <li>условного обозначения (<em>vyañjakena upadiśyante</em>);</li>
            <li>при отсутствии [независимой причины]</li>
            <li>не обнаруживается и действующего начала (<em>na kārakam</em>).<a href="#citation-894" id="ref-894" class="citation-mark"><sup>894</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>856. Ведь ветер лишь раздувает (<em>preraṇe</em>) огонь,</li>
            <li>поддерживая, но не порождает (<em>na tu saṃbhave</em>) его.</li>
            <li>Когда это воздействие прекращается, огонь угасает.</li>
            <li>Как же тогда условия могут служить доказательством</li>
            <li>существования существа (<em>sattvaprasādhakāḥ</em>)?<a href="#citation-895" id="ref-895" class="citation-mark"><sup>895</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>857. Изрекаемое как обусловленное</li>
            <li>и необусловленное (<em>saṃskṛtāsaṃskṛtaṃ vācyam</em>),</li>
            <li>лишено опоры (<em>upādānavivarjitam</em>) —</li>
            <li>как может оно что-либо устанавливать?</li>
            <li>Лишь в воображении глупцов так [существует] огонь.<a href="#citation-896" id="ref-896" class="citation-mark"><sup>896</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>858. Из взаимного действия условий (<em>anyonyasya balādhānād</em>)</li>
            <li>для людей возникает огонь (<em>vahnir vai jāyate</em>).</li>
            <li>Но кем приведено в движение существо (<em>sattvaḥ pravartitaḥ kena</em>),</li>
            <li>раз его мыслят подобным огню (<em>vahnivat kalpyate</em>)?<a href="#citation-897" id="ref-897" class="citation-mark"><sup>897</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>859. Для собрания <em>скандх</em> и <em>аятан</em> (<em>skandhāyatanakadambasya</em>)</li>
            <li>отсутствие «я» (<em>nairātmā</em>) не берёт начала в <em>манасе</em></li>
            <li>и прочем (<em>manādyākāraṇaḥ</em>); подобно каравану (<em>sārthavat</em>),</li>
            <li>оно неотлучно от ума (<em>cittena saha vartate</em>).<a href="#citation-898" id="ref-898" class="citation-mark"><sup>898</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>860. Эти двое (<em>dvāv etau</em>) — непрерывно сияющие (<em>bhāsvarau nityaṃ</em>) —</li>
            <li>свободны от причины и следствия (<em>kāryakāraṇavarjitau</em>).</li>
            <li>Поистине, [пример с] огнём не служит для них доказательством (<em>asādhakas teṣāṃ</em>),</li>
            <li>но логики (<em>tārkikā</em>) этого не осознают.<a href="#citation-899" id="ref-899" class="citation-mark"><sup>899</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>861. Ум, существа и нирвана</li>
            <li>поистине сияющи по своей природе (<em>prakṛtyā bhāsurā</em>).</li>
            <li>Омрачённые безначальными помехами (<em>doṣa</em>),</li>
            <li>[они] нераздельны и подобны пространству (<em>gaganopamāḥ</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>862. Подобно теням слонов, ложей и прочего,</li>
            <li>омрачённые воззрениями тиртхиков (<em>tīrthyadṛṣṭi</em>),</li>
            <li>затемнённые мановиджняной (<em>manovijñāna</em>), —</li>
            <li>[они] очищаются огнём и подобным (<em>agnirādyaiḥ</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>863. Увидев [явления] такими, как они есть (<em>yathābhūta</em>),</li>
            <li>омрачения (<em>kleśa</em>) разрываются.</li>
            <li>Оставив дебри примеров и аналогий (<em>dṛṣṭāntagahana</em>),</li>
            <li>они вступают в сферу Благородных (<em>āryagocara</em>).<a href="#citation-900" id="ref-900" class="citation-mark"><sup>900</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>864. Поскольку через различение знания и познаваемого (<em>jñāna-jñeya-vibhāgena</em>)</li>
            <li>воображается их отличие (<em>anyatvaṃ kalpyate</em>) —</li>
            <li>дурномыслящие (<em>durmedhā</em>) не осознают [истины].</li>
            <li>Хотя и говорится о неизрекаемом (<em>avaktavya</em>), они не постигают его.<a href="#citation-901" id="ref-901" class="citation-mark"><sup>901</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>865. Подобно тому как из сандала (<em>candanajā</em>) глупцы (<em>bāla</em>)</li>
            <li>делают барабан (<em>bherī</em>) — и не иначе, —</li>
            <li>так и дурные логики (<em>kutārkika</em>) [поступают] со знанием (<em>jñāna</em>),</li>
            <li>подобным сандалу и алоэ (<em>candanāgaru-saṃkāśa</em>).<a href="#citation-902" id="ref-902" class="citation-mark"><sup>902</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>866. Поднявшись [после трапезы], [из пищи] остаётся лишь то,</li>
            <li>что прилипло к сосуду (<em>pātra-saṃśrita-mātraka</em>).</li>
            <li>Свободным от изъянов — искажений лица и прочего (<em>mukha-vikārā-ādi</em>) —</li>
            <li>следует правильно обращаться с чистой пищей (<em>śuddha-bhakta</em>).<a href="#citation-903" id="ref-903" class="citation-mark"><sup>903</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>867. Кто постигает этот метод (<em>naya</em>), следуя рассуждению (<em>yuktitaḥ</em>),</li>
            <li>исполнен ясности (<em>prasādavān</em>), предан практике (<em>yoga-paraḥ</em>)</li>
            <li>и свободен от различений (<em>akalpanaḥ</em>), свободен от опор (<em>anāśritaḥ</em>)</li>
            <li>и устремлён к истинному смыслу (<em>artha-paraḥ</em>), —</li>
            <li>тот озаряет золотой путь Дхармы (<em>hiraṇmayī dharma-gati</em>).<a href="#citation-904" id="ref-904" class="citation-mark"><sup>904</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>868. Сеть его дурных воззрений (<em>ku-dṛṣṭi-jāla</em>) запятнанная построениями понятий</li>
            <li>и заблуждением, основанными на представлениях</li>
            <li>о бытии и небытии (<em>bhāva-abhāva-pratyaya-moha-kalpanā</em>), —</li>
            <li>вместе с влечением, неприязнью и гневом (<em>rāga, doṣa, pratigha</em>)</li>
            <li>прекращается (<em>nivartate</em>). Незапятнанный (<em>nirañjana</em>),</li>
            <li>он орошается лучами Будд (<em>buddha-karaiḥ sicyate</em>).<a href="#citation-905" id="ref-905" class="citation-mark"><sup>905</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>869. Тиртхики сбиты с толку [поиском] причины (<em>kāraṇa-dig-mūḍhāḥ</em>);</li>
            <li>другие смущены условиями (<em>pratyaya-vihvalāḥ</em>);</li>
            <li>иные же, утверждая реальность беспричинности (<em>ahetu-sadbhāvāt</em>),</li>
            <li>впадают в нигилизм (<em>uccheda</em>), принимая его за путь Благородных.<a href="#citation-906" id="ref-906" class="citation-mark"><sup>906</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>870. Таково преобразование через созревание (<em>vipāka-pariṇāma</em>)</li>
            <li><em>манаса</em> (<em>manas</em>) и сознания (<em>vijñāna</em>):</li>
            <li><em>манас</em> возникает из <em>Алая-виджняны</em> (<em>ālaya-saṃbhūta</em>),</li>
            <li>а сознание порождается <em>манасом</em> (<em>mano-bhava</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>871. Из <em>Алая-виджняны</em> все сознания (<em>sarva-cittāni</em>)</li>
            <li>разворачиваются, подобно волнам (<em>taraṃga-vat</em>).</li>
            <li>Все обусловлены отпечатками (<em>vāsanā-hetuka</em>)</li>
            <li>и возникают согласно условиям (<em>yathā-pratyaya-saṃbhava</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>872. Связанные последовательностью мгновений (<em>kṣaṇa-bheda-saṃkalā-baddha</em>),</li>
            <li>схватывающие как объекты собственные проявления ума (<em>svacittārtha-vigrāhin</em>),</li>
            <li>принимая вид форм, признаков и образов (<em>saṃsthāna-lakṣaṇa-ākāra</em>) —</li>
            <li>[они] возникают из <em>манаса</em>, [зрительного] органа</li>
            <li>и прочего (<em>mano-cakṣv-ādi-saṃbhava</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>873. Связанное с безначальными помехами (<em>anādi-doṣa-saṃbaddha</em>),</li>
            <li>возникший из васан несуществования объекта (<em>artha-abhāva-vāsanā-udita</em>) —</li>
            <li>ум воспринимается как внешнее (<em>bahirdhā dṛśyate cittaṃ</em>).</li>
            <li>[Понимание] этого — устранение воззрений тиртхиков (<em>tīrtha-dṛṣṭi-nivāraṇa</em>).<a href="#citation-907" id="ref-907" class="citation-mark"><sup>907</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>874. Всё прочее возникает именно из этого</li>
            <li>как причины (<em>tad-hetukam evānyat</em>),</li>
            <li>опираясь на него, разворачивается.</li>
            <li>Когда возникает воззрение (<em>dṛṣṭi</em>) —</li>
            <li>разворачивается и сансара.<a href="#citation-908" id="ref-908" class="citation-mark"><sup>908</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>875. Явления (<em>bhāva</em>), подобные иллюзии и сновидению (<em>māyā-svapna</em>),</li>
            <li>уподобляются городу гандхарвов (<em>gandharva-nagara</em>);</li>
            <li>подобные миражу и луне в воде (<em>marīci-udaka-candra</em>) —</li>
            <li>[всё это] следует созерцать как собственное различение (<em>sva-vikalpa</em>).<a href="#citation-909" id="ref-909" class="citation-mark"><sup>909</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>876. Благодаря прекращению деятельности (<em>vṛtti-bheda</em>) —</li>
            <li>[открывается] Таковость</li>
            <li>и опирающееся на неё совершенное знание (<em>samyagjñāna</em>);</li>
            <li>а также высшие <em>самадхи</em> — «Самадхи иллюзии» (<em>māyā-samādhi</em>),</li>
            <li>«Самадхи, идущего путём героя» (<em>śūraṃgama-samādhi</em>) и прочие.<a href="#citation-910" id="ref-910" class="citation-mark"><sup>910</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>877. Благодаря вступлению на ступени (<em>bhūmipraveśāt</em>) [он] обретает</li>
            <li><em>сверхзнания</em> (<em>abhijñā</em>) и <em>силы</em> (<em>vaśitāni</em>);</li>
            <li><em>тело, подобное магическому знанию</em> (<em>jñāna-māyopama-kāyam</em>),</li>
            <li>и посвящение (<em>abhiṣikta</em>), [даруемое] Сугатами.<a href="#citation-911" id="ref-911" class="citation-mark"><sup>911</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>878. Когда ум (<em>citta</em>) затихает (<em>nivartate</em>),</li>
            <li>мир (<em>jagat</em>) видится успокоенным (<em>nivṛtta</em>);</li>
            <li>обретаются ступень «Радостная» (<em>muditā-bhūmi</em>),</li>
            <li>а затем и ступень Будды (<em>buddhabhūmi</em>).<a href="#citation-912" id="ref-912" class="citation-mark"><sup>912</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>879. Когда основание [ума] преобразовано (<em>āśrayeṇa nivṛttena</em>),</li>
            <li>[он], подобный драгоценному камню [чинтамани],</li>
            <li>принимающему все формы (<em>viśvarūpa maṇi</em>),</li>
            <li>совершает деяния ради существ (<em>sattva-kṛtyāni</em>),</li>
            <li>подобно отражениям в воде (<em>pratibimba jale</em>).<a href="#citation-913" id="ref-913" class="citation-mark"><sup>913</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>880. Свободная от сторон бытия и небытия (<em>sadasat-pakṣa-nirmuktam</em>),</li>
            <li>[не принимающая] ни то, ни другое, ни их совместность,</li>
            <li>ни её отрицание (<em>ubhayaṃ nobhayaṃ na ca</em>);</li>
            <li>выходящая за пределы [путей] пратьекабудд и шраваков —</li>
            <li>[такой] становится седьмая ступень (<em>saptamī bhavet</em>).<a href="#citation-914" id="ref-914" class="citation-mark"><sup>914</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>881. Для тех, чьи дхармы постигаются через непосредственное</li>
            <li>внутреннее видение (<em>pratyātma-dṛṣṭa-dharma</em>), [путь],</li>
            <li>очищающий подлинные ступени (<em>bhūta-bhūmi-viśodhita</em>),</li>
            <li>свободный от внешних воззрений тиртхиков (<em>bāhya-tīrthya-vinirmukta</em>) —</li>
            <li>следует провозгласить Махаяной (<em>mahāyānaṃ vinirdiśet</em>).<a href="#citation-915" id="ref-915" class="citation-mark"><sup>915</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>882. Разворот различения (<em>parāvṛttir vikalpasya</em>),</li>
            <li>лишённый упадка и уничтожения (<em>cyuti-nāśa-varjita</em>),</li>
            <li>подобный волосу зайца и драгоценному камню (<em>śaśaroma-maṇi-prakhya</em>) —</li>
            <li>[этот] метод следует провозглашать</li>
            <li>освобождённым (<em>muktānāṃ deśayet nayam</em>).<a href="#citation-916" id="ref-916" class="citation-mark"><sup>916</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>883. Подобно тому как текст проясняется текстом (<em>grantho granthena</em>),</li>
            <li>так и рассуждение проверяется рассуждением (<em>yuktyā yuktiḥ</em>);</li>
            <li>если из этого возникает верная логика (<em>yuktir bhaved</em>),</li>
            <li>не следует выстраивать её иначе (<em>anyathā tu na kalpayet</em>).<a href="#citation-917" id="ref-917" class="citation-mark"><sup>917</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>884. Зрение (<em>cakṣuḥ</em>), карма (<em>karma</em>) и жажда (<em>tṛṣṇā</em>),</li>
            <li>а также неведение (<em>avidyā</em>) как лоно (<em>yoni</em>);</li>
            <li>зримый образ и зрение (<em>cakṣu-rūpe</em>), <em>манас</em> (<em>manas</em>),</li>
            <li>а также замутнённый ум (<em>āvila-manas</em>)…<a href="#citation-918" id="ref-918" class="citation-mark"><sup>918</sup></a></li>
        </ul>
    </blockquote>

    <p class="text-center font-bold mt-8">Так завершается Махаяна-сутра, именуемая «Благородная Ланкаватара-сутра» (<em>āryasaddharmalaṅkāvatāra</em>), вместе с разделом гатх (<em>sagāthaka</em>).</p>

    <p class="text-center mt-4">Те дхармы, что возникают из причины (<em>hetuprabhavā</em>), —<br>
    их причину Татхагата поведал;<br>
    и то, как [происходит] их прекращение (<em>nirodho</em>), —<br>
    об этом говорит Великий Шрамана.</p>

</div>


