<div class="citations mt-4 text-lg">
    <h4 class="text-center text-gray-800 font-bold text-xl my-4">ПРИМЕЧАНИЯ</h4>
<hr class="my-8 border-t-4 border-gray-500">
     <p class="my-2" id="citation-496"><sup>496</sup> Махамати восхваляет Будду, который воспринимая мир как иллюзию, не теряет при этом бесконечной любви к тем, кто в этой иллюзии запутался.<a href="#ref-496" class="text-blue-500 hover:underline ml-2">↩</a></p>
    <p class="my-2" id="citation-497"><sup>497</sup> Вечность и уничтожение — это две бездны, в которые падает человеческий разум: вера в то, что есть нечто постоянное (душа, бог, материя), что никогда не меняется и вера в то, что после смерти всё просто исчезает в «ничто», и никакой связи причин и следствий нет. Если в 1-й гатхе мир сравнивался с «цветком в небе» (абсолютное отсутствие), то здесь — со сном. Во сне всё кажется очень реальным: ты чувствуешь вкус, страх, радость. Но когда ты просыпаешься, ты понимаешь, что всё это было лишь «игрой ума». Мир — это «коллективный сон», который обладает логикой, пока ты в нем, но лишен сущности, если смотреть из пробужденного состояния. Мир не «становится» сном после просветления. Он всегда им является, даже прямо сейчас, когда читаются эти строки. Разница лишь в том, осознаётся это или нет.<a href="#ref-497" class="text-blue-500 hover:underline ml-2">↩</a></p>
    <p class="my-2" id="citation-498"><sup>498</sup> В буддийской философии термин «дхарма» (<em>dharma</em>) как правило (но это одно из значений) используется для описания мельчайших элементарных единиц опыта: ощущения, восприятия, волевых импульсов, состояния сознания. Иными словами, всё, что вообще может стать содержанием опыта. Махамати утверждает, что все эти единицы без исключения (<em>sarva</em>) подобны магической иллюзии (<em>māyā</em>).</p>

    <p><em>Citta-vijñāna-varjitāḥ</em> — «не схватываются как ум или сознание» — означает, что дхармы не обладают собственной «внутренней жизнью» и попытка определить дхармы через категории «ума» или «сознания» — уже заблуждение. В действительности, нет ни дхарм, ни ума, ни сознания как отдельных сущностей — есть лишь единый поток, свободный от приписывания признаков. В них нет никакого субъекта, который воспринимал бы или осознавал бы себя. Они воспринимаемы лишь как вспышки в поле опыта, не имея самостоятельной природы, потому что само различение между «умом» и «объектом» есть продукт различения.</p>

    <p>Если в гатхе 2 мир сравнивался со сном — где иллюзия возникает сама по себе, без видимого усилия, — то здесь акцент смещается на выстроенную структурность: магия предполагает искусного «фокусника» (кармические отпечатки и различающий ум), который создаёт видимость реального из ничего. Даже такие понятия, как «шуньята» или «нирвана», если они мыслятся как объекты, также подпадают под это определение.<a href="#ref-498" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-499"><sup>499</sup> Гатха описывает два уровня постижения Будды. Первый — двойное отсутствие «я»: в личности (<em>pudgala-nairātmya</em>) и во всех явлениях (<em>dharma-nairātmya</em>). Второй — устранение двух завес: завесы клеш (<em>kleśāvaraṇa</em>), порождаемой страстями и омрачениями, и завесы познаваемого (<em>jñeyāvaraṇa</em>), порождаемой ложными построениями ума, закрывающими прямое видение реальности.</p>
    <p class="my-2"><em>Animittena viśuddham</em> — «очищено через беспризнаковое» — согласно комментарию Нагабодхи, <em>animitta</em> здесь выступает не как качество, а как средство: беспризнаковое сосредоточение (<em>animitta-samādhi</em>), одно из трёх врат освобождения (<em>vimokṣamukha</em>) наряду с <em>шуньятой</em> и <em>бесжеланием</em> (не обусловленность желанием, без-устремлённость) (<em>apraṇihita</em>). Нагабодхи поясняет: «Беспризнаковое — это пребывание в Таковости, где нет ни схватывающего, ни схватываемого». Очищение (<em>viśuddhi</em>) здесь — не изменение и не «стирание» чего-либо, это распознавание изначальной чистоты природы ума (<em>prakṛti-prabhāsvara-citta</em>): двойственность «я — дхармы» и «клеши — познаваемое» рассеивается сама собой, как туман под солнцем.<a href="#ref-499" class="text-blue-500 hover:underline ml-2">↩</a></p>
    <p class="my-2" id="citation-500"><sup>500</sup> Гатха строится на трёх последовательных отрицаниях, указывающих на природу Будды за пределами любых категорий. Будда не «входит» в нирвану как существо, достигающее цели; не «пребывает» в нирване как в месте или состоянии; и нирвана не является Его свойством или качеством. Все три отрицания направлены против одной и той же ошибки различающего ума (<em>vikalpa</em>) — попытки схватить природу Будды через отношение к нирване как к достижению, месту или обладанию.</p>
    <p class="my-2">Последние две строки раскрывают положительный смысл этих отрицаний: природа Будды — это недвойственная истина (<em>advayatattva</em>), в которой нет ни познающего, ни познаваемого, ни крайности бытия, ни крайности небытия. Применение четырёхкрайнего отрицания (<em>catuṣkoṭi</em>) к природе Будды указывает на то, что Он тождествен Таковости (<em>tathatā</em>) — реальности, недоступной для любых логических определений. С точки зрения учения о наполненной пустоте, эта реальность — изначальная мудрость, свободная от двойственности, а потому не описываемая ни через отсутствие, ни через присутствие.<a href="#ref-500" class="text-blue-500 hover:underline ml-2">↩</a></p>
    <p class="my-2" id="citation-501"><sup>501</sup> «Видеть» (<em>paśyanti</em>) в этой гатхе — это постижение мудростью (<em>prajñā</em>): созерцающий проникает в нерождённую природу Будды как Дхармакаю, тождественную Таковости (<em>tathatā</em>). То, что никогда не возникало, находится вне круговорота рождения и смерти — и именно это постижение разрушает основу цепляния (<em>upādāna</em>), питающего сансарное существование: привязанность к <em>скандхам</em>, к ощущениям, к взглядам и к идее «я». Цепляние прекращается само собой — подобно тому, как страх перед змеёй исчезает в момент распознавания верёвки. Плодом этого распознавания становится незапятнанность (<em>nirañjana</em>) — чистота, не привязанная ни к этому миру, ни к иному, ни к сансаре, ни к нирване, поскольку устранена сама её причина.<a href="#ref-501" class="text-blue-500 hover:underline ml-2">↩</a></p>
    <p class="my-2" id="citation-502"><sup>502</sup> Гатхи 7–10 образуют единую нарастающую последовательность, ведущую от описания механизма заблуждения к его окончательному преодолению.</p>
    <p>В гатхах 7–8 раскрывается природа ошибки познания. Сознание не воспринимает мир как он есть — оно непрерывно пульсирует (<em>spandate</em>), порождая образы из кармических семян (<em>vijñāna-bīja</em>), хранящихся в Алайе. Невежды принимают эти образы за внешнюю реальность — как олени принимают марево за воду, как больные глаза видят пятна в пустоте. Объекта нет; есть лишь вибрация сознания, принятая за твёрдую вещь.</p>
    <p>В гатхе 9 под удар попадает сама медитативная практика. Медитирующий, медитация, объект созерцания, отбрасывание омрачений и видение истины — всё это также <em>kalpanā</em>, воображение ума. Освобождение наступает через распознавание того, что вся эта триада вместе с её плодами — построение ума. Последнее препятствие на пути — цепляние за духовное.</p>
    <p>И в завершении принцип <em>шуньяты</em> применяется к самому себе. Дхармы лишены сущности, возникнув из домысливания (<em>manyanā</em>) — но и само домысливание есть <em>шунья</em>, и даже мысль «это шунья» подлежит той же <em>шуньяте</em>. Это <em>шуньята шуньяты</em> (<em>śūnyatā-śūnyatā</em>), устраняющая последнюю опору: привязанность к самому понятию <em>шуньяты</em>. Инструмент, которым опустошается мир от иллюзорных сущностей, сам должен быть опустошён.<a href="#ref-502" class="text-blue-500 hover:underline ml-2">↩</a></p>
    <p class="my-2" id="citation-503"><sup>503</sup> Восьмеричное или девятиричное: стандартная схема йогачары включает восемь сознаний (пять чувственных, <em>манас</em>, <em>манас-виджняна</em> и <em>Алайя-виджняна</em>). Упоминание девятого сознания встречается в некоторых школах — это <em>амала-виджняна</em> (<em>amala-vijñāna</em> — незапятнанное сознание), которое рассматривается как чистая природа ума за пределами <em>Алайи</em>.<a href="#ref-503" class="text-blue-500 hover:underline ml-2">↩</a></p>
    <p class="my-2" id="citation-504"><sup>504</sup> Гатхи 11–14 образуют единый блок, описывающий механику сансарного сознания — от природы видимого мира до причин его непрекращающегося блуждания.</p>
    <p>Гатха 11 вводит ключевой образ: пять <em>скандх</em> подобны отражению деревьев в воде. Отражение видимо, но не имеет собственной сущности в воде — дерево есть, отражение есть, но отражение не является деревом. Так и <em>скандхи</em> видимы, но лишены самостоятельной природы. <em>Vijñaptyā na vikalpayet</em> — «не следует подвергать различению посредством представления» — означает: не приписывай отражению реальность того, что оно отражает.</p>

    <p>Гатха 12 умножает образы: мир подобен майе, механической кукле веталы, сновидению, молнии и облаку — все они указывают на одно: мир лишён собственной природы, мгновенен и функционирует как механизм. <em>Trisaṃtati</em> — «три преемственности» — это три механизма, поддерживающие иллюзию непрерывности:<br>- кармическая преемственность (действие и следствие),<br>- преемственность омрачений (страсти и заблуждения),<br>- преемственность сознания (поток различающего ума).<br>
    Видение мира как пресекающего эти три преемственности — то есть распознавание его как лишённого непрерывности, как мгновенно возникающего и исчезающего — само по себе освобождает.</p>

    <p>Гатха 13 вскрывает причину: сознание развёртывается из-за безосновательного различения (<em>ayoniśa vikalpa</em>) — различения, возникающего без реального объекта, подобно тому, как в темноте верёвка принимается за змею. Восемь или девять виджнян — лишь волны на поверхности единого океана Алайи; их разнообразие не отменяет единства основы.</p>
    <p>Гатха 14 описывает инерцию этого процесса: В <em>Алайе</em> непрерывно прорастают отпечатки (<em>vāsanā</em>), и ум влечётся к объектам — как железо к магниту — в силу закона зависимой природы. Распознавание самого процесса, механизма этого притяжения и есть начало освобождения.<a href="#ref-504" class="text-blue-500 hover:underline ml-2">↩</a></p>
    <p class="my-2" id="citation-505"><sup>505</sup> Здесь прослеживается движение от изначальной природы пробуждения (<em>gotrabhū</em>) к её раскрытию в спонтанном сострадательном действии (<em>anābhoga-caryā</em>). Татхагатагарбха, природа Будды (<em>gotrabhū</em>), изначально пребывающая во всех существах, открывается через <em>prajñā</em>, поскольку логическое рассуждение (<em>tarka</em>), оперирующее категориями двойственности, не способно её постичь. Когда ум прекращает устремляться к объектам, совершается <em>āśrayaparāvṛtti</em> — поворот основы, устраняющий разделение на познающего (<em>jñāna</em>) и познаваемое (<em>jñeya</em>). Плодом этого поворота является <em>самадхи</em>, подобное иллюзии (<em>māyopama-samādhi</em>), в котором обнаруживается иллюзорная природа всех явлений, включая само это <em>самадхи</em>. Десять <em>бхуми</em> бодхисаттвы распознаются здесь как построения различающего ума — подобно тому, как человек, видящий ступени на радуге, постигает, что ступеней нет, есть лишь свет и влага. «Царь-Ум» (<em>cittarājan</em>) — это очищенная <em>Алайя</em> (<em>pariśuddha-ālaya</em>), в которой прекратились и распознавание (<em>saṃjñā</em>), и двойственное сознание (<em>vijñāna</em>): все виджняны распознаются как её собственные проявления, подобно тому как океан распознаёт волны как воду. После поворота основы ум пребывает в непреходящей устойчивости (<em>śāśvatam</em>) — качестве, выходящем за пределы временно́й длительности. Образ дворца (<em>vimāna</em>), подобного лотосу и рождённого из сферы иллюзии (<em>māyā-gocara</em>), указывает на Самбхогакаю — Тело Блаженства, воспринимаемое бодхисаттвами высших ступеней и возникающее в пространстве <em>vijñaptimātra</em>. Утвердившийся в этом состоянии бодхисаттва действует через спонтанное, непреднамеренное действие (<em>anābhoga-caryā</em>), возникающее из самой природы пробуждения, не обусловленное причинно-следственными построениями ума. Образ драгоценного камня, отражающего все формы и остающегося неизменным, являет недвойственную природу этого сострадания, в котором нет разделения на действующего и того, ради кого действуют.<a href="#ref-505" class="text-blue-500 hover:underline ml-2">↩</a></p>
    <p class="my-2" id="citation-506"><sup>506</sup> Гатхи 19–20 завершают тему иллюзорности, начатую в предшествующих гатхах, доводя её до предельного вывода. Гатха 19 разрушает последнюю двойственность буддийской мысли: разделение на обусловленное (<em>saṃskṛta</em>) и необусловленное (<em>asaṃskṛta</em>) — сансару и нирвану. Оба полюса существуют лишь в различении (<em>vikalpanā</em>): в конечной реальности нет ни сансары, ни нирваны — есть недвойственная Таковость (<em>advaya-tathatā</em>). Цепляние за «необусловленное» — последняя и наиболее тонкая привязанность: практикующий отпустил мирские желания, но ухватился за нирвану как за объект. Метафора бесплодной женщины, видящей сына во сне, передаёт природу этой ошибки с точностью: сын кажется совершенно реальным, пока длится сон, — и исчезает при пробуждении. <em>Dhiṅ bhūḍhā</em> — «позор глупцам» — в традиции комментаторов читается как выражение сострадательного сожаления о тех, кто страдает от того, чего нет.</p>
    <p>Гатха 20 представляет собой перечисление без глагола — список понятий, подлежащих постижению как <em>vikalpamātra</em>: отсутствие собственной природы, невозникновение, личность, <em>скандхи</em>, поток сознания, условия, <em>элементы</em>, познаваемое, <em>шуньята</em>, бытие и небытие. Будда включает в этот список и само учение о <em>шуньяте</em>: даже оно — идея, и цепляние за него воспроизводит ту же структуру заблуждения. <em>Bhavābhavam</em> — «бытие и небытие» — намеренно стоит последним: отрицаются обе крайности, и само это отрицание не становится новой опорой. Когда ум отпускает все понятия, включая идею отпускания, открывается Таковость (<em>tathatā</em>).<a href="#ref-506" class="text-blue-500 hover:underline ml-2">↩</a></p>
    <p class="my-2" id="citation-507"><sup>507</sup> В гатхах 21–25 последовательно опровергаются представления об учении, всеведении, языке, возникновении и нирване.</p>
    <p>Всё учение Будды — искусное средство. Признаки — будь то «шуньята», «скандхи» или «нирвана» — это обозначения, существующие лишь в различающем уме; они не указывают на независимые сущности. Невежды же принимают признак и обозначаемое за обладающее собственной природой (<em>bhāvena</em>), превращая инструмент в цель.</p>
    <p>Будда знает природу всех дхарм, но не обладает «всеведением» как качеством. Он пребывает посреди всего, однако «всего» не существует. Утверждение «не познаю и не научаю» указывает, что пробуждение происходит через распознавание (<em>abhijñā</em>), без действия Будды как деятеля.</p>
    <p>Все обозначения (<em>prajñapti</em>) — лишь имена, за которыми не стоят соответствующие признаки. Пример волосяного узла используется для описания «я», которому невежды приписывают самостоятельное существование. Оно — только сплетение элементов. Как узел видим, но лишён основы помимо волос, так и «я» лишено основы помимо <em>скандх</em>.</p>
    <p>«Ничто не рождается из небытия» — опровергается возникновение из несуществующего через образ сына бесплодной женщины; «не разрушается условиями» — опровергается действительное разрушение примером цветка в небе. Когда обусловленный мир распознаётся как подобный этим образам, двойственность схватывающего и схватываемого прекращается сама собой.</p>
    <p>Будда не угасает (<em>na nirvāmi</em>) через бытие, действие или признак. Покой наступает через прекращение сознания, являющегося причиной различения (<em>vikalpa-hetu-vijñāna-nivṛtti</em>) — наиболее точное определение нирваны в йогачаре. Нирвана — прекращение самой причины сансары.</p>
    <p>Скобочная строка — возможно позднейшая приписка — указывает, что природа мира подобна иллюзии (<em>māyopama</em>), сам же мир при пробуждении не исчезает.</p>
    <p>Метод <em>прасанга</em>, применяемый здесь, опровергает все опоры различающего ума, пока не останется ничего, за что можно ухватиться — освобождение от цепляния (<em>upādāna</em>) без впадения в крайность уничтожения (<em>uccheda</em>).<a href="#ref-507" class="text-blue-500 hover:underline ml-2">↩</a></p>
    <p class="my-2" id="citation-508"><sup>508</sup> Гатхи 26–30 разъясняют природу явлений через образ прекращения волн и серию иллюзорных сравнений. Когда прекращается «великий поток» (<em>mahā-ogha</em>), не возникают и волны; так и многообразие сознаний прекращается при угасании условий, поддерживающих омрачённое восприятие. Явления описываются как пустые (<em>śūnya</em>), лишённые собственной природы (<em>niḥsvabhāva</em>), нерождённые (<em>ajāta</em>) и подобные иллюзии или сновидению. Это не означает их полного отсутствия: они появляются как видимость, но не обладают собственной реальностью.</p>
    <p>Будда говорит об «одной природе» (<em>eka-svabhāva</em>), свободной от логических построений и представлений. Она доступна непосредственному видению благородных, рассудком же её постичь невозможно. Многообразие мира объясняется помрачением восприятия. Человеку с расстройством зрения видятся несуществующие огоньки, подобным образом из-за возмущения элементов (<em>dhātu-saṃkṣobha</em>) возникает кажимость самостоятельных вещей. Иллюзия не является самостоятельной сущностью, она проявляется лишь как способ восприятия. Поэтому дхармы подобны магическому представлению — они видимы, но не обладают независимым бытием.<a href="#ref-508" class="text-blue-500 hover:underline ml-2">↩</a></p>
    <p class="my-2" id="citation-509"><sup>509</sup> Здесь раскрывается распад двойственной структуры опыта, отрицается реальность основных опор обычного сознания: нет ни схватывающего (<em>grāhaka</em>), ни схватываемого (<em>grāhya</em>), ни связываемого, ни самого связывания. Эти отношения возникают лишь в области заблуждения и потому сравниваются с миражом, сновидением и зрительным недугом.</p>
    <p>Тот, кто стремится к истине, достигает состояния без различений (<em>nirvikalpa</em>), где исчезает противопоставление субъекта и объекта. Тогда становится возможным «видение Будды», то есть постижение истинной природы. В таком видении нечего утверждать и нечего отрицать: мудрый не выдвигает умозрительных идей, потому что дхармы не возникают из противопоставления «существующего» и «несуществующего». Многообразие мира появляется лишь вследствие заблуждения сознания в пределах трёх миров (<em>traidhātuka</em>).</p>
    <p>Сравнение мира со сном не утверждает его небытие, а подчёркивает способ существования: как во сне воспринимаются формы, прикосновения и действия, не имея самостоятельной реальности, так и в бодрствующем опыте всё многообразие явлений имеет ту же природу видимости.<a href="#ref-509" class="text-blue-500 hover:underline ml-2">↩</a></p>
    <p class="my-2" id="citation-510"><sup>510</sup> Теперь переходим от анализа иллюзорности мира к описанию пути пробуждения. Ум назван «источником трёх миров» (<em>traidhātuka-yoni</em>): именно из его заблуждающей активности возникает воспринимаемая реальность. Поняв это, практикующий перестаёт воспринимать мир как самостоятельное существование. Мудрость видит отсутствие возникновения и исчезновения, тогда как неведение воспринимает эти процессы как реальные.</p>
    <p class="my-2">Далее описывается высшая сфера пробуждения — божественная обитель Акаништха. Там Будды пребывают вне двойственных форм ума и его факторов, обладая <em>силами</em>, <em>сверхзнаниями</em> и <em>духовной властью</em>. В этой сфере присутствует совершенное пробуждение, тогда как в мире людей проявляются лишь его явленные формы (<em>nirmāṇa</em>). Бесчисленные проявленные тела Будд возникают ради блага существ и проповедуют Дхарму. Тем самым подчёркивается различие между истинным состоянием пробуждения и его сострадательными проявлениями в мире сансары.<a href="#ref-510" class="text-blue-500 hover:underline ml-2">↩</a></p>
    <p class="my-2" id="citation-511"><sup>511</sup> Гатхи 41–44 описывают природу Таковости (<em>tathatā</em>), её сокрытие в существах и раскрытие через обращение основы. Таковость вневременна (лишена начала, середины и конца), недвойственна (свободна от бытия и небытия), всепроникающа, неподвижна и изначально чиста. Парадокс <em>acitra-citra-saṃbhava</em> — «единообразное, но порождающее многообразие» — указывает на природу реальности: как океан без внутренних различий порождает разнообразные волны, так Таковость, лишённая внутреннего разнообразия, является источником всего многообразия мира.</p>
    <p>Эта природа скрыта во всех существах как татхагатагарбха (<em>gotra</em>), покрытая слоем представлений (<em>vijñapti</em>). Сокрытие — не уничтожение; чистая природа остаётся нетронутой, подобно сокровищу в грязной одежде. Заблуждение (<em>bhrānti</em>) порождает иллюзию (<em>māyā</em>), а не наоборот: мир не создаёт невежество — невежество создаёт мир.</p>
    <p>Механизм сокрытия раскрывается в гатхе 43. Всё существует из-за помрачения ума (<em>citta-mohena</em>). <em>Алайя-виджняна</em> проецирует мир, опутанный двойственностью схватывающего и схватываемого (<em>svabhāva-dvaya</em>). Этот мир — лишь представление (<em>vijñapti-mātra</em>), непрерывный поток ложных воззрений о дхармах и личности (<em>dṛṣṭy-augha</em>).</p>
    <p>Раскрытие происходит через обращение основы (<em>āśraya-parāvṛtti</em>) — преображение <em>Алайи</em>, раскрытие изначальной природы, подобно тому как зеркало, очищенное от пыли, обнаруживает свою отражающую способность. Тот, кто совершил это обращение, пребывает в совершённой природе (<em>niṣpanna-dharma</em>) — <em>паринишпанна-свабхава</em> из учения о трёх природах — и становится «сыном» Будды, духовным наследником Дхармы.<a href="#ref-511" class="text-blue-500 hover:underline ml-2">↩</a></p>
    <p class="my-2" id="citation-512"><sup>512</sup> Четыре великих элемента (<em>mahābhūta</em>) — тепло, влажность, движение и твёрдость — воображены невеждами как природа дхарм. Это наложение несуществующего на существующее (<em>asadbhūta-samāropa</em>). Но в конечной истине нет ни обозначаемого (<em>lakṣya</em>), ни признака (<em>lakṣaṇa</em>).</p>
    <p>Устройство тела из восьми веществ (<em>aṣṭa-dravya</em>) — четырёх элементов и четырёх производных качеств (цвет, запах, вкус, осязаемость) — воображается невеждами как «форма» (<em>rūpa</em>). Цепляясь за это деление как за истину, существа остаются в клетке сансары.</p>
    <p>Невежды воображают возникновение из совокупности причин и условий (<em>hetu-pratyaya-sāmagrya</em>), принимая искусные средства за абсолютную истину. В конечной реальности (<em>paramārtha</em>) возникновения нет (<em>anutpāda</em>). Не зная этого, существа блуждают в обители трёх миров (<em>tribhavālaya</em>).<a href="#ref-512" class="text-blue-500 hover:underline ml-2">↩</a></p>
    <p class="my-2" id="citation-513"><sup>513</sup> Утверждение «все явления лишены собственной природы» (<em>sarva-bhāva-asvabhāva</em>) — тоже лишь слова людей. Даже учение о <em>шуньяте</em> возникает из воображения (<em>kalpanā</em>) и является искусным средством.</p>
    <p class="my-2">Бытие подобно сну: кажется действительным, но при пробуждении раскрывается как нереальное. В конечной истине такого бытия не существует (<em>nāsti</em>). Исследующий (<em>parīkṣat</em>) не пребывает ни в сансаре, ни в нирване, он за пределами двойственности в Таковости (<em>tathatā</em>).<a href="#ref-513" class="text-blue-500 hover:underline ml-2">↩</a></p>
    <p class="my-2" id="citation-514"><sup>514</sup> Здесь описывается механизм сансары через зависимую природу и опровергается представление о независимом сознании.</p>
    <p><em>Алайя-виджняна</em> в виде «семени» (<em>bījā</em>), проявляется в сфере ума (<em>citta-gocara</em>). Невежды, привязанные к двойственности воображения (<em>kalpa-dvaya</em>) — разделению на схватывающего и схватываемое, — принимают это проявление за реальное возникновение. Однако возникновения нет (<em>anutpāda</em>): есть лишь развёртывание семян.</p>
    <p>Невежество, жажда и карма — не внешний враг (Мара), это внутренние процессы, развёртывающиеся в силу зависимой природы (<em>pāratantrya</em>). Страдание порождается не внешними силами, оно обусловлено внутренними процессами. Зависимая природа (<em>paratantra-svabhāva</em>) — второй элемент учения о трёх природах — объясняет механизм сансары.</p>
    <p>Невежды воображают объекты, но эти объекты — лишь блуждание в сфере ума (<em>citta-gocara-vibhrama</em>). Даже в самом воображении (<em>kalpanāyām</em>) они не осуществлены (<em>aniṣpanna</em>) — это отрицание воображаемой природы (<em>parikalpita-svabhāva</em>). Объекты не существуют ни внешне, ни как завершённые структуры внутри ума: они — само блуждание.</p>
    <p>Будда заявляет: он не видит сознания, свободного от условий (<em>pratyaya-vinirmukta</em>). Всё сознание в сансаре обусловлено — это критика идеи «чистого сознания» как отдельной сущности. Однако это не утверждение небытия: то, что полностью освобождено от условий и лишено собственных признаков (<em>svalakṣaṇa-vivarjita</em>), не пребывает в теле и потому недостижимо как объект (<em>agocara</em>). Оно не «не существует» — оно недоступно для обычного ума, который способен воспринимать лишь обусловленное.<a href="#ref-514" class="text-blue-500 hover:underline ml-2">↩</a></p>
    <p class="my-2" id="citation-515"><sup>515</sup> Гатхи 54–55 излагают метафору упайи — искусных средств. Царь или богатый купец забавляет сыновей игрушечными зверями и обещает показать настоящих в лесу. Игрушки отвлекают детей от страдания и подготавливают их к восприятию действительности. Дом символизирует мир понятий, лес — действительность вне различений. Подобным образом Будда через признаки (<em>lakṣaṇa</em>) — учения о <em>скандхах</em>, <em>дхату</em> и <em>аятанах</em> — ведёт к <em>Пределу истинности</em> (<em>bhūtakoṭi</em>). Эти признаки понимаются как отражения дхарм (<em>pratibimba</em>), служащие указанием на истину. <em>Предел истинности</em> постигается как <em>pratyātmavedyā</em>, в личном опыте. <em>Bhūtakoṭi</em> означает высшую вершину (<em>koṭi</em>) Таковости (<em>tathatā</em>). «Сыновья» обозначают шраваков и бодхисаттв — наследников Дхармы.<a href="#ref-515" class="text-blue-500 hover:underline ml-2">↩</a></p>
    <p class="my-2" id="citation-516"><sup>516</sup> Гатхи 56–59 излагают образ океана и волн как модель сознания. Океан обозначает глубинный поток <em>Алайя-виджняны</em>, волны — возникающие из него формы сознания (<em>taraṅga-vijñāna</em>): чувственные сознания, ум и манас. Подобно тому как ветер приводит океан в движение, объекты восприятия (<em>viṣaya</em>) возбуждают проявления сознания. Ветер не создаёт воду, он лишь вызывает волны; так и объекты не создают сознание, а возбуждают его проявления.</p>
    <p class="my-2">Фраза <em>nṛtyamānāḥ pravartante</em> («разворачиваются, танцуя») указывает на подвижность и изменчивость процесса. Поток сознания непрерывно преобразуется, однако его непрерывность не прерывается (<em>vyuccheda</em>), что отвергает представление о полном уничтожении потока.</p>
    <p class="my-2">Возникновение сансары объясняется «искривлением» сознания (<em>cittaṃ namati</em>): ум склоняется к разделению на познаваемое и познающего (<em>grāhya--grāhaka</em>). Это разделение возникает через различающее воображение (<em>vikalpa</em>), хотя у видимого (<em>dṛśya</em>) нет тех признаков (<em>lakṣaṇa</em>), которые ему приписываются. Эту ситуацию образно выражают строки:</p>
    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>«Когда же форма принята за суть,</li>
        <li>Кривое зеркало доставит эту "радость",</li>
        <li>Страдальческое Я бытует».</li>
        <li class="text-center">(«Золотой Дамдин»)</li>
    </ul>
    <p>В следующей гатхе говорится, что поток <em>Алайя-виджняны</em> проявляется как <em>vijñapti</em> — явление сознания. Когда исчезает двойственность познаваемого и познающего (<em>grāhya-grāhakāpagama</em>), это проявление узнаётся как <em>tathatā</em>, Таковость. Тем самым сансара и пробуждение относятся к одному и тому же потоку сознания и различаются способом его восприятия.</p>
    <p>В то же время последовательность гатх отражает классическую схему трёх <em>природ</em> йогачары (<em>trisvabhāva</em>): разделение на субъект и объект соответствует <em>воображаемой природе</em> (<em>parikalpita</em>), поток взаимозависимых проявлений сознания — <em>зависимой природе</em> (<em>paratantra</em>), а исчезновение двойственности и распознавание Таковости — <em>совершенной природе</em> (<em>pariniṣpanna</em>).<a href="#ref-516" class="text-blue-500 hover:underline ml-2">↩</a></p>
    <p class="my-2" id="citation-517"><sup>517</sup> Продолжая анализ природы явлений, переходим от описания потока сознания к отрицанию личностной сущности. В пяти <em>скандхах</em> отсутствуют «я» (<em>ātman</em>), живое существо (<em>sattva</em>) и личность (<em>pudgala</em>). Тем самым отвергаются различные формы представления о носителе существования: вечная душа, живая сущность и носитель качества «неизменная личность». Остаётся процесс возникновения и прекращения сознания (<em>vijñāna</em>), который происходит без самостоятельного деятеля: сознание возникает и угасает как обусловленный процесс. Это поясняется через образ картины. На плоском изображении могут казаться видимыми впадины и выступы, хотя в действительности их нет. Так и в явлениях (<em>bhāva</em>) воспринимается их «вещность» (<em>bhāvatva</em>) — кажущаяся сущность, приписываемая им различающим умом. Эта «вещность» не принадлежит самим явлениям, а возникает как результат умственного приписывания.</p>
    <p>Эта мысль усиливается двумя классическими буддийскими сравнениями — городом гандхарвов и маревом в пустыне. Город гандхарвов обозначает призрачное образование, подобное облачным миражам, а марево (<em>mṛgatṛṣṇikā</em>, «оленья жажда») — видимость воды, за которой гонится жаждущее животное. Подобным образом видимый мир постоянно проявляется перед сознанием; однако посредством мудрости (<em>prajñā</em>) его предполагаемая реальность не обнаруживается. Мудрость не уничтожает явление, она раскрывает его подлинную природу и проявление продолжается, но без приписываемой ему сущности.<a href="#ref-517" class="text-blue-500 hover:underline ml-2">↩</a></p>
   <hr class="my-8 border-t-4 border-gray-500">
</div>

<div class="citations mt-4 text-lg">
    <h4 class="text-center text-gray-800 font-bold text-xl my-4">ПРИМЕЧАНИЯ</h4>
<hr class="my-8 border-t-4 border-gray-500">
    <p class="my-2" id="citation-518"><sup>518</sup> В завершении цепи отрицаний, переходим от анализа явлений к самой природе реальности. После отрицания «я» в <em>скандхах</em> (гатха 60), отрицания «вещности» явлений (гатха 61) и их самостоятельной реальности (гатха 62) утверждается, что истинная природа не обусловлена средствами познания (<em>pramāṇa</em>) и органами чувств (<em>indriya</em>), не описывается через причинность («ни причина, ни следствие») и лишена разделения на познающего и познаваемое (<em>buddhi--boddhavya</em>). Тем самым отвергается сама структура познавательного отношения. Также она свободна от обозначаемого (<em>lakṣya</em>) и признака (<em>lakṣaṇa</em>), то есть от языковых и понятийных построений.</p>
    <p>В следующей гатхе этот принцип применяется к самому Будде. Если рассматривать Будду как нечто возникающее в зависимости от <em>скандх</em>, то никакой самостоятельной сущности нигде и никем обнаружено не было. Поэтому вопрос об «исчезновении» Будды лишается основания: нельзя говорить об исчезновении того, что никогда не существовало как самостоятельный объект. Тем самым отвергается воззрение уничтожения (<em>uccheda-dṛṣṭi</em>), предполагающее уничтожение некой сущности при нирване. Будда не утверждается как нечто вечное, но и не сводится к временной структуре; речь идёт о действительности, которая не поддаётся схватыванию в понятиях существования и не-существования.<a href="#ref-518" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-519"><sup>519</sup> Невидимая природа возникновения объясняется через доступные формы рассуждения: условия (<em>pratyaya</em>), причины (<em>hetu</em>), примеры (<em>dṛṣṭānta</em>), тезис (<em>pratijñā</em>) и основание (<em>kāraṇa</em>). Эти логические средства не устанавливают самостоятельной реальности явлений, они служат лишь указанием на их способ проявления. Возникновение, о котором идёт речь, не следует понимать как рождение сущности; речь идёт о видимости возникновения при отсутствии реального возникновения (<em>anutpāda</em>). Для прояснения используются образы, показывающие видимость без самостоятельной основы: сон (<em>svapna</em>), город гандхарвов (<em>gandharva-nagara</em>), огненное колесо от вращающегося факела (<em>cakra</em>), мираж (<em>marīcī</em>), а также небесные явления — луна и солнце, чьи образы могут восприниматься как возникающие формы. Подобные сравнения указывают на то, что воспринимаемое может казаться реальным, не обладая собственной сущностью.</p>
    <p>Пример гончара (<em>kulāla-dṛṣṭānta</em>) иллюстрирует зависимое возникновение формы: горшок появляется из глины благодаря условиям и действию мастера, но не обладает самостоятельной природой. Аналогичным образом все явления предстают как формы, возникающие в зависимости от условий.</p>
    <p class="my-2">Поэтому мир называется сном, заблуждением (<em>vibhrama</em>) и магической иллюзией (<em>māyā</em>). Его пустотность (<em>śūnyatā</em>) и воображаемость (<em>kalpita</em>) не отрицают условного проявления мира, но указывают на отсутствие у него собственной, независимой сущности.<a href="#ref-519" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-520"><sup>520</sup> Здесь описывается постижение нерождённости и его плоды. Истинная природа не имеет опоры ни в Трёх Мирах (<em>trailokya</em>), ни во внутреннем (<em>adhyātma</em>), ни во внешнем. Тем самым отвергается привычное стремление ума искать основание либо в субъекте («внутреннее»), либо в мире объектов («внешнее»). Реальность не опирается ни на одну из этих противоположностей. Узрев, что бытие нерождённо (<em>anutpanna bhava</em>), йогин обретает стойкость в постижении невозникновения (<em>anutpatti-kṣānti</em>). Обычно <em>kṣānti</em> понимают как терпение, но здесь подразумевается устойчивое принятие истины нерождённости: ум более не пытается утвердить возникновение сущностей. В традиции бодхисаттвы это состояние связано с глубокой стадией пути, когда <em>шуньята</em> переживается непосредственно.</p>
    <p>Далее описываются плоды такого постижения. <em>Самадхи</em>, <em>подобное иллюзии</em> (<em>māyopama-samādhi</em>), подразумевает видение явлений как подобий иллюзии без отрицания их проявления. <em>Manomaya-kāya</em> («тело, рожденное из ума») указывает на способность сознания свободно проявляться в различных формах. <em>Сверхзнания</em> (<em>abhijñā</em>), <em>власть</em> (<em>vaśitā</em>) и <em>силы</em> (<em>bala</em>) понимаются как естественные проявления очищенного сознания. Выражение <em>cittasya citritā</em> («многообразие сознания») подчёркивает, что эти качества не являются внешними приобретениями, они представляют собой разнообразные проявления одного и того же пробуждённого ума.<a href="#ref-520" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-521"><sup>521</sup> Касательно природы заблуждения и способа проявления сознания: даже там, где явления распознаны как нерождённые (<em>anutpanna</em>), пустые (<em>śūnya</em>) и лишённые собственной природы (<em>asvabhāva</em>), заблуждение всё ещё может возникать. Оно не обладает собственной основой: возникает лишь благодаря условиям (<em>pratyaya</em>) и прекращается вместе с ними. Подобно волнам на озере после утихания ветра: они ещё есть, но новые не возникают, а старые постепенно затихают. Тем самым подчёркивается обусловленная устроенность омрачений — они не имеют самостоятельной сущности и потому могут исчезать.</p>
    <p>Сознание проявляется как внутренний поток переживаний и вместе с тем как внешний мир форм (<em>rūpin</em>). Иного видимого (<em>dṛśya</em>) не существует. Разделение на «внутреннее» и «внешнее» возникает вследствие воображающего различения (<em>vikalpa</em>), свойственного невеждам (<em>bāla</em>). Таким образом утверждается принцип <em>vijñapti-mātra</em>: воспринимаемый мир есть проявление сознания, а различие субъекта и объекта возникает как его ошибочное восприятие.<a href="#ref-521" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-522"><sup>522</sup> Просветлённые направляют многообразие мира, используя условные обозначения (<em>prajñapti</em>), через три средства: намерение (<em>saṃkalā</em>) — бодхичитту, то есть решимость спасать всех существ; образ Будды (<em>buddhabimba</em>) — проявления Будды в различных формах, соответствующих Нирманакае; разрушение омрачений существ (<em>bhūtānāṃ vidāraṇa</em>) — разрушение их омрачений (<em>kleśa</em>), подобно тому как врач разрушает болезнь.</p>
    <p>Гатха 72 описывает структуру двойственного познания (<em>grāhaka--grāhya</em>). Три вида познаваемого (<em>grāhya</em>): тело (<em>deha</em>), основа (<em>pratiṣṭhā</em>) как внешний мир, и наслаждение (<em>bhoga</em>) как объекты чувственного опыта. Три вида познающего (<em>grāhaka</em>): манас (<em>manas</em>) как эго-сознание, восприятие (<em>udgraha</em>) как непосредственное схватывание объекта, и различение (<em>vikalpa</em>) как понятийное мышление. Все шесть суть лишь представления (<em>vijñapti</em>) и не обладают самостоятельной действительностью; в Таковости (<em>tathatā</em>) нет ни познающего, ни познаваемого.</p>
    <p>Пока различение (<em>vikalpa</em>) и различаемое (<em>vikalpya</em>) остаются в сфере слов-знаков и понятий (<em>akṣara-gocara</em>), Истина (<em>tattva</em>) остаётся недоступной. Логики (<em>tārkika</em>) особенно подвержены этому заблуждению, поскольку логическое рассуждение (<em>tarka</em>) неизбежно опирается на двойственные различения, тогда как Истина недвойственна. Это указание на пределы применимости разума.</p>
    <p>Когда йогин постигает мудростью (<em>prajñā</em>) отсутствие собственной природы (<em>naiḥsvabhāvya</em>) явлений — то есть то, что они существуют лишь условно и не обладают независимой природой, — он обретает покой (<em>viśramati</em>): прекращение различающего мышления, при котором ум пребывает в своей природе. Йогин утверждается в беспризнаковом сосредоточении (<em>ānimitta</em>) — одном из трёх врат освобождения (<em>vimokṣamukha</em>), наряду с <em>шуньятой</em> (<em>śūnyatā</em>) и без-устремлённостью (<em>apraṇihita</em>). Беспризнаковое означает, что ум более не цепляется за признаки (<em>lakṣaṇa</em>) явлений.<a href="#ref-522" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-523"><sup>523</sup> Здесь разъясняется условный характер учения о трёх колесницах, природа мира как представление и недвойственное действие природы Будды.</p>
    <p>Три колесницы (<em>yāna-traya</em>) — шраваков, пратьекабудд и бодхисаттв — уподобляются петуху, покрытому сажей: сажа создаёт видимость различия, но сущность остаётся той же. Так и различие трёх путей возникает из неведения; в действительности природа Будды едина. Поэтому в истинном смысле нет ни шраваков, ни пратьекабудд. То, что воспринимается как формы шраваков или Победителя, — это лишь проявления (<em>nirmāṇa</em>), которые сострадательные бодхисаттвы показывают существам в соответствии с их способностями и склонностями. Такие формы относятся к сфере проявленного тела Будды (Нирманакая) и служат искусными средствами наставления.</p>
    <p>Далее утверждается, что три мира (<em>tribhava</em>) — лишь представление (<em>vijñapti-mātra</em>), возникающее через воображаемую двойственность природ (<em>svabhāva-dvaya</em>), то есть различение субъекта и объекта. Когда происходит обращение основы — преобразование основы сознания и прекращение этой двойственности, — раскрывается Таковость, свободная от представлений о дхармах и личности.</p>
    <p>Природа Будды (<em>buddhatā</em>) действует без различающего мышления (<em>nirvikalpa</em>). Она уподобляется естественным источникам света: луне, солнцу, пламени светильника и драгоценному камню. Эти явления освещают и отражают всё без выбора и предпочтения. Так же и пробуждённая природа действует спонтанно и беспристрастно, не опираясь на различение «я» и «другой» или «близкий» и «чужой».<a href="#ref-523" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-524"><sup>524</sup> Явления лишены пребывания, разрушения и возникновения (<em>sthiti-bhaṅga-utpatti</em>) и свободны от крайностей вечности и непостоянства (<em>nitya–anitya</em>). Даже разделение на «омрачение» (<em>saṃkleśa</em>) и «очищение» (<em>vyavadāna</em>) — лишь условное обозначение. В действительности эти различия подобны волосяному комку: они кажутся существующими, но не имеют собственной природы.</p>
    <p>В примере с куклой (<em>puttalikā</em>), ошибочно принимаемой как золотой, сначала воспринимается лишь блеск (<em>kanakābha</em>) и предполагается сходство с золотом. Но затем возникает второй, более глубокий обман: на основании этого сходства делается вывод, что кукла действительно золотая, и даже её основа / материал (<em>bhūmi</em>) домысливается как золото. Так видимость превращается в «сущность». Это нарастающее искажение, когда признак принимается за природу, а затем распространяется на всё целое.</p>
    <p>Так же и мир: сначала возникает явленность, затем различение приписывает ей определённость, и далее она утверждается как реально существующая. Невежды, омрачённые безначальными умом и умственными факторами (<em>citta-caitta anādi</em>), принимают явления, возникающие как иллюзия и мираж (<em>māyā-marīci</em>), за действительные (<em>tattvataḥ</em>). Это процесс, в котором иллюзия усиливается, закрепляется и расширяется, превращаясь в устойчивую картину мира. Если ещё заострить до предела (выразить афористично), то суть гатхи можно свести к такой схеме:</p>
    <ul class="list-disc mb-8 pl-2 space-y-1 ml-4">
        <li>сначала «кажется золотым» (видимость / <em>ābhāsa</em>) →</li>
        <li>затем «это золото» (схватывание / <em>grāha</em>) →</li>
        <li>затем «оно сделано из золота» (наложение на основу / <em>adhyāropa</em>) →</li>
        <li>и это закрепляется как реальность (<em>tattvataḥ-bhrānti</em>).</li>
    </ul>
    <p>Так возникает инерция сансары.<a href="#ref-524" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-525"><sup>525</sup> Переходим к описанию природы <em>Алайя-виджняны</em> — хранилища сознания — через ряд парадоксальных образов, показывающих её состояние в сансаре и при пробуждении.</p>
    <p><em>Алайя</em> раскрывается через несколько граней. Единое семя (<em>eka-bīja</em>) обозначает единую основу потока сознания: из неё возникают бесчисленные переживания и формы существования, но сама основа остаётся единой — подобно океану, из которого возникают множество волн, но вода остаётся одной. Семя-источник (<em>bījaka</em>) указывает на способность этой основы порождать проявления: в <em>Алайе</em> содержатся кармические семена (<em>bīja</em>) и отпечатки (<em>vāsanā</em>), из которых возникают восприятия, мысли, формы мира и сами субъекты опыта. Всесемянное (<em>sarva-bījaka</em>) — состояние <em>Алайи</em> в сансаре, содержащей семена всех возможных переживаний и форм рождения; опыт существ оказывается многообразным (<em>citra</em>), поскольку различные семена созревают в различные состояния сознания, миры и формы жизни. Единый океан (<em>samudra-eka</em>) подчёркивает недвойственность основы сознания: как океан остаётся одним, несмотря на множество волн, так и поток сознания остаётся одной основой, несмотря на бесчисленные проявления.</p>
    <p>При обращении основы (<em>āśraya-parāvṛtti</em>) — ключевом преобразовании в йогачаре — происходит преображение: единое семя очищается (<em>śuddha</em>) и обращается (<em>parāvṛtta</em>), становясь бессемянным (<em>abīja</em>) — кармические семена больше не производят новых рождений. В этом состоянии сознание равно (<em>sama</em>) и лишено различений (<em>nirvikalpa</em>): прекращается разделение на субъект и объект, чистое и нечистое, сансару и нирвану. Напротив, в загрязнённом состоянии из-за избытка омрачений (<em>udreka</em>) возникает смешение рождений (<em>janma-saṃkara</em>) — непрерывный поток сансарического существования; семя становится многообразным (<em>citra</em>), поскольку в нём присутствуют семена бесчисленных карм и состояний сознания.</p>
    <p>Гатхи 83–84 также объясняют предшествующие гатхи 79–82, показавшие, что воспринимаемые явления подобны иллюзии. Иллюзорность воспринимаемого мира не означает, что переживания возникают без причины — их причиной являются кармические семена в <em>Алайя-виджняне</em>, создающие кажущееся многообразие опыта, подобно тому как из одного океана возникают многочисленные волны.</p>
    <p class="my-2">Вместе гатхи 79–84 образуют последовательное объяснение природы сансары и её прекращения, проводя через три уровня постижения: воспринимающий (иллюзия зрения — различение возникает как ошибка ума, гатха 79); сущностный (явления суть <em>шуньята</em> — они лишены собственной природы, гатха 80; омрачённый ум принимает иллюзорное за действительное, гатхи 81–82); ментальный (кармические семена в <em>Алайя-виджняне</em> как причина сансары, гатха 83; обращение основы и прекращение семян как освобождение, гатха 84). Так описывается переход от иллюзорного многообразия опыта к недвойственному знанию через преобразование самого основания сознания.<a href="#ref-525" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-526"><sup>526</sup> Гатхи 85–91 раскрывают учение о двух истинах и <em>шуньяте</em> не только явлений, но и самих философских понятий. В абсолютной истине (<em>paramārtha-satya</em>) ничто не возникает из условий (<em>pratyaya</em>) и не прекращается. Возникновение и прекращение относятся лишь к воображаемым условиям (<em>kalpita pratyaya</em>). Условия не обладают собственной природой — они существуют только на уровне относительной истины (<em>saṃvṛti-satya</em>): в относительном мире говорится о причинности, тогда как в абсолютном смысле она не обнаруживается. Три мира (<em>tribhava</em>) также являются лишь условными обозначениями (<em>prajñapti-mātra</em>). Логики (<em>tārkika</em>) совершают ошибку, принимая обозначения (<em>prajñapti</em>) за нечто действительное (<em>vastu</em>). Потому подвергается критике склонность разума превращать понятия в основополагающие сущности.</p>
    <p class="my-2">Интеллектуальное исследование (<em>jijñāsā</em>) природы явлений не устраняет заблуждение (<em>bhrānti</em>). Освобождение достигается только через прямое видение того, что явления не обладают собственной природой и в действительности не возникают (<em>anutpatti</em>). Здесь проводится различие между рассудочным знанием и мудростью (<em>prajñā</em>) как непосредственным видением. Явления называются подобными магии (<em>māyopama</em>), потому что они существуют условно, и их существование обманчиво (<em>vitatha</em>) и мимолётно, подобно вспышке молнии (<em>vidyut</em>). Явления видимы и переживаемы, но не обладают независимой сущностью. Даже возникновение, разрушение и омрачённость не устраняются как процессы, в абсолютном смысле их нет, но они продолжают происходить на уровне относительной истины. Устраняется лишь понятийное измышление (<em>vikalpa</em>) невежд, принимающих условные процессы за самостоятельную действительность.</p>
    <p>Гатха 91 доводит этот разбор до предела: отрицаются все понятия, включая центральные идеи самой йогачары — такие как <em>Алайя-виджняна</em>. Понятия служат средствами объяснения и практики, но не являются абсолютной истиной. Когда ум начинает цепляться за них как за действительность, он становится рабом дурной логики (<em>kutārkika</em>).</p>
    <p class="my-2">Гатхи 79–91 образуют строгую последовательность, где постепенно опустошается всё: иллюзия восприятия (79), <em>шуньята</em> явлений (80–82), <em>шуньята</em> кармических семян и основы сознания (83–84), <em>шуньята</em> причинности (85–90) и, наконец, <em>шуньята</em> философских понятий (91). Освобождение достигается через прекращение цепляния за любые понятийные устроения. Это почти классическая выстроенность мадхьямаки внутри текста йогачары — довольно редкое сочетание.<a href="#ref-526" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-527"><sup>527</sup> Когда бодхисаттвы — сыны Победителя (<em>jinātmaja</em>) — видят мир как только-сознание (<em>citta-mātra</em>), речь идёт о непосредственном видении природы опыта. Мир воспринимается как проявление сознания.</p>
    <p class="my-2">В результате этого постижения они обретают тело нирваны (<em>nairvāṇika kāya</em>) — способ существования, свободный от кармических построений (<em>kriyā-saṃskāra</em>). Деятельность больше не создаёт кармических последствий. Такое действие происходит без усилия и намеренного устроения, подобно тому как свет солнца распространяется естественно. Это состояние сопровождается духовными качествами Будды — <em>силами</em> (<em>bala</em>), <em>сверхзнаниями</em> (<em>abhijñā</em>) и <em>властями</em> (<em>vaśitā</em>), то есть способностями действовать свободно и действенно ради блага существ.</p>
    <p>Гатха 93 раскрывает парадокс учения о только-сознании. Сознание разворачивается как явленность всех форм (<em>sarva-rūpa-avabhāsa</em>): мир переживается как горы, реки, люди, мысли и чувства. Однако эти формы не существуют как независимые сущности. В действительности нет ни самостоятельного сознания, ни самостоятельных явлений — есть лишь безначальное, заблуждающееся сознание (<em>anādika bhrānta-citta</em>), принимающее собственную явленность за внешнюю действительность. Это подобно сновидению: переживание есть, но ни субъект, ни объекты не обладают самостоятельной природой.</p>
    <p>Когда это распознаётся, йогин мудростью (<em>prajñā</em>) видит мир как лишённый самой явленности (<em>anābhāsa</em>). Поэтому бодхисаттвы превосходят четыре уровня понятийного устроения: признаки (<em>nimitta</em>) — схватываемые отметки явлений; вещность (<em>vastu</em>) — представление о самостоятельном существовании; представления (<em>vijñapti</em>) — разделение на воспринимающее и воспринимаемое; колебания ума (<em>mano-vispandita</em>) — непрерывное разворачивание различения. Они выходят за пределы самой структуры явленности. Тогда ум пребывает без различений (<em>nirvikalpa</em>), потому что ничто более не устанавливается как данное.
    <a href="#ref-527" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-528"><sup>528</sup> Гатхи 95–100 продолжают изложение учения о только-сознании (<em>citta-mātra</em>) и направлены на опровержение представления о независимом существовании внешних явлений.</p>
    <p>Вначале используется ряд классических буддийских образов иллюзии: город гандхарвов (<em>gandharva-nagara</em>), магия (<em>māyā</em>), волосяной комок (<em>keśoṇḍuka</em>) и мираж (<em>marīcikā</em>). Все они ложны, но воспринимаются как существующие. Таково и мысленное построение (<em>bhāvanā</em>) явлений: ум создаёт представление о чём-либо и принимает его как независимо существующее.</p>
    <p>Утверждается, что все явления нерождённы (вне возникновения) (<em>anutpanna</em>). То, что воспринимается как возникновение, есть лишь заблуждение (<em>bhrānti-mātra</em>). Невежды, привязанные к двойственному построению (<em>kalpa-dvaya</em>) субъекта и объекта, принимают это заблуждение за действительное возникновение.</p>
    <p>Что касается структуры этого процесса. Сознание, связанное с возникновением нового рождения (<em>aupapattya-aṅgika citta</em>), возникает из кармических отпечатков (<em>vāsanā</em>). Эти отпечатки накапливаются в потоке сознания и производят разнообразные переживания. Поэтому сознание проявляется как многообразный поток (<em>vicitra</em>), подобный непрерывному движению волн на поверхности океана (<em>taraṅga-ogha</em>). Когда же причины — кармические отпечатки и омрачения — отсечены (<em>taccheda</em>), этот процесс больше не проявляется.</p>
    <p>Далее текст обращается к логическому опровержению внешних явлений. Если бы образы в сознании возникали благодаря внешним явлениям, то их существование должно было бы само по себе порождать соответствующие образы. Однако мы не видим, чтобы изображения объектов возникали в пустом пространстве или на голой стене. Это показывает, что внешний предмет сам по себе не объясняет появление образа в сознании.</p>
    <p>Поэтому утверждается: если бы сознание зависело от внешних признаков (<em>nimitta</em>), оно было бы порождённым условиями (<em>pratyaya-janita</em>). В таком случае положение «только-сознание» (<em>citta-mātra</em>) было бы ложным. Следовательно, источником переживаемых образов является сам поток сознания.</p>
    <p>Последняя гатха формулирует вывод: сознание воспринимает само себя (<em>cittena gṛhyate citta</em>). Это означает, что переживаемый мир является проявлением самого сознания. При этом истинная природа сознания (<em>citta-dharmatā</em>), отождествляемая с Таковостью (<em>tathatā</em>), изначально чиста (<em>śuddhā</em>).</p>
    <p>Эта чистота сравнивается с небом (<em>gagana</em>), в котором не остаётся следов птиц. Подобным образом кармические отпечатки (<em>vāsanā</em>) и омрачения не принадлежат самой природе сознания: они лишь временно проявляются в его потоке и исчезают при пробуждении.<a href="#ref-528" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-529"><sup>529</sup> Источник сансары — привязанность к собственному сознанию (<em>sva-citta-abhiniveśa</em>). Сознание принимает свои проявления за внешние явления, хотя вне сознания не существует независимого видимого объекта (<em>dṛśya</em>). Поэтому переживаемый мир описывается как только-сознание — проявление самого потока сознания.</p>
    <p>Далее излагается трёхуровневая структура сознания: сознание/ум (<em>citta</em>) — это <em>Алайя-виджняна</em>, глубинный поток, в котором сохраняются кармические семена (<em>bīja</em>) и отпечатки (<em>vāsanā</em>). Манас (<em>manas</em>) — сознание, создающее представление «я» (<em>manyanā</em>) и принимающее поток сознания за постоянное «я». Различающее сознание (<em>vijñāna</em>) — пять чувственных сознаний и ментальное, посредством которых воспринимаются объекты (<em>viṣaya</em>).</p>
    <p><em>Алайя-виджняна</em> нейтральна (<em>avyākṛta</em>), <em>манас</em> может усиливать омрачение или участвовать в очищении (<em>ubhaya-saṃcara</em>), а различающее сознание бывает благим или неблагим (<em>kuśala--akuśala</em>), участвуя в создании кармы.<a href="#ref-529" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-530"><sup>530</sup> В высшей истине (<em>paramārtha</em>) отсутствует двойственность представлений (<em>vijñapti-dvaya</em>) — разделение на познающего и познаваемое. Когда устанавливается состояние без проявлений (<em>nirābhāsa</em>), исчезает и деление на три колесницы (<em>yāna-traya</em>), поскольку в конечной истине существует лишь одна колесница (<em>ekayāna</em>).<a href="#ref-530" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-531"><sup>531</sup> Эти гатхи описывают путь бодхисаттвы через десять ступеней (<em>daśa-bhūmi</em>) и завершают изложение учения о «только-сознании» (<em>citta-mātra</em>).</p>
    <p>Первые семь ступеней ещё относятся к сфере деятельности сознания. Восьмая ступень — состояние «без образов» (<em>nirābhāsa</em>), соответствующее неподвижной земле (<em>acalā-bhūmi</em>), где бодхисаттва достигает стойкости в понимании невозникновения дхарм (<em>anutpattika-dharma-kṣānti</em>) и перестаёт цепляться за признаки (<em>nimitta</em>). Девятая (<em>sādhumatī</em>) и десятая (<em>dharmameghā</em>) ступени вместе с высшей обителью Будды (<em>vihāra</em>) обозначают полноту пробуждения. Все эти ступени называются «принадлежащими природе Будды» (<em>mamātmikā</em>), то есть рассматриваются как проявления одной природы. Эта чистая ступень постигается непосредственно внутри себя (<em>pratyātmavedyā</em>) и символически связывается с высшей небесной областью Акаништха (<em>akaniṣṭha</em>), называемой также обителью Великого Владыки (<em>māheśvara</em>). В буддийском контексте это образ высшего состояния пробуждения.</p>
    <p>Подобно тому как от пламени исходят лучи, от природы Будды возникают многообразные и благие проявления, создающие Трёхмирье (<em>tribhava</em>). Будды могут проявлять миры или использовать уже существующие, созданные кармой существ, и проповедуют в них различные колесницы (<em>yāna</em>), соответствующие способностям существ.</p>
    <p>Последняя гатха подчёркивает, что постижение ступеней не происходит в обычной последовательности времени. Решающий прорыв происходит мгновенно, подобно действию воина в разгаре боя. Даже учение о «только-сознании» должно быть превзойдено: окончательный плод — утверждение в состоянии «без образов» (<em>nirābhāsa</em>), свободном от любых признаков и опор на понятия.<a href="#ref-531" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-532"><sup>532</sup> Рассмотрим последовательное отрицание всех построения различающего ума — от крайностей бытия и небытия до высших духовных достижений.</p>
    <p>Невежды воспринимают мир через извращённые схватывания (<em>grāha-viparyasta</em>), принимая за реальность различия, создаваемые умом. Видимое многообразие (<em>vicitratā</em>) есть заблуждение (<em>viparyāsa</em>), возникающее из разделения на субъект и объект.</p>
    <p>Когда мудрость свободна от различений (<em>nirvikalpa-jñāna</em>), утверждение о существовании объектов теряет основание. Сознание не тождественно формам (<em>rūpa</em>) и по своей природе свободно от двойственного разделения.</p>
    <p>Органы чувств сравниваются с магией (<em>māyā</em>), а воспринимаемые объекты — со сновидением (<em>svapna</em>). Подобно иллюзии или сну, они кажутся реальными, но не обладают самостоятельным существованием. Поэтому в конечном смысле не обнаруживаются ни деятель (<em>kartṛ</em>), ни действие (<em>karman</em>), ни сам процесс действия (<em>kriyā</em>).</p>
    <p>Далее отрицание расширяется даже на высшие медитативные состояния: четыре <em>дхьяны</em> (<em>dhyāna</em>), четыре безмерных состояния (<em>apramāṇa</em>), <em>самадхи</em> сфер без форм (<em>ārūpya-samāpatti</em>) и даже полное прекращение восприятия (<em>saṃjñā-nirodha-samāpatti</em>). Все они принадлежат сфере условной истины и не существуют в абсолютном смысле «только-сознания» (<em>citta-mātra</em>).</p>
    <p>И наконец, утверждается, что даже четыре плода пути шраваки — <em>Вступление в поток</em> (<em>srotāpatti</em>), состояние <em>Однажды-возвращающегося</em> (<em>sakṛdāgāmin</em>), <em>Невозвращающегося</em> (<em>anāgāmin</em>) и <em>Архата</em> (<em>arhat</em>) — являются лишь движениями ума (<em>citta-vibhrama</em>). Все подобные достижения относятся к условной истине (<em>saṃvṛti-satya</em>), тогда как в высшей истине (<em>paramārtha-satya</em>) нет ни пути, ни плодов — есть только недвойственная природа сознания.<a href="#ref-532" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-533"><sup>533</sup> Невежды рассматривают пустоту (<em>śūnyatā</em>), непостоянство (<em>anityatā</em>) и мгновенность (<em>kṣaṇikatā</em>) как свойства обусловленных явлений (<em>saṃskṛta</em>). Для объяснения мгновенности они используют традиционные примеры — течение реки (<em>nadī</em>), пламя светильника (<em>dīpa</em>) и подобные им образы. Эти примеры должны показать, что явления непрерывно возникают и исчезают, однако такое объяснение остаётся лишь понятийным построением (<em>vikalpa</em>), а не непосредственным постижением. Истинная мгновенность понимается иначе. Она не означает быструю смену состояний, а указывает на отсутствие реальной деятельности возникновения и исчезновения (<em>nirvyāpāra</em>). (В буддийской логике термин <em>nirvyāpāra</em> используется для критики внешних школ (например, вайшешиков), которые считали, что между причиной и следствием должно быть некое связующее «действие» (<em>vyāpāra</em>). Буддисты же настаивают на «недеятельности»: явления мгновенны, у них нет времени на «действие», следствие возникает просто в силу наличия причины, без дополнительных посредников.) Это состояние описывается как уединённость (<em>vivikta</em>), то есть свобода от загрязнений и наслоений структур понятий, и как свобода от действия (<em>kriyā-varjita</em>). Поэтому истинный смысл мгновенности (<em>kṣaṇikārtha</em>) определяется как невозникновение всех дхарм (<em>anutpatti</em>). Явления кажутся возникающими и исчезающими только на уровне понятий, тогда как в высшем смысле они изначально нерождённы и потому мгновенны.<a href="#ref-533" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-534"><sup>534</sup> В индийской философии обсуждался вопрос о возникновении существующего и несуществующего (<em>sat</em> и <em>asat</em>). Представители школ Санкхья и Вайшешика рассматривали подобные проблемы в рамках своих метафизических теорий и нередко объявляли некоторые вопросы неопределёнными (<em>avyākṛta</em>), то есть не поддающимися окончательному решению в логическом рассуждении.</p>
    <p>Буддийская традиция различает четыре способа ответа (<em>catur-vidha vyākaraṇa</em>), которые применяются в зависимости от характера вопроса и уровня понимания собеседника:</p>
    <p class="ml-4">— прямой ответ (<em>ekāṃśa-vyākaraṇa</em>), когда вопрос допускает однозначное решение;</p>
    <p class="ml-4">— встречный вопрос (<em>paripṛcchā</em>), направляющий собеседника к самостоятельному пониманию;</p>
    <p class="ml-4">— аналитический ответ (<em>vibhajya-vyākaraṇa</em>), когда вопрос требует различения нескольких аспектов;</p>
    <p class="ml-4">— оставление вопроса без ответа (<em>sthāpanīya</em>), применяемое в случаях, когда сам вопрос основан на ошибочных предпосылках.</p>
    <p>Последний способ используется преимущественно при обсуждении с представителями иных философских традиций (<em>tīrthika</em>), чтобы не укреплять ложные воззрения (<em>tīrtha-vāda</em>), возникающие из неправильно поставленного вопроса.<a href="#ref-534" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-535"><sup>535</sup> Здесь излагается учение о двух истинах (<em>satya-dvaya</em>) и рассматривается природа заблуждения.</p>
    <p>В условной истине (<em>saṃvṛti-satya</em>) явления считаются существующими, поскольку именно так они воспринимаются и обозначаются в обычном опыте. В высшей истине (<em>paramārtha-satya</em>) никакие дхармы не обладают собственной природой (<em>svabhāva</em>). Поэтому даже высшая истина определяется не как утверждение небытия, а как видение отсутствия собственной природы дхарм (<em>niḥsvabhāvatva</em>).</p>
    <p>Если бы явления обладали собственной природой, зависящей от слов (<em>abhilāpa</em>), то они могли бы возникать из словесных обозначений. Поскольку этого не происходит, собственная природа явлений не обнаруживается. Речь сама по себе не имеет реального объекта (<em>nirvastu</em>): слова являются лишь условными обозначениями и не обладают самостоятельным бытием. Соответственно, и заблуждение (<em>viparyāsa</em>) не является реальной сущностью. Если бы заблуждение было чем-то реально существующим, оно имело бы собственную природу и не могло бы быть распознано как заблуждение. Однако именно возможность распознавания показывает, что оно лишено собственной природы. Поэтому воспринимаемые явления не обладают самостоятельной реальностью, а существуют лишь на уровне условного обозначения.<a href="#ref-535" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-536"><sup>536</sup> Видимое многообразие (<em>citra</em>) объясняется деятельностью сознания (<em>citta</em>), пропитанного отпечатками омрачений (<em>dauṣṭhulya-vāsanā</em>). Схватывание воспринимаемых форм (<em>rūpāvabhāsa-grahaṇa</em>) возникает как заблуждение сознания (<em>citta-vibhrama</em>), которое принимает собственные проявления за нечто внешнее (<em>bahirdhā</em>). Гатха 125 утверждает, что различающие построения ума (<em>vikalpa</em>) должны быть оставлены. Это может происходить либо через аналитическое различение, либо через недвойственное созерцание (<em>avikalpa</em>); оба подхода приводят к видению подлинной сути <em>Шуньяты</em> (<em>śūnyatā-tattva-darśana</em>).</p>
    <p>Мир кажется реальным для существ, чьё сознание пропитано неведением (<em>ajñāna-vāsita</em>). Поэтому текст использует ряд традиционных образов иллюзии — магический слон, картина, ложное золото, — чтобы показать условный характер воспринимаемой реальности. Благородный (<em>ārya</em>), достигший правильного видения, не воспринимает ни заблуждение как реальную сущность, ни какую-либо «истину», скрытую внутри него. Если бы истина содержалась внутри заблуждения, само заблуждение обладало бы истинной природой, что невозможно. Даже после устранения грубых заблуждений ум может вновь создавать признаки (<em>nimitta</em>), за которые он начинает цепляться. Такие признаки становятся новым источником заблуждения, подобно зрительным иллюзиям, возникающим при болезни глаз (<em>timira</em>).<a href="#ref-536" class="text-blue-500 hover:underline ml-2">↩</a></p>
<hr class="my-8 border-t-4 border-gray-500">

</div>

<div class="citations mt-4 text-lg">
    <hr class="my-8 border-t-4 border-gray-500">
    <p class="my-2" id="citation-537"><sup>537</sup> Шесть элементов (различение, различаемое, процесс различения; узы, скованный, сковывание) возникают в процессе различения (<em>pravartate</em>), но именно их распознавание делает их условиями освобождения (<em>mokṣa-hetu</em>) — подобно яду, превращённому в лекарство.</p>
    <p>Даже ключевые буддийские понятия — ступени пути (<em>bhūmi</em>), истины (<em>satya</em>), земли Будд (<em>kṣetra</em>), три типа пробуждённых — суть воображаемые построения (<em>kalpita</em>), указывающие на их условный, а не абсолютный характер. Все метафизические категории — буддийские и небуддийские (личность, <em>скандхи</em>, атомы, первоматерия, Ишвара, деятель) — строятся различением в поле «Только-сознания» (или «Только-ума») (<em>citta-mātra</em>). Сознание (<em>citta</em>) — основание всего опыта, но невежды воспринимают его как многообразие явлений, тогда как в действительности оно лишено признаков (<em>alakṣaṇa</em>).</p>
    <p>Классическое отрицание «я» (<em>anātman</em>): ни «я» не содержится в <em>скандхах</em>, ни <em>скандхи</em> — в «я». При этом проводится срединный путь: явления не существуют так, как воображаются, но и не отсутствуют полностью. Если бы явления существовали так, как их воспринимают невежды, то это восприятие уже было бы истинным знанием — чего нет. Поскольку дхармы лишены собственной природы (<em>abhāva = niḥsvabhāva</em>), нельзя утверждать ни действительное омрачение (<em>saṃkleśa</em>), ни действительное очищение (<em>śuddhi</em>). Отвергаются обе крайности — утверждение и отрицание.<a href="#ref-537" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-538"><sup>538</sup> <em>Зависимая природа</em> (<em>paratantra-svabhāva</em>) определяется через заблуждение (<em>bhrānti</em>), признак (<em>nimitta</em>) и мысленное построение (<em>saṃkalpa</em>); речь идёт о потоке опыта, возникающем в зависимости от условий (<em>pratyaya</em>). <em>Воображаемая природа</em> (<em>vikalpita-svabhāva</em>) состоит в именовании (<em>nāma</em>), приписываемом этим признакам, благодаря чему складывается представление о предметах как обладающих воображаемой самостоятельностью. <em>Совершенная природа</em> (<em>pariniṣpanna-svabhāva</em>) раскрывается при отсутствии именования, признаков и мысленных построений. В этом случае зависимости (<em>pratyaya</em>) понимаются как не обладающие собственной предметностью / вещностью / объективностью (<em>avastu</em>) и существующие лишь в качестве условных указаний (<em>saṃketa</em>). Тем самым утверждается их лишённость собственной природы.<a href="#ref-538" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-539"><sup>539</sup> Здесь перечисляются разные способы проявления Будды. Термины <em>vaipākika</em> («связанный с результатом зрелости») и <em>nairmāṇika</em> («проявляющийся») указывают на разные уровни активности пробуждённого ума:<br>
    — один обращён к существам, принимает форму речи, тела, мира;<br>
    — другой глубже, связан с внутренним созреванием, но всё же выражается условно.</p>
    <p>Гатха 141 допускает двойное чтение. Её можно понимать как перечисление трёх форм проявления (<em>nisyanda</em>, <em>dharma</em>, <em>nirmāṇa</em>), но также — как единый акт проявления, который лишь по-разному воспринимается в зависимости от готовности ума. Краткость санскритского стиха сознательно сохраняет эту неопределённость.</p>
    <p>Вся речь, даже буддийская, принадлежит уровню проявления (<em>nairmāṇika</em>). Поэтому она не окончательна, а содержит скрытый смысл (<em>saṃdhi</em>). Буквальное значение — лишь указатель; подлинное постижение требует проникновения за слова — в то, что не может быть сказано, но раскрывается в недвойственном видении.<a href="#ref-539" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-540"><sup>540</sup> Дхармы характеризуются как нерождённые (<em>anutpannāḥ</em>), при этом не утверждается их полное отсутствие или не-существование. Их реальность поясняется через традиционные сравнения — город гандхарвов, сон, магическое видение, призрачное творение (<em>nirmāṇa</em>), — указывающие на зависимый и лишённый собственной природы характер явлений. Весь процесс сансары и освобождения относится к сфере ума / сознания (<em>citta</em>): возникновение, развёртывание и прекращение описывают не становление самостоятельных сущностей, они указывают на динамику самого ума / сознания. Видимость объектов (<em>arthābhāsa</em>) определяется как способ проявления ума / сознания. То, что воспринимается как объект, не обладает самостоятельной сущностью и наличествует лишь как воображаемое (<em>kalpita</em>). В этом смысле говорится о «только-Уме» (<em>citta-mātra</em>), где предметность / вещность / определённость не утверждается как самостоятельная реальность. Освобождение связывается с прекращением различения (<em>vikalpa</em>): при отсутствии развёртывания цепи понятий исчезает приписывание ограниченной конкретности, и тем самым устраняется основание заблуждения.<a href="#ref-540" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-541"><sup>541</sup> Не простая для перевода и понимания гатха: <em>parikalpitaṃ svabhāvena sarvadharmā ajānakāḥ / paratantraṃ samāśritya vikalpo bhramate nṛṇām</em>. <em>parikalpita-svabhāva</em> — это ложное представление, что дхармы обладают собственной, независимой природой (<em>svabhāva</em>), но на самом деле такой природы никогда не было. Потому что если бы эта воображаемая природа существовала, она должна была бы когда-то возникнуть (<em>jāta</em>). Но поскольку её <strong>никогда</strong> не было, то и возникнуть она <strong>не могла</strong> — следовательно, она <strong>нерождённа</strong> (<em>ajāta</em>).<a href="#ref-541" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-542"><sup>542</sup> Гатхи 147–156 раскрывают, как из безначальных отпечатков и размножествления цепи понятий возникает различающее мышление, порождающее видимость внешних объектов. Пока сознание занято этой видимостью, оно остаётся в плену двойственности субъекта и объекта. Различение, опираясь на <em>зависимую природу</em>, то есть на обусловленный поток сознания, воображает существование самостоятельных явлений — это и есть <em>воображаемая природа</em>. Но поскольку эта природа лишь воображена, а не действительно существует, все дхармы в этой логике не рождены. Когда же йогин, исследуя реальность правильным рассуждением, прекращает цепляние за познающего и познаваемое, двойственное построение угасает. Тогда раскрывается правильное знание, чья сфера — Таковость, лишённая всяких образов. Это состояние — <em>совершенная природа</em>, в которой нет ни заблуждения, ни его опоры.<a href="#ref-542" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-543"><sup>543</sup> Здесь описывается возникновение телесности и речи как продолжение того же процесса различения. Зачатие связывается с соединением родительских факторов и сознания-сокровищницы (<em>ālaya-vijñāna</em>), после чего развёртывание тела описывается через традиционные стадии эмбрионального развития. Тело характеризуется как нечистое и обусловленное кармой. После рождения восприятие форм возникает на основе чувственного контакта и усиливается через воображение (<em>kalpanā</em>), что ведёт к дальнейшему разрастанию воспринимаемого мира. Речь возникает как результат телесных условий и различения; она описывается как воспроизведение, лишённое собственной сущности. Тем самым язык включается в общий механизм построения видимости.<a href="#ref-543" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-544"><sup>544</sup> В этих гатхах раскрывается парадоксальное положение языка: он одновременно необходим для передачи Учения и принципиально неспособен выразить его суть.</p>
    <p>Рассудочное исследование (<em>yukti</em>) приводит к отрицательному результату: собственная природа (<em>svabhāva</em>) дхарм не устанавливается (<em>nāvadhāryate</em>), а потому невыразима (<em>anabhilāpya</em>), как следствие отсутствия того, что могло бы быть выражено.</p>
    <p>Формула «ни есть, ни нет» (<em>nāsti asti iti na vidyate</em>) направлена против наивного реализма и нигилизма одновременно. Обусловленное (<em>pratyaya-utpādita</em>) не подпадает под категории бытия и небытия, поскольку обе предполагают самостоятельную основу. Воззрения иноверцев (<em>tīrtha-dṛṣṭi</em>) характеризуются именно приписыванием обусловленному одной из этих крайностей. Срединность буддийского пути состоит в отказе от самого вопроса «существует ли?» применительно к тому, что возникает в зависимости от условий.</p>
    <p class="my-2">Если дхармы невыразимы, то как возможна передача Учения? Именование (<em>abhidhāna</em>) укоренялось на протяжении сотен рождений (<em>janmāntara-śata</em>) через взаимное различение (<em>paraspara-vikalpa</em>) понятий. То есть язык имеет историю, он не дан изначально, и формируется в процессе существования. Без обозначений мир погрузился бы в путаницу / смешение (<em>saṃmoha</em>) — что звучит как парадокс: смятение / путаница / неразбериха возникает не из-за языка, а из-за его отсутствия. Язык устанавливает условный порядок (<em>saṃvṛti</em>), предотвращая хаос, но этот же порядок заслоняет высшую истину (<em>paramārtha</em>), превосходящую словесное выражение. Тем самым язык получает двойственный статус: будучи ограничен по своей природе, он является искусным средством, позволяющим указать на то, что само указанию не поддаётся.<a href="#ref-544" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-545"><sup>545</sup> Невежды выстраивают явления (<em>bhāva</em>) посредством трёх видов различения (<em>vikalpa</em>): через заблуждение (<em>bhrānti-vikalpa</em>) — ложное восприятие действительности; через именование (<em>nāma-vikalpa</em>) — присвоение имён явлениям; через конструирование, возникающее из условий (<em>pratyaya-janita-vikalpa</em>) — построение представлений на основе зависимого возникновения.</p>
    <p>Дхармы по своей природе (<em>prakṛti</em>) не прекращаются (<em>aniruddha</em>) и не возникают (<em>anutpanna</em>) — они подобны пространству (<em>gagana</em>). Те же явления, чья природа есть небытие (<em>abhāva-svabhāva</em>), обладают признаком воображаемого (<em>vikalpita-lakṣaṇa</em>), что соотносится с <em>воображаемой природой</em> (<em>parikalpita-svabhāva</em>) в учении о трёх природах (<em>tri-svabhāva</em>).</p>
    <p>Далее приводится ряд образов иллюзорности: мерцание (<em>pratibhāsa</em>), отражение (<em>bimba</em>), магия (<em>māyā</em>), мираж (<em>marīcī</em>), сновидение (<em>svapna</em>), огненное колесо вращаемой горящей палки (<em>alāta-cakra</em>), город гандхарвов (<em>gandharva-nagara</em>) и эхо (<em>pratiśrutka</em>). Все эти образы указывают на ложное возникновение (<em>samodbhava</em>) — явления кажутся существующими, но лишены собственной основы.<a href="#ref-545" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-546"><sup>546</sup> Перечисление шести синонимов совершенной природы (<em>niṣpanna-lakṣaṇa</em>) акцентирует внимание на одной из граней реальности: <em>advaya</em> указывает на преодоление субъект-объектной двойственности; <em>tathatā</em> — на непреложность, которая есть вне зависимости от того, распознана она или нет; <em>śūnya</em> — на отсутствие неизменной сущности; <em>bhūtakoṭi</em> (буквально «предел действительного / истинного») — на границу, где прекращается различающая деятельность ума; <em>dharmatā</em> — на природу дхарм как таковую; <em>nirvikalpa</em> — на недвойственное неразличающее сознавание. Множественность обозначений служит педагогической цели, обращаясь к разным аспектам опыта практикующего и помогая распознать объединяющую и пронизывающую всю сферу опыта невыразимую истину.</p>
    <p>Подлинная <em>праджня</em> (<em>prajñā</em>) находится за пределами того, что может быть вымышлено (<em>kalpita</em>). Обычное понимание «мудрости» предполагает познавательную способность, схватывающую истину через понятия. Здесь же утверждается обратное: пока ум остаётся в сфере речи и мышления (<em>vāk-citta-gocara</em>), он впадает в крайности (<em>dvaya-anta</em>). Истинная <em>праджня</em> — это прекращение самой деятельности различения, а не её усовершенствование. Это радикальное переопределение мудрости отличает йогачару от школ, где познание совершенствуется через утончение инструментов анализа.</p>
    <p>Сфера сознания (<em>citta-gocara</em>) поддерживает крайности «есть / нет»; с её устранением (<em>vidhūta</em>) сознание прекращается (<em>nirudhyate</em>) — здесь <em>nirodha</em> означает прекращение различающего действия, а не уничтожение сознавания как такового. Это прекращение и есть условие раскрытия Таковости (<em>tathatā-avasthā</em>). Парадокс в том, что Таковость не достигается — она раскрывается при устранении того, что её заслоняет. Поэтому <em>ārya-gocara</em> (сфера опыта Благородных) описывается через отрицание: отсутствие схватывания объектов (<em>viṣaya-grahaṇa-abhāva</em>).</p>
    <p>Гатха 178 указывает на несоизмеримость двух способов видения. Мир для невежд (<em>bāla</em>) и мудрецов (<em>manīṣin</em>) — это два различных способа установления реальности. Невежда видит вещи как обладающие определимыми признаками (<em>lakṣaṇa</em>); мудрец распознаёт отсутствие этих признаков (<em>alakṣaṇa</em>). Разница в самой структуре восприятия.</p>
    <p>Образ сплава харакута, внешне похожего на золото, (гатха 179) показывает механизм ошибки: нечто кажется золотом (<em>suvarṇa-ābha</em>), хотя золотом не является (<em>asuvarṇa</em>). Заблуждающиеся логики (<em>kutārkika</em>) — те, кто полагается на умозаключения, исходящие из ложных предпосылок, — выстраивают внутренне последовательные, но ложные построения. Ошибка в исходной точке: принятие видимости за действительность.</p>
    <p>Гатха 180 отвергает обе крайности через указание на их общую ошибку: представление о самостоятельном существовании, которое может возникнуть или исчезнуть. Формула «не существовав — возникает; существовав — уничтожается» (<em>abhūtvā utpāda, bhūtvā vinaśa</em>) описывает обыденное понимание становления, опирающееся на веру в вещность / плотность / конкретность. Срединный путь отвергает обе крайности через распознавание того, что ни возникновения, ни уничтожения никогда не было — есть лишь условное появление и исчезновение в различающем уме.<a href="#ref-546" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-547"><sup>547</sup> Утверждение об отсутствии начала и конца (<em>anādy-anidhana</em>) у дхарм направлено против представления о возникновении как событии во времени. «Подлинный признак действительного» (<em>bhūta-lakṣaṇa</em>) — природа дхарм, свободная от временных определений. Логики (<em>tārkika</em>), названные «мыслящими как ремесленники» (<em>kāraṇa-karavat</em>), не постигают этого, поскольку применяют понятия причины и следствия, творения, творца, процесса, уместные в сфере условного изготовления, к природе дхарм, где они неприменимы.</p>
    <p>Кажущееся противоречие видится в том, что утверждается существование (<em>vidyate</em>) прошлого, будущего и настоящего, но из этого выводится нерождённость (<em>ajātaka</em>) всех дхарм. Если все <strong>три времени существуют одновременно</strong>, то никакого действительного <strong>перехода из небытия в бытие не происходит</strong>. «Возникновение» оказывается лишь <strong>сменой позиции внимания</strong>.</p>
    <p>Воззрения тех, кто не является мудрецами (<em>na budhāḥ</em>), предполагают</p>
    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>превращение (<em>pariṇāma</em>),</li>
        <li>время (<em>kāla</em>),</li>
        <li>устройство первоэлементов и</li>
        <li>органов чувств (<em>bhūta-bhāvendriya</em>),</li>
        <li>промежуточное состояние (<em>antarābhava</em>),</li>
    </ul>
    <p> как нечто устойчивое, но претерпевающее изменение, существующее во времени, обладающее устроенностью или переходящее из состояния в состояние. Но природа дхарм не схватывается ни одним из понятий, описывающих становление.</p>
    <p>Победители (<em>jina</em>) не описывают мир как зависимо возникший (<em>pratītya-samutpanna</em>) — отвергается понимание зависимого возникновения как действительного процесса. Мир — лишь поток условий (<em>pratyaya</em>), подобный городу гандхарвов (<em>gandharva-saṃnibha</em>) — тому, что кажется существующим, но лишено основы. Зависимое возникновение осмысливается не как процесс, где одно порождает другое, скорее это указание на отсутствие самостоятельной неизменной основы / сущности у воспринимаемого.</p>
    <p>Всё, что может быть выражено формулой «это есть то» (<em>tad idam</em>), принадлежит сфере условного обозначения (<em>dharma-saṃketa</em>). То же, что отделено от обозначения (<em>saṃketāt pṛthag-bhūta</em>), не рождается и не прекращается (<em>na jāto na nirudhyate</em>). Проводится граница между относительной истиной, где действуют обозначения, и высшей, где понятия рождения и прекращения неприменимы. Обозначение не искажает действительность — оно создаёт относительную действительность, за пределами которой находится то, что обозначению не поддаётся.<a href="#ref-547" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-548"><sup>548</sup> Образ отражения (<em>bimba</em>) в зеркале, воде, глазу, сосудах и драгоценных камнях показывает, что отражение видится (<em>dṛśyate</em>), но нигде не существует (<em>na asti kutracit</em>) как самостоятельное явление. Оно возникает при совпадении условий — отражающей поверхности и отражаемого — но не обладает собственной основой. Так и ум (<em>citta</em>) проявляется как видимость объектов (<em>bhāvābhāsa</em>): образы видятся, но их действительность подобна мареву (<em>mṛgatṛṣṇā</em>) в небе, сновидению или сыну бесплодной женщины. Множественность образов подчёркивает, что сама природа различающего ума — производить видимость при отсутствии соответствующей основы.</p>
    <p>Отрицание внешних признаков Махаяны направлено против овеществления Учения. Махаяна — это не звуки (<em>ghoṣa</em>) и не буквы (<em>akṣara</em>), не истины (<em>satya</em>) как доктрины и не освобождения (<em>vimokṣa</em>) как достижения, даже не сфера «без образов» (<em>nirābhāsa-gocara</em>) как особое состояние. Все эти определения превращают путь в предмет, которым можно овладеть. Подлинная Махаяна — владычество над <em>самадхи</em> (<em>samādhi-vaśa-vartitā</em>), то есть свобода действия в недвойственном сосредоточении. «Тело, рождённое из ума» (<em>manomaya-kāya</em>) — способность проявляться в любых формах для блага существ, украшенная цветами <em>владычества</em> (<em>vaśitā-puṣpa-maṇḍita</em>) — совершенными способностями бодхисаттвы. Махаяна переопределяется как живое, не застывшее учение.</p>
    <p>Явление (<em>bhāva</em>) не обнаруживается в условиях (<em>pratyaya</em>) ни как единое (<em>ekatva</em>), ни как раздельное (<em>pṛthaktva</em>). Обе эти крайности предполагают самостоятельность — либо целого, либо частей. «Рождение» (<em>janma</em>) переосмысливается как совпадение условий (<em>samāsama</em>), «прекращение» (<em>nirodha</em>) — как их распад (<em>nāśa</em>). Тем самым устраняется представление о событии: ничто не рождается и не умирает; изменяется лишь сочетание условий, которому различающий ум приписывает значение возникновения или исчезновения.<a href="#ref-548" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-549"><sup>549</sup> Различение двух видов <em>шуньяты</em> направлено против смешения уровней. «<em>Шуньята нерождённого</em>» (<em>ajāta-śūnyatā</em>) указывает на изначальную природу дхарм, которая никогда не возникала и потому не может исчезнуть. «<em>Шуньята возникшего</em>» (<em>jāta-śūnyatā</em>) относится к <em>шуньяте</em> обусловленных явлений — она сама обусловлена и потому исчезает (<em>naśyate</em>). Высшей объявляется <em>шуньята нерождённого</em>, поскольку она не зависит от различения между существованием и не-существованием явлений. Это защита от понимания <em>шуньяты</em> как отсутствия чего-то: подлинная <em>шуньята</em> — не результат устранения, это изначальная природа.</p>
    <p>Перечисление синонимов — Таковость (<em>tathatā</em>), <em>Шуньята</em> (<em>śūnyatā</em>), <em>Предел истинности</em> (<em>koṭi</em>), Нирвана (<em>nirvāṇa</em>), Дхармадхату (<em>dharmadhātu</em>), <em>тело, рождённое из ума</em> (<em>manomaya-kāya</em>) — показывает, что все эти термины указывают на одну действительность, рассматриваемую с разных сторон. Множественность обозначений (<em>paryāya</em>) служит искусным средством, потому что разные практикующие откликаются на разные указания в зависимости от склада ума.</p>
    <p>Следование букве (<em>grantha</em>) вместо смыслу (<em>artha</em>) в изучении Сутр, Винаи и Абхидхармы означает принятие текстов как самодостаточных источников очищения (<em>viśuddhi</em>). Те, кто полагают (<em>kalpayanti</em>) очищение через внешнее следование, не утвердились в учении об отсутствии «я» (<em>nairātmya</em>), поскольку сохраняют веру в субъект, который может быть очищен через накопление знаний или соблюдение правил. Смысл же указывает на распознавание изначальной чистоты, которая не достигается, а раскрывается.</p>
    <p>Утверждение о том, что бытие не установлено (<em>na sādhita</em>) ни тиртхиками, ни Буддами, ни кем-либо через условия (<em>pratyaya</em>), подрывает саму основу спора о существовании и не-существовании. Если бытие не обосновано, то вопрос о небытии (<em>nāsti</em>) лишается смысла: небытие предполагает предшествующее бытие, которое затем отрицается. Ложный взгляд, утверждающий возникновение (<em>utpāda-vāda-durdṛṣṭi</em>), порождает различение (<em>vikalpa</em>) «есть» и «нет» (<em>asti-nāsti</em>). Различение рождается не из действительности, оно появляется из ошибочного представления о возникновении как событии.</p>
    <p>Для того, кто видит мир в уединённости (<em>vivikta paśyataḥ jagat</em>) — то есть отдельно от наложений различающего ума, — не возникает (<em>na upaiti</em>) крайностей «есть» или «нет» (<em>asti-nāsti</em>). Уединённость (<em>vivikta</em>) здесь — не какая-то пространственная отделённость, это видение природы явлений как отдельной от понятийных построений. Поскольку ничто не возникает (<em>na utpadyate</em>) и ничто не прекращается (<em>na nirudhyate</em>), сами категории бытия и небытия не находят применения. Это завершение пути отрицания, так как устраняется не только утверждение о существовании, но и сама структура утверждения-отрицания.<a href="#ref-549" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-550"><sup>550</sup> Рога зайца (<em>śaśa-viṣāṇa</em>) — классический образ невозможного, того, что может быть названо, но не может существовать. У людей возникает представление (<em>vikalpa vidyate</em>) даже о таком. Те, кто принимают воображаемое за действительное, заблуждаются подобно оленям, бегущим за миражом (<em>mṛgatṛṣṇā</em>). Олени видят воду там, где её нет, и гибнут в погоне за этой видимостью. Так и привязанность к воображаемому (<em>vikalpa-abhiniveśa</em>) поддерживает само воображение (<em>vikalpa saṃpravartate</em>) — ум производит образы, затем цепляется за них, и это цепляние служит основой для дальнейшего производства образов.</p>
    <p>Если воображение без причины (<em>nirhetu</em>), то само воображение не может быть обосновано / неправомерно / логически несостоятельно / неуместно / не может существовать (<em>vikalpa na yujyate</em>). Воображение не имеет внешней опоры — оно порождает свои объекты и затем принимает их за причину собственного действия. Этот замкнутый круг разрывается через распознавание отсутствия исходной причины.</p>
    <p>Образы безводного места и миража в небе усиливают указание на природу восприятия невежд (<em>bāla</em>). Объекты (<em>artha</em>) являются им как действительные, подобно воде в мираже. Для Благородных (<em>ārya</em>) же здесь нет различий / разделения / предпочтения (<em>na viśeṣataḥ</em>). Это означает отсутствие различения между существующим и несуществующим объектом. Благородные распознают, что сама структура субъект-объектного восприятия иллюзорна, и потому для них не встаёт вопрос о действительности воспринимаемого. Видение Благородных (<em>ārya-darśana</em>) характеризуется как чистое (<em>śuddha</em>) — свободное от наложений различающего ума. Оно рождается из трёх врат освобождения (<em>vimokṣa-traya</em>) — <em>шуньяты</em>, беспризнаковости и отсутствия стремления (бесцельности). Эти трое врат составляют единое постижение, рассматриваемое с разных сторон. Видение Благородных свободно от рождения и распада (<em>utpāda-bhaṅga-nirmukta</em>), поскольку обе эти категории принадлежат различающему уму, и пребывает в состоянии «без образов» (<em>nirābhāsa-pracārin</em>).<a href="#ref-550" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-551"><sup>551</sup> Различение учений для трёх колесниц (<em>yāna-traya</em>) показывает градацию в зависимости от способностей. Сыновьям Победителей (<em>jina-putra</em>) — бодхисаттвам — провозглашается глубина (<em>gāmbhīrya</em>), величие (<em>audārya</em>) и обширность (<em>vaipulya</em>) Учения, знание (<em>jñāna</em>) и великолепие чистых земель (<em>kṣetra-vibhūti</em>). Шравакам же преподаётся непостоянство (<em>anityatā</em>) — учение о трёх мирах (<em>tribhava</em>) как <em>шунье</em> (<em>śūnya</em>), лишённой «я» и «моего» (<em>ātma-ātmīya-vivarjita</em>), а также общие признаки дхарм (<em>sāmānya-lakṣaṇa</em>). Пратьекабуддам указывается на непривязанность ко всем дхармам (<em>sarva-dharmeṣu asaṃsakti</em>), уединение (<em>viveka</em>) и одиночное странствие (<em>eka-cārikā</em>) — плод, находящийся за пределами логики (<em>atarkika</em>).</p>
    <p>Различие учений обусловлено разными способностями постижения. Шраваки нуждаются в указании на непостоянство для устранения привязанности к обусловленному. Пратьекабудды постигают через уединённое созерцание зависимого возникновения. Бодхисаттвы же проникают в глубину недвойственной природы и действуют в чистых землях для блага существ.<a href="#ref-551" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-552"><sup>552</sup> Пока обладающий телом (<em>dehin</em>) воображает внешнее как имеющее собственную природу (<em>svabhāva-kalpita bāhya</em>) и принимает зависимую природу (<em>paratantra</em>) за действительную, он не видит (<em>apaśyan</em>) заблуждения о «я» (<em>ātma-saṃbhrānti</em>). Из-за этого его ум продолжает разворачиваться (<em>citta pravartate</em>) — производить различения и цепляться за их объекты. Распознавание того, что внешнее есть проявления воображения, а <em>зависимая природа</em> лишена самостоятельности, прекращает это развёртывание.<a href="#ref-552" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-553"><sup>553</sup> Утверждение о перестановке ступеней (<em>bhūmi</em>) указывает на условность их последовательности. Десятая становится первой, первая — восьмой, и так далее. В состоянии без образов (<em>nirābhāsa</em>) порядок (<em>krama</em>) невозможен, поскольку сама идея последовательности принадлежит различающему уму. Ступени устанавливаются как воспитательное средство для тех, кто движется через постепенное очищение. Для того же, кто пребывает в недвойственном постижении, нет ни первой, ни десятой ступени — есть лишь одна природа, которая не постигается через последовательное продвижение. Это указание на мгновенное пробуждение (<em>ekakṣaṇa-abhisambodha</em>), где все ступени схлопываются в единое распознавание.<a href="#ref-553" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-554"><sup>554</sup> Состояние «без образов» (<em>nirābhāsa</em>) часто ошибочно понимается как небытие (<em>abhāva</em>) явлений — их полное исчезновение или отрицание. Гатха 207 устраняет эту ошибку: для йогинов отсутствие образов не означает небытие. Образы прекращаются как объекты различающего ума, но это не превращает мир в пустоту в смысле полного отсутствия. Плод Благородных (<em>ārya-phala</em>) рождается из равенства (<em>samatva</em>) бытия и небытия, то есть постижения того, что обе эти крайности принадлежат различающему уму и в высшей истине неприменимы. Это указание развивается через риторический вопрос: как может небытие явлений (<em>bhāva-abhāva</em>) установить равенство (<em>samatā</em>)? Ответ подразумевается отрицательный — никак. Отрицание мира, утверждение «ничего нет», само по себе есть крайность и потому не может привести к освобождению. Равенство возникает иначе — через прекращение различения.</p>
    <p>Когда ум не распознаёт (<em>na jānāti</em>) колебания (<em>cala</em>) во внешнем (<em>bāhya</em>) и внутреннем (<em>adhyātmika</em>), тогда угасает заблуждение (<em>nāśa</em>). Колебание здесь означает психическую нестабильность, вызванную цеплянием. Ум воспринимает внешнее как источник желания или страха, а внутреннее — как «я», которое испытывает эти состояния. Это разделение и есть корень страдания. Прекращение распознавания подразумевает, что ум перестаёт накладывать различение «внешнее-внутреннее» на недвойственную основу.</p>
    <p class="my-2">Угасание (<em>nāśa</em>) происходит благодаря видению равного ума (<em>samatā-citta-darśana</em>). «Равный ум» не является безразличием или притуплённостью, как можно ошибочно вообразить. Здесь это недвойственное постижение без разделения на субъект и объект. В этом видении бытие и небытие распознаются как равно условные — обе категории утрачивают применимость. Это и есть подлинное равенство, из которого рождается плод — освобождение через распознавание природы ума, но не через отрицание явлений.</p>
    <p>В гатхах прослеживается такая последовательность: состояние без образов не есть небытие; небытие не может установить равенство; равенство возникает через прекращение различения внешнего и внутреннего.<a href="#ref-554" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-555"><sup>555</sup> Метафора «клин клином» (<em>kīla yathā kīlaṃ</em>) описывает безличный механизм замещения одного цепляния другим. В безначальной сансаре (<em>anādimati saṃsāre</em>), охваченной цеплянием за бытие (<em>bhāva-grāha-upagūhita</em>), посредством невежд (<em>bālaiḥ</em>) — через них как через условие — ум (<em>citta</em>), будучи увлечён одним, отводится от другого. Подобно тому как застрявший клин выбивается другим клином, одно заблуждение вытесняется другим. Невежды здесь не выступают как деятели, а являются условием, в котором ум разворачивает различение (<em>vikalpa</em>). Одно цепляние оставляется, и возникает другое: отпускается одно воззрение — устанавливается другое; оставляется «бытие» — возникает «небытие». Каждый раз прежний клин устраняется новым, однако сохраняется сама структура схватывания. То, что отвело от предыдущего, становится причиной (<em>hetu</em>), объектом (<em>ālambana</em>) и опорой для движения ума (<em>mano-gati-samāśraya</em>). Эта тройственная устроенность даёт причину уму для дальнейшего разворачивания. Сознание (<em>vijñāna</em>) основывается на этом и продолжает своё течение. Пока устанавливаются причина и опора, движение ума не прекращается. Каждая новая опора становится новым клином. Прекращение сансары связано с прекращением самого установления опоры. Когда это распознано, прекращается движение ума — и вместе с ним прекращается разворачивание сознания.<a href="#ref-555" class="text-blue-500 hover:underline ml-2">↩</a></p>
    <hr class="my-8 border-t-4 border-gray-500">
</div>

<div class="citations mt-4 text-lg">

<p class="my-2" id="citation-556"><sup>556</sup> Перечисляются три источника сновидных <em>сверхзнаний</em> (<em>abhijñā</em>): кармическое созревание (<em>vaipākika</em>), благословение (<em>adhiṣṭhāna</em>) и рождение в телах и уделах (<em>nikāya-gati-saṃbhava</em>). Все они порождают четыре вида <em>сверхзнания</em> (<em>abhijñā catur-vidhā</em>), обретаемых во сне (<em>svapne labhyante</em>). Указание на сон здесь принципиально, потому что сон служит моделью того, как работает сознание вообще. Во сне есть образы, переживания и даже «знание», однако нет внешнего объекта. Сознание (<em>citta</em>) через отпечатки (<em>vāsanā</em>) порождает явленность (<em>pratibhāsa</em>) без какой-либо внешней опоры. Тем самым сон показывает, что сознание может полностью функционировать без внешнего основания.</p>
<p>И то, что обретается во сне, и то, что возникает благодаря <em>благосклонности</em> Будды (<em>buddha-prasāda</em>), относится к существам, чьё пребывание в телах, уделах и родах (<em>nikāya-gati-gotra</em>) является результатом созревания сознания (<em>vijñāna-vipāka-ja</em>). Здесь снимается различие между «обычным опытом» и «мистическим опытом». Даже переживания, приписываемые <em>благословению</em> Будды — будь-то видения, откровения, духовные прозрения, — остаются внутри того же механизма созревания кармических семян в потоке сознания.</p>
<p>Это продолжает логику гатх 209–210, где было показано, что ум сам создаёт цикл замены одного цепляния другим. Здесь добавляется утверждение, расширяющее понимание: даже «высокие» состояния — <em>сверхзнания</em> (<em>abhijñā</em>) и благословенные переживания — всё ещё внутри этого цикла. Они не выходят за пределы созревания сознания (<em>vijñāna-vipāka</em>). Практикующий может принять сновидное <em>сверхзнание</em> или благословенное видение за прорыв к абсолютной истине, тогда как это лишь очередное проявление обусловленного сознания.</p>
<p>Связь со сном выполняет двойную задачу. Во-первых, сон показывает отсутствие опоры (<em>ālambana</em>) — то, о чём говорилось в гатхе 210. Ум ищет опору, но опора может полностью отсутствовать, а опыт всё равно разворачивается. Во-вторых, сон демонстрирует, что даже «высшие способности» не требуют внешней опоры — они целиком порождаются внутри потока сознания.</p>
<p>Это глубокое переосмысление опыта. Источник один — созревание сознания (<em>vijñāna-vipāka</em>). Пока практикующий принимает <em>сверхзнания</em> или благословенные переживания за достижения, он остаётся в сансаре, лишь на более тонком уровне. Подлинное освобождение не наступает через накопление духовных опытов, даже самых возвышенных; необходимо распознавание того, что все они — проявления обусловленного сознания. Когда это распознано, прекращается цепляние за опыт как таковой — и вместе с ним прекращается разворачивание сансары.<a href="#ref-556" class="text-blue-500 hover:underline ml-2">↩</a></p>

<p class="my-2" id="citation-557"><sup>557</sup> Гатхи 213–215 раскрывают природу учения о возникновении как искусного средства, направленного на тех, кто не распознаёт механизм проявления.</p>
<p>Ум, сформированный отпечатками (<em>vāsanā-bhāvita</em>), разворачивается (<em>pravartate</em>) как видимость явлений (<em>bhāvābhāsa</em>). Когда невежды (<em>bāla</em>) этого не понимают (<em>na budhyante</em>), тогда излагается (<em>deśayet</em>) учение о возникновении (<em>utpāda</em>). Само учение о зависимом возникновении (<em>pratītya-samutpāda</em>) здесь служит объяснением для тех, кто заблуждается, принимая проявление сознания за внешнюю действительность, и потому «возникновение» — искусное средство, соответствующее уровню непонимания.</p>
<p>Гатха 214 показывает, как язык закрепляет проявление. Пока речь (<em>vākya</em>) выстраивает (<em>vikalpeti</em>) явление (<em>bhāva</em>), наделяя его признаками (<em>lakṣaṇa-anvita</em>), ум постигает (<em>vibudhyate</em>) это, не видя (<em>apaśyan</em>) собственного заблуждения (<em>sva-vibhrama</em>). Язык не просто обозначает готовые явления — он активно строит их через приписывание признаков. Слова не указывают на независимо существующие объекты, они создают устойчивые образы через многократное повторение. Ум принимает эти языковые построения за действительность, не распознавая, что сам производит то, что затем воспринимает как внешнее.</p>
<p>Гатха 215 обнажает парадокс учения о возникновении через серию вопросов Махамати. Почему говорится (<em>varṇyate</em>) о возникновении (<em>utpāda</em>)? Почему не говорится о видимом (<em>dṛśya</em>)? Ведь видимое по своей природе невидимо (<em>adṛśya dṛśyamāna</em>) — чьё оно (<em>kasya</em>), что именно описывается (<em>kiṃ varṇyate</em>) и откуда исходит (<em>kutaḥ</em>)? Видимое невидимо означает: оно не имеет собственной данности / основы, не существует как самостоятельный объект. Нет объекта (<em>kiṃ</em>), нет обладателя (<em>kasya</em>), нет источника (<em>kutaḥ</em>) — а значит, нет основания для описания возникновения. Возникновение предполагает, что нечто появляется — но если это нечто само есть лишь видимость, порождённая умом, то говорить о его возникновении значит удваивать иллюзию.</p>
<p>Связка гатх 213–215 завершает тему, начатую в гатхах 209–212. Механизм цепляния (209–210) действует даже в духовном опыте (211–212), а само учение о возникновении (213–215) — условное средство для тех, кто не распознал этот механизм. Когда распознано, что явления являются проявлениями отпечатков (<em>vāsanā</em>), а язык закрепляет эту проекцию через приписывание признаков, учение о возникновении утрачивает необходимость. Подлинное постижение состоит в распознавании того, что никакого возникновения никогда не было — есть лишь безначальное разворачивание сознания, принимаемое за процесс становления.<a href="#ref-557" class="text-blue-500 hover:underline ml-2">↩</a></p>

<p class="my-2" id="citation-558"><sup>558</sup> Ум по своей природе ясен (<em>svaccha citta svabhāvena</em>), чист и незапятнан, подобно прозрачному зеркалу или чистому пространству, но <em>манас</em>, седьмое сознание, чья природа есть воображение «я» (<em>ātma-grāha</em>), производит омрачение (<em>manaḥ kaluṣa-kāraka</em>). <em>Манас</em> вместе с сознаниями (<em>vijñāna</em>) постоянно вбрасывает отпечатки (<em>vāsanā kṣipate sadā</em>), производит и закрепляет кармические семена, которые затем прорастают как новые проявления.</p>
<p>Когда <em>Алайя</em> покидает тело (<em>ālaya muñcate kāyaṃ</em>), <em>манас</em> устремляется к новому становлению (<em>manaḥ prārtayate gatim</em>). <em>Алайя</em> — хранилище всех семян, основа непрерывности потока сознания — отделяется от распадающегося тела. <em>Манас</em>, движимый неосознанным цеплянием за существование, влечёт поток к новому рождению (<em>gati</em>). Сознание (<em>vijñāna</em>), видя явленность объектов (<em>viṣaya-ābhāsa</em>), увлекается заблуждением (<em>bhrāntiṃ dṛṣṭvā pralabhyate</em>) — принимает проявления за действительность и цепляется за них, запуская новый цикл обусловленного существования.</p>
<p>Всё видимое есть ум (<em>madīya dṛśyate citta</em>); внешнего не существует (<em>bāhya artha na vidyate</em>). Разделение на «внутреннее» и «внешнее» само есть построение различающего ума. То, что воспринимается как внешний объект, есть проявление того же потока сознания. Освобождение происходит через прекращение деятельности <em>манаса</em> как производителя омрачения. Когда <em>манас</em> перестаёт накладывать воображение «я» на поток сознания, прекращается вбрасывание новых отпечатков. Изначально ясная природа ума раскрывается сама собой как распознавание того, что всегда было. Удерживание Таковости в памяти (<em>anusmara</em>) означает непрерывное пребывание в этом распознавании, где заблуждение видится как заблуждение, и не принимается за действительность.<a href="#ref-558" class="text-blue-500 hover:underline ml-2">↩</a></p>

<p class="my-2" id="citation-559"><sup>559</sup> Три непостижимые (<em>acintya</em>) области:</p>
<ul class="list-disk mb-6 pl-2 space-y-1 ml-2">
    <li>сфера созерцающих (<em>dhyāyin-viṣaya</em>) — то, что постигается в глубоком сосредоточении, недоступно рассудочному анализу,</li>
    <li>карма — механизм созревания действий — превосходит возможности логического обоснования и</li>
    <li>величие Будды (<em>buddha-māhātmya</em>) не может быть постигнуто умом, находящимся в сансаре.</li>
</ul>
<p>Все три относятся к сфере сознания (<em>vijñāna-gocara</em>). Это означает, что они принадлежат обусловленному. Непостижимость указывает на границу применимости понятийного мышления внутри самой сферы обусловленного.</p>
<p>Будущее и прошлое (<em>anāgata-atīta</em>), нирвана, личность (<em>pudgala</em>) и речь (<em>vac</em>) излагаются условно (<em>saṃvṛti</em>). Высшая же истина вне всякого выражения (<em>paramārtha anakṣara</em>) — она не схватывается, не описывается буквами, словами, символами или понятиями.<a href="#ref-559" class="text-blue-500 hover:underline ml-2">↩</a></p>

<p class="my-2" id="citation-560"><sup>560</sup> Последователи различных направлений и иноверцы (<em>tīrthya</em>), опираясь на односторонние воззрения (<em>dṛṣṭi-ekāṃśa</em>), заблуждаются в отношении «только-ума» (<em>citta-mātra</em>) и воображают внешнее бытие. Их заблуждение заключается в превращении самого учения о «только-уме» в воззрение, за которое удерживаются. «Внешнего нет» становится новой позицией, «есть только ум» — новым объектом цепляния.</p>
<p>Пратьекабодхи, буддхатва, архатство, лицезрение Будды — всё, что во сне кажется достижением, в пробуждении раскрывается как скрытое семя (<em>gūḍha-bīja</em>). Переворачивается привычная схема пути: то, что ранее воспринималось как плод практики, раскрывается проявлением уже имеющихся семян. «Достижение» не прибавляет ничего нового, лишь разворачивает скрытое содержимое сознания.</p>
<p>Вопросы Махамати — где (<em>kutra</em>), для кого (<em>keṣāṃ</em>), как (<em>kathaṃ</em>), почему (<em>kasmāt</em>), с какой целью (<em>kim-arthaṃ</em>) — предполагают место, субъекта, механизм, причину и цель. Ум, совершенно умиротворённый (<em>citta atiśānta</em>), не может быть этим ограничен. Он находится вне сторон бытия и небытия (<em>sat-asat</em>).</p>
<p>Для заблуждающихся излагается учение, связанное с возникновением и распадом (<em>utpāda-bhaṅga</em>), но лишённое определяемого и признака (<em>lakṣya-lakṣaṇa-varjita</em>). Оно говорит о возникновении, однако нет того, что возникает. От гатхи к гатхе последовательно снимаются все опоры: внешний мир, духовные достижения, понятийное мышление, учение как собрание «истин». Не остаётся ничего, за что мог бы держаться ум. Это раскрывает ум как не нуждающийся в опоре.<a href="#ref-560" class="text-blue-500 hover:underline ml-2">↩</a></p>

<p class="my-2" id="citation-561"><sup>561</sup> Различение (<em>vikalpa</em>) — это <em>манас</em> вместе с пятью сознаниями (<em>vijñāna pañca</em>). Семя ума (<em>citta-bīja</em>) приходит в движение (<em>pravartate</em>), подобно отражению в текущей воде (<em>bimba ogha jala</em>). Образ отражения в текущей воде показывает природу различения: отражение видится, но оно нестабильно, зависит от движения воды и не обладает собственной основой. Более того, оно неотделимо от самого движения потока и возникает вместе с ним. Так же семя ума — кармические отпечатки, хранящиеся в <em>Алайе</em>, — приходит в движение в самой совместной деятельности <em>манаса</em> и пяти сознаний. <em>Манас</em> вместе с сознаниями и есть различение: в этом функционировании происходит схватывание объектов и приведение семян в активность, порождая новые проявления. Прекращение движения — это остановка различающей деятельности ума и сознаний. Семена перестают прорастать, поскольку прекращается вся совокупность условий их приведения в движение — деятельность <em>манаса</em> и функционирование сознаний. Когда ум (<em>citta</em>), <em>манас</em> (<em>manas</em>) и сознание (<em>vijñāna</em>) не приходят в движение (<em>na pravartate</em>), тогда обретается <em>тело, рождённое умом</em> (<em>manomaya-kāya</em>), и ступень Будды (<em>buddha-bhūmi</em>).<a href="#ref-561" class="text-blue-500 hover:underline ml-2">↩</a></p>

<p class="my-2" id="citation-562"><sup>562</sup> Условия (<em>pratyaya</em>), элементы (<em>dhātu</em>), <em>скандхи</em>, собственные признаки дхарм (<em>dharma-svalakṣaṇa</em>), условные обозначения (<em>prajñapti</em>), личность (<em>pudgala</em>) и ум (<em>citta</em>) — всё это подобно сну и волоскам перед глазами (<em>svapna-keśoṇḍuka</em>). Этот ряд перечислений охватывает всю буддийскую аналитику: условия зависимого возникновения, элементы восприятия, совокупности существования, характеристики явлений, языковые обозначения, представление о личности и сам ум. Тем самым под одну линию подводятся как наивные представления, так и тонкие аналитические категории — все они принадлежат одному уровню видимости. Как волоски перед глазами видятся при болезни зрения, но не существует, так же и все аналитические построения видятся умом и переживаются как непосредственно данные, но не обладают собственной основой.</p>
<p>Увидев мир подобным иллюзии и сну (<em>māyā-svapna-upama</em>), следует опереться на истинную природу (<em>tattva samāśrayet</em>). Истинная природа свободна от признаков (<em>lakṣaṇa-mukta</em>) и не устанавливается ни доводами (<em>yukti</em>), ни причинами (<em>hetu</em>). Здесь снимается последняя опора — логическое обоснование. Истинная природа не подлежит установлению — ни через рассуждение, ни через причинность, поскольку сама установка на установление принадлежит различающему уму. Опора на <em>таттву</em> означает прекращение поиска обоснования. Мир, заблуждающийся в доводах и причинах (<em>yukti-hetu-visaṃmūḍha</em>), следует направить к истинной природе. Состояние Благородных (<em>ārya-vihāra</em>), не передаётся через учение — оно постигается каждым в себе самом, лично (<em>pratyātma-vedya</em>). Речь не идёт о замене одного способа познания другим, следует отказаться от самого стремления установить истину как объект. Благодаря умиротворению всех множащихся умопостроений (<em>sarva-prapañca-upaśama</em>) заблуждение более не разворачивается. Если различение принимается как мудрость (<em>prajñā yāvat vikalpante</em>), то продолжается заблуждение.<a href="#ref-562" class="text-blue-500 hover:underline ml-2">↩</a></p>

<p class="my-2" id="citation-563"><sup>563</sup> Все воззрения — иллюзия. Бытие и небытие, постоянство и непостоянство, <em>шуньята</em> и «сущность» — лишь выстроенные понятия ума. Мир и сансара разворачиваются через сознание и видимое. С прекращением цепляния к объектам — связи, рождение, смерть и свобода теряют власть над умом.<a href="#ref-563" class="text-blue-500 hover:underline ml-2">↩</a></p>

<p class="my-2" id="citation-564"><sup>564</sup> Различение «внутреннего» и «внешнего», как и противопоставление дхарм и условий, — продукт умственных построений (<em>vikalpa</em>). Их распознавание ведёт к состоянию «без образов» (<em>nirābhāsa</em>), где нет схватывания каких-либо образов как независимых сущностей.</p>
<p>Если рассматривать соотнесённость ума и отпечатков, то ум не отделён от отпечатков (<em>vāsanā</em>), но и не тождествен им. Ум не имеет отличительного признака (<em>abhinnalakṣaṇa</em>): его нельзя выделить как самостоятельную сущность, отделённую от своих проявлений, хотя он и «окружён» ими.</p>
<p>«Загрязнение» указывает не на внешнее примешивание, это искажённый режим работы ума, обусловленный <em>мано-виджняной</em>. Сама чистота ума не затрагивается отпечатками — и потому «очищение» не есть удаление чего-либо инородного.</p>
<p>Сравнение с небом показывает абсурдность попытки ограничить <em>Алаю</em> категориями бытия и небытия. Когда деятельность <em>мано-виджняны</em> прекращается (<em>vyāvṛtti</em>), исчезает омрачённость, и через всестороннее постижение дхарм ум распознаётся как «Будда».</p>
<p>Прекращение трёх потоков (<em>saṃtati</em>) означает выход за пределы временной развёртки. В этом состоянии отсутствуют как утверждение бытия, так и его отрицание, и устраняются четыре логические крайности (<em>catuṣkoṭi</em>). Существование / становление (<em>bhava</em>) раскрывается как всегда подобное иллюзии — распознавание его изначального характера.<a href="#ref-564" class="text-blue-500 hover:underline ml-2">↩</a></p>

<p class="my-2" id="citation-565"><sup>565</sup> Две природы (<em>воображаемая</em> и <em>зависимая</em>) и семь ступеней — <em>citta-saṃbhava</em> применяются как способы структурирования реальности. <em>Совершенная природа</em> (<em>niṣpanna</em>) — прекращение самой структурирующей деятельности. Поэтому «остальные ступени» и «ступень Будды» — это исчерпание уровневого мышления.<a href="#ref-565" class="text-blue-500 hover:underline ml-2">↩</a></p>

<p class="my-2" id="citation-566"><sup>566</sup> Пока что-либо воспринимается (<em>upalabhyate</em>) как внешнее, как нечто отдельное от ума и обладающее собственной сущностью, продолжается заблуждение (<em>bhrānti</em>). При пробуждении собственного ума (<em>sva-citta-saṃbodha</em>) оно не возникает и не прекращается (<em>na pravartate na nivartate</em>), так как не обладает собственной основой. Заблуждение существует лишь до тех пор, пока есть восприятие объектов.</p>
<p>Когда распознана природа ума, заблуждение не устраняется как нечто бывшее, а распознаётся как никогда не бывшее.</p>
<p>В отсутствии возникновения (<em>anutpāda</em>) нет и причинности как реального порождения (<em>kāraṇābhāva</em>). Как только появляется уверенность, что нечто «есть» (<em>bhāva</em>), схватывание, связь, так сразу ум ввергается в цепь связанных событий и происходит попадание в сансару (<em>saṃsāraprāpti</em>).</p>
<p>Видя всё как иллюзию (<em>māyādi-sadṛśa</em>), не схватывай признаки (<em>lakṣaṇaṃ na vikalpayet</em>), распознай природу воспринимаемого.<a href="#ref-566" class="text-blue-500 hover:underline ml-2">↩</a></p>

<p class="my-2" id="citation-567"><sup>567</sup> Будда учит двояко: через признаки (<em>lakṣaṇa</em>) — структуры, в которых разворачивается различение, и через прямое постижение (<em>adhigama</em>) — вне опоры на признаки.</p>
<p class="my-2">Четырёхчастный способ наставления — установление (<em>siddhānta</em>) и разъяснение через доводы (<em>yukti-deśanā</em>) — относится к области, где действует различение. Учение работает внутри заблуждения, постепенно лишая его опор. Где есть форма и структура (<em>saṃsthāna, ākṛti</em>), там возникает различение (<em>vikalpa</em>). Где отсутствуют имя и структура (<em>nāma-saṃsthāna-viraha</em>), там раскрывается собственная природа (<em>svabhāva</em>) как несхватываемость.</p>
<p class="my-2">Гатха 248 провозглашает: пока есть различение, существует воображаемый признак (<em>kalpita-lakṣaṇa</em>); при отсутствии различения не остаётся и того, что могло бы быть названо «природой».</p>
<p class="my-2">Используемые в гатхах термины истинность (<em>tattva</em>), готра и Таковость (<em>tathatā</em>) указывают на одно. Готра, иногда упоминаемая как <em>татхагата-готра</em>, здесь понимается как природа основы (<em>vastu-svabhāva</em>), а основа в данном случае принимается как <em>tattva</em>. Таковость (<em>tathatā</em>) свободна от схватывания умом (<em>citta-nirmukta</em>) и лишена измышлений (<em>kalpanā</em>). Триада <em>tattva</em>–<em>gotra</em>–<em>tathatā</em> здесь предвосхищает позднейшую махаянскую и ваджраянскую схему «Основа–Путь–Плод», хотя в <strong><em>Ланкаватаре</em></strong> она ещё не оформлена как систематическая модель. Тем не менее, теоретическая основа для такого прочтения уже заложена: <em>tattva</em> как недвойственная данность, <em>gotra</em> как её неотъемлемая возможность, <em>tathatā</em> как её осуществление в недвойственном видении.</p>
<p class="my-2">Вечная, неизменная, чистая основа (<em>vastu</em>) объясняет возможность пути. Если бы её не было, различение между омрачением и очищением теряло бы смысл. Омрачение и очищение происходят относительно основы, как движение облаков относительно неба. Как говорилось ранее, сфера Благородных (<em>ārya-gocara</em>) — это видение, в котором схватывание двойственности прекращено, а термины «истинность», «готра», «Таковость» указывают на предел различающего мышления.<a href="#ref-567" class="text-blue-500 hover:underline ml-2">↩</a></p>

<p class="my-2" id="citation-568"><sup>568</sup> Кривизна зеркала ума реализует иллюзию двойственности воспринимаемого. При «встряхивании» (<em>vidhūtaṃ</em>) этого зеркала кривизна становится (<em>bhavet</em>) бесконечной (плоское зерцало) и «пыль» иллюзии независимых образов осыпается, обнажая изначальную чистоту зеркала, и всё «движущееся» (вся вселенная) узнаётся йогином как собственный ум (<em>svacittaṃ paśyato jagat</em>).<a href="#ref-568" class="text-blue-500 hover:underline ml-2">↩</a></p>

<p class="my-2" id="citation-569"><sup>569</sup> Проследим путь от различения к недвойственной мудрости, изложенный в гатхах 251–260. Этот фрагмент представляет последовательное прояснение: от распознавания иллюзорного характера явлений — к постижению недвойственной природы ума.</p>
<p>Гатха 251 указывает на парадокс: явления возникают в зависимости от условий (<em>pratyaya</em>), но при этом лишены различений (<em>vikalpa</em>). Условия обусловливают проявление, однако сами проявления не обладают той определённостью, которую им приписывает различающий ум. Подобно иллюзии или сну, они являются, но не имеют самостоятельной основы. Видение (<em>vipaśyanā</em>) этой природы освобождает ум от заблуждения.</p>
<p>Гатхи 252–253 проводят ключевое различие между природой ума и его омрачённым состоянием. Отпечатки скверны (<em>dauṣṭhulya-vāsanā</em>) — кармические семена клеш — разнообразны и связаны с умом, проявляясь вовне как «внешние объекты». Однако это проявление — не истинная природа ума (<em>citta-dharmatā</em>). Природа ума изначально чиста (<em>śuddhā</em>); сам ум не порождён заблуждением (<em>bhrānti</em>). Заблуждение, состоящее из омрачений, скрывает природу ума, делая её невидимой, подобно тому, как облака скрывают солнце, не затрагивая его сияния.</p>
<p>Гатха 254 раскрывает недвойственность заблуждения и истины. То, что воспринимается как заблуждение (<em>bhrānti-mātra</em>), и есть Таковость (<em>tattva</em>) — иной истины нет. Таковость не находится в обусловленном (<em>saṃskāra</em>) как его свойство и не существует отдельно от него как запредельная ему сущность. Она постигается через прямое видение (<em>darśana</em>) самих обусловленных явлений в их истинной природе — подобно тому как пустотность верёвки постигается через саму верёвку, а не помимо неё. (Помним известное выражение «Сутры сердца»: «Здесь, о Субхути: форма — <em>шуньята</em>; <em>шуньята</em> — форма. Форма неотделима от <em>шуньяты</em>; <em>шуньята</em> неотделима от формы.»)</p>
<p>Когда йогин видит обусловленное (<em>saṃskṛta</em>) освобождённым от обозначаемого (<em>lakṣya</em>) и признака (<em>lakṣaṇa</em>) — то есть от наложения понятий имени и характеристики, — тогда весь мир (<em>jagat</em>) рассеивается / очищается для того, кто узрел свой собственный ум (<em>sva-citta</em>). Мир не исчезает физически; исчезает его кажущаяся внешность, определённость и вещественность.</p>
<p>Гатхи 256–257 представляют три последовательных уровня постижения. Сначала утверждается видение «только-ума» (<em>citta-mātra</em>): воспринимаемое не имеет внешнего источника. Затем, пребывая в опоре на Таковость (<em>tathatā-ālambana</em>), йогин превосходит и саму идею «только-ума» — ведь цепляние за «ум» воспроизводит ту же двойственность. Наконец, превзойдя «только-ум», йогин превосходит и состояние «без образов» (<em>nirābhāsa</em>) — последнюю тонкую опору различающего сознания. Утвердившийся в этом состоянии, он зрит саму Махаяну — недвойственную реальность, которую нельзя ни схватить, ни описать.</p>
<p>Гатха 258 описывает плод этого постижения: путь без усилий (<em>anābhoga-gati</em>), умиротворённый и очищенный обетами бодхисаттвы, ведёт к высшему знанию (<em>jñāna</em>), лишённому представления о «я» (<em>anātmaka</em>). Это знание настолько свободно от схватывания, что не цепляется даже за состояние «без образов» — последнюю возможную опору.</p>
<p>Гатхи 259–260 дают схему различения сфер опыта. Сфера ума (<em>citta-gocara</em>) соотносится с истиной страдания (<em>duḥkha-satya</em>), поскольку именно на уровне ума разворачивается переживание обусловленности. Сфера знания (<em>jñāna-gocara</em>) связана с истиной происхождения (<em>samudaya</em>), как распознавание причинности. Сфера мудрости (<em>prajñā-gocara</em>) охватывает две истины — прекращение и путь, — а также землю Будды (<em>buddha-bhūmi</em>), где мудрость действует спонтанно. Тот, кто распознаёт эти три сферы, не запутывается в признаках (<em>lakṣaṇa</em>) — не принимает построения понятий за реальность.</p>
<p>Эта последовательность гатх представляет завершённый путь от распознавания иллюзорности через постепенное отбрасывание всё более тонких опор к окончательному постижению недвойственной природы реальности.<a href="#ref-569" class="text-blue-500 hover:underline ml-2">↩</a></p>
<hr class="my-8 border-t-4 border-gray-500">
</div>

<div class="citations mt-4 text-lg">
    <hr class="my-8 border-t-4 border-gray-500">

    <p class="my-2" id="citation-570"><sup>570</sup> Глагол <em>viśudhyate</em> («очищается») не означает, что знание Будды было загрязнено и затем стало чистым. Речь идёт об устранении условий искажения (<em>vikalpa, samāropa, apavāda</em>), вследствие чего знание более не искажается как двойственное. Знание Будды — это не некая сущность или скрытый плод, это способ видения, при котором ум перестаёт искажать собственную природу. Оно не «раскрывается» как заранее существующая сущность — оно просто становится очевидным, когда прекращается наложение понятий.<a href="#ref-570" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-571"><sup>571</sup> Сознание возникает не само по себе и не из внешних объектов как независимых явлений. Оно — событие при сочетании условий: органа чувств (<em>cakṣus</em>), формы (<em>rūpa</em>), света (<em>āloka</em>), пространства (<em>ākāśa</em>) и <em>манаса</em>. <em>Алая</em> служит основой этого возникновения — она хранит кармические отпечатки, которые становятся явными при встрече с условиями. Без условий <em>Алая</em> не проявляется как сознание; без <em>Алаи</em> условия не порождают познавательного действия.</p>
    <p>В момент возникновения сознания одновременно проявляется тройственная структура: схватываемый объект (<em>grāhya</em>), схватывание (<em>grāha</em>) и схватывающий субъект (<em>grahītṛ</em>). Они не существуют как отдельные явления и не имеют собственной основы (<em>avastuka</em>) (<em>nāsti nāma hy avastukam</em>, буквально: «ничто из этого не имеет основы — ни имени, ни сущности») — это единое расщепление недвойственного опыта на кажущуюся двойственность.</p>
    <p class="my-2">Заблуждение заключается в овеществлении этого расщепления: различающий ум принимает его за действительное устройство реальности — как если бы объект, субъект и связь между ними существовали независимо и предшествовали событию познания. В действительности всё это — единый процесс различения (<em>vikalpa</em>), который сам порождает видимость тройственности из недвойственной основы.</p>
    <p>Однако отсутствие собственной основы не означает беспричинности (<em>nirhetu</em>). Различение обусловлено (<em>sapratyaya</em>): оно возникает из кармических отпечатков (<em>vāsanā</em>), хранящихся в <em>Алае</em>, при встрече с соответствующими условиями. Будда отвергает обе крайности: и овеществление различения (принятие его за нечто реальное), и его отрицание как беспричинной случайности.</p>
    <p>Распознавание (<em>abhijñā</em>) того, что субъект и объект не предшествуют познанию, а возникают одновременно с ним как его внутреннее расщепление, разрушает саму опору различения — и тройственная структура сансарного сознания рассыпается.<a href="#ref-571" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-572"><sup>572</sup> Здесь последовательно подрывается доверие к языку, понятийному мышлению и умозрительным построениям, показывая их принадлежность к сфере различения (<em>vikalpa</em>).</p>
    <p>В гатхе 264 устанавливается принципиальное несовпадение имени (<em>nāma</em>) и объекта (<em>artha</em>): ни имя не возникает в объекте, ни объект — в имени. Тем самым отвергается представление о языке как прямом отражении реальности. Различение, возникающее в зависимости от причин и условий, не должно приниматься как достоверное основание познания.</p>
    <p>Далее это видение углубляется: не только явления лишены собственной природы (<em>svabhāva</em>), но и высказывания о них лишены основы. Различается <em>шуньята</em> как предмет учения и её смысл как непосредственное постижение; не различающий их впадает в блуждание между крайностями.</p>
    <p>В гатхе 266 критикуется попытка установить «истину» посредством домысливания (<em>manyanā</em>). В этом случае учение остаётся на уровне условных обозначений (<em>prajñapti</em>). «Пять способов установления единства» (<em>pañcadhā ekatva-siddhi</em>) подразумеваются пять логически невозможных попыток доказать единство между двумя разными категориями. Эти пять пар:</p>
    <ul class="list-disk mb-6 pl-2 space-y-1 ml-2">
        <li>Имя и объект (<em>nāma-artha</em>): Нельзя утверждать, что имя и то, что оно обозначает, — одно и то же. (Если бы так было, то «огонь» жёг бы язык.)</li>
        <li>Объект восприятия и объект схватывания (<em>grāhya-grāhaka</em>): Схватываемое (<em>grāhya</em>) и схватывающий (<em>grāhaka</em>) не могут быть едины. (Если бы они были одним, не было бы познания.)</li>
        <li>Причина и следствие (<em>hetu-phala</em>): Причина и следствие не могут быть едины. (Если бы они были одним, причина уничтожалась бы одновременно с возникновением следствия — и ничего бы не возникало.)</li>
        <li>Части и целое (<em>avayava-avayavin</em>): Целое не может быть тождественно своим частям. (Если бы так было, целое исчезало бы при удалении одной части, но также не могло бы существовать без них — логический тупик.)</li>
        <li>Субъект действия и действие (<em>kartṛ-karma</em>): Действующий и действие не могут быть едины. (Если бы они были одним, действие происходило бы само по себе, без деятеля — или наоборот.)</li>
    </ul>

    <p>Все эти попытки установить <em>ekatva</em> (единство, тождество) между различными сторонами опыта — продукт <em>vikalpa</em>. Они кажутся логичными, но ведут к абсурду.</p>
    <p>Гатха 267 направлена против крайностей «есть» и «не-есть». Разрастание понятий (<em>prapañca</em>) выступает как среда, подверженная воздействию Мары, то есть омрачения. Подчёркивается также опасность нигилистического уклона: стремление к утверждению небытия рассматривается как следствие неверного понимания отсутствия «я» (<em>nairātmya</em>).</p>
    <p>Завершает этот ряд отказ от метафизических положений (вечность, творец) путём сведения их к уровню рассудочных построений. Высшая истина (<em>paramārtha-satya</em>) определяется как невыразимая; её постижение связано с угасанием различения, в котором открывается видение дхарм.<a href="#ref-572" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-573"><sup>573</sup> Здесь <em>манас</em> — омрачённый ум (<em>kliṣṭa-manas</em>), который постоянно схватывает поток <em>Алаи</em> как «я». В йогачаре различаются три уровня сознания: <em>ālaya-vijñāna</em> (сознание-сокровищница), <em>manas</em> (омрачённый ум), <em>vijñāna</em> (различающие сознания). Шестое сознание (ментальное сознание) думает о явлениях, объединяет данные от пяти чувств в целостные объекты, а седьмое (<em>манас</em>) занято поддержанием чувства «я». Оно работает непрерывно, даже во сне. Именно оно «загрязняет» (<em>kliṣṭa</em>) наш опыт чувством «я». Оно не видит объектов внешнего мира, а обращено внутрь — к <em>ālaya-vijñāna</em>, которое ошибочно принимает за постоянное «я».<a href="#ref-573" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-574"><sup>574</sup> Фраза «Распознав наложение как наложение» (<em>samāropaṃ samāropya</em>) указывает на распознавание, выявление самого процесса, механизма наложения признака, воззрения, причин, бытия. (Смотри подглаву 21 главы II). Когда йогин свободен от наложения и отрицания, открывается <em>tathatā</em>.<a href="#ref-574" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-575"><sup>575</sup> Сознание, возникающее из <em>Алаи</em>, по своей природе недвойственно; оно лишь кажется расчленённым на субъект и объект. Поэтому «единый смысл» (<em>eka-artha</em>) опыта не может быть постигнут двойственным умом (<em>dvi-citta</em>), потому что само схватывание его искажает. Гатха отвергает и реализм («объект существует сам по себе»), и субъективизм («всё — вымысел»): двойственность лишена собственной основы и обусловлена структурой сознания.<a href="#ref-575" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-576"><sup>576</sup> Карма не имеет самостоятельного источника — она условна и лишена собственной природы.<a href="#ref-576" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-577"><sup>577</sup> Шесть гатх последовательно отрицают все категории буддийского учения. Когда видится истинная природа ума, нет ни говорящего, ни сказанного — даже <em>шуньята</em> здесь не утверждается.</p>
    <p>Если же собственный ум не распознан, возникает сеть воззрений — система определённых взглядов.</p>
    <p>Потому далее отрицаются условия, органы чувств, элементы, <em>скандхи</em> (274); карма и её результаты (275); добро и зло, время, нирвана, сама «природа дхарм» (276); Будда, истины, причины, плоды, заблуждение (277). Это отрицание направлено против схватывания этих понятий как реальных сущностей, обладающих собственной природой. Учение о «только-уме» вводится ради устранения всех воззрений — включая само это учение.<a href="#ref-577" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-578"><sup>578</sup> Всё, что составляет сансарный опыт — клеши, действия, тело, деятель и результат — имеет природу иллюзии. Сравнения с миражом, сном и городом гандхарвов указывают на зависимость от условий и отсутствие самостоятельной основы.</p>
    <p class="my-2">Установление в «только-уме» означает распознавание того, что вся структура опыта разворачивается как деятельность сознания. В этом распознавании признак бытия устраняется — больше не схватывается как разделение на субъект и объект. Тем самым устраняются крайние воззрения о вечном существовании и полном уничтожении. Учение о «только-уме» здесь — средство устранения крайностей.<a href="#ref-578" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-579"><sup>579</sup> Этот блок завершает отрицание всех представлений и переходит к описанию пути через учение о «только-уме».</p>
    <p>Нирвана свободна от всех определений — в ней нет ни <em>скандх</em>, ни «я», ни каких-либо признаков (281). Само цепляние за освобождение как за достижимую цель должно быть оставлено. Вхождение в «только-ум» означает распознавание того, что все категории — включая освобождение и связанность — возникают в уме и не обладают независимой реальностью.</p>
    <p>Корень заблуждения — принятие видимого за внешнее и независимо существующее (282). Люди считают объекты внешними, но сам ум возник из неявленного (<em>adṛśya</em>), из глубины, которая не становится объектом восприятия. Поэтому истинная природа ума остаётся невидимой для того, кто не распознал её.</p>
    <p><em>Васаны</em> — кармические отпечатки — проявляются как тело, объекты наслаждения и место обитания (283). Всё, что воспринимается как «мир», есть развёртывание этих отпечатков. Но сам ум не является ни бытием, ни небытием; он не обнаруживается в васанах как нечто определённое. <em>Васаны</em> — это способ проявления, но не сама природа ума.</p>
    <p class="my-2">Образ белой основы и пятна (284) указывает на изначальную чистоту ума. Пятно видно на белом фоне, но само белое в пятне не проявляется — загрязнение скрывает чистоту. Так <em>васаны</em> и <em>клеши</em> скрывают природу ума, подобно тому как облака скрывают небо. Ум в своей истинной природе остаётся незапятнанным, но не виден из-за наслоений.</p>
    <p>Различаются три уровня познавательной деятельности (285–286). Умом (<em>citta</em>), связанным с объектами, накапливается карма. Знание (<em>jñāna</em>) способно различать и распознавать природу кармы, но оно ещё вовлечено в рассуждение (<em>tarka</em>) — мышление, опирающееся на умозаключения и построения. Мудрость (<em>prajñā</em>) выводит за пределы образов (<em>nirābhāsa</em>) — прекращается опора на представления и формы. В этом состоянии без образов и в высшем постижении (<em>viśeṣa</em>) разворачивается истинное знание — недвойственное постижение, свободное от разделения на познающего и познаваемое. Здесь достигается истинная сила (<em>prabhāva</em>) — спонтанная действенность пробуждённого ума.<a href="#ref-579" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-580"><sup>580</sup> Когда все аспекты ума освобождаются от структур понятий, достигается недвойственная природа дхарм (<em>avikalpa-dharmatā</em>). Шраваки останавливаются на этом уровне — они постигают шуньяту «я» и успокаивают ум, и не идут дальше к полному пробуждению.</p>
    <p>Что касается бодхисаттв, то на каждой высшей ступени принятия истины (<em>kṣānti</em>) у бодхисаттвы раскрывается чистое знание, тождественное знанию Татхагаты. <em>Kṣānti</em>  часто переводят как «терпение», но в махаяне это глубокое принятие истины, стадия реализации. Далее в тексте упоминается <em>anutpattika-dharma-kṣānti</em> (принятие не-возникновения дхарм), достигаемая на восьмой бхуми. Повтор <em>kṣānte kṣānte</em> указывает, что на каждой такой ступени, по мере углубления, раскрывается новое качество знания. Это знание благое (<em>śubha</em>) — не только в моральном смысле, оно также чистое, недвойственное, свободное от омрачений. Знание возникает ради высшего смысла (<em>viśeṣa-artha</em>) — спасения всех существ. При этом оно свободно от условной / предписанной / намеренной  деятельности (<em>samudācāra-varjita</em>).<a href="#ref-580" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-581"><sup>581</sup> Смотри подглаву 19 главы II.<a href="#ref-581" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-582"><sup>582</sup> Ум возник из того, что само не возникало (<em>abhūta</em>) — из <em>Алаи</em>, недвойственной основы. Но сам ум как объект не схватывается — его нельзя увидеть, как видят форму или звук. То, что люди воспринимают как тело, объекты наслаждения и мир — всё это проявления кармических отпечатков (<em>vāsanā</em>) и не является независимой реальностью.<a href="#ref-582" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-583"><sup>583</sup> Гатха опровергает представление о форме как реально существующем явлении. Никакая форма не состоит полностью из элементов (<em>bhautika</em>), поскольку всё воспринимаемое — проявление ума. Даже то, что кажется плотным и вещественным, возникает из кармических отпечатков и не имеет независимой основы.</p>
    <p>Одновременно существуют формы, лишённые природы элементов (<em>abhautika</em>) — такие как град гандхарвов, сновидения, магические иллюзии и марево. Они воспринимаются как внешние, но не обладают материальностью.</p>
    <p>Различие между двумя типами форм, которые обе иллюзорны, в способе проявления и восприятия: одни кажутся материальными, другие воспринимаются как нематериальные. Граница между «материальным» и «воображаемым» условна, потому что все формы возникают в поле сознания и не существуют независимо от него.<a href="#ref-583" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-584"><sup>584</sup> «Тройственная мудрость» (<em>trividhā prajñā</em>) — три последовательных уровня постижения, ведущие к сфере Благородных (<em>ārya-gocara</em>):</p>
    <ul class="list-none mb-6 pl-2 space-y-1 ml-2">
    <li>(1) отсутствие «я» в личности (<em>pudgala-nairātmya</em>),</li>
    <li>(2) отсутствие «я» в дхармах (<em>dharma-nairātmya</em>),</li>
    <li>(3) недвойственное постижение природы ума.</li>
</ul>

    <p>Эти уровни могут соотноситься с путями шраваков, пратьекабудд и бодхисаттв, однако в данном контексте акцент сделан на внутренней градации самой мудрости, а не на типах пути. Как указывает гатха 294, лишь через вхождение в «только-ум» (<em>cittamātra</em>) эта мудрость достигает полноты и становится незапятнанной мудростью Татхагат (<em>tāthāgatī amalā prajñā</em>).<a href="#ref-584" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-585"><sup>585</sup> Гатха критикует две крайности причинности: происхождение из существующего ведёт к воззрению о единстве (причина и следствие — одно), происхождение из несуществующего — к воззрению о различии (полный разрыв между причиной и следствием). Обе позиции порождают философские крайности, которые йогачара устраняет через учение о зависимой природе — потоке условий без вещественного носителя.<a href="#ref-585" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-586"><sup>586</sup> Связывание (<em>bandhana</em>) — сансарное закрепощение — состоит из косной приверженности (<em>dauṣṭhulya</em>) к признакам (<em>nimitta</em>) и рождается из ума. Ключевая ошибка заключается в не распознавании воображаемого как воображаемого (наложение признаков на поток опыта), невежды измышляют зависимое как независимую реальность — принимают обусловленный поток за нечто вещественное.<a href="#ref-586" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-587"><sup>587</sup> Зависимое (<em>paratantra</em>) — причинно-обусловленный поток ума; воображаемое (<em>parikalpita</em>) — тот же поток, воспринятый через наложение признаков и схватывание как определённого, вещественного. Это два способа восприятия одного процесса.<a href="#ref-587" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-588"><sup>588</sup> Нет третьей истины помимо условной и высшей. Воображаемое — это условная истина (ошибочное восприятие), высшая истина — устранение воображаемого и прямое постижение Таковости. Попытки найти третье основание (материю, абсолют, независимый ум) бесплодны — есть только заблуждение и его прекращение.<a href="#ref-588" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-589"><sup>589</sup> Есть единое (<em>ekaṃ vastu</em>), и оно кажется множественным (<em>citram</em>), хотя множественности в нём нет — это и есть модель признаков воображаемого (<em>parikalpita-lakṣaṇa</em>). Единое (<em>vastu</em>) — это зависимая природа; множественность (<em>citra</em>) — воображаемая природа.<a href="#ref-589" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-590"><sup>590</sup> Это — точная модель зависимой природы (<em>paratantra</em>): видимость (многообразие форм) возникает, но её основание — подобно глазной болезни — не тождественна видимому и в то же время не есть ничто. Болезнь — не форма и не отсутствие формы, но причина видимости. Так и зависимое — не нечто и не пустота, это обусловленный поток, порождающий видимость явлений.<a href="#ref-590" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-591"><sup>591</sup> Как золото без примесей, вода без мути, небо без облаков — так зависимое, освобождённое от воображаемого, предстаёт как совершенная природа.<a href="#ref-591" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-592"><sup>592</sup> Три вида шраваков и три вида бодхисаттв — это классификации на уровне пути. Нирманические (<em>nirmita</em>) шраваки — созданные Буддой для блага существ; рождённые из обета (<em>praṇidhānaja</em>) — обретшие путь благодаря стремлению; рождённые из Дхармы (<em>dharmasaṃbhava</em>) — достигшие освобождения через прямое постижение, свободные от клеш.</p>
    <p>Сам Будда лишён всех признаков (<em>lakṣaṇa</em>) — он не является объектом, который можно определить или схватить. Однако его образ (<em>buddhabimba</em>) отражается в уме каждого существа. Повтор «<em>citte citte</em>» (в уме, в уме) подчёркивает, что это происходит в каждом отдельном уме — не как внешний объект, а как внутреннее проявление природы Будды. Подобно луне, отражающейся в разных водоёмах: луна одна, но отражений множество, и каждое видится там, где есть вода.<a href="#ref-592" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-593"><sup>593</sup> Ум колеблется между двумя ошибками: считать воображаемое реальным (<em>samāropa</em>) и отрицать сам опыт (<em>apavāda</em>). Обе принадлежат сфере различения (<em>vikalpa</em>) и поддерживают его непрерывность. Освобождение — прекращение самого различения, а не утверждение некоего «истинного» положения вещей.<a href="#ref-593" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-594"><sup>594</sup> Будда здесь опровергает попытку создать новую двойственность: «есть реальный поток (<em>paratantra</em>) и есть его отсутствие — воображаемое (<em>parikalpita</em>)». Если бы воображаемое было просто небытием, не связанным с зависимым, мы имели бы две независимые реальности: бытие и ничто. Текст утверждает их соотнесённость: воображаемое — не отсутствие реальности, а сама реальность (зависимый поток), воспринятая ошибочно. Как в примере со «змеёй» и «верёвкой»: змея — это не отсутствие чего-то ещё, а сама верёвка, ошибочно принятая за змею.<a href="#ref-594" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-595"><sup>595</sup> Механизм иллюзии (<em>parikalpita</em>): ум соединяет признак (<em>nimitta</em>) — вспышку восприятия, образ — с именем (<em>nāma</em>) — понятием, ярлыком. В этот момент поток (<em>paratantra</em>) застывает в объект, нечто конкретное. <em>Paratantra</em> не видится напрямую — только через призму <em>parikalpita</em>. Две первые из пяти дхарм (<em>nimitta, nāma</em>) порождают воображаемое, скрывающее зависимое.<a href="#ref-595" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-596"><sup>596</sup> <em>Parodbhava</em> («возникновение иного») — технический термин, обозначающий проецирование объекта как «иного» по отношению к воспринимающему. В йогачаре это составляет основу двойственного восприятия.</p>
    <p class="my-2">Гатха 308 не утверждает, что зависимая природа «очищается» и становится совершенной. Напротив, совершенная природа (<em>pariniṣpanna-svabhāva</em>) постигается тогда, когда прекращается само порождение «иного» посредством воображаемого (<em>parikalpita</em>). При этом не возникает никакой новой реальности; прекращается лишь искажение, создающее видимость разделения на «субъект» и «объект».<a href="#ref-596" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-597"><sup>597</sup> <strong>Десять видов воображаемого (<em>parikalpita</em>) и шесть видов зависимого (<em>paratantra</em>):</strong></p>
    <p class="my-2"><strong>Десять видов воображаемого (<em>daśavidha-parikalpa</em>)</strong></p>
    <p class="my-2">Это классификация того, как именно наш ум «разрезает» реальность на части, создавая ложные объекты:</p>
    <ol class="list-decimal list-outside ml-8 space-y-1 pl-5">
        <li class="my-2"><strong>Воображение признака (<em>lakṣaṇa</em>)</strong>: приписывание вещам формы, цвета и т.д.</li>
        <li class="my-2"><strong>Воображение явления (<em>bhāva</em>)</strong>: приписывание вещам статуса реально существующих сущностей.</li>
        <li class="my-2"><strong>Воображение связи (<em>saṃbandha</em>)</strong>: вера в то, что признаки принадлежат объекту (например, «белизна» принадлежит «раковине»).</li>
        <li class="my-2"><strong>Воображение различия (<em>vibhāga</em>)</strong>: разделение единого потока на разные дхармы.</li>
        <li class="my-2"><strong>Воображение неизменной сущности (<em>svabhāva</em>)</strong>: приписывание вещам независимого, вечного «я».</li>
        <li class="my-2"><strong>Воображение причины (<em>hetu</em>)</strong>: поиск внешних причин для явлений.</li>
        <li class="my-2"><strong>Воображение воззрения (<em>dṛṣṭi</em>)</strong>: приверженность философским догмам.</li>
        <li class="my-2"><strong>Воображение рассуждения (<em>tarka</em>)</strong>: попытка постичь истину через логические выкладки.</li>
        <li class="my-2"><strong>Воображение рождения (<em>janma</em>)</strong>: вера в реальность возникновения и смерти.</li>
        <li class="my-2"><strong>Воображение невозникновения (<em>ajātia</em>)</strong>: даже цепляние за идею «пустоты как отсутствия рождения» здесь считается видом воображения.</li>
    </ol>
    <p class="my-2 mt-4"><strong>Шесть видов зависимого (<em>ṣaḍvidha-paratantra</em>)</strong></p>
    <p class="my-2">Это уровни обусловленности, которые составляют поток нашего сознания:</p>
    <ol class="list-decimal list-outside ml-8 space-y-1 pl-5">
        <li class="my-2"><strong>Зависимость от причины (<em>hetu</em>)</strong>: обусловленность первичными кармическими семенами.</li>
        <li class="my-2"><strong>Зависимость от условий (<em>pratyaya</em>)</strong>: обусловленность вторичными факторами (органы чувств, объекты).</li>
        <li class="my-2"><strong>Зависимость от признака (<em>lakṣaṇa</em>)</strong>: зависимость восприятия от того, какой образ всплывает в уме.</li>
        <li class="my-2"><strong>Зависимость от различения (<em>vikalpa</em>)</strong>: зависимость опыта от текущей работы мысли.</li>
        <li class="my-2"><strong>Зависимость от выражения (<em>abhilāpa</em>)</strong>: зависимость восприятия от языка и слов (мы видим то, что можем назвать).</li>
        <li class="my-2"><strong>Зависимость от чистоты/нечистоты (<em>viśuddhi-aviśuddhi</em>)</strong>: зависимость от того, насколько ум затуманен <em>васанами</em> в данный момент.</li>
    </ol>
    <p class="my-2">Таковость (<em>tathatā</em>) — не объект познания, это прекращение схватывания. К ней не применимы определения, понятия и образы — она постигается лишь в прямом опыте.<a href="#ref-597" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-598"><sup>598</sup> Этот стих — краткая схема для практика.</p>
    <p><strong>Пять дхарм</strong> — вехи анализа опыта: образ (<em>nimitta</em>) + имя (<em>nāma</em>) → различение (<em>vikalpa</em>) → правильное знание (<em>samyagjñāna</em>) → Таковость (<em>tathatā</em>).</p>
    <p><strong>Три природы</strong> — вехи постижения реальности: воображаемое (<em>parikalpita</em>) → зависимое (<em>paratantra</em>) → совершенное (<em>pariniṣpanna</em>).</p>
    <p>Обе схемы описывают один процесс: как ум заслоняет реальность и как она раскрывается при распознавании этого механизма.<a href="#ref-598" class="text-blue-500 hover:underline ml-2">↩</a></p>
    <hr class="my-8 border-t-4 border-gray-500">
</div>

<div class="citations mt-4 text-lg">
    <hr class="my-8 border-t-4 border-gray-500">

    <p class="my-2" id="citation-599"><sup>599</sup> Гатха использует метод <em>prasaṅga</em> (доведение до абсурда): если допустить, что форма состоит из реальных элементов (<em>bhūta</em>), то сами элементы должны обладать той же природой — быть «материальными» (<em>bhautika</em>). Это ведёт к логической несостоятельности понятия «элемента» как первоосновы. Следовательно, ни объект (<em>lakṣya</em>), ни его признаки (<em>lakṣaṇa</em>) не могут быть установлены как имеющие собственную природу.<a href="#ref-599" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-600"><sup>600</sup> Различие между «великими элементами» как причиной (<em>kāraṇa</em>) и конкретными формами (земля, вода и т.п.) как следствием (<em>kārya</em>) показывает условность самой схемы «элементного» объяснения. При анализе самих элементов не обнаруживается никакой «материальности» (<em>bhautikam</em>); они действуют как структуры понятий, а не как самостоятельные сущности. Схема «элемент-как-причина → форма-как-следствие» работает на уровне условного обозначения (<em>saṃvṛti</em>), но при анализе не обнаруживается независимой основы.<a href="#ref-600" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-601"><sup>601</sup> Этот стих уравнивает «реальные, вещественные» физические объекты с классическими буддийскими примерами иллюзорности. Их объединяет отсутствие собственной природы при наличии видимости. «Вещественность» — это способ, которым наш ум их обозначает (<em>prajñapti</em>). Пять типов видимости:
    <ul class="list-disc mb-6 pl-2 space-y-1 ml-2">
        <li>физические тела, «материальные» формы (<em>dravya-prajñapti-rūpa</em>) — вещи обыденного мира;</li>
        <li>магические образы (<em>māyā-jāti</em>) — иллюзии фокусника;</li>
        <li>сновидения (<em>svapna-rūpa</em>) — образы во сне;</li>
        <li>град гандхарвов (<em>gandharva-nagara</em>) — небесные миражи;</li>
        <li>мираж (<em>mṛgatṛṣṇā</em>, буквально «жажда оленя») — образ воды в пустыне.</li>
    </ul>
    Все они представляют собой формы проявления, лишённые собственной основы.<a href="#ref-601" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-602"><sup>602</sup> Перечисляемые группы включают:
    <ul class="list-none my-6 pl-2 space-y-1 ml-2">
        <li><strong>Пять видов иччхантиков</strong> (<em>icchantika</em>) — существ, временно или по обету лишённых возможности войти в нирвану. Согласно <strong><em>Ланкаватаре</em></strong> (смотри подглаву 18 главы II), они разделяются на две категории, внутри которых выделяются несколько типов состояний:
            <ul class="list-none mb-6 pl-2 space-y-1 ml-2">
                <li><strong>I.</strong> Те, кто отринул корни благодетели (<em>atyanta-icchantika</em>), существа, чей путь к пробуждению пресечен их собственными деяниями и воззрениями:
                    <ol class="list-decimal mb-6 pl-2 space-y-1 ml-2">
                        <li>хулители Махаяны: те, кто активно отвергает и порочит учение о «только-уме» и пути Бодхисаттв,</li>
                        <li>совершившие «безмерные» грехи: те, кто совершил пять тягчайших преступлений (убийство матери, отца, архата, ранение Будды или внесение раскола в Сангху),</li>
                        <li>лишенные веры: те, в ком семена доверия к Дхарме полностью «выжжены» клешами, и у них нет ни малейшего раскаяния.</li>
                    </ol>
                </li>
                <li><strong>II.</strong> Те, кто исполнен сострадания (<em>mahākaruṇā-icchantika</em>), бодхисаттвы, которые становятся «иччхантиками» по доброй воле:
                    <ol class="list-decimal mb-6 pl-2 space-y-1 ml-2" start="4">
                        <li>связанные обетом: они дали клятву: «Пока все существа не спасутся, я не войду в нирвану». Поскольку сансара бесконечна, они добровольно отказываются от окончательного угасания,</li>
                        <li>пребывающие в «не-колеснице» (<em>ayāna</em>): те, кто осознал, что нирвана и сансара нераздельны, и потому остаются в мире, чтобы действовать на благо других, не стремясь к личному уходу.</li>
                    </ol>
                </li>
            </ul>
        </li>

        <li><strong>Пять родов</strong> (<em>pañca-gotra</em>) — классификация духовных предрасположенностей (согласно подглаве 17 главы II):
            <ol class="list-decimal mb-6 pl-2 space-y-1 ml-2">
                <li>род шраваков: ориентированы на личное освобождение и покой архата,</li>
                <li>род пратьекабудд: склонны к уединенному постижению двенадцати звеньев зависимого возникновения,</li>
                <li>род Татхагат: обладают потенциалом полного пробуждения ради блага всех существ (путь Бодхисаттв),</li>
                <li>неопределенный род: существа, чьи «семена» позволяют им примкнуть к любому из вышеперечисленных путей в зависимости от условий,</li>
                <li>род лишённых условий (<em>agotra</em>): те, в ком семена освобождения временно не проявлены.</li>
            </ol>
        </li>

        <li><strong>Пять колесниц</strong> (<em>pañca-yāna</em>) — это классификация уровней Учения, согласно способностей разных существ:
            <ol class="list-decimal mb-6 pl-2 space-y-1 ml-2">
                <li>Колесница богов и людей (<em>deva-manuṣya-yāna</em>): путь мирской добродетели. Опирается на соблюдение пяти запретов и совершение десяти благих деяний ради обретения благоприятного перерождения в высших мирах сансары.</li>
                <li>Колесница шраваков (<em>Śrāvaka-yāna</em>): путь «слушателей». Нацелен на личное освобождение от страданий через постижение <em>Четырех Благородных Истин</em> и достижение нирваны архата.</li>
                <li>Колесница пратьекабудд (<em>Pratyekabuddha-yāna</em>): путь «самостоятельно пробужденных». Глубокое созерцание двенадцати звеньев зависимого возникновения в одиночестве, ведущее к покою.</li>
                <li>Колесница Татхагат / Бодхисаттв (<em>Tathāgata-yāna</em>): путь Махаяны. Стремление к полному пробуждению ради спасения всех живых существ через постижение <em>шуньяты</em> и природы ума.</li>
                <li>Божественная колесница (<em>Brahma-yāna</em>): В контексте сутры часто упоминается как высшие медитативные состояния (<em>dhyāna</em>) и безмерные (<em>brahma-vihāra</em>) (сосредоточение на безмерных состояниях ума — любви, сострадании и т.д.), которые подготавливают ум к запредельному знанию.</li>
            </ol>
        </li>

        «Не-колесница» (<em>ayāna</em>) указывает на состояние, когда все идеи «пути» и «движения» оставлены. Когда йогин осознает, что мир — это лишь проявление его собственного ума, исчезает разделение на «того, кто идет», «путь» и «цель». <em>Ayāna</em> — это синоним Единой колесницы (<em>Ekayāna</em>), которая объемлет все пути, но сама не является ограниченным методом.<br>

        <li><strong>Шесть видов нирваны</strong> (<em>ṣaḍvidha-nirvāṇa</em>) — это перечень воззрений на природу освобождения, которые Будда классифицирует от ложных к истинному:
            <ol class="list-decimal mb-6 pl-2 space-y-1 ml-2">
                <li>Нирвана как прекращение (<em>nirodha</em>): Ошибочное воззрение шраваков, которые видят в нирване только остановку потока <em>скандх</em>, подобно угасанию светильника. Это «пустота как уничтожение».</li>
                <li>Нирвана как отсутствие признаков (<em>animitta</em>): Представление о том, что освобождение — это некое «пространство», где нет форм и объектов. Это застревание на стадии отрицания внешнего мира.</li>
                <li>Нирвана как невозникновение (<em>anutpāda</em>): Интеллектуальное понимание того, что дхармы не рождаются. Если это остается лишь теорией, это «сухая нирвана» без живой реализации.</li>
                <li>Нирвана как погружение в блаженное сосредоточение (<em>dhyāna-sukha</em>): Принятие глубоких состояний созерцательного блаженства в высших мирах (мирах без форм) за окончательное освобождение. Это временное успокоение, не пресекающее корни <em>васан</em>.</li>
                <li>Нирвана философов (<em>tīrthika-nirvāṇa</em>): Различные идеи небуддийских школ — вера в слияние души с <em>Атманом</em>, достижение вечного рая или окончательное разделение «духа и материи». Сутра называет это «воображаемой нирваной».</li>
                <li>Истинная нирвана Татхагат (<em>tathāgata-nirvāṇa</em>): Также известна как «нирвана без опоры» (<em>apratiṣṭhita-nirvāṇa</em>). Это прямое постижение того, что нирвана и сансара нераздельны в своей основе — в <em>Алае</em>.</li>
            </ol>
        </li>

        <li>Упоминание «<strong>двадцати четырёх делений <em>скандх</em></strong>» (<em>skandhabhedāś caturviṃśat</em>) представляет собой характерную для раздела <em>Sagāthakam</em> краткую числовую формулу. Сама сутра не даёт прямой расшифровки этого числа. Наиболее вероятное толкование связывает его с классификацией 24 дхарм, не связанных с умом (<em>citta-viprayukta-saṃskāra</em>). Эти дхармы входят преимущественно в <em>saṃskāra-skandha</em> и описывают условные силы и закономерности, управляющие процессами существования, кармы, языка, времени, пространства и причинно-следственных связей, но не являющиеся ни формой (<em>rūpa</em>), ни сознанием (<em>citta</em>), ни сопутствующими ему ментальными факторами (<em>caitta</em>). Полный список зафиксирован в трактате йогачары «Разъяснение ста дхарм» (<strong><em>Mahāyāna-śatadharma-prakāśamukha-śāstra</em></strong>), традиционно приписываемом Васубандху:<br>
        <em>Prāpti</em> (обретение), <em>Aprāpti</em> (не-обретение), <em>Sabhāgatā</em> (однородность), <em>Āsaṃjñika</em> (состояние без восприятия), <em>Asaṃjñi-samāpatti</em> (сосредоточение без восприятия), <em>Nirodha-samāpatti</em> (прекращение восприятия и чувств), <em>Jīvitendriya</em> (жизненная сила), <em>Jāti</em> (рождение), <em>Sthiti</em> (пребывание), <em>Jarā</em> (старение), <em>Anityatā</em> (непостоянство), <em>Nāmakāya</em> (группа имён), <em>Padakāya</em> (группа фраз), <em>Vyañjanakāya</em> (группа фонем), <em>Pṛthagjanatva</em> (состояние обычного человека), <em>Pravṛtti</em> (развёртывание, поворот, обращение), <em>Pratiniyama</em> (индивидуальная определённость), <em>Yoga</em> (связь), <em>Dravya/Jāva</em> (скорость), <em>Anukrama</em> (порядок), <em>Kāla</em> (время), <em>Deśa</em> (место), <em>Saṃkhyā</em> (число), <em>Sāmagrī</em> (совокупность условий).<br>
        Такое детальное деление служит педагогическим приёмом: даже при самом тонком аналитическом разборе «личности» на составляющие элементы всё это остаётся условным проявлением ума, лишённым собственной природы (<em>svabhāva</em>). Другие толкования числа 24 (например, как сумма дхарм по <em>скандхам</em>) встречаются реже и обычно не дают точного соответствия.
        </li>

        <li>Под «<strong>восемью видами формы</strong>» (<em>aṣṭau rūpāṇi</em>) в абхидхарме понимают восемь основных типов материальной формы: четыре великих элемента (земля, вода, огонь, воздух) и четыре производные формы, непосредственно воспринимаемые чувствами (видимая форма, звук, запах, вкус). Все они входят в <em>rūpa-skandha</em> и рассматриваются как условные проявления, лишённые собственной природы.</li>

        <li><strong>Двадцать четыре Будды</strong> — традиционные списки Будд прошлого. В тхеравадинской традиции (смотри <strong><em>Buddhavaṃsa</em></strong>) упоминается 28 Будд прошлого, завершающихся Готамой. Сокращённый список из 24 Будд включает:<br>
        Dīpaṅkara, Koṇḍañña, Maṅgala, Sumana, Revata, Sobhita, Anomadassī, Paduma, Nārada, Padumuttara, Sumedha, Sujāta, Piyadassī, Atthadassī, Dhammadassī, Siddhattha, Tissa, Phussa, Vipassī, Sikhī, Vessabhū, Kakusandha, Koṇāgamana, Kassapa.<br>
        В полной версии перед Dīpaṅkarой добавляются ещё трое: Taṇhaṅkara, Medhaṅkara и Saraṇaṅkara; за ними следует Готама как 28-й Будда.
        </li>

        <li><strong>Два вида сынов Победителя</strong> (<em>jinaputra</em>):
            <ul class="list-disc mb-6 pl-2 space-y-1 ml-2">
                <li>бодхисаттвы, прилагающие усилия / обладающие гордостью (<em>sābhīmānika-bodhisattva</em>) — те, кто находится на первых семи бхуми (ступенях). Они всё ещё воспринимают путь как постепенное продвижение, прилагают сознательные усилия и работают над устранением завес (<em>āvaraṇa</em>).</li>
                <li>бодхисаттвы необратимости / рожденные в Дхарме (<em>dharmatā-niṣyanda-bodhisattva</em>)— начиная с восьмой бхуми (<em>acalā</em> — <em>Непоколебимая</em>). Они действуют спонтанно, без искусственных усилий (<em>anābhoga</em>), их сознание естественно неотделимо от Таковости (<em>dharmatā / tathatā</em>). Их называют подлинными «сынами Будды», поскольку их деятельность — это чистое, ненапряжённое проявление великого сострадания, свободное от цепляния за «путь» и «плод».</li>
            </ul>
        </li>

        <li><strong>Сто восемь методов</strong> (<em>naya</em>): число 108 в этой гатхе возможно отсылает к пассажу в начале главы II, где Будда обещает разъяснить сто восемь положений (<em>aṣṭottara-śata-pada</em>), переданных прежними Буддами. Каждое из них подвергается полному отрицанию: «Рождение — это не рождение», «Нирвана — это не нирвана», «Бодхисаттва — это не бодхисаттва» — и так далее, охватывая <em>скандхи</em>, <em>дхату</em>, <em>аятаны</em>, <em>парамиты</em>, мирские явления и все возможные категории мышления. Цель этого — полностью лишить ум всякой опоры на структуры понятий (<em>vikalpa</em>), показав, что все эти положения возникают лишь как проявления ума (<em>cittamātra</em>) и лишены собственной природы (<em>svabhāva</em>).</li>

        <li><strong>Три вида шраваков</strong>:
            <ol class="list-decimal mb-6 pl-2 space-y-1 ml-2">
                <li>Шраваки, опирающийся на [достижение] плода (<em>Phalāśrita-śrāvaka</em>): те, кто достиг четырех ступеней святости (от <em>Вступившего в поток</em> до <em>Архата</em>) и полностью удовлетворен покоем нирваны. Они пребывают в состоянии «прекращения» (<em>nirodha</em>) и не стремятся к дальнейшему обучению, их трудно пробудить для деятельности на благо других.</li>
                <li>Шраваки, устремлённые к высшему (<em>Abhisamayāntika-śrāvaka</em>): ученики, которые, постигнув отсутствие «я» личности, начинают видеть ограниченность своего пути. Они открыты учению о «только-уме» и могут вступить на путь бодхисаттвы.</li>
                <li>Шраваки по проявлению (<em>Nirmāṇa-śrāvaka</em>): это бодхисаттвы или даже Будды, принимающие облик шраваков ради пользы существ. Их цель — подавать пример дисциплины тем, кто пока не готов воспринять Махаяну напрямую.</li>
            </ol>
        </li>

        <li><strong>Единое поле Будд</strong> (<em>buddhakṣetra</em>) — указание на недвойственную природу Таковости (<em>tathatā</em>). Несмотря на то что в учении описываются мириады миров и чистых земель, все они — условные проявления одного и того же сострадательного ума.</li>

        <li><strong>Три освобождения</strong> (<em>vimukti</em>) — это три аспекта созерцания, через которые ум освобождается от цепляния за двойственность субъекта и объекта. Их называют «вратами», поскольку именно через них осуществляется переход от обусловленного к необусловленному.
            <ol class="list-decimal mb-6 pl-2 space-y-1 ml-2">
                <li>Освобождение через <em>шуньяту</em> (<em>śūnyatā-vimokṣa</em>): постижение, что все дхармы лишены собственной природы и возникают лишь как проявления ума.</li>
                <li>Освобождение через отсутствие признаков (<em>animitta-vimokṣa</em>): прекращение схватывания признаков — формы, имени, качества — как реальных опор познания.</li>
                <li>Освобождение через отсутствие стремлений (<em>apraṇihita-vimokṣa</em>): состояние, в котором исчезает всякое волевое стремление — даже к нирване, — и ум не строит будущее.</li>
            </ol>
        </li>

        <li><strong>Четыре потока ума</strong> — термин <em>cittadhārā</em> в гатхе 318 упоминается без расшифровки. Сама <strong><em>Ланкаватара</em></strong> не даёт перечня этих потоков. Поздние йогачаринские традиции предлагали различные толкования — от трёх стадий сосредоточения до анализа восьми сознаний.</li>

        <li><strong>Шесть видов отсутствия «я»</strong> (<em>nairātmya</em>) — характерная для <em>Sagāthakam</em> числовая формула, не раскрываемая в самом тексте. В йогачаринской традиции под этим обычно понимают детализацию двух основных видов <em>nairātmya</em>:
            <ul class="list-disc mb-2 pl-2 space-y-1 ml-2">
                <li><em>pudgala-nairātmya</em> (отсутствие «я» в личности),</li>
                <li><em>dharma-nairātmya</em> (отсутствие «я» в дхармах).</li>
            </ul>
            Шесть видов могут относиться к анализу безличностности в контексте <em>скандх</em>, <em>дхату</em>, <em>аятан</em>, причинности, кармы и мышления — но сама <strong><em>Ланкаватара</em></strong> оставляет эту схему без пояснения, подчёркивая, что все такие деления — условные указания, лишённые собственной природы.
        </li>

        <li><strong>Четырёхчастное познаваемое</strong> (<em>jñeya</em>): некоторые традиции понимают четыре вида познаваемого как:
            <ul class="list-disc mb-2 pl-2 space-y-1 ml-2">
                <li>собственные признаки (<em>svalakṣaṇa</em>),</li>
                <li>общие признаки (<em>sāmānyalakṣaṇa</em>),</li>
                <li>различение (<em>vikalpa</em>),</li>
                <li>истинную природу (<em>dharmatā</em>).</li>
            </ul>
            Однако эта схема не восходит напрямую к <strong><em>Ланкаватаре</em></strong> и представляет собой позднюю систематизацию.
        </li>
    </ul>

    Все эти классификации в самом тексте даны без объяснения и без иерархии, тем самым подчёркивается их принадлежность к уровню условного обозначения (<em>prajñapti</em>): множественность систем не ведёт к постижению истинности, она лишь умножает построения различающего ума. Истинное постижение достигается через их превосхождение в прямом видении Таковости.

<a href="#ref-602" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-603"><sup>603</sup> Четыре характеристики Махаяны:
    <ul class="list-disc mb-6 pl-2 space-y-1 ml-2">
        <li>не связана с причинностью (<em>kāraṇa-visaṃyukta</em>) — не обусловлена, выходит за пределы логических построений;</li>
        <li>свободна от ошибок воззрений (<em>dṛṣṭi-doṣa-vivarjita</em>) — не подпадает под крайности;</li>
        <li>постигается лично (внутренним опытом) и непосредственно (<em>pratyātma-vedya</em>) — не через внешний авторитет;</li>
        <li>неколебима (<em>acala</em>), недвижная — пребывает в Таковости, указывает на состояние Татхаты, где нет «прихода и ухода» (движения мысли).</li>
    </ul>
    Это определение отличает Махаяну от систем, опирающихся на логику, догмы и внешний авторитет.<a href="#ref-603" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-604"><sup>604</sup> Классификации «возникновения» и «невозникновения» — восьми- или девятикратные — представляют собой разнообразные искусные средства (<em>upāya</em>), с помощью которых ученик постепенно освобождается от цепляния за двойственность. Однако сутра подчёркивает, что за этим многообразием стоит единая цель — прямое постижение «только-ума».<a href="#ref-604" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-605"><sup>605</sup> <strong>Восемь аспектов мира без форм</strong> (<em>ārūpya</em>): мир без форм обычно описывается через четыре состояния, достигаемые в глубокой медитации. Но каждое из них можно рассматривать двояко:
    <ul class="list-disc mb-6 pl-2 space-y-1 ml-2">
        <li>как результат кармы — то есть перерождение в этом состоянии,</li>
        <li>и как медитативное переживание — временное пребывание в нём здесь и сейчас.</li>
    </ul>
    Так получается восемь аспектов, хотя по сути это те же четыре состояния. Эти четыре состояния таковы:
    <ul class="list-disc mb-6 pl-2 space-y-1 ml-2">
        <li>сфера бесконечного пространства (<em>ākāśānantyāyatana</em>),</li>
        <li>сфера бесконечного сознания (<em>vijñānānantyāyatana</em>),</li>
        <li>сфера отсутствия чего-либо (<em>ākiṃcanyāyatana</em>),</li>
        <li>сфера ни восприятия, ни не-восприятия (<em>naivasaṃjñānāsaṃjñāyatana</em>).</li>
    </ul>
    Эти тонкие состояния — всё ещё часть обусловленного опыта, они не есть освобождение. Как и всё прочее, они возникают как проявление ума и подлежат той же логике <em>cittamātra</em> и <em>vikalpa</em>.<br>
    <strong>Шесть видов <em>дхьян</em></strong> (<em>ṣaḍvidhā dhyāna</em>): в главе II подглава 34 сутра описывает четыре вида <em>дхьяны</em> бодхисаттв:
    <ul class="list-disc mb-6 pl-2 space-y-1 ml-2">
        <li><em>Bālopacārikā-dhyāna</em> — <em>дхьяна</em>, практикуемая как новичками (<em>bāla</em>), так и продвинутыми; на этой стадии йогин анализирует <em>скандхи</em>, <em>дхату</em>, <em>аятаны</em> и т.д., но ещё цепляется за признаки.</li>
        <li><em>Arthapravicaya-dhyāna</em> — <em>дхьяна</em> исследования смысла (<em>artha</em>); здесь йогин постигает учение о «только-уме» (<em>cittamātra</em>) и отсутствии внешних объектов.</li>
        <li><em>Tathatālambanā-dhyāna</em> — <em>дхьяна</em> с опорой на Таковость (<em>tathatā</em>); ум пребывает в недвойственном видении, но ещё сохраняет лёгкое различение между опорой и тем, кто опирается.</li>
        <li><em>Tathāgata-dhyāna</em> — <em>дхьяна</em> Татхагаты; здесь прекращается всякая двойственность, всякий след схватывания; это состояние чистого, самосветящегося сознания, свободного от усилий и понятий.</li>
    </ul>
    Однако гатха 321 упоминает «шесть видов сосредоточения». Хотя сутра не раскрывает их, в комментаторской традиции к этим четырём часто добавляют:
    <ul class="list-disc mb-6 pl-2 space-y-1 ml-2">
        <li><em>Nirodha-samāpatti</em> — сосредоточение прекращения, где временно приостанавливаются все формирующие факторы (упоминается в гатхах и прозе как предел сансарического ума).</li>
        <li><em>Anābhogā-gati</em> — спонтанное движение без усилий, состояние восьмой бхуми и выше, где деятельность сострадания возникает без волевого намерения (смотри гатху 258 и главу X).</li>
    </ul>
    <strong>Семь аспектов «выхода»</strong> (<em>niryāṇa</em>): сутра упоминает «семикратный выход» (<em>niryāṇaṃ saptadhā</em>), но не раскрывает его содержания. В комментаторской традиции эти аспекты иногда соотносят с различными моментами видения:
    <ul class="list-disc mb-6 pl-2 space-y-1 ml-2">
        <li>распознаванием условности признаков (<em>lakṣaṇa</em>),</li>
        <li>постижением отсутствия собственной природы (<em>svabhāva</em>),</li>
        <li>прекращением двойственности познающего и познаваемого (<em>advaya</em>),</li>
        <li>и далее — с раскрытием невозникновения (<em>anutpāda</em>) и Таковости (<em>tathatā</em>).</li>
    </ul>
    Однако такие сопоставления — интерпретации. В самой сутре речь идёт о разных сторонах одного и того же освобождения.<a href="#ref-605" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-606"><sup>606</sup> Белый цвет (<em>śukla</em>) в Индии — цвет мирян, чистоты и высокого статуса. Йогин же должен окрашивать белые одежды природными красителями — глиной, навозом, соком плодов и листьев — чтобы устранить привязанность к внешнему благообразию и социальному положению. Синий, красный и особенно цвет охры (<em>kāṣāya</em>, буквально «цвет навоза») — это цвета, считавшиеся нечистыми в брахманской традиции, но ставшие священными для буддийского отшельника.<a href="#ref-606" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-607"><sup>607</sup> Мера Магадхи (<em>māgadha</em>) — традиционная мера объёма чаши для подаяний, принятая в области Магадха (современный Бихар), где проповедовал Будда. Чаша должна вмещать достаточно пищи для одного приёма, но не более — это предотвращает накопление и способствует умеренности.<a href="#ref-607" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-608"><sup>608</sup> Эти гатхи излагают правила монашеского быта (<em>vinaya</em>) для йогина-практика. Акцент на внешней простоте и отказе от собственности, предписания об одежде и утвари, запрет на ремёсла и торговлю — всё это направлено на устранение привязанности к вещам и социальным связям.<a href="#ref-608" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-609"><sup>609</sup> Йогин должен пребывать в уединённых местах — пустых домах, кладбищах, под деревьями, в пещерах — и избегать скопления людей. Предписания о пище строги: не принимать еду из домов, где случилось рождение или смерть и бушуют эмоции, не проповедовать ради подаяния влиятельным людям, не принимать пищу, приготовленную специально или в монастырях с постоянной кухней, «где постоянно вьется дым». Йогин собирает пищу как пчела нектар — понемногу, не истощая источник и не создавая обязательств.<a href="#ref-609" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-610"><sup>610</sup> Йогин созерцает мир свободным от крайностей возникновения / уничтожения и существования / несуществования. Хотя мир и предстаёт как связка обозначаемого (<em>lakṣya</em> — объект) и признака (<em>lakṣaṇa</em> — его характеристики), это лишь способ явленности, а не истинная природа. Видение йогина проникает сквозь эту структуру к недвойственной основе.<a href="#ref-610" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-611"><sup>611</sup> Сила <em>самадхи</em>, <em>сверхзнания</em> (<em>abhijñā</em>) и <em>власть</em> / <em>владычество</em> (<em>vaśitā</em>) достигаются через прекращение измышления возникновения (<em>utpāda-kalpanā</em>). Йогин не должен измышлять происхождение мира ни из философских первопричин — атомов (<em>aṇu</em>, Вайшешика), времени (<em>kāla</em>, некоторые школы), первоматерии (<em>pradhāna</em>, Санкхья), — ни даже из буддийских причин и условий (<em>hetu-pratyaya</em>).<a href="#ref-611" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-612"><sup>612</sup> Мир воспринимается как пёстрый и многообразный (<em>citra</em>), но это лишь развёртывание собственных кармических отпечатков (<em>vāsanā</em>), воображённых умом (<em>sva-kalpa-kalpita</em>). Его природа подобна магии и сну — видимость без основы. Йогин избегает двух крайностей: отрицания (<em>apavāda</em> — нигилизм: «ничего нет») и наложения (<em>samāropa</em> — овеществление: «это реально существует»). Три мира (<em>tribhava</em>), которые предстают как тело, объекты наслаждения и место пребывания (<em>deha-bhoga-pratiṣṭhā</em>), не следует измышлять как независимо существующие.<a href="#ref-612" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-613"><sup>613</sup> Приняв пищу и выразив почтение Буддам и Бодхисаттвам, йогин устанавливает тело прямо и устойчиво. Опираясь на Винаю, Сутры и рассуждение, он сводит учение к его сути и созерцает: <em>пять дхарм</em> (образ, имя, различение, правильное знание, Таковость), собственный ум (<em>svacitta</em>) и отсутствие «я» (<em>nairātmya</em>). Созерцание чистоты природы дхарм, ступеней и Земли Будды ведёт к посвящению на великом лотосе (<em>mahāpadma-abhiṣeka</em>) — образу высшего пробуждения. Упоминается четыре вида посвящения (<em>abhiṣeka</em>): <em>Jñāna-abhiṣeka</em> (посвящение мудростью), <em>Ādhyātmika-abhiṣeka</em> (внутреннее посвящение), <em>Lokottara-abhiṣeka</em> (посвящение, выходящее за мирское), <em>Mahāpadma-abhiṣeka</em> (великое посвящение лотоса).<a href="#ref-613" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-614"><sup>614</sup> Пройдя все состояния существования (<em>gati</em>) с умом, встревоженным бытием (<em>bhava-udvega</em>), йогин обращается к чудесной йоге и вступает на благой и мирный путь.<a href="#ref-614" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-615"><sup>615</sup> В этом фрагменте описывается важный этап практики: переживание ярких образов (<em>nimitta</em>) в созерцании. Несмотря на их светимость и чистоту, они рассматриваются как препятствие, поскольку сохраняют структуру различения. Привязанность к ним может привести к ограниченным формам освобождения (шравака, пратьекабудда) или к отклонению на внешние пути (<em>tīrthya</em>). Состояние <em>nirābhāsa</em> («без образов») означает прекращение даже этих тонких проявлений сознания. Образ «рук Будд, очищающих голову» (рукоположение) представляет собой символическое выражение окончательного устранения последнего объекта схватывания (<em>nimitta</em>).<a href="#ref-615" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-616"><sup>616</sup> Утверждение некой «позиции Срединного пути» может стать ловушкой, возникающей из-за приверженности понятиям. Две ошибки разрушают Срединное: учение о беспричинности (<em>ahetuvāda</em>) и цепляние за бытие из страха перед <em>пустотой</em>. Постижение всего как «только-ум» устраняет опору двойственности, разделяющее различение истощается, и таким образом осуществляется Срединный путь. Некоторые, отрицая объекты и не видя пустоту ума, принимают ум за реальную основу — и тем самым впадают в новую форму схватывания.<a href="#ref-616" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-617"><sup>617</sup> Под «бытием» (<em>bhāva</em>) понимается попытка найти свободу внутри мира понятий, просто сменив одну «хорошую» мысль на другую, не осознав саму «деятельность ума» (<em>cittavṛtti</em>).<a href="#ref-617" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-618"><sup>618</sup> Огонь и дождь — это отсылка к «двойному чуду» (<em>yamaka-pātihāriya</em>). Когда Будда одновременно излучает пламя и потоки воды, он демонстрирует власть над элементами.<a href="#ref-618" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-619"><sup>619</sup> Весь макрокосм — это застывшие формы <em>Алая-виджняны</em>. Всё, что мы считаем «мёртвой материей», имеет тот же корень, что и наши мысли.<a href="#ref-619" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <hr class="my-8 border-t-4 border-gray-500">
</div>

<div class="citations mt-4 text-lg">
    <hr class="my-8 border-t-4 border-gray-500">

    <p class="my-2" id="citation-620"><sup>620</sup> Ум не просто воспринимает опыт — он его искажает и достраивает. Из-за ошибочности различающего мышления (<em>vikalpa-viparyāsa</em>) и разрастания понятий (<em>prapañca-spandita</em>) невежды связываются распознаваниями (<em>saṃjñā</em>): накладывают имена и представления на то, что видят, слышат, мыслят и познают.<a href="#ref-620" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-621"><sup>621</sup> <em>Зависимая природа</em> — это динамика опыта, она является носителем «образов» (<em>nimitta</em>). В момент «наклеивания» ярлыков имени возникает <em>воображаемая природа</em> (<em>parikalpita</em>).<a href="#ref-621" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-622"><sup>622</sup> Когда разум исследует опыт, не обнаруживается ни зависимого, ни воображаемого как чего-то существующего. <em>Совершенная природа</em> (<em>niṣpanna</em>) также не есть нечто — она не может быть указана как существующее, следовательно, о ней невозможно помыслить в привычных категориях.<a href="#ref-622" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-623"><sup>623</sup> Этот фрагмент содержит краткое изложение учения о трёх природах (<em>tri-svabhāva</em>).</p>
    <p>Множественность опыта возникает через искажённые различения (<em>svavikalpa-viparyāsa</em>) и разрастание понятий (<em>prapañca</em>). Ум связывает себя распознаваниями (<em>saṃjñā</em>) в видимом, слышимом, мыслимом и познаваемом.</p>
    <p>Воображаемое (<em>parikalpita</em>) не существует отдельно — оно возникает в зависимом (<em>paratantra</em>). Имя (<em>nāma</em>) воображаемо, образ (<em>nimitta</em>) зависим.</p>
    <p>При исследовании не обнаруживается ни зависимое, ни воображаемое как нечто существующее. Совершенное (<em>niṣpanna</em>) также не есть нечто — чему же быть измышляемым?</p>
    <p>Если совершенное свободно от «есть» и «нет», как возможны две другие природы? Они «устанавливаются» в воображаемом как способы видения одного опыта: пёстрым (<em>citra</em>) — в различении (<em>vikalpa</em>), чистой сферой Благородных (<em>āryagocara</em>) — вне различения.</p>
    <p>Разрыв связи между зависимым и воображаемым ведёт к крайностям иноверцев (<em>tīrthya</em>): либо к реализму (принятие иллюзии за реальность), либо к нигилизму (отрицание самого потока опыта).</p>
    <p>Измышление (<em>kalpanā</em>) обусловлено — оно возникает из причин и видения. Совершенная природа не объект; это свобода от двойственного различения (<em>vikalpa-dvaya</em>).</p>
    <p>Путь ведёт от возникновения множественности к её прекращению. Где различение угасает, раскрывается недвойственное — как то, что всегда было, но было сокрыто.<a href="#ref-623" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-624"><sup>624</sup> Не только воображаемое (<em>parikalpita</em>) и зависимое (<em>paratantra</em>), но даже <em>совершенная природа</em> (<em>niṣpanna</em>), если её схватывать как объект, — не есть истина. Также Будды, их поля (<em>kṣetra</em>), проявления (<em>nirmāṇa</em>), учения — единая и три колесницы — и даже сама нирвана, провозглашённая Буддой, всё это пусто (<em>śūnya</em>) и лишено возникновения (<em>utpatti-varjita</em>). Нет ничего, что можно было бы утвердить как «существующее» или «возникающее» — ни в сансаре, ни в нирване. Даже высшая истина становится ловушкой, если её принять за опору.<a href="#ref-624" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-625"><sup>625</sup> «Тридцать шесть видов Будд по десять видов — по отдельности» — числовая формула <em>Sagāthakam</em> без прямой расшифровки в тексте сутры. Она указывает на бесчисленные условные проявления Будды (преимущественно <em>nirmāṇakāya</em> — Тело Проявления), которые появляются в разных формах, под различными именами и в многообразных землях Будд в зависимости от кармы и склонностей существ. Число «тридцать шесть» (и упоминаемые десять различий) служит примером полноты такого многообразия. В контексте учения о «только-уме» (<em>cittamātra</em>) Будда подчёркивает, что даже это разнообразие форм пробуждения, потоки сознания существ и их миры — не являются ни «землями», ни вместилищами (<em>loka-bhājana</em>); они лишь кажущиеся проявления сознания, лишённые самостоятельной реальности. (Подробные классификации множественных проявлений Будды встречаются в <strong><em>Аватамсака-сутре</em></strong> и других текстах, но <strong><em>Ланкаватара</em></strong> использует эти числа преимущественно риторически.)<a href="#ref-625" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-626"><sup>626</sup> Как воображаемое (<em>kalpita</em>) кажется пёстрым зрелищем, хотя пестроты в нём нет, — так же Дхарма Будды и весь мир кажутся множественными, но не содержат множественности. Многообразие — не свойство реальности, оно возникает лишь как приписывание ума.<a href="#ref-626" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-627"><sup>627</sup> Будда Дхармы (<em>Dharmabuddha</em>) — уровень недвойственного видения, свободный от всяких воображаемых форм. Все остальные образы Будды — его проявления (<em>nirmita</em>), возникающие в зависимости от кармических склонностей существ. Когда существа «видят Будду», они видят поток своих собственных семян (<em>svabīja-saṃtāna</em>) — то есть свои кармические отпечатки, созревающие в виде видения.<a href="#ref-627" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-628"><sup>628</sup> Различение (<em>vikalpa</em>) возникает из цепляния за ложные образы (<em>bhrānti-nimitta</em>). Но Таковость (<em>tathatā</em>) — не некая «реальность за пределами» этого различения; она не иная, чем то, что проявляется как <em>vikalpa</em>. Само измышление (<em>vikalpanā</em>) не обладает образами (<em>nimitta</em>) — образы лишь кажутся, не имея реальной основы. Таким образом, не устанавливается ни внешняя истина, ни внутренняя иллюзия как отдельные.<a href="#ref-628" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-629"><sup>629</sup> Все формы Будды — Естественный (Изначальный) (<em>svābhāvika</em>), Блаженства (<em>saṃbhoga</em>), Явленный (<em>nirmita</em>), пять Явленных (<em>pañca-nirmita</em>) и их множественные проявления — [числовая классификация тридцати шести здесь неясна; возможно, имеется в виду множественность подвидов или проявлений в разных мирах] не существуют как самостоятельные сущности. Они суть (<em>bhavet</em>) Естественный Будда, то есть недвойственная природа, лишённая собственной сущности (<em>svabhāva</em>). Даже учение о «Телах Будды» носит указательный характер: в Таковости нет ни множественности, ни единства.<a href="#ref-629" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <hr class="my-8 border-t-4 border-gray-500">
</div>

<div class="citations mt-4 text-lg">
    <hr class="my-8 border-t-4 border-gray-500">

    <p class="my-2" id="citation-630"><sup>630</sup> Эти гатхи раскрывают механизм возникновения заблуждения и путь его прекращения.</p>
    <p>Внешние отпечатки (<em>bāhya-vāsana</em>) не являются внешними объектами как таковыми, это следы, отпечатки, склонности, привычки, оставленные прежним цеплянием за кажущееся внешнее. Из них возникает различение (<em>vikalpa</em>) — двойственное схватывание. Это различение имеет две взаимосвязанные стороны:</p>
    <ul class="list-disc mb-6 pl-2 space-y-1 ml-2">
        <li><strong>зависимое</strong> (<em>tantra = paratantra</em>) — то, посредством чего происходит схватывание, то есть обусловленная основа процесса;</li>
        <li><strong>воображаемое</strong> (<em>kalpita = parikalpita</em>) — то, что схватывается, кажущийся объект, лишённый собственной природы.</li>
    </ul>
    <p>Заблуждение (<em>bhrānti</em>) всегда разворачивается двояко:</p>
    <ul class="list-disc mb-6 pl-2 space-y-1 ml-2">
        <li>с одной стороны — как кажущаяся внешняя опора (<em>bāhya-ālambana, grāhya</em> — схватываемое),</li>
        <li>с другой — как опора на сознание / ум (<em>citta</em>), схватывающее (<em>grāhaka</em>).</li>
    </ul>
    <p>Третьего не существует.</p>
    <p>Все традиционные аналитические схемы — шесть органов чувств (<em>indriya</em>), двенадцать источников восприятия (<em>āyatana</em>), восемнадцать элементов опыта (<em>dhātu</em>) — сводятся к одному: всё это «только-ум» (<em>cittam eva</em>).</p>
    <p>Прекращение заблуждения связано с распознаванием этой структуры.</p>
    <ul class="list-disc mb-6 pl-2 space-y-1 ml-2">
        <li>Понимание обусловленности / сцепки / связи между собственными семенами (<em>svabīja</em>) и схватываемым устраняет цепляние за «я» (<em>ātma-grāha</em>).</li>
        <li>Проникновение в природу умственных измышлений (<em>citta-kalpa-avatāra</em>) устраняет цепляние за дхармы (<em>dharma-grāha</em>).</li>
    </ul>
    <p>Так ум, свободный от двойного цепляния, пребывает в изначально присущем покое, прежде скрытом измышлениями.<a href="#ref-630" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-631"><sup>631</sup> Этот фрагмент описывает путь от <em>Алая-виджняны</em> через аналитические схемы к роду Татхагаты (<em>tathāgata-gotra</em>), превосходящему все умственные построения.</p>
    <p><em>Алая-виджняна</em> разворачивается как различающие сознания (411). Внутренние основы восприятия (<em>ādhyātmika-āyatana</em>) — шесть органов чувств — кажутся внешними вследствие двойственности. Это не означает, что существует реальное «внешнее», это лишь указывает на механизм иллюзии.</p>
    <p>Как глазные мушки или образы сна (412), как город гандхарвов или мираж (413) — не существуют, но видятся, — такова <em>зависимая природа</em> (<em>paratantra</em>). Даже различие между обусловленным (<em>saṃskṛta</em>) и необусловленным (<em>asaṃskṛta</em>), между временным и постоянным — это воображение, не имеющее основы.</p>
    <p>Будда использует условные обозначения (<em>upacāra</em>) для трёх аспектов сознания — <em>citta, manas, vijñāna</em>, — хотя они лишены собственных признаков (414). Эти схемы, вместе с двойным отсутствием «я» (<em>pudgala/dharma-nairātmya</em>), <em>пятью дхармами</em> и <em>тремя природами</em>, являются сферой видения Будд (415) — искусные средства наставления, и не устанавливают иную реальность.</p>
    <p>По признакам эти три сознания различны, но их основание одно (416). Подобно единой краске, которая на стене видится пёстрой картиной, единая основа проявляется как множественность.</p>
    <p>В роде Будды (<em>buddha-gotra</em>) всех этих схем нет (417), всё это — средства обучения и не относится к самой готре.</p>
    <p>Род Татхагаты (<em>tathāgata-gotra</em>) определяется путём отрицания (418): он свободен от признаков ума, от <em>манаса</em> и сознания, от <em>дхарм</em> и их <em>природ</em>. В этом роде (419) не совершается даже намеренное благо (<em>śubha</em>). Это указание на выход за пределы кармического действия. Когда прекращаются все проявления (<em>samudācāra</em>), включая благие, готра пребывает в изначальной чистоте.</p>
    <p>Эта готра украшена (420) естественными качествами: <em>высшими знаниями</em> (<em>abhijñā</em>), <em>властью</em> (<em>vaśitā</em>), <em>силами</em> (<em>bala</em>) и <em>самадхи</em>. <em>Тело, созданное из ума</em> (<em>manomaya-kāya</em>), — свободное проявление, не связанное ограничениями формы.<a href="#ref-631" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-632"><sup>632</sup> Эти гатхи указывают на переход от пути как последовательности ступеней к уровню, где сам путь утрачивает определимость.</p>
    <p>Восьмая ступень (<em>aṣṭamī bhūmi</em>) определяется как переломный этап: здесь утрачивается привязанность к причинам и признакам, и бодхисаттва входит в род Татхагаты (<em>tathāgata-gotra</em>).</p>
    <p>Последующие ступени отмечены углублением недвойственного видения.</p>
    <p>«Всё прочее» — пути, основанные на различении, причинности и определимости — «ведёт к двум колесницам», не выходящим за пределы двойственного мышления.<a href="#ref-632" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-633"><sup>633</sup> Упоминание «семи ступеней» носит условный характер и связано с педагогическим упрощением для незрелых. В действительности речь идёт о более развёрнутой системе ступеней бодхисаттвы. На седьмой ступени устраняется грубость (<em>dauṣṭhulya</em>) тела, речи и ума, тогда как на восьмой происходит преображение основы (<em>āśraya-parāvṛtti</em>) — коренной поворот сознания, сравниваемый с пробуждением. Упоминание пятой и восьмой ступеней вместе (425) может указывать на два ключевых момента: 5-я ступень (<em>sudurjayā</em> — <em>Труднопреодолимая</em>) — овладение искусными средствами и вхождение в мирскую деятельность; 8-я (<em>acalā</em> — <em>Непоколебимая</em>) — естественное проявление этих средств без усилия и различения. Обе связаны с царским достоинством: на 5-й — как символ овладения, на 8-й — как естественное проявление.<a href="#ref-633" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-634"><sup>634</sup> Здесь последовательно снимаются все возможные категории мышления: возникновение и невозникновение, <em>шуньята</em> и не-<em>шуньята</em>, существование и несуществование, признак, обозначение и вещественность. В «только-уме» ни одно из этих противопоставлений не устанавливается.</p>
    <p>Различение «истинного» и «ложного» относится к уровню учения для шраваков и пратьекабудд и не применяется на пути бодхисаттвы.</p>
    <p>Относительная истина (<em>saṃvṛti</em>) определяется как само заблуждение относительно лишённого собственной природы; в высшем смысле (<em>paramārtha</em>) никакие явления не устанавливаются.</p>
    <p>Обозначения и речь вводятся Буддой как условные средства, но не имеют основания в реальности: то, что возникает из наименования, лишь кажется существующим.<a href="#ref-634" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-635"><sup>635</sup> Этот стих (он связан со стихами 140-143 и 382) проводит тонкое различие внутри проявления Дхармы:</p>
    <ul class="list-disc mb-6 pl-2 space-y-1 ml-2">
        <li><em>deśanā-dharma-niṣyanda</em> — излияние дхарм в форме проповеди, исходящее из недвойственной природы;</li>
        <li><em>niṣyanda-nirmita</em> — то, что проявляется из этого излияния: живые формы учения, рождённые состраданием.</li>
    </ul>
    <p>Оба уровня составляют изначальных Будд — недвойственные выражения Дхармы. Прочие формы (<em>nirmāṇa-vigraha</em>) — условные проявления, установленные для существ, воспринимающих мир двойственно.<a href="#ref-635" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-636"><sup>636</sup> Эти гатхи раскрывают природу заблуждения и препятствия к постижению «только-ума» (эти же гатхи смотри в десятой подглаве второй главы).</p>
    <p>Воспринимаемое (<em>dṛśya</em>) не обнаруживается как независимый объект (435), но ум вводится в заблуждение им — принимает его за внешнее и реальное. То, что кажется разделённым на тело (<em>deha</em>), объекты наслаждения (<em>bhoga</em>) и место обитания (<em>pratiṣṭhāna</em>), на самом деле — единый поток <em>Алая-виджняны</em>. Эта триада не описывает три независимые реальности, она указывает на три способа, которыми ум схватывает самого себя как объект.</p>
    <p>Чистое учение (436) включает: ум, <em>манас</em> и сознание (<em>citta-manas-vijñāna</em>); <em>три природы</em> (<em>tri-svabhāva</em>); <em>пять дхарм</em> (<em>nimitta, nāma, vikalpa, samyagjñāna, tathatā</em>); двойное отсутствие «я» (<em>pudgala/dharma-nairātmya</em>). Как уже говорилось ранее, все эти схемы — искусные средства для устранения заблуждения.</p>
    <p>Это учение — сфера личного постижения (<em>pratyātma-gati-gocara</em>) (437). Оно не доступно рассудочным логикам (<em>tārkika</em>), опирающимся на умозаключения, и шравакам, остановившимся на анализе отсутствия «я» личности. Постижение возникает не через логическое доказательство, а через прямое распознавание природы ума.</p>
    <p>Все понятия возникают во взаимной зависимости (438). «Длинное» существует только относительно «короткого», «бытие» — только в противопоставлении «небытию». Нет независимого доказательства (<em>sādhaka</em>) бытия или небытия — они устанавливаются лишь друг через друга. Попытка найти абсолютное основание в одном из членов пары обречена: оба лишены собственной природы.</p>
    <p>Разложение формы (<em>rūpa</em>) до атомов (<em>aṇu</em>) не приводит к обнаружению неделимой основы (439). Процесс деления можно продолжать бесконечно, и в конце концов невозможно вообразить никакую форму — она исчезает в анализе. Но это не означает, что «ничего нет». Учение о «только-уме» (<em>cittamātra</em>) указывает на то, что форма с самого начала не была независимым объектом, а возникала в уме. Те, кто придерживаются ложных воззрений (<em>kudṛṣṭi</em>) — этернализма (вера в вечные атомы) или нигилизма (отрицание причинности), — не принимают это учение, поскольку продолжают искать объект «где-то там».<a href="#ref-636" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-637"><sup>637</sup> Запрет измышлять <em>шуньяту</em> или <em>не-шуньяту</em> (440) означает, что даже такая основополагающая доктрина может стать ловушкой при схватывании. «Есть» (<em>asti</em>) и «нет» (<em>nāsti</em>) — это умопостроения (<em>kalpanā</em>), способы, которыми ум структурирует опыт. Воображаемый объект (<em>kalpyam artham</em>) не обнаруживается не потому, что его «нет», сам поиск объекта как независимой данности изначально ошибочен.</p>
    <p>Невежды (441) пытаются найти основу формы в её составляющих: качествах (<em>guṇa</em> — цвет, запах и т.д.), атомах (<em>aṇu</em>) и веществе (<em>dravya</em>). Это попытка свести целое к частям. Но при анализе ни один атом не обнаруживается как независимая единица — каждый атом сам может быть подвергнут дальнейшему делению (известный способ выделения сторон ориентирования). Если части не существуют сами по себе, то и целое (<em>artham</em>) не может быть обнаружено. Форма воспринимается, но её поиск как определённой реальности, целостности не имеет успеха.</p>
    <p>Собственный ум (<em>svacitta</em>), принявший облик видимого (<em>dṛśya-saṃsthāna</em>), кажется внешним (<em>bahirdhā</em>) (442). «Внешнего видимого нет» (<em>bāhyaṃ na vidyate dṛśyam</em>): хотя восприятие присутствует, но нет независимого внешнего объекта, который бы существовал вне ума.</p>
    <p>Повтор «не обнаруживается» (<em>na vidyate</em>) в завершении каждой гатхи указывает на невозможность найти опору там, где её привычно ищут. Попытка схватить в длящемся опыте нечто существующее, определённое, устойчивое, отличное от ума заканчивается ничем.<a href="#ref-637" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-638"><sup>638</sup> Эти гатхи совпадают с гатхами 3-5 третьей главы.<a href="#ref-638" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-639"><sup>639</sup> Эти гатхи совпадают с гатхами 15-19 третьей главы.<a href="#ref-639" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-640"><sup>640</sup> Эти гатхи совпадают с гатхами 7 и 8 третьей главы.<a href="#ref-640" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <hr class="my-8 border-t-4 border-gray-500">
</div>

<div class="citations mt-4 text-lg">
    <hr class="my-8 border-t-4 border-gray-500">

    <p class="my-2" id="citation-641"><sup>641</sup> Здесь разбирается ошибка в самом способе мыслить о мире.</p>
    <p>Обычно считают: раз есть причины и условия — значит, есть реально возникающие вещи. Но Будда показывает, что это лишь способ описания и не указывает на подлинное возникновение.</p>
    <p>Четыре крайности — «есть», «нет», «и есть и нет», «ни есть ни нет» — это попытки ума закрепить реальность в определённых рамках. Но ни одна из них не подходит: как только ум пытается определить мир через такие категории, он уже искажает его. Когда эта привычка мышления прекращается, происходит поворот ума: исчезает поиск того, «что существует», и становится видно, что нет никакого самостоятельного «я» или сущностей. Даже то, что называется «возникновением из условий», не означает настоящего рождения. Ведь сами условия зависят от других условий — и так без конца. Нигде нельзя найти точку, где «вещь действительно возникла». В итоге нет ни подлинного возникновения, ни подлинного прекращения, а «причинность» — лишь условное описание взаимозависимого процесса, который ум ошибочно принимает за реальные вещи.</p>
    <p><strong><em>Причинность объясняет видимость мира, но не доказывает реальность его возникновения.</em></strong><a href="#ref-641" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-642"><sup>642</sup> Эта гатха раскрывает глубинный смысл термина «только» (<em>mātra</em>) в «только-ум» (<em>cittamātra</em>).</p>
    <p>«Только» не означает умаление, ослабления — «всего лишь ум» в противовес «внешним объектам». Это указание на пребывание в собственной природе (<em>svabhāva-saṃsthāna</em>), не зависящей от условий (<em>pratyaya</em>) и не нуждающейся во внешнем бытии (<em>bhāva</em>). Здесь имеет место определение через отрицание зависимости: ум не опирается на условия, которые сами были бы внешними ему. Все условия разворачиваются внутри самой природы ума.</p>
    <p>Выражение <em>niṣṭhābhāva-param</em> (буквально «превосходящее основание бытия» или «запредельное всякой опоре») указывает на то, что эта природа не имеет внешней точки опоры.</p>
    <p>Употребление ведантийского термина <em>brahman</em> («высшее, не-двойственное»), показывает, что Будда использует известную слушателям лексику для обозначения высшей недвойственной реальности, но наполняет её йогачаринским содержанием: свобода от всякого схватывания, включая схватывание самого ума как объекта.<a href="#ref-642" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-643"><sup>643</sup> Гатхи 474-487 совпадают с гатхами 20-33 третьей главы.<a href="#ref-643" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-644"><sup>644</sup> <em>arthasaṃkrānta</em> — не означает реального перехода в объект, ум является в форме «как если бы был объект».<a href="#ref-644" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-645"><sup>645</sup> <em>āgantuka</em> — «привнесённое, временное, наносное, не свойственное изначально, пришедшее извне». Омрачённость не свойственна уму, она временна.<a href="#ref-645" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-646"><sup>646</sup> Здесь важно подчеркнуть, что <em>āśraya</em> и <em>ālambya</em> не являются двумя независимыми реальностями, это взаимозависимые аспекты одного процесса.<a href="#ref-646" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-647"><sup>647</sup> <em>Dharmatā</em> (истинная природа) тождественна <em>tathatā</em> — Таковости. Явления не обладают собственной природой (<em>svabhāva</em>) и не являются полным «ничто», поскольку условный поток опыта продолжается. Будда отвергает как цепляние за «есть», так и утверждение «нет». Срединный путь состоит в прекращении самого этого двойственного движения ума.<a href="#ref-647" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-648"><sup>648</sup> Этот фрагмент направлен не столько на утверждение «только-ума», сколько на устранение последних форм скрытого реализма — в том числе представления о некой «истинной реальности», доступной мудрым.</p>
    <p>Воображаемое (<em>kalpita</em>) и сам акт воображения (<em>kalpyamāna</em>) не обладают той природой, которую им приписывает различение (<em>vikalpa</em>) (502). Однако различение не прекращается незамедлительно даже при таком распознавании — оно продолжает разворачиваться по инерции, пока не устранено само неузнавание ума.</p>
    <p>Удивительно, но именно необнаружимость объекта и порождает различение (503): не находя устойчивого основания, ум восполняет это отсутствием через построение систем понятий. Возникает вопрос: откуда берётся кажущаяся «сущностность» явлений (<em>bhāvatā</em>)? (504). Ответ таков: она не существует сама по себе — видимость возникает из неузнавания собственного ума (505).</p>
    <p>Далее отвергается представление о «двух уровнях реальности» как о двух разных объектах (506–507). Если предположить, что нечто существует «иначе», чем его воображают, оно всё равно не становится доступным рассудочному познанию. Если же допустить, что оно существует для Благородных, то это уже не тот объект, который мыслится неразумными. А если оно не существует и для Благородных, тогда исчезает различие между ними и обычными существами. Тем самым разрушается сама идея «объекта истины».</p>
    <p>Различие между Благородными и неразумными проводится не по линии объекта, а по состоянию ума (508): у первых отсутствует заблуждение, поскольку устранён сам механизм различения, тогда как вторые продолжают творить воображаемое из-за нечистоты потока сознания.</p>
    <p>Таким образом, здесь отрицается не только внешний объект, но и возможность обнаружить некую «истинную сущность» как противоположность иллюзии. Отвергается сама идея об освобождении как постижении особого объекта, и вместо этого указывается на прекращение различения при очищении потока сознания.<a href="#ref-648" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-649"><sup>649</sup> Эти гатхи направлены против самой схемы «возникновения» как перехода от небытия к бытию.</p>
    <p>Если нечто мыслится как возникшее из небытия (то есть из ничего), то у него нет внутренней причины, нет собственной природы (<em>svabhāva</em>), а значит, оно не может быть «тем, чем оно есть» само по себе. Но и «нерождённое» как нечто самостоятельное также отвергается: ни «возникшее», ни «не-возникшее» не существуют вне условий. Тем самым разрушается противопоставление рождения и нерождения.</p>
    <p>Видя обусловленность как лишённую собственной основы, мудрый не выбирает между «есть» и «нет», поскольку сама обусловленность (<em>pratītyasamutpāda</em>) не устанавливает ни одну из этих позиций, а выходит из самого акта различения, прекращая механизм, порождающий эти противопоставления.<a href="#ref-649" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-650"><sup>650</sup> «<strong>Сфера наименований</strong>» (<em>abhidhānaviṣayaṃ yānam</em>) — это вся область опыта, разделённого умом на части и обозначенного понятиями. Это и произнесенные слова, и сама привычка ума «вырезать» из единой реальности отдельные предметы, наделяя их границами и именами. Пока мы опираемся на различающее мышление, даже высшее Учение остается для нас лишь набором образов и названий. Истинный же Смысл (<em>Artha</em>) открывается только тогда, когда ум перестает именовать реальность и видит её напрямую, до всякого разделения на «это» и «то».<a href="#ref-650" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-651"><sup>651</sup> «<strong>Верно проведённый смысл</strong>» (<em>arthaṃ sunītaṃ</em>) — это постижение сути реальности, уже очищенной от слоёв умопостроений. Оно не ограничено просто «правильным пониманием» слов, необходим прямой опыт того, что стоит за этими словами. Смысл считается «верно проведённым» (извлечённым) тогда, когда ум перестаёт накладывать на реальность привычные образы и названия, позволяя истине проявиться самой по себе, без искажений, вносимых именующим умом.<a href="#ref-651" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-652"><sup>652</sup> «<strong>Искажают смысл</strong>» (<em>vyabhicaranti te hy artham</em>) — буквально означает, что подлинная суть «расходится» с тем, как её описывают. Из-за опоры на сухую логику и теоретизирование смысл теряет свою устойчивость и однозначность. Вместо прямого видения реальности ум начинает блуждать среди логических построений, и в результате описание «промахивается» мимо истины, подменяя живой опыт мёртвой схемой.<a href="#ref-652" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-653"><sup>653</sup> «<strong>Преподаны через логику, проповедуют через рациональную логику</strong>» (<em>tarkeṇa</em>) — здесь имеется в виду вера в то, что реальность можно полностью ограничить системой логических доказательств. Ошибка — не в рассуждении как таковом, а в превращении умозаключения (<em>tarka</em>) в единственный критерий истины.<a href="#ref-653" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-654"><sup>654</sup> Эти четыре (<em>caturvidham</em>) принимаются умом за опору (<em>ālambana</em>), и относительно них разворачивается <em>kalpanā</em> (воображение/построение понятий), превращающих поток в «объекты»:</p>
    <ul class="list-disc mb-6 pl-2 space-y-1 ml-2">
        <li><em>lakṣaṇa</em> — признак (внешняя черта, по которой узнают объект),</li>
        <li><em>bhāva</em> — бытие (представление/предвзятость о том, что объект «существует» как нечто устойчивое),</li>
        <li><em>saṃsthāna</em> — форма / расположение (пространственная или структурная организация: круглое, высокое, сложное и т.п.),</li>
        <li><em>nāma</em> — имя (словесное обозначение).</li>
    </ul>
    <a href="#ref-654" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-655"><sup>655</sup> Скорее всего «<strong>Луну и Солнце</strong>» (<em>soma—bhāskara</em>) здесь не следует понимать буквально. В традиционных комментариях они выступают как символы двух крайностей:</p>
    <ul class="list-disc mb-6 pl-2 space-y-1 ml-2">
        <li>Луна — покой, единство, недеятельность;</li>
        <li>Солнце — активность, множественность, развёртывание.</li>
    </ul>
    <p>Тем самым речь идёт о тенденции приписывать реальность либо «единому», либо «множественному». Обе позиции рассматриваются как результат различающего мышления (<em>vikalpa</em>) и потому утрачивают подлинный смысл Учения.<a href="#ref-655" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-656"><sup>656</sup> «<strong>Искусные в отбрасывании представлений, искусные в растворении механизмов обозначения</strong>» (<em>saṃjñā-vivarta-kuśalā</em>). <em>saṃjñā</em> — «представление», «распознавание», «восприятие» или «обозначение», «маркировка», «указание» — это способность ума узнавать предметы и выделять их из общего потока. Она работает как «инструмент для наклеивания ярлыков»: именно благодаря ей мы делим реальность на отдельные вещи и даем им имена. Мудрость заключается в том, чтобы видеть мир напрямую, до того как сработает это «распознавание» и превратит живую Таковость в набор понятий.<a href="#ref-656" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-657"><sup>657</sup> Допущение полного исчезновения кармы разрушает саму возможность объяснения опыта.<a href="#ref-657" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-658"><sup>658</sup> Карма не «исчезает с объектом», но и не существует как нечто вещественное — она сохраняется как поток без материального содержимого.<a href="#ref-658" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-659"><sup>659</sup> Форма прекращается, сознание продолжается — и именно эта связь сохраняет кармическую непрерывность. <em>Bhavālaya</em> здесь — <em>Алайя-виджняна</em> как основа существования (<em>bhava</em>), в которой пребывают кармические семена.<a href="#ref-659" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-660"><sup>660</sup> Если карма обрывается, то ни страдание, ни освобождение невозможны — путь теряет смысл.<a href="#ref-660" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-661"><sup>661</sup> Допущение «возрождения того же» ведёт к признанию тождества.<a href="#ref-661" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-662"><sup>662</sup> Нет ни тождества, ни различия, а только условная связь без утверждения какой-либо сущности. И потому не утверждается ни возникновение, ни уничтожение. Поскольку нет ни утверждения бытия, ни утверждения небытия, само понятие «разрушения» (<em>pradhvaṃsa</em>) не устанавливается — нечему разрушаться и нет того, во что переходить.<a href="#ref-662" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-663"><sup>663</sup> Ошибка заключается не в самих явлениях, а в том, как их понимают.</p>
    <p>Воображаемое и зависимое нельзя разорвать: то, что мы принимаем за «объекты», возникает из зависимого течения ума. Но сами эти «объекты» — лишь наложение, а не нечто самостоятельное.</p>
    <p>Поэтому воображаемое нельзя ни утвердить как реально существующее, ни отбросить как полностью несуществующее. Оно не имеет собственной основы, но и не является «ничем».</p>
    <p>Когда видят зависимое как есть, исчезает ложное наложение, и то же самое воображаемое обнаруживается как Таковость.</p>
    <p>Ошибка — либо принимать воображаемое за реальное, либо пытаться его полностью уничтожить. Обе позиции — <em>samāropa</em> (приписывание существования) и <em>apavāda</em> (отрицание) — крайности, разрушающие учение.<a href="#ref-663" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-664"><sup>664</sup> «<strong>Уничтожает воображаемое</strong>» (<em>kalpitaṃ yatra nāśenti</em>) — здесь имеется в виду крайность нигилизма. Ошибка в том, что человек не просто разоблачает иллюзию, а начинает отрицать вообще всё, заявляя, что «ничего не существует». Вместо того чтобы понять, что наши представления о вещах ложны, он пытается уничтожить саму основу условного бытия (<em>paratantra-svabhāva</em>). Будда предупреждает, что такие люди опасны: считая, что за именами нет никакой основы, они разрушают само Учение и сбивают других с пути.<a href="#ref-664" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-665"><sup>665</sup> Подобно тому как золото в руднике уже есть, и не создано усилием, так и роды существ (<em>sattvagotra</em>) — изначально присутствуют, и не порождены кармой. Поскольку объект кармы (<em>dṛśya</em>) не существует как независимая реальность, карма не устанавливается как нечто вещественное, и перерождение — не переход некой сущности из одного состояния в другое.<a href="#ref-665" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-665.0"><sup>665.0</sup> Сами явления не имеют собственной сущности — это видят те, кто постиг истину. Но обычное восприятие приписывает им устойчивое существование.</p>
    <p>Если бы вещи действительно были такими, какими их воображают, не возникало бы заблуждения: всё было бы очевидно и не вызывало бы цепляния. Но омрачение возникает именно потому, что принимается за реальное то, что таким не является.</p>
    <p>Сансара разворачивается потому, что ум, увлекаясь множественностью и различиями, схватывает их как реальные через чувственное восприятие, поддерживаемое неведением (<em>avidyā</em>) и жаждой (<em>tṛṣṇā</em>).<a href="#ref-665.0" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <hr class="my-8 border-t-4 border-gray-500">
</div>

<div class="citations mt-4 text-lg">
    <hr class="my-8 border-t-4 border-gray-500">

    <p class="my-2" id="citation-667"><sup>667</sup> Здесь различаются два состояния. Одно — когда человек просто отрицает реальность явлений: тогда восприятие как бы «гаснет», теряет опору. Другое — видение йогина: восприятие продолжается, но без цепляния за «есть» и «нет». Поэтому простое отрицание бытия не является освобождением и не тождественно пути йогина. Или если коротко: «не видеть» не означает «видеть правильно» и «отключить восприятие» не значит «освободиться».<a href="#ref-667" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-668"><sup>668</sup> Здесь отвергается взгляд, что «ничего не существует». Если бы причины сансары отсутствовали даже условно, то не было бы ни омрачения, ни самого круговорота — а значит, освобождение наступало бы само собой, без усилия. Но раз переживаются заблуждение и страдание, значит, причины действуют — хотя и не как самостоятельные сущности, а зависимо. Поэтому требуется путь, и простое отрицание не ведёт к освобождению.<a href="#ref-668" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-669"><sup>669</sup> После утверждения, что у явлений нет собственной сущности, легко сделать вывод: «значит, ничего вообще не существует». Но если бы это было так, тогда не было бы причины для сансары, а значит, все уже были бы освобождены — без всякой практики. Поэтому различие между неразумным и Благородным не в том, признаёт ли он «есть» или «нет». Различие в том, что неразумный цепляется за «есть» или утверждает «ничего нет». Благородный не утверждает ни «есть», ни «нет», поскольку сама структура противопоставления (<em>vikalpa</em>) более не формируется при прохождении трёх врат освобождения — свобода от утверждения неизменного бытия, от схватывания признаков и от желания результата.<a href="#ref-669" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-670"><sup>670</sup> В выражении <em>sva-sāmānyā alakṣaṇāḥ</em> возможно двойное прочтение: как указание, что «собственное» и «общее» лишены самостоятельных признаков; как перечисление: собственные признаки, общие признаки и их отсутствие. В контексте сутры предпочтительно первое: речь не идёт о классификации признаков, вероятнее всего — о разрушении представления о реальном существовании признаков.<a href="#ref-670" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-671"><sup>671</sup> «<strong>Блистательные проявления</strong>» (<em>vibhūti</em>) — это особые способности и яркие проявления ума, возникающие по мере его очищения. Термин может означать «могущество», «совершенства», «проявление силы» или «блистательные проявления». Речь не идёт о внешних «чудесах» как цели. Это естественное раскрытие возможностей освобождённого ума.<a href="#ref-671" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-672"><sup>672</sup> Данный блок представляет собой одну из наиболее прямых и резких полемических атак <strong><em>Ланкаватара-сутры</em></strong> против Вайшешики (<em>vaiśeṣika</em>), которая здесь обозначается презрительным прозвищем Kaṇabhuk (буквально «поедатель крошек/атомов») — насмешливым искажением имени Kaṇāda («поедатель зёрен»), основателя Вайшешики. Прозвище подчёркивает нелепость атомистической теории с точки зрения йогачары, то есть попытки объяснить построение мира из неделимых «крошек» (<em>paramāṇu</em>).<a href="#ref-672" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-673"><sup>673</sup> <em>Asatkāryavāda</em> — центральная доктрина Вайшешики и Ньяи, согласно которой следствие (<em>kārya</em>) является совершенно новым и ранее не существовавшим в причине (<em>kāraṇa</em>). В <strong><em>Ланкаватаре</em></strong> это трактуется как разрыв непрерывности становления и определение мира как набора независимых сущностей.<a href="#ref-673" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-674"><sup>674</sup> <em>Nava dravyāṇi</em> — девять вечных первоэлементов / стихий / категорий / субстанций (этот термин принят в англоязычных переводах, но в современном русском употребляется в специфическом значении) Вайшешики: земля (<em>pṛthivī</em>), вода (<em>ap</em>), огонь (<em>tejas</em>), воздух (<em>vāyu</em>), эфир/пространство (<em>ākāśa</em>), время (<em>kāla</em>), направление/пространство (<em>diś</em>), душа/«я» (<em>ātman</em>) и ум (<em>manas</em>). Эти <em>dravya</em> мыслятся как независимые реальности (<em>sat</em>), существующие до и независимо от познающего ума — что прямо противоречит <em>cittamātra</em>.<a href="#ref-674" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-675"><sup>675</sup> <em>Dravyair-ārabhyate dravyaṃ</em> — «элемент порождает элемент». Это попытка объяснить мир как механический конструктор, где вещи просто «сцепляются» друг с другом.<a href="#ref-675" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-676"><sup>676</sup> Эта критика вайшешики важна для понимания позиции <strong><em>Ланкаватары</em></strong>:</p>
    <ul class="list-disc mb-6 pl-2 space-y-1 ml-2">
        <li><strong>Вайшешика</strong> утверждает: мир состоит из вечных первоэлементов (<em>dravya</em>); атомы (<em>paramāṇu</em>) беспричинны и независимы; следствие возникает как нечто новое (<em>asatkāryavāda</em>); явления существуют независимо от ума.</li>
        <li><strong><em>Ланкаватара</em></strong> отвергает: независимость атомов (они — проекции ума); утверждение <em>dravya</em> как самостоятельных основ (всё — <em>cittamātra</em>); разрыв между причиной и следствием (всё — <em>pratītyasamutpāda</em>); приписывание вечности любым явлениям (<em>sarvaṃ anityam</em>).</li>
    </ul>
    <a href="#ref-676" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-677"><sup>677</sup> <em>Pūrvā koṭi</em> («первый, прежний, начальный предел») — попытка установить абсолютное начало потока существования. Если бы сансара имела начало (<em>ādi</em>), то возникал бы вопрос: что было до этого начала? Либо — ничто (<em>śūnya</em>), что ведёт к <em>asatkāryavāda</em> (возникновение из несуществующего), либо — нечто вечное (<em>nitya</em>), что требует введения абсолютной причины (<em>īśvara, pradhāna</em>). Обе позиции отвергаются: сансара — безначальный поток (<em>anādi-pravāha</em>), где каждый момент обусловлен предыдущим, без первой точки опоры.<a href="#ref-677" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-678"><sup>678</sup> Это — классический аргумент <em>prasaṅga</em> (приведение к абсурду). Если <em>asatkāryavāda</em> верна, то из абсолютного небытия может возникнуть всё что угодно, включая <em>śvānoṣṭrakharaśṛṅga</em> (рога собаки, верблюда, осла) — стандартные примеры невозможного (<em>asat</em>) в индийской логике.<a href="#ref-678" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-679"><sup>679</sup> Если восприятие (<em>cakṣu-rūpa-vijñāna</em>) возникало бы из абсолютного небытия, не было бы упорядоченности причин и следствий (<em>niyama</em>). Но опыт показывает строгую обусловленность: из глины — горшок, из нитей — ткань, из травы — циновка. Эта упорядоченность подразумевает не просто механическое соединение элементов, имеет место сопряжённая структурность самого потока сознания (<em>citta-santāna</em>), где каждое проявление связано с соответствующими отпечатками (<em>vāsanā</em>).<a href="#ref-679" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-680"><sup>680</sup> Если бы результат возникал просто из соединения условий (<em>pratyaya-samāgama</em>), без связи с природой самих условий, то любое соединение порождало бы любой результат. Но этого не происходит: каждое проявление связано с определённым порядком условий. Следовательно, возникновение не является механическим сложением элементов. В контексте учения это указывает на зависимость проявления от структуры сознания, а не только от внешних условий.<a href="#ref-680" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-681"><sup>681</sup> Это критика санкхьи: гуны (<em>sattva, rajas, tamas</em>) преображаются, порождая мир, но сама <em>pradhāna</em> остаётся вечной.<a href="#ref-681" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-682"><sup>682</sup> Отвергается реальное порождение: ни условия, ни обусловленное не имеют собственной природы. Поэтому «возникновение» не может быть ни из существующего, ни из несуществующего — причинность остаётся лишь условным обозначением.<a href="#ref-682" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-683"><sup>683</sup> <em>Svapakṣa</em> (собственная позиция) определяется через четыре отрицания: <em>sadasat-pakṣa-vigata</em> — свободна от позиций «есть» и «нет» (выход из тетралеммы); <em>hetu-pratyaya-varjita</em> — свободна от причин и условий (не устанавливает их как независимые реальности); <em>utpāda-bhaṅga-rahita</em> — лишена возникновения и прекращения (не утверждает изменение как переход от бытия к небытию); <em>lakṣya-varjita</em> — не имеет объекта определения (не устанавливает никакой сущности как познаваемого). Все четыре отрицания указывают на один смысл — устранение всех попыток схватить реальность через понятия.<a href="#ref-683" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-684"><sup>684</sup> <em>Ahetuka</em> («беспричинный») здесь не является отрицанием обусловленности (<em>pratītyasamutpāda</em>). Имеется в виду отрицание независимых причин (<em>svabhāva-hetu</em>), существующих как отдельные реальности. Мир не имеет «причины» в смысле первоначала или некоего основания, но проявляется как непрерывный поток взаимообусловленности. Видение мира как <em>māyā-svapna-upama</em> (подобного иллюзии и сну) устраняет схватывание (<em>grāha</em>) объектов как реальных, что прекращает различение (<em>vikalpa</em>) и очищает поток ума (<em>cittadhārā</em>).<a href="#ref-684" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-685"><sup>685</sup> Термин <em>na yujyate</em> указывает на логическую несостоятельность: если ум мыслится без объекта (<em>avastuka</em>), то формула «только-ум» теряет опору и не может быть утверждена даже как условное обозначение. Выбор перевода «невозможно утверждать» (вместо «не применим», «не удерживается», «логически не состоятелен», «неуместен») сделан ради ясности: речь о том, что никакое утверждение — даже об «уме самом по себе» — не выдерживает анализа в отсутствие объекта.<a href="#ref-685" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-686"><sup>686</sup> Здесь раскрывается предел учения «только-ум» (<em>cittamātra</em>). Оно может пониматься двояко:</p>
    <ul class="list-disc mb-6 pl-2 space-y-1 ml-2">
        <li>Как отрицание внешних объектов — «только ум» противопоставляется «объекту». Это уровень <em>paratantra</em>: устраняется цепляние за внешнее, но сохраняется представление об уме как о носителе опыта.</li>
        <li>Как указание на недвойственность — прекращение самого разделения на «схватываемое» (<em>grāhya</em>) и «схватывающее» (<em>grāhaka</em>).</li>
    </ul>
    <p>Гатхи 563–566 показывают противоречия первого понимания:</p>
    <ul class="list-disc mb-6 pl-2 space-y-1 ml-2">
        <li>Если объект (<em>vastu</em>) не обнаруживается, то и ум, мыслимый как противоположность ему, также не устанавливается (563).</li>
        <li>Если ум возникает, приняв объект за опору (<em>ālambana</em>), он не может быть беспричинным (<em>ahetuka</em>) — он остаётся в потоке обусловленности (564).</li>
        <li>Для Благородных Таковость и «только-ум» «и устанавливаются, и не устанавливаются» (565): они не являются предметом утверждения, а служат лишь искусным средством (<em>upāya</em>).</li>
        <li>Пока ум разворачивается как «схватывающее» и «схватываемое», то это обыденное (<em>laukika</em>) сознание, и к нему «только-ум» не применимо (566).</li>
    </ul>
    <p>Таким образом, «только-ум» — педагогическое средство, чтобы ослабить цепляние за внешнее. На высшем уровне отпускается и само представление об «уме» как об опоре.<a href="#ref-686" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-687"><sup>687</sup> Здесь тонкость логики: если тело-переживаемое-опора возникают как отдельные от ума (подобно сну, где есть «спящий ум» и «содержание сна»), то был бы один ум (воспринимающий) и другой ум (порождающий образы). Но такой двойственности нет.<a href="#ref-687" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-688"><sup>688</sup> <em>Khaḍga-svadhāra</em> (меч — собственное лезвие) и <em>aṅguli-svāgra</em> (палец — собственный кончик) — стандартные примеры невозможности самонаправленного действия. <em>Citta</em> не может сделать само себя объектом познания (<em>svadarśana</em>), поскольку познание требует разделения на субъект и объект, а это разделение уже есть <em>vikalpa</em>, а не сама природа <em>citta</em>.<a href="#ref-688" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-689"><sup>689</sup> Утверждение «порождающее» (<em>utpādaka</em>) и «порождаемое» (<em>utpādya</em>) — условное обозначение для описания двух граней становления / бытия (<em>bhava-lakṣaṇa</em>): того, из чего возникает (семена-<em>vāsanā</em>), и того, что возникает (проявления-представления-<em>vijñapti</em>). Но обе эти стороны лишены собственной независимой сущности (<em>svabhāva</em>): «порождающее» само обусловлено прежними проявлениями, «порождаемое» не существует независимо от «порождающего». Тем самым утверждение причинности (<em>hetu-phala</em>) уже содержит в себе указание на отсутствие собственной природы / отсутствие «я» (<em>nairātmya</em>).<a href="#ref-689" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-690"><sup>690</sup> Если бы ум мог порождать объекты независимо от условий, он мог бы создавать их где, когда и как угодно. Но поскольку этого не происходит, объекты не существуют сами по себе.<a href="#ref-690" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-691"><sup>691</sup> Отвергается даже идея, что «ум создаёт объект как нечто отдельное». В учении <em>cittamātra</em> объект — не продукт ума, ставший затем независимым от него и воспринимаемым как «внешнее». Есть единый поток, в котором возникает кажимость двойственности. Объект — не то, что ум «видит», а то, чем ум «становится». Но даже это «становление» — лишь кажимость. То есть событие «восприятия объекта» происходит в потоке ума и не более.<a href="#ref-691" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-692"><sup>692</sup> Парадокс: если <em>artha</em> (многозначный термин, здесь переведен как «объект») нигде не обнаруживается (<em>nāsti kutracit</em>), то чем «питается» (<em>puṣṭa</em>) ум-<em>citta</em>, разворачивающееся как видимость объектов (<em>arthābhāsa</em>)? Если объекта нет, откуда видимость? Это указывает на то, что <em>arthābhāsa</em> возникает не из встречи с внешним объектом, а из внутренних семян (<em>bīja</em>) в <em>Алайе-виджняне</em>.<a href="#ref-692" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-693"><sup>693</sup> Различение (<em>vikalpa</em>) не может быть «подкреплёно» (<em>puṣṭa</em>) отсутствием (<em>abhāva</em>), поскольку из ничего ничто не возникает. Но оно также не подкреплено наличием объекта (<em>bhāva</em>), поскольку объект не обнаруживается. Следовательно, видимость объекта (<em>arthābhāsa</em>) — не результат восприятия внешнего и не произвольная галлюцинация. Они — проявление отпечатков (<em>vāsanā</em>) из <em>Алаи</em>. Сами отпечатки признаются ни «существующими» (<em>sat</em>), ни «несуществующими» (<em>asat</em>), условно пребывающими в потоке.<a href="#ref-693" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-694"><sup>694</sup> Здесь отвергается и наличие, и отсутствие как основания для видимости объекта, наивысшая точка критики схемы «ум ↔ объект»:</p>
    <ul class="list-disc mb-6 pl-2 space-y-1 ml-2">
        <li>Если объект существует (<em>asti</em>) — он должен быть независимым от ума, что противоречит <em>cittamātra</em>.</li>
        <li>Если объект не существует (<em>nāsti</em>) — ум не может с ним «связываться» (<em>saṃbaddha</em>), нечем «подкрепляться» (<em>puṣṭa</em>).</li>
        <li>Если объект «и существует, и не существует» — логическое противоречие.</li>
        <li>Если объект «ни существует, ни не существует» — тетралемма не даёт выхода.</li>
    </ul>
    <p>Следовательно, сама схема «ум воспринимает объект» (<em>grāhya-grāhaka</em>) ошибочна с самого начала. Видимость объекта (<em>arthābhāsa</em>) — не восприятие чего-то внешнего и не галлюцинация на пустом месте, они — проявление скрытых отпечатков (<em>vāsanā</em>) из <em>Алая-виджняны</em>.</p>
    <p>Эти <em>vāsanā</em> сами:</p>
    <ul class="list-disc mb-6 pl-2 space-y-1 ml-2">
        <li>не являются «объектами» (<em>artha</em>) — поскольку не обнаруживаются до проявления,</li>
        <li>не являются «ничем» (<em>abhāva</em>) — поскольку обладают способностью проявляться,</li>
        <li>не являются «умом» (<em>citta</em>) в смысле различающего сознания — поскольку предшествуют различению.</li>
    </ul>
    <p>Таким образом, вся двойственность «есть/нет», «ум/объект» устраняется — остаётся лишь безначальный поток (<em>pravāha</em>) условно взаимосвязанных проявлений, не имеющих опоры ни в «бытии», ни в «небытии».<a href="#ref-694" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-695"><sup>695</sup> Ум колеблется между «ничего нет» и «всё реально», потому что принимает причины и условия за реальные. Но тот, кто видит становление как <em>ahetuka</em> и <em>anutpāda</em>, выходит за пределы этих крайностей.<a href="#ref-695" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-696"><sup>696</sup> Даже если «различие между умом и объектом вызвано безначальными причинами», это не спасает положение — ведь объект не обнаруживается даже в <em>безначальном</em>. Значит, различие — преломление процесса восприятия, лишённое всякой основы и не имеющее независимой сущности.<a href="#ref-696" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-697"><sup>697</sup> Если бы не-существующее (<em>abhāva</em>) могло «подкреплять», то невозможное стало бы возможным. Но раз этого не происходит, значит, ум не возникает из отсутствия объекта.<a href="#ref-697" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-698"><sup>698</sup> Когда видится беспричинность, становится ясно, что ни ум, ни его объект не имеют собственной основы. Поэтому «подкрепление» не устанавливается, а три мира/три становления (<em>tribhava: kāmadhātu, rūpadhātu, arūpadhātu</em>) лишены самостоятельной деятельности/активности (<em>kriyā</em>) в смысле независимого действия — всякое «действие» есть лишь проявление условно взаимосвязанных потоков, не имеющих независимого от них деятеля.<a href="#ref-698" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-699"><sup>699</sup> <em>Samavāya</em> — термин Вайшешики, где он означает «действительное, неотделимое сцепление между целым и его частями (<em>avayavin</em> и <em>avayava</em>), материей и её качествами, причиной и следствием». <strong><em>Ланкаватара</em></strong> использует его критически: явление никогда не обнаруживается вне такого «сочетания» условий, но и само это сочетание не обладает самостоятельным существованием.<a href="#ref-699" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-700"><sup>700</sup> «Беспричинность» (<em>ahetuka</em>) и «не-возникновение» (<em>anutpāda</em>) не означают, что ничего не существует. Речь о том, что явления не имеют собственной основы и не возникают как самостоятельные сущности. Они обнаруживаются лишь как зависимые сочетания (<em>samavāya</em>), и потому называются пустыми. Это отказ считать их реально возникшими. Термин <em>samavāya</em> здесь используется критически: явление не обнаруживается вне своего «сочетания» (условий, частей, моментов), но и само это «сочетание» не существует как независимая реальность. Это двойное отрицание: ни явление само по себе, ни его связь с другим не устанавливаются как неизменное и существующее.<a href="#ref-700" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-701"><sup>701</sup> Не-возникновение (<em>anutpāda</em>) провозглашается ради отвращения от идеи возникновения (<em>utpādavinivṛttyartham</em>). Отрицание возникновения используется как лекарство против реалистической привязанности к <em>bhāva</em>. Одновременно подчёркивается, что беспричинность (<em>ahetuvāda</em>) здесь — отрицание собственной независимой причины. Неразумные (<em>bālāḥ</em>) не способны это понять и впадают либо в утверждение, либо в отрицание.</p>
    <p>Махамати пытается уличить Будду в противоречии: если явления подобны иллюзиям и беспричинны, то почему они называются нерождёнными и пустыми?</p>
    <p>Явление не обнаруживается вне сочетания (<em>samavāya-vinirmukta</em>). Как только мы пытаемся найти его «само по себе», вне причинно-условной структуры, оно исчезает. Поэтому оно объявляется пустым, нерождённым и лишённым собственной природы (<em>śūnya</em>, <em>anutpanna</em> и <em>asvabhāva</em>). Это подтверждение отсутствия неизменной собственной сущности.</p>
    <p>Далее Будда усиливает примеры иллюзорности (<em>māyā, svapna, gandharvanagara, mṛgatṛṣṇā, keśoṇḍuka</em>). Мир многообразен (<em>vaicitrya</em>), но это многообразие не имеет неизменной собственной основы. Само сочетание частей не существует как сущность, поскольку нет видимого объекта (<em>dṛśyābhāvāt</em>). Однако это не является разрушением, уничтожением мира (<em>pralaya</em>), о котором говорят иноверцы. Здесь проводится чёткая граница между буддийским <em>śūnyatā</em> и всё отвергающим разрушением.<a href="#ref-701" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-702"><sup>702</sup> Даже понятие «беспричинности» (<em>ahetutva</em>) само по себе не должно становиться новой сущностью. Когда мудрец видит отсутствие как «беспричинного», так и самой «беспричинности», отпадает всякое воззрение, цепляющееся за реальность возникновения и уничтожения.<a href="#ref-702" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-703"><sup>703</sup> В гатхе 589 Махамати перебирает возможные способы понимания «не-возникновения» (<em>anutpāda</em>): как небытие (<em>abhāva</em>), как признак возникновения, как имя для явления, как нечто бессмысленное.</p>
    <p>В ответе (590) Будда не принимает ни одну из этих позиций буквально. «Не-возникновение» не утверждается как самостоятельное явление (<em>bhāva</em>), не является характеристикой обусловленного (<em>pratyaya-lakṣaṇa</em>) и не сводится к пустому наименованию. Однако при этом подчёркивается, что сам термин не является бессмысленным: он имеет значение как указание, устраняющее представление о реальном возникновении явлений. Таким образом, «не-возникновение» не вводит новой сущности и не отрицает всё как ничто, а служит средством освобождения от крайних представлений.</p>
    <p><strong>«Не-возникновение» не есть ни реальное явление, ни характеристика возникновения, ни пустое имя; но и не бессмысленно — оно указывает на отсутствие подлинного возникновения, не утверждая при этом новой сущности.</strong><a href="#ref-703" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-704"><sup>704</sup> Признак не-возникновения (<em>anutpāda-lakṣaṇa</em>) лежит за пределами познания шраваков, пратьекабудд и тиртиков, а также бодхисаттв, находящихся на первых семи бхуми. Прямое принятие не-возникновения дхарм (<em>anutpattikadharmakṣānti</em>) становится возможным лишь начиная с восьмой ступени (<em>acalā</em>).<a href="#ref-704" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-705"><sup>705</sup> Не-возникновение определяется здесь через три аспекта: прекращение опоры на причины и условия (<em>hetupratyaya-vyāvṛtti</em>), отрицание всякой внешней первопричины (<em>kāraṇasya niṣedhanam</em>) и утверждение «только-ум» (<em>cittamātra-vyavasthāna</em>).<a href="#ref-705" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-706"><sup>706</sup> <em>Ahetuvṛtti</em> — проявление явлений без независимой причины; она свободна от двойственности воображаемого объекта и самого процесса воображения, а также от крайностей «есть» и «нет» (<em>sat</em> / <em>asat</em>).<a href="#ref-706" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-707"><sup>707</sup> Не-возникновение отождествляется с поворотом основы (<em>āśrayaparāvṛtti</em>), при котором исчезает двойственность ума и воспринимаемого (<em>citta-dṛśya</em>), а также различение <em>воображаемой</em> и <em>зависимой природ</em>.<a href="#ref-707" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-708"><sup>708</sup> Даже «только-ум» не должен становиться новым объектом цепляния. Истинное не-возникновение предполагает полное отбрасывание всех воззрений (<em>sarva-dṛṣṭi-prahāṇa</em>), включая любые утверждающие толкования <em>cittamātra</em>.<a href="#ref-708" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-709"><sup>709</sup> Здесь проводится важное различие между двумя пониманиями <em>шуньяты</em>. Явления пусты не в смысле абсолютного отсутствия (<em>śūnyayā</em>), что превращает <em>шуньяту</em> в абсолютное ничто, а именно в силу не-возникновения (<em>anutpāda-śūnyayā</em>). Таким образом, <em>anutpāda</em> уточняет и углубляет смысл <em>шуньяты</em>, предохраняя её от крайностей.<a href="#ref-709" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-710"><sup>710</sup> Если бы нечто существовало вне условного потока (<em>kalāpa</em>), оно было бы вечным или не-бытием. Но поскольку всё — лишь зависимая динамика, такого «обособленного» нет.<a href="#ref-710" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-711"><sup>711</sup> <em>Saṃkalā</em> передаётся как «сцепление». В отличие от совокупности условий (<em>kalāpa</em>), оно указывает на умственное связывание, в котором возникает видимость целостности. Если <em>kalāpa</em> — ход развития зависимого возникновения, то <em>saṃkalā</em> — её схватывание как «явления».<a href="#ref-711" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-712"><sup>712</sup> Постижение того, что явления не возникают вне сцепления и совокупности условий, и есть стойкость в не-возникновении (<em>anutpāda-kṣānti</em>) (605) — прямое видение отсутствия независимого возникновения.</p>
    <p>Когда весь мир видится как только сцепление (<em>saṃkalā-mātra</em>), ум входит в <em>самадхи</em> (606) — непосредственное видение.</p>
    <p>Различаются внутреннее и внешнее сцепление (607): внутреннее (<em>ādhyātmika</em>) — психические факторы (неведение, жажда, карма), внешнее (<em>bāhira</em>) — материальные условия (глина, инструменты, элементы). Оба — лишь взаимозависимые структуры без собственной природы.</p>
    <p>Тот, кто утверждает возникновение явлений «от иного» (<em>parataḥ</em>), как от независимой причины (608), не утверждён ни в рассуждении / логике (<em>yukti</em>), ни в учении / предании (<em>āgama</em>), поскольку не видит взаимозависимости.</p>
    <p>Условия взаимно обусловлены (<em>anyonya-pratyaya</em>) (609) и не обладают независимым существованием.</p>
    <p>То, что принимается за «дхармы» (тепло, текучесть и т.д.), есть лишь совокупность условий (<em>kalāpa</em>), а не самостоятельные сущности (610); потому все явления лишены собственной природы (<em>niḥsvabhāva</em>).<a href="#ref-712" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <hr class="my-8 border-t-4 border-gray-500">
</div>

<div class="citations mt-4 text-lg">
    <h4 class="text-center text-gray-800 font-bold text-xl my-4">ПРИМЕЧАНИЯ</h4>
    <hr class="my-8 border-t-4 border-gray-500">
    <p class="my-2" id="citation-713"><sup>713</sup> Здесь используется характерный для индийской диалектики приём доведения позиции оппонента до абсурда (<em>prasaṅga</em>). В тексте все примеры — «горшок», «ткань», «корона», «рог» и даже «рога зайца» — поставлены в один грамматический ряд. Это риторический ход: вряд ли оппонент действительно признаёт существование «рогов зайца». Смысл приёма следующий: если утверждается, что наличие причины делает вещь реальной, то тогда необходимо либо признать реальность всего, что мыслится как причинно обусловленное, либо провести различие между «реальными» и «нереальными» причинами. Но если такое различие вводится, оно оказывается произвольным, поскольку само понятие «причины» уже опирается на допущение сочетания / сопряжённости / сцепки (<em>saṃkalā</em>). Следовательно, даже то, что считается «реальным» (причинно возникшим), и то, что считается «нереальным» (<em>śaśa-viṣāṇa</em>), в равной степени лишены собственной природы (<em>svabhāva</em>), поскольку оба устанавливаются лишь через представление.<a href="#ref-713" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-714"><sup>714</sup> Фраза «нет, нет» (<em>nāsti nāsti</em>) обозначает позицию полного отрицания (<em>ucchedavāda</em>). <em>Ланкаватара</em> отвергает как утверждение независимого существования (<em>astitva</em>), так и позицию полного отрицания. Указываемый смысл в том, что само «существование» не устанавливается независимо, оно возникает лишь во взаимозависимости (<em>anyonyāpekṣa</em>) условий. <em>Anyonyāpekṣa</em> здесь указывает на <em>pratītyasamutpāda</em>: «существование» устанавливается не само по себе (<em>svabhāvataḥ</em>), а лишь во взаимном соотнесении условий. Ни одно из условий не существует независимо, чтобы служить абсолютным основанием для других.<a href="#ref-714" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-715"><sup>715</sup> Здесь отвергаются попытки совместить зависимое возникновение с «беспричинностью» (<em>ahetuka</em>). Если утверждается, что нечто проявляется, «опираясь» (<em>āśritya</em>) на другое, то тем самым уже признаётся зависимость. Но если эта «опора» объявляется беспричинной, то возможны варианты: (1) либо «опирающееся» также беспричинно (<em>ahetuka</em>) — но тогда нарушается сама зависимость (зависимое не может быть беспричинным), либо (2) не-беспричинно, но тогда «опора» уже не беспричинна, а является причиной «опирающегося». Оба варианта логически несостоятельны. Это критика попыток ввести «первую беспричинную причину» (<em>pradhāna</em> у Санкхьи, <em>īśvara</em> у Ньяи) как основание мира.<a href="#ref-715" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-716"><sup>716</sup> <em>Anavasthā</em> («бесконечный регресс») — классический аргумент индийской логики: если всякая опора сама требует опоры, цепь уходит в бесконечность, и ничто не устанавливается. Тогда не было бы ни определённого нечто (<em>kiṃcit</em>), ни вообще чего бы то ни было — поскольку установление любого явления требовало бы завершённой бесконечности обоснований.<a href="#ref-716" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-717"><sup>717</sup> Аналогия <em>māyā</em> (иллюзии): фокусник использует листья, щепки как материальную основу для представления и создания иллюзии, но зрителям кажется, что они видят не их, а иллюзорные образы (слонов, дворцов). Подобно этому, многообразие воспринимаемого мира (<em>vaicitrya</em>) возникает, опираясь на то, что принимается за реальный объект (<em>vastu</em>), но само это многообразие — проекция ума.<a href="#ref-717" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-718"><sup>718</sup> Иллюзия (<em>māyā</em>) не сводится к тому, благодаря чему она возникает. И сами эти компоненты, когда служат опорой иллюзии, воспринимаются не в своей «подлинной» природе, а уже как часть иллюзорного представления. Подобным образом то, что принимается за опору восприятия (<em>āśraya</em>), само оказывается образом иллюзии (<em>māyākāra</em>). Нет «реальной основы» иллюзорного проявления — сама идея «основы» уже входит в структуру заблуждения.<a href="#ref-718" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-719"><sup>719</sup> Если явление «исчезает» (<em>vinaśyati</em>), опираясь на <em>vastu</em>, то в самом моменте видения (<em>dṛśya-kāla</em>) не обнаруживается двойственность (<em>dvaya</em>) субъекта и объекта, опоры и опирающегося. Если двойственности нет, то как возможно различение (<em>vikalpa</em>) — процесс, требующий разделения на познающего и познаваемое?</p>
    <p class="my-2">В гатхе указывается на то, что <em>vikalpa</em> не происходит в самом процессе восприятия — оно возникает как последующее наложение (<em>adhyāropa</em>), когда ум разделяет недвойственный опыт на «я» и «объект». В прямом видении (<em>sākṣātkāra</em>) нет ни субъекта, ни объекта — есть просто проявление, лишённое схватывания (<em>grāha-rahita</em>). Таким образом, <em>vikalpa</em> возникает как структура ума поверх недвойственного момента восприятия.<a href="#ref-719" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-720"><sup>720</sup> То, что возникает через различение (<em>vikalpita</em>), не существует как независимая реальность (621). Но и само различение (<em>vikalpa</em>) не обнаруживается как независимый процесс — оно лишь условное обозначение для механизма, разделяющего недвойственный опыт на «субъект» и «объект».</p>
    <p class="my-2">Когда различение не обнаруживается, исчезает само противопоставление сансары и нирваны. Эти понятия порождены <em>vikalpa</em>: сансара — как цепляние за различённое, нирвана — как идея прекращения различения. При устранении самого механизма различения не остаётся ни того, ни другого.</p>
    <p class="my-2">Если <em>vikalpa</em> не обнаруживается, то ум не разворачивается (<em>apravṛtti</em>). Но тогда как возможен сам ум? Если допустить, что ум существует только в своём развёртывании как различение, то при прекращении различения не остаётся и ума как объекта утверждения.</p>
    <p class="my-2">Поэтому <em>cittamātra</em> («только-ум») не применим (<em>na yujyate</em>). Это не означает прекращение опыта, однако сам термин «ум» перестаёт быть уместным — поскольку при таком подходе связан с противопоставлением ума и объекта. При устранении этого противопоставления не остаётся ни объекта, ни ума как его противоположности. Таким образом, <em>cittamātra</em> — искусное средство (<em>upāya</em>) для устранения веры во внешние объекты, но не окончательная позиция. Когда его цель достигнута, оно само должно быть оставлено.<a href="#ref-720" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-721"><sup>721</sup> <em>Aneka-mati-bhinnatva</em> («раздробленность множеством мнений») возникает, когда Учение понимается через различение (<em>vikalpa</em>) как набор идей / понятий. Тогда теряется суть (<em>sāratā</em>), то есть указание на опыт, свободный от разделения (<em>sākṣātkāra</em>). При отсутствии этой сути невозможно освобождение (<em>mokṣa</em>), поскольку освобождение — это устранение самого механизма цепляния за мнения. Вместе с этим не постигается природа многообразия мира (<em>loka-vicitratā</em>), так как она принимается как независимая данность, не соотнесённая со скрытыми отпечатками (<em>vāsanā</em>).<a href="#ref-721" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-722"><sup>722</sup> <em>Bhramaṇī-kṛtam</em> («приведенное в кружение», «созданное подобным вихрю без центра») указывает на движение, кружение, вращение, ввод в заблуждение через динамику (корень √<em>bhram</em> — «блуждать», «вращаться», «заблуждаться»). Ум не просто «искажён», он приведён во вращающееся, нестабильное проявление, как мираж или отражение на колеблющейся поверхности (сравни «голова пошла кругом», «кружение в вихре страстей»). <em>Bimba-vat</em> («подобно отражению») усиливает эту мысль: как отражение в колеблющейся воде множится и дрожит, не имея собственной сущности, так и <em>citta</em> проявляется через <em>vāsanā</em> без внешнего объекта и без внутренней устойчивости.<a href="#ref-722" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-723"><sup>723</sup> Неразумные полагают явления реальными, основываясь на условиях (<em>pratyaya</em>), и тем самым утверждают причинность как независимую структуру. Мудрые же не устанавливают явления подобным образом.</p>
    <p class="my-2">Ум Благородных (<em>āryopaga citta</em>) описывается как <em>śiva</em> — умиротворённый, благой. Он «свободен от собственной природы (<em>svabhāva</em>) и от [обычного] ума (<em>citta</em>)» — парадоксальное указание на то, что он превосходит двойственный ум, противопоставляющий себя объекту. Здесь «<em>citta</em>, свободный от <em>citta</em>» знаменует выход за пределы разума, ограниченного понятиями.<a href="#ref-723" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-724"><sup>724</sup> Риторический вопрос выражает кажущийся парадокс: если всё пусто (<em>śūnya</em>) и не возникло, то нет ни учителя, ни ученика, ни самого учения. Учение о <em>шуньяте</em> словно отрицает возможность собственной передачи. Тем не менее, Будды «преподают» именно это из сострадания. Таково искусное средство (<em>upāya</em>): использовать слова для указания на то, что превосходит слова, без привязанности к самим словам.<a href="#ref-724" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-725"><sup>725</sup> Возражение оппонента учению <em>cittamātra</em>: если внешнего мира нет, то (1) у опыта нет основания (<em>pratiṣṭhā</em>) — на чём тогда «утверждён» мир? и (2) невозможно объяснить восприятие движения (<em>gamana-āgamana</em>) — на основе чего видимость прихода и ухода?<a href="#ref-725" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-726"><sup>726</sup> Аналогия с птицей в небе: движение воспринимается как осмысленное и направленное, хотя реальной опоры (<em>apratiṣṭha</em>) нет. Это создаётся различением (<em>vikalpa</em>), которое структурирует опыт как движение в пространстве. Так же и воплощённые существа «перемещаются в мире» — это разворачивание ума в самом себе (<em>svacitte caṅkramante</em>). Нет внешнего пространства как независимой реальности, есть только видимость движения, порождаемая <em>vikalpa</em>.<a href="#ref-726" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-727"><sup>727</sup> Вопрос о механизме проявления в <em>cittamātra</em>. Если ум один, как он одновременно проявляется как субъект (<em>deha</em> — тело), объект (<em>bhoga</em> — переживаемое) и основание опыта (<em>pratiṣṭhā</em> — опора)? И каков инструмент (<em>kena</em>) этого развёртывания (<em>pravartate</em>)? Это требование объяснить структуру <em>cittamātra</em> изнутри, без обращения к внешним причинам.<a href="#ref-727" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-728"><sup>728</sup> Когда мир видится как свободный от (<em>vivikta</em>) познающего (<em>buddhi</em>) и познаваемого (<em>boddhavya</em>), эта двойственность распознаётся как построение ума. Тогда имя (<em>nāma</em>) и различение (<em>vikalpa</em>) теряют опору и прекращают разворачиваться.<a href="#ref-728" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-729"><sup>729</sup> <em>Cittadarśana</em> («в<em>и</em>дение ума») — распознавание его природы. Это прекращает действие (<em>kriyā</em>), обозначение / знак (<em>akṣara</em>) и различение (<em>vikalpa</em>) — три грани структурирования опыта. Нев<em>и</em>дение собственного ума (<em>adarśana svacitta</em>) — источник возобновления различения. Пока ум не распознан в своей природе, <em>vikalpa</em> продолжает автоматически разворачиваться.<a href="#ref-729" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-730"><sup>730</sup> Четыре бесформенные <em>скандхи</em> (<em>vedanā, saṃjñā, saṃskāra, vijñāna</em>) не поддаются установленному исчислению — их содержание непрерывно меняется. Форма (<em>rūpa</em>) не может существовать отдельно от великих элементов (<em>mahābhūta</em>: земля, вода, огонь, воздух). Следовательно, многообразие форм (<em>rūpa-bahutva</em>) — понятийная структура, лишённая собственной основы.<a href="#ref-730" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-731"><sup>731</sup> Последовательное устранение всех возможных опор: форма не существует независимо от элементов; элементы не существуют без признаков (<em>lakṣaṇa</em>); <em>скандхи</em> не могут стать альтернативной основой формы. Таким образом, «возникновение формы» оказывается лишённой всякой опоры.<a href="#ref-731" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-732"><sup>732</sup> Гатхи 643–647 описывают процесс прекращения (<em>nirodha</em>) через видение истинной природы явлений.</p>
    <p class="my-2">Когда <em>скандхи</em> и <em>аятаны</em> видятся как лишённые собственных признаков (<em>alakṣaṇa</em>) (643), ум обращается вспять (<em>nivartate</em>) — происходит поворот основы (<em>āśraya-parāvṛtti</em>) через видение отсутствия «я» дхарм (<em>dharma-nairātmya</em>).</p>
    <p class="my-2">Сознание возникает как восьмеричное (<em>aṣṭadhā vijñāna</em>) из-за разделения на объекты и органы чувств (644). По признакам (<em>lakṣaṇa</em>) оно классифицируется как тройственное (<em>citta, manas, vijñāna</em>). В состоянии «без образов» (<em>nirābhāsa</em>) все эти разделения прекращаются.</p>
    <p class="my-2"><em>Манас</em> (седьмое сознание) схватывает <em>Алаю</em> и принимает её за «я» (<em>ātman</em>), а познание — за «моё» (<em>ātmīya</em>) (645). Из-за этого двойственного схватывания (<em>dvaya-grāha</em>) разворачивается весь обусловленный опыт. При полном постижении (<em>parijñāna</em>) этого механизма схватывание прекращается.</p>
    <p class="my-2">Когда видится то, что свободно от противопоставления «иное/тождественное» (<em>anya</em>/<em>ananya</em>) (646), как неподвижное (<em>asaṃcara</em>), тогда не измышляется двойственность «я» и «моё».</p>
    <p class="my-2">То, что не развёрнуто (<em>apravṛtta</em>), не питает опыт и не является причиной сознания (647). Свободное от структуры причины-следствия (<em>kārya-kāraṇa</em>), прекращённое (<em>niruddha</em>) не разворачивается вновь. Это указание на <em>nirvāṇa</em> как на прекращение самого механизма обусловленного возникновения.<a href="#ref-732" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-733"><sup>733</sup> Махамати спрашивает, каким образом различение, «только-ум» и мир оказываются лишёнными причин и признаков. Ответ указывает, что ум сам проявляется как видимое, но из-за непостижения этого возникает представление об «ином» — внешнем объекте. Это «иное» возникает из схватывания содержания ума как чего-то отдельного. Когда это не понимается, возникает крайность небытия — воззрение, что ничего нет. Но и существование не может быть установлено: если объект не обнаруживается ни сам по себе, ни даже в самом акте схватывания, то его бытие не имеет основания.<a href="#ref-733" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-734"><sup>734</sup> Будда последовательно раскрывает несостоятельность основных воззрений: бытие и небытие, вечность и непостоянство, а также представление о самостоятельной причине. Даже компромиссная позиция — «отбросить четыре крайности (<em>catuṣkoṭi</em>), но сохранить причинность» — оказывается лишь различием в обозначениях (<em>saṃjñāntara-viśeṣa</em>), не имеющим доказательства (<em>na sādhita</em>).</p>
    <p class="my-2">Если принять непостоянство условий (<em>anityāḥ pratyayāḥ</em>), это устраняет крайность вечности (<em>nitya-doṣa</em>). Однако тогда сами условия, будучи преходящими, не могут выступать в качестве устойчивых причин, и представление о возникновении и прекращении теряет основание. Видение ума и видимого (<em>citta--dṛśya</em>) приводит к прекращению различения (<em>vikalpa</em>) и к повороту без опоры (<em>nirāśraya-parāvṛtti</em>).</p>
    <p class="my-2">Любая доктрина, утверждающая реальность причины и следствия (<em>kārya-kāraṇa</em>) как независимую структуру, остаётся на уровне мирского учения (<em>lokāyata</em>) — даже если носит буддийские одежды.</p>
    <p class="my-2">Истинное учение — одно (<em>aham ekaṃ svasiddhāntam</em>): <em>cittamātra</em>, где видимое распознаётся как проявление ума, двойственность — как структура схватываемое--схватывающее (<em>grāhya-grāhaka</em>), а крайности вечности и уничтожения (<em>śāśvata-uccheda</em>) — как пустые построения. Пока ум разворачивается (<em>pravartate</em>) как двойственный — это <em>lokāyata</em>. Когда же мир видится как собственный ум (<em>svacittaṃ paśyataḥ jagat</em>) — различение (<em>vikalpa</em>) прекращается (<em>apravṛtti</em>).<a href="#ref-734" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-735"><sup>735</sup> Постижение возникновения и исчезновения (<em>āya--vyaya</em>) как характеристик явленного (<em>kārya</em>) прекращает различение (<em>vikalpa</em>). Речь идёт о в<em>и</em>дении их как процессов, не имеющих независимого основания.</p>
    <p class="my-2">Все парные понятия — вечное и непостоянное, сотворённое и несотворённое, высшее и низшее — относятся к уровню мирского мышления (<em>lokāyata</em>), поскольку сохраняют структуру противопоставлений.</p>
    <p class="my-2">Пребывание в шести уделах (<em>ṣaḍ-gati</em>: боги, асуры, люди, животные, преты, обитатели мира Ямы) обусловлено деяниями (<em>karma</em>), различающимися как низкие, средние и высшие. Сохраняя благое (<em>kuśala</em>), достигают либо более благоприятного состояния (<em>viśeṣa</em>), либо освобождения (<em>mokṣa</em>).<a href="#ref-735" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-736"><sup>736</sup> Как одна форма (<em>rūpa</em>) сменяется другой (например, пламя свечи, где каждый момент — новое пламя), так и ум (<em>citta</em>) возникает и тут же исчезает. Это педагогический приём, показывающий отсутствие устойчивого «я», переходящего из момента в момент.<a href="#ref-736" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-737"><sup>737</sup> В каждом объекте восприятия (<em>rūpe rūpe</em>) происходит различение (<em>vikalpa</em>). Это различение и есть то, что называется «существом» (<em>jantu</em>). Нет никакой сущности за пределами этого процесса различения.<a href="#ref-737" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-738"><sup>738</sup> Учение о мгновенном возникновении и исчезновении (<em>kṣaṇika-vāda</em>) не окончательно (<em>na yuktam</em> = «не соответствует высшей истине»). Оно принадлежит уровню зависимого возникновения (<em>idaṃpratyayatā</em> = <em>pratītyasamutpāda</em>). Когда прекращается схватывание формы (<em>rūpa-grāha</em>), исчезает сама двойственность рождения и распада.<a href="#ref-738" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-739"><sup>739</sup> Такие понятия, как неведение (<em>avidyā</em>) и Таковость (<em>tathatā</em>), в рассуждениях используются как пары: заблуждение/просветление, сансара/нирвана. Но сама Таковость недвойственна (<em>advayā</em>): она не противостоит неведению как нечто иное. Буддийские термины тоже могут стать ловушкой, если их принимать как реальные противоположности.<a href="#ref-739" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-740"><sup>740</sup> Если считать условия (<em>pratyaya</em>) и порождённое ими (<em>pratyayotpanna</em>) независимыми дхармами, неизбежно возникают допущения: причина существует, следствие реально, есть вечное, есть непостоянное. Принятие любого элемента учения как реально существующего порождает крайности (<em>nityānta, ucchedānta</em>).<a href="#ref-740" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-741"><sup>741</sup> Отсылка к классическому тезису буддизма: в этом теле заключён весь мир и путь к его прекращению. В контексте <em>cittamātra</em>: мир — проявление ума, действующего через это тело.<a href="#ref-741" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-742"><sup>742</sup> Различение (<em>vikalpa</em>) обычных людей основано на схватывании (<em>grāha</em>) трёх <em>природ</em> (<em>tri-svabhāva</em>) и двойственности схватывающего-схватываемого (<em>grāhya-grāhaka</em>) как реальных — это корень измышления воззрений (<em>dṛṣṭi</em>).<a href="#ref-742" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-743"><sup>743</sup> В классическом индийском трактате структура такова: <em>pūrvapakṣa</em> — позиция оппонента (тезис, который будет опровергнут); <em>uttarapakṣa</em> — окончательный ответ (правильный вывод). В данном стихе Будда говорит: «Я ввожу понятие «собственной природы» (<em>svabhāva</em>) как своего рода временный тезис (<em>pūrvapakṣa</em>), чтобы через него прийти к истине».<a href="#ref-743" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-744"><sup>744</sup> <em>Chidra-doṣa</em> («изъян разрыва») обозначает внутреннюю несвязность (логический изъян (в полемике), уязвимость восприятия), делающую невозможным установление устойчивой связи между явлениями. В буддийской полемике этот аргумент используется против теорий причинности: если причина и следствие неразрывны — причинность теряет смысл; если между ними есть промежуток, возникает «разрыв» (<em>chidra</em>), и связь невозможна. В данном контексте это означает: из-за такой несвязности нет устойчивого установления (<em>niyama</em>) и не подтверждается разворачивание ума как направленного на объект процесса. Однако из-за схватывания двойственности (<em>dvaya-grāha</em>) возникает видимость этого разворачивания. Таковость (<em>tathatā</em>) при этом всегда недвойственна.<a href="#ref-744" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-745"><sup>745</sup> Говоря, что неведение, жажда, карма не имеют источника (<em>ayonija</em>), Будда указывает, что все попытки обосновать становление (<em>bhava</em>) ведут либо к <em>anavasthā</em> (бесконечному регрессу, «источник источника источника ...»), либо к <em>kṛtakatva</em> (вере в творение из ничего). Оба пути несостоятельны, поэтому <em>bhava</em> не возникает [как независимая реальность].<a href="#ref-745" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-746"><sup>746</sup> Те, кто не постиг Таковость, говорят о четырёх видах разрушения (<em>caturvidha-pradhvaṃsa</em>) явлений — имея в виду различные способы понимания прекращения: (1) полное уничтожение, временное исчезновение, растворение и тому подобное или (2) разрушение формы, разрушение качеств, разрушение через отсутствие причины и разрушение в момент возникновения. Это предполагает, что нечто реально существовало, а затем прекратилось.</p>
    <p class="my-2">В различении (<em>vikalpa</em>) с двойственным разворачиванием (<em>dvidhā-vṛtti</em>) — как схватывающее и схватываемое — не обнаруживается ни бытие (<em>bhāva</em>), ни небытие (<em>abhāva</em>). Оно свободно от четырёх крайностей (<em>catuṣkoṭi</em>) и лишено двойственных воззрений (<em>darśana-dvaya</em>). Это означает, что само представление о разрушении возникает лишь при допущении реальности объекта. Но если явления изначально нерождены (<em>anutpanna</em>), то нечему и разрушаться. Различение между существованием и уничтожением — сама структура заблуждения.<a href="#ref-746" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-747"><sup>747</sup> Ум изначально не вовлечён в двойственное разворачивание (<em>dvidhā-vṛtti</em>). Когда это видится, иллюзия прекращается сама — поскольку никогда не была реальной.<a href="#ref-747" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-748"><sup>748</sup> Махамати принимает учение о нерождённости, но просит получить логическое основание (<em>yukti</em>), которое навсегда устранит склонность к двойственным воззрениям. Его молитва в гатхе 680 выражает бодхисаттвское намерение: остаться на пути, не скатившись в крайности «есть/нет» (<em>asti</em>/<em>nāsti</em>), не смешавшись с иноверцами и не ограничившись путём шраваки.<a href="#ref-748" class="text-blue-500 hover:underline ml-2">↩</a></p>
<hr class="my-8 border-t-4 border-gray-500">
</div>

<div class="citations mt-4 text-lg">
   <hr class="my-8 border-t-4 border-gray-500">

    <p class="my-2" id="citation-749"><sup>749</sup> Различные термины — освобождение (<em>vimokṣa</em>), причина (<em>hetu</em>), беспричинность (<em>ahetu</em>) — при сведении к единому признаку не-возникновения (<em>anutpāda-eka-lakṣaṇa</em>) вводят в заблуждение: различающиеся понятия принимаются за тождественные. Мудрым следует избегать этого смешения.<a href="#ref-749" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-750"><sup>750</sup> Три аспекта активности ума определяются через три термина:</p>
    <p class="my-2 ml-4"><em>Saṃkalpa</em> (схватывание, собирание) — <em>citta</em> (ум как основа).</p>
    <p class="my-2 ml-4"><em>Parikalpa</em> (воображение) — <em>manas</em> (седьмое сознание).</p>
    <p class="my-2 ml-4"><em>Vikalpa</em> (различение) — <em>manovijñāna</em> (ментальное сознание).</p>
    <p class="my-2">Все три, при рассмотрении, свободны от объекта (<em>lakṣya</em>) и признака (<em>lakṣaṇa</em>) — они не устанавливают независимых реальностей.<a href="#ref-750" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-751"><sup>751</sup> Не-возникновение, о котором говорят иноверцы (<em>tīrthya</em>), и не-возникновение в учении Будды (<em>mannaya</em>) совпадают лишь по названию; их отождествление приводит к изъяну воззрений. Цель (<em>prayojana</em>) учения — не-возникновение, и его смысл (<em>artha</em>) — также не-возникновение. Те, кто понимают это посредством правильного рассуждения (<em>yukti-jña</em>), постигают учение Будды. Цель — устранение воззрений (<em>dṛṣṭi-saṃkoca</em>). Не-возникновение лишено опоры (<em>anālaya</em>) — оно не устанавливает новое воззрение. Оно провозглашается через постижение двойственности схватываемого и схватывающего.<a href="#ref-751" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-752"><sup>752</sup> Махамати спрашивает (691): не сводится ли учение об «не-возникновении» (<em>anutpāda</em>) к учению о «беспричинности» (<em>ahetuvāda</em>) иноверцев? Если явления «нерождены», означает ли это, что они возникают беспричинно?</p>
    <p class="my-2">Будда отвечает (692), что «беспричинность» (<em>ahetuvāda</em>) иноверцев и их понимание «нерождённости» — искажённое воззрение (<em>viṣama-darśana</em>). <em>Cittamātra</em>, которое провозглашает Будда, свободно от крайностей «есть» (<em>asti</em>) и «нет» (<em>nāsti</em>). Следует отвергнуть как «возникновение» (<em>utpāda</em>), так и «нерождённость» (<em>anutpāda</em>), когда они основаны на воззрениях (<em>dṛṣṭi-hetuka</em>) (693). Даже в учениях, провозглашающих <em>ahetuvāda</em> или <em>anutpāda</em>, скрытно присутствует опора на представление о причине (<em>kāraṇāśraya</em>). Это показывает, что термины сами по себе ничего не гарантируют — важно устранение самой структуры схватывания.<a href="#ref-752" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-753"><sup>753</sup> Махамати формулирует практический парадокс (694): бодхисаттва должен действовать через искусные средства (<em>upāya</em>) и обеты (<em>praṇidhāna</em>), помогая существам. Но если нет действия без усилия (<em>anābhoga-kriyā</em>), значит, любое действие совершается с усилием — а это предполагает деятеля, цепляние за «я», и порождает карму. Если же есть действие с усилием (<em>kriyā</em>), возникает смешение воззрений (<em>dṛṣṭi-saṃkara</em>): «я действую», «я спасаю существ». Как тогда возможна деятельность бодхисаттвы? (Если совсем наивно: «Как же бодхисаттве действовать правильно, если любое действие будет неправильным?») И если все дхармы лишены сущности (<em>asattva</em>), откуда берётся целостность (<em>maṇḍala</em>) самого пути?</p>
    <p class="my-2">Ответ Будды (695) не звучит в терминах «как действовать правильно», он устраняет основание такого вопроса: там, где не устанавливается связь (<em>visaṃyoga</em>) между схватывающим и схватываемым (<em>grāhaka-grāhya</em>), нет ни разворачивания деятельности (<em>pravṛtti</em>), ни её прекращения (<em>nivṛtti</em>) как реальных процессов. Само представление о переходе из одного состояния в другое (<em>bhāvād bhāvāntara</em>) — «я несовершенен, стану совершенным», «существа страдают, я их спасу» — это порождение ума (<em>citta-samutthita</em>).</p>
    <p class="my-2">Иными словами: деятельность бодхисаттвы возможна именно потому, что она не опирается на реальность деятеля, действия и объекта действия. Действие происходит, но без схватывания структуры «я → делаю → для них». Это и есть <em>anābhoga-kriyā</em> — действие без цепляния за двойственность.<a href="#ref-753" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-754"><sup>754</sup> Махамати требует последовательного разъяснения (696–699): как понимать «не-возникновение» (<em>anutpāda</em>) дхарм? Он просит изложение без противоречий, свободное от изъянов иноверческих позиций и от учения о «беспричинности» (<em>ahetuvāda</em>). Также он просит объяснить «не-разворачивание» (<em>apravṛtti</em>) и «прекращение» (<em>nivṛtti</em>), свободные от крайностей «есть» и «нет», но не разрушающие условную связь причины и плода. Кроме того, он требует указать последовательность ступеней (<em>bhūmi-krama</em>) и то, по каким признакам различаются дхармы (<em>dharma-lakṣaṇa</em>), поскольку мир пребывает в смятении из-за двойственных воззрений.</p>
    <p class="my-2">Ответ Будды (700) не даёт требуемой системы и снимает саму установку на её построение, указывая, что через понятия «возникновение», «не-возникновение» и им подобные не постигается причина умиротворения (<em>śama-hetu</em>). Будда не утверждает никакой «схемы» (<em>maṇḍala</em>) и не устанавливает «природу дхарм» (<em>dharmatā</em>) как нечто, подлежащее определению и изложению.<a href="#ref-754" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-755"><sup>755</sup> Махамати цитирует стандартные формулы учения (<em>śūnya, kṣaṇika, niḥsvabhāva, ajāta</em>), указывая, что они могут стать ловушкой, если их измышляют как позиции. Поэтому он требует раскрытия механизма самого различения (<em>vikalpa</em>) — как оно возникает и как прекращается.<a href="#ref-755" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-756"><sup>756</sup> В этих двух гатхах дана кратчайшая схема разворачивания иллюзии и её изживания. Объект не обладает самостоятельной природой: он возникает как видимая грань (облик, «врата события восприятия») (<em>mukha</em>), вначале как просто присутствие, а затем формируемая сочетанием цветов, форм, иных составляющих и усложняемая множащимися умопостроениями (<em>prapañca</em>). Как только эта видимость принимается как нечто внешнее, запускается различение (<em>vikalpa</em>). Постижение этого процесса и видение действительности такой, какова она есть (<em>yathābhūtam</em>), прекращает разворачивание ума (<em>pravṛtti</em>). Ум перестаёт вовлекаться в схватывание того, что сам же и выстраивает.<a href="#ref-756" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-757"><sup>757</sup> Отвержение элементов (<em>bhūta</em>) означает отказ от веры в то, что они существуют сами по себе, вне ума. Когда это понято, не обнаруживается возникновение независимого бытия (<em>bhāva-utpatti</em>).</p>
    <p class="my-2">Ум проявляется в форме объектов (<em>bhūtākāra</em>) — то, что кажется внешним миром, есть аспект самого ума. Парадокс в том, что ум принимает форму явлений, но сам не возникает (<em>anutpanna</em>). Это постоянная практика (<em>sadā vibhāvayet</em>) — непрерывное созерцание ума как источника всех форм, но самого остающегося нерождённым.<a href="#ref-757" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-758"><sup>758</sup> Отказ от веры в нечто возникшее (<em>bhūtāni</em>) как реально существующее устраняет представление о его возникновении (<em>utpatti</em>). Ум созерцается как принимающий форму того, что есть (<em>bhūtākāra</em>), но при этом нерождённый (<em>anutpanna</em>) — видимость присутствует, опора отсутствует. Попытка же устранить различение (<em>vikalpa</em>) посредством различения лишь воспроизводит двойственность (<em>dvaya</em>).<a href="#ref-758" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-759"><sup>759</sup> Иллюзия (<em>māyā</em>) используется как способ указания на не-возникновение (<em>anutpāda</em>): фокусник создаёт видимость без опоры, так и ум выстраивает объекты без независимой природы. Но если считать саму иллюзию возникшей беспричинно — это утрата верной позиции (<em>siddhānta-hāni</em>). Иллюзорность не означает отсутствия причин и условий. Видимость возникает зависимо — через различение (<em>vikalpa</em>) и отпечатки (<em>vāsanā</em>); просто это «возникновение» не устанавливает никакой независимой природы. Отрицание причинности разрушает и объяснение заблуждения, и саму возможность его прекращения.<a href="#ref-759" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-760"><sup>760</sup> Ум видится подобным отражению (<em>bimba</em>), сформированному безначальными представлениями (<em>anādi-mati</em>). Он принимает форму объекта (<em>arthākāra</em>), хотя самого объекта (<em>artha</em>) нет как независимо установленного, внешнего уму. Образ в зеркале — ни тождественен зеркалу, ни отличен от него. При этом он не отсутствует (нельзя утверждать, что его нет), поскольку воспринимается. Таков признак возникновения (<em>utpāda-lakṣaṇa</em>): явление не возникает как нечто, обладающее самостоятельной природой, но и не есть полное отсутствие. Оно — зависимая видимость.<a href="#ref-760" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-761"><sup>761</sup> Город гандхарвов, иллюзия и прочее возникают в зависимости от причин и условий. Таково и возникновение всех явлений. Явления не возникают как нечто, обладающее независимой природой. Тем не менее, их проявление (<em>saṃbhava</em>) не есть полное не-возникновение (<em>asaṃbhava</em>) — не является полным отсутствием, поскольку восприятие переживается в опыте.<a href="#ref-761" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-762"><sup>762</sup> Ум создаёт и принимает иллюзию личности (<em>puruṣākāra</em>) — иллюзорное «я» как центр опыта, которая немедленно требует объект и схватывает его как периферию. Отсюда разворачивается двойственный вихрь (<em>dvidhāvṛtti</em>). Этот процесс образно описывают как искривление, вихрь, отражение, зыбь на воде, мерцание, змею, кусающую собственный хвост, неузнавание собственного облика. Эта двойственность поддерживается языком: «я»/«явления» (<em>ātman</em>/<em>dharma</em>), «я»/«иное», «я»/«моё». Невежды принимают это за данность — потому и страдают.<a href="#ref-762" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-763"><sup>763</sup> Обычные шраваки и архаты достигают своего освобождения, опираясь на множество внешних условий (<em>vipula-pratyaya</em>): наставление учителя, уединение, отсутствие раздражителей, дисциплину, медитацию, отречение. Но их путь — это путь зависимости (<em>ādhīna</em>). Они не видят природы ума, а лишь устраняют омрачения.</p>
    <p class="my-2">Однако есть ученик, которого Татхагата называет <em>pañcamaṃ śrāvakam</em> — «пятым слушателем». Он не полагается на внешние опоры. Его собственная сила (<em>sva-bala</em>) — это прямое видение природы ума. И он не отделён от Победителей (<em>jina-adhīna</em>), ибо природа Будды — его собственная природа. Такого ученика следует вести (<em>nayet</em>), потому что он способен принять высшее указание, недоступное тем, кто цепляется за форму освобождения. Сам Татхагата ведёт его через своё милосердие и нераздельность с умом такого ученика. Более литературно гатха звучала бы так:</p>
    <p class="my-2">«В то время как обычные слушатели (шраваки) и архаты ограничены зависимостью от внешних обстоятельств, существует "пятый тип" практикующего. Обладая внутренней силой и связью с Победителями, он выходит за пределы своего рода. Такого шраваку Будда направляет к полному пробуждению Махаяны, отделяя его от тех, кто ищет лишь личного успокоения».</p>
    <p class="my-2">Судзуки перевёл эту гатху как перечисление пяти классов учеников, что противоречит грамматике санскрита и доктринальной логике <em>Ланкаватары</em>.<a href="#ref-763" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-764"><sup>764</sup> Здесь речь идёт о четырёх видах ложного непостоянства, которые невежды приписывают реальности:</p>
    <p class="my-2 ml-4"><em>kālāntara-anityatā</em> — непостоянство как временной интервал («существует сейчас, исчезнет потом»),</p>
    <p class="my-2 ml-4"><em>pradhvasta-anityatā</em> — непостоянство как разрушение («было целым, стало разрушенным»),</p>
    <p class="my-2 ml-4"><em>paramārtha-anityatā</em> — непостоянство, приписываемое высшей истине («даже пустота изменчива»),</p>
    <p class="my-2 ml-4"><em>itaretara-anityatā</em> — взаимное непостоянство («А отличается от В, значит оба непостоянны»).<a href="#ref-764" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-765"><sup>765</sup> Все небуддийские школы — от материалистов до идеалистов — пытаются найти основу мира:</p>
    <p class="my-2">либо в атомах (<em>aṇu</em>), либо в качествах (<em>guṇa</em>), либо в первоматерии (<em>prakṛti</em>), либо в первопричине (<em>kāraṇa</em>).</p>
    <p class="my-2">Но все они остаются в двойственности: либо мир реален/существует (<em>sat</em>), либо нереален/не-существует (<em>asat</em>). А путь освобождения — вне этих крайностей.<a href="#ref-765" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-766"><sup>766</sup> <em>Bhūtāni</em> — это то, что принимается за реальные основы вещей; в небуддийских теориях — элементы (<em>mahābhūta</em>), но в контексте сутры это указывает на любые сущности, мыслимые как самостоятельно существующие. <em>Bhautika</em> — то, что считается «составленным из элементов»: дом, тело, гора. Но поскольку сами «элементы» — лишь умопостроения, их «производное» не может быть сотворено ими.</p>
    <p class="my-2">Таким образом, и «элементы», и «мир из элементов» — две стороны одного и того же заблуждения: веры в независимую природу у того, что возникает зависимо.<a href="#ref-766" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-767"><sup>767</sup> Различие между умом (<em>citta</em>) и ментальными факторами (<em>caitta</em>) — аналитическое разложение опыта, через которое разворачивается текущее (<em>vartamāna</em>). Однако множественность форм (<em>rūpa</em>) не указывает на их самостоятельную природу. Утверждение «форма — это ум, не состоящий из элементов» (<em>na bhautikam</em>) отрицает представление о форме как составленной из первооснов (<em>bhūta</em>). Форма — проявление, лишённое независимого основания, не результат построения из элементов.<a href="#ref-767" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-768"><sup>768</sup> Все признаки (<em>lakṣaṇa</em>) возникают взаимозависимо. Ум накладывает на эту сеть представление о причине и следствии. Невежды, выстроив эту структуру, говорят: «шуньята есть» или «шуньяты нет». Но <em>шуньята</em> не подпадает ни под «есть», ни под «нет».<a href="#ref-768" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-769"><sup>769</sup> Перечисляются базовые схемы понятийного установления:</p>
    <p class="my-2 ml-4">— триада доказательства: средство установления, доказательство, осуществление (<em>sādhana</em>) — устанавливающий, доказывающий (субъект) (<em>sādhaka</em>) — устанавливаемое, доказываемое (<em>sādhya</em>),</p>
    <p class="my-2 ml-4">— пары противоположностей (холод/жар) и</p>
    <p class="my-2 ml-4">— структура определения: определяемое и его признак (<em>lakṣya-lakṣaṇa</em>).</p>
    <p class="my-2">Утверждение, что они «не устанавливаются логиками» (<em>na prasādhita</em>), не означает их опровержение внутри системы рассуждения. Оно означает отсутствие у них самостоятельной опоры. Все они принадлежат сфере различения (<em>vikalpa</em>) и не выдерживают анализа как способы окончательного установления реальности.<a href="#ref-769" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-770"><sup>770</sup> Перечисление охватывает систему восьми сознаний: <em>citta</em> — <em>Алая-виджняна</em> (основа), <em>manas</em> — седьмое сознание, проецирующее «я», шесть других — пять чувственных сознаний и мановиджняна.</p>
    <p class="my-2">Все они кажутся связанными с «я» (<em>ātma-saṃyuta</em>), но лишены как единства (<em>ekatva</em>), так и различия (<em>anyatva</em>) — они не составляют единую сущность и не существуют как отдельные реальности.<a href="#ref-770" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-771"><sup>771</sup> Санкхья, вайшешика, джайны, логики и теисты, проповедующие Ишвару — все они впали в крайности бытия и небытия (<em>sat-asat-pakṣa</em>) и лишены постижения уединённого смысла (<em>vivikta-artha</em>). <em>Vivikta-artha</em> — истина, свободная от наслоений понятий-идей. Она постигается только через личное благородное знание (<em>pratyātma-ārya-jñāna</em>). Она не может быть узнана через логику (<em>tarka</em>), философские позиции (<em>pakṣa</em>) или веру во внешнего творца (<em>īśvara</em>).<a href="#ref-771" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-772"><sup>772</sup> Здесь проводится ключевое для йогачары различие: <em>citta</em> в этом контексте — очищенная основа (<em>Татхагата-гарбха</em> / чистая <em>Алайя</em>). С ней соединена (<em>saṃyukta</em>) истинная природа существа (<em>sattva</em>). А <em>manas</em>, седьмое сознание, источник привязанности к «я», от неё разъединен (<em>visaṃyukta</em>).</p>
    <p class="my-2"><em>Sattva</em> здесь не просто «существо», это подлинная сущность бытия (<em>Татхагата-гарбха</em>). Его чистый признак (<em>viśuddha-lakṣaṇa</em>) — это отсутствие загрязнений (<em>āvaraṇa</em>), возникших из-за деятельности <em>манаса</em>.</p>
    <p class="my-2">Пребывание вместе с мудростью (<em>jñāna</em>) указывает на состояние после поворота (<em>vyāvṛtti</em>), когда виджняна преобразовалась в джняну. Это динамическое единство сущности и мудрости.<a href="#ref-772" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-773"><sup>773</sup> «<strong>Свободные от цепляния</strong>» (<em>nirupādāna</em>): <em>upādāna</em> — «цепляние», «присвоение», а также «топливо» для продолжения сансары. <em>Nirupādāna</em> указывает на полное прекращение питания <em>скандх</em> привязанностью, свобода от всех форм схватывания, включая тонкие объекты медитации.</p>
    <p class="my-2"><em>Ārūpya-loka</em> — четыре бесформенных состояния самадхи (бесконечное пространство, бесконечное сознание, ничто, ни восприятие ни не-восприятие). Шраваки могут застрять в них, принимая за нирвану.</p>
    <p class="my-2">[Пробуждённые] существа не пребывают (<em>na avatiṣṭhati</em>) даже там — это непребывающая нирвана (<em>apratiṣṭhita-nirvāṇa</em>) бодхисаттвы, который не уходит в паринирвану и не цепляется за сансару.<a href="#ref-773" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-774"><sup>774</sup> Здесь намеренно сталкиваются две позиции: отсутствие «я» (<em>nairātmya</em>) и учение о существе (<em>sattva</em>). Сутра утверждает <em>anātman</em>, но предупреждает, что если понимать это как полное отсутствие <em>sattva</em>, то путь, очищение и пробуждение становятся невозможными. <em>Sattva</em> здесь — основа для преобразования виджняны в джняну. Без этой основы возникает крайность отрицания (<em>uccheda</em>): даже само сознание (<em>vijñāna</em>) становится невозможным (<em>asaṃbhava</em>).<a href="#ref-774" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-775"><sup>775</sup> «<strong>Четыре устоявшихся [утверждения]»</strong> (<em>catvāraḥ sthitāḥ</em>): четыре философские позиции оппонента, пытающегося доказать реальность внешних объектов. Сутра спрашивает: как могут эти утверждения «устоять», если отрицать форму (<em>rūpa</em>) и различение субъект-объект (<em>adhyātma-bāhya</em>)? Без основы (<em>sattva</em>), без объектов (<em>rūpa, viṣaya</em>) и без субъекта (<em>adhyātma</em>) виджняна не имеет условий для развёртывания (<em>na pravartate</em>).<a href="#ref-775" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-776"><sup>776</sup> Логики (<em>tārkika</em>) утверждают, что <em>скандхи</em>, включая форму (<em>rūpa</em>), необходимы для промежуточного состояния (<em>antarābhava</em>) между смертью и новым рождением. Но одновременно они признают мир без-форм (<em>ārūpya-dhātu</em>), где сознание существует без опоры на <em>скандху</em> формы. Если бесформенное становление (<em>arūpa-bhava</em>) возможно там, то обязательность <em>скандхи</em> формы здесь произвольна.</p>
    <p class="my-2">Это противоречие показывает, что <em>скандхи</em> — условные шаблоны ума (<em>cittamātra</em>), они не являются независимыми реальностями.<a href="#ref-776" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-777"><sup>777</sup> Если отрицать основу пути (<em>sattva</em>) и процесс преобразования (<em>vijñāna</em>), то освобождение (<em>mokṣa</em>) становится случайным, без усилий (<em>aprayatnena</em>). Это фактически сводит буддийский путь к учению об отсутствии деяния (<em>akriyāvāda</em>). Сутра указывает, что такая позиция совпадает с воззрениями тиртхиков, отрицающих причинность и этику. Логики не видят, что их радикальное отрицание «я» и сознания разрушает саму возможность осознанного пути (<em>prayatna</em>) и поворота сознания (<em>vyāvṛtti</em>). Йогачара же сохраняет условную реальность <em>sattva</em> и <em>vijñāna</em> как необходимую основу пути.<a href="#ref-777" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-778"><sup>778</sup> Сутра допускает, что в рамках дискуссии может признаваться наличие тонкой формы (как у сарвастивадинов), но указывает: в мире без-форм (<em>ārūpya</em>) отсутствует грубое чувственное восприятие (<em>darśana</em>). Из отсутствия восприятия не следует полное небытие сознания или сущности (<em>tad-abhāva</em>). Если принять «отсутствие» абсолютно, рушится триада: Учение (<em>siddhānta</em>), Путь (<em>yāna</em>) и Практик (<em>yāyin</em>).</p>
    <p class="my-2">Это защищает условную реальность <em>sattva</em> и <em>vijñāna</em> как необходимую основу пути даже в состояниях, свободных от проявленности.<a href="#ref-778" class="text-blue-500 hover:underline ml-2">↩</a></p>
    <hr class="my-8 border-t-4 border-gray-500">
</div>

<div class="citations mt-4 text-lg">

    <hr class="my-8 border-t-4 border-gray-500">
    <p class="my-2" id="citation-779"><sup>779</sup> «Восьмеричное» указывает на совокупность видов сознания. Гатха подчёркивает, что этот множественный процесс не может быть схвачен как единое целое в одном мгновении.<a href="#ref-779" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-780"><sup>780</sup> Три гатхи выстраивают единый аргумент: сознание связано с органами чувств и отпечатками, но не схватывается как единое в одном мгновении. Отсутствие одновременного действия формы и органов чувств указывает на их мгновенный характер. Если форма не установлена, сознание не имеет опоры для развёртывания, а без этого развёртывания сансара не возникает.<a href="#ref-780" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-781"><sup>781</sup> Наставники (<em>vināyaka</em>) не утверждают, что разрушение (<em>bhaṅga</em>) и возникновение (<em>utpatti</em>) — две последовательные стадии одного процесса. Видимая непрерывность явлений (<em>bhāva</em>) возникает как пульсация различения (<em>vikalpa-spandita</em>).<a href="#ref-781" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-782"><sup>782</sup> Заблуждающиеся принимают органы чувств и их объекты как самостоятельно существующие. Невежды закрепляют этот опыт через имена, принимая словесные обозначения за сами вещи. Благородные распознают смысл за именем — то есть видят условный характер обозначений.<a href="#ref-782" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-783"><sup>783</sup> Шестое сознание (<em>manovijñāna</em>) не схватывается через присвоение (<em>upādāna</em>), поскольку не является устойчивым объектом. Утверждать о нём «оно существует» — значит допускать именно ту ошибку, от которой свободны Благородные. Поэтому они и называют его неопределимым.<a href="#ref-783" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-784"><sup>784</sup> Логики (<em>tārkika</em>), стремясь избежать крайностей вечности (<em>śāśvata</em>) и уничтожения (<em>uccheda</em>), остаются на уровне рассудочных построений. Лишённые прямого знания (<em>jñāna</em>), они не способны правильно различить обусловленное (<em>saṃskṛta</em>) и необусловленное (<em>asaṃskṛta</em>) как таковые. Страх крайностей сам по себе удерживает в рамках этих крайностей: избегая одного полюса, логики неизбежно склоняются к другому. Прямое знание (<em>jñāna</em>) позволяет увидеть обусловленное и необусловленное в их различии, не опасаясь ни того ни другого.<a href="#ref-784" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-785"><sup>785</sup> Даяние рассматривается одновременно как единое с умом и как отличное от него через соотношение с <em>манасом</em> и прочими ментальными факторами. Если определить его как совокупность ума и ментальных факторов, присвоение уже предполагает множественность составляющих. Тогда единство оказывается неустановимым.<a href="#ref-785" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-786"><sup>786</sup> Пример огня используется для обоснования «я», связанного с присвоением: огонь одновременно сжигает и сжигается, то есть выступает и субъектом, и объектом одного процесса. Вопрос в конце гатхи обращён к логикам: если они принимают такую структуру для огня, почему отказываются принять её для «я»?<a href="#ref-786" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-787"><sup>787</sup> Ум (<em>citta</em>) всегда обладает природной ясностью (<em>bhāsvara</em>) — независимо от споров о возникновении или не-возникновении явлений. Логики пытаются доказать «я» (<em>ātman</em>) через рассуждения и примеры, но не обращаются к этой непосредственной ясности сознания.<a href="#ref-787" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-788"><sup>788</sup> <em>Vijñāna-gahvara</em> указывает на запутанность в собственных умственных построениях о сознании. Не имея верного способа видения, логики переходят от одной позиции к другой, пытаясь обосновать «я» через рассуждение.<a href="#ref-788" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-789"><sup>789</sup> Здесь <em>ātman</em> указывает на изначальную чистоту ума (<em>śuddhi-lakṣaṇa</em>). Она постигается только через внутренний опыт (<em>pratyātma-gati-gamya</em>). Сутра отождествляет её с Лоном Татхагаты (<em>tathāgata-garbha</em>). Логики не имеют к этому доступа, поскольку ищут «я» через рассуждение о внешнем.<a href="#ref-789" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-790"><sup>790</sup> Различение между тем, что присваивается, и тем, кто присваивает, раскрывает структуру опыта. Когда это различие ясно вместе с признаками <em>скандх</em>, возникает знание, открывающее верный способ видения.<a href="#ref-790" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-791"><sup>791</sup> Тиртхики учат, что <em>Алая</em> — это вместилище, связанное с «я» (<em>ātman</em>). При таком подходе дхармы как они есть не раскрываются.<a href="#ref-791" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-792"><sup>792</sup> Различение категорий само становится путём: видение истины и освобождение следуют как прямое следствие этого распознавания.<a href="#ref-792" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-793"><sup>793</sup> <em>Upādāna</em> здесь употребляется в значении основы или опоры, а не присвоения. Ум, сияющий по природе, отождествляется с Лоном Татхагаты как тем, на что опирается существование живых существ. Свобода от крайностей указывает на выход за пределы рассудочных определений.<a href="#ref-793" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-794"><sup>794</sup> Сравнение (<em>upamā</em>) в индийской традиции включает четыре элемента: <strong>сопоставляемое</strong> (<em>upameya</em>), <strong>образ</strong> (<em>upamāna</em>), <strong>общее свойство</strong> (<em>sādhāraṇa-dharma</em>) и <strong>связку сравнения</strong>. В буддийских текстах сравнение (<em>upamā</em>) направляет внимание и указывает на то, что уже дано, но не распознано. В этой гатхе начинается серия сравнений, продолжающаяся до 762-й. Все они построены по одной схеме: искомое присутствует в <em>скандхах</em>, но требует определённых условий для распознавания. Речь идёт о несоответствии способа внимания тому, что ищется.</p>
    <p class="my-2">Здесь <strong>сопоставляемое</strong> — существо (<em>sattva</em>) в <em>скандхах</em>, <strong>образ</strong> — золото в руде, <strong>общее свойство</strong> — присутствие, не совпадающее с непосредственной видимостью. Сияние золота скрыто в самородке (<em>jātarūpa</em>) и в песке (<em>śarkara</em>), но раскрывается после очистки (<em>parikarma</em>). Последующие образы — звук в инструменте, сокровища под землёй, плод во чреве — разворачивают ту же логику в различных ситуациях.<a href="#ref-794" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-795"><sup>795</sup> Будда определяется здесь через незапятнанное знание (<em>anāsrava-jñāna</em>), свободное от омрачений. «Постоянный покой» (<em>sadāśānti</em>) — это нирвана как непосредственно переживаемое состояние. Прибежище понимается как опора на саму чистую природу ума.<a href="#ref-795" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-796"><sup>796</sup> Ум по природе ясный (<em>prakṛti-prabhāsvara</em>), но в сопряжении (<em>saṃyukta</em>) с вторичными омрачениями (<em>upakleśa</em>), <em>манасом</em> и прочим он выступает как связанный с «я» (<em>ātman</em>).<a href="#ref-796" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-797"><sup>797</sup> Ум (<em>citta</em>) по природе сияющий, ему присуща изначальная ясность. <em>Манас</em> и прочее выступают как иное по отношению к уму — это различие проявляется через омрачение. Именно через них накапливается карма, и потому оба — ум и <em>манас</em> — вовлекаются в омрачение. Различение их природ важно для понимания того, откуда берётся загрязнение.<a href="#ref-797" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-798"><sup>798</sup> «Пришлые» (<em>āgantuka</em>) указывает на то, что омрачения чужды природе ума. «Безначальные» (<em>anādi</em>) означает отсутствие начала во времени, но это не делает их сущностными. «Охвачено» (<em>upeta</em>) подчёркивает, что связь ума с омрачениями носит наложенный характер. Сравнение с одеждой показывает, что очищение открывает уже имеющуюся чистоту, устраняя пришлые наслоения.<a href="#ref-798" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-799"><sup>799</sup> «<em>Ātman</em>» здесь употребляется условно и не указывает на независимую сущность, речь идёт об очищенной природе ума. Смысл сравнения состоит в том, что устранение омрачений снимает пришлые наслоения, открывая основу. Как ткань остаётся тканью, а золото — золотом, так и при исчезновении загрязнений проявляется изначальная ясность, которая прежде была скрыта.<a href="#ref-799" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-800"><sup>800</sup> Образ несведущего, ищущего звук внутри инструмента, указывает на ошибку в направлении поиска. Звук возникает из условного взаимодействия, а не содержится в инструменте как вещь. Так же и «личность» — условное обозначение, возникающее на основе <em>скандх</em>, а не сущность, скрытая среди них.<a href="#ref-800" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-801"><sup>801</sup> Аналогия указывает на ограниченность обычного способа поиска: как скрытое под землёй не обнаруживается без особых условий, так и при анализе <em>скандх</em> не выявляется никакой самостоятельной сущности. «Личность» — условное обозначение (<em>prajñapti</em>), возникающее на основе <em>скандх</em>, а не предмет, который можно найти среди них.<a href="#ref-801" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-802"><sup>802</sup> Несведущие не понимают, что переживание представляет собой совокупность ума и ментальных факторов, обладающих своими качествами и действующих вместе. И тем самым не понимают, что «личность» — лишь условное обозначение этого же процесса.<a href="#ref-802" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-803"><sup>803</sup> Аналогия с плодом во чреве указывает на присутствие без видимости: плод существует, но не обнаруживается без соответствующего способа видения. Так же и «я» в <em>скандхах</em> не является скрытой сущностью среди составляющих опыта, оно распознаётся лишь при правильном направлении внимания.<a href="#ref-803" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-804"><sup>804</sup> Речь идёт не о скрытой «вещи» внутри, а о том, что не распознаётся без соответствующего способа видения.<a href="#ref-804" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-805"><sup>805</sup> Здесь имеются в виду обладающие теоретическим знанием, ещё не достигшие прямого постижения. Непостоянство и <em>шуньята</em> присутствуют в явлениях, но остаются недоступными без прямого опыта.<a href="#ref-805" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-806"><sup>806</sup> Перечисляются ключевые этапы и плоды пути бодхисаттвы. Если полностью отрицать какую-либо основу, способную претерпевать очищение и преображение, путь лишается того, кто по нему идёт, а его результаты — того, в ком они раскрываются.<a href="#ref-806" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-807"><sup>807</sup> Требование «показать» предполагает объект; ответ указывает на зависимость такого требования от собственных понятийных построений.<a href="#ref-807" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-808"><sup>808</sup> Речь идёт об искажённом понимании отсутствия «я», ведущем к отказу от практики.<a href="#ref-808" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-809"><sup>809</sup> Здесь <em>ātma-vāda</em> указывает на природу ума как чистую основу — то, что сжигает нигилистические искажения учения об отсутствии «я». Это учение свободно от ошибок тиртхиков.<a href="#ref-809" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-810"><sup>810</sup> Смысл раскрывается только в непосредственном опыте.<a href="#ref-810" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-811"><sup>811</sup> Речь идет о способах понимания, а не о реальной структуре «я».<a href="#ref-811" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-812"><sup>812</sup> Обычные категории описания неприменимы к уму.<a href="#ref-812" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-813"><sup>813</sup> Если единый ум не признаётся условием восприятия, для логиков неизбежно следуют два абсурдных вывода: явления оказываются беспричинными, а познавательный процесс — лишённым основания для развёртывания.<a href="#ref-813" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-814"><sup>814</sup> Субъект и объект возникают взаимозависимо; поиск их независимого основания не находит опоры.<a href="#ref-814" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-815"><sup>815</sup> «Град» (<em>pura</em>) указывает на образ защищённого прибежища: Нирвана описывается как состояние, в котором нет угрозы возвращения к омрачениям.<a href="#ref-815" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-816"><sup>816</sup> <em>Atyadeśayan</em> подчёркивает исчерпывающую, предельно подробную проповедь. «Три тысячи сутр» — символ полноты учения. Приставка <em>ati-</em> указывает на проповедь, выходящую за рамки обычного изложения.<a href="#ref-816" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-817"><sup>817</sup> Акаништха — высшая сфера Мира Форм. Окончательное пробуждение связывается с полным отсутствием страсти: Мир Страстей слишком груб, Мир Без Форм лишён условий для проявления пути. Здесь указывается состояние, где устранены омрачения и сохраняется возможность завершения пробуждения.<a href="#ref-817" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-818"><sup>818</sup> <em>Asidhārā-vrata</em> — образ предельно точной практики: требуется непрерывная ясность и внимательность. Освобождение связано с прекращением привязанности к объектам.<a href="#ref-818" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-819"><sup>819</sup> Вопрос гатхи направлен против самой схемы «есть / нет» — она неприменима к явлениям, лишённым независимой сущности. Таковость являет себя даже неразумным, поэтому говорить о её отсутствии бессмысленно. Отсутствие «я» в ней указывает на отсутствие независимой сущности при сохранении проявленности.<a href="#ref-819" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-820"><sup>820</sup> Категории «сотворённое» и «несотворённое» исчерпывают логические варианты, однако ни одна из них не указывает на самостоятельную порождающую причину. <em>Anutpanna</em> фиксирует природу явлений как изначально невозникшую — то, что неразумные не различают из-за привязанности к причинно-следственным схемам.<a href="#ref-820" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-821"><sup>821</sup> Оба члена пары — причины и условия — рассматриваются в гатхе как лишённые самостоятельной порождающей силы. Возникновение приписывается им лишь в рассуждении: само по себе оно нигде не обнаруживается как независимый факт.<a href="#ref-821" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-822"><sup>822</sup> Перечисляются классические схемы причинности: предшествование, следование, одновременность. Примеры со светильником, горшком и учеником иллюстрируют условные связи, однако ни одна из этих схем не устанавливает независимого происхождения явлений.<a href="#ref-822" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-823"><sup>823</sup> Признаки, накапливаемые через усилие, присущи и Чакравартину — они относятся к сфере мирского совершенства. Пробуждение Будды выходит за пределы того, что достигается через накопление условий, и потому такие признаки не выражают его природы.<a href="#ref-823" class="text-blue-500 hover:underline ml-2">↩</a></p>
    <hr class="my-8 border-t-4 border-gray-500">
</div>

<div class="citations mt-4 text-lg">
    <hr class="my-8 border-t-4 border-gray-500">
    <p class="my-2" id="citation-824"><sup>824</sup> <em>Pratyātma-dṛṣṭi-gatika</em> указывает, что знание открывается через прямое личное видение — при непосредственном обращении ума к самому себе. Словесная передача и рассуждение служат вспомогательными условиями для такого обращения.<a href="#ref-824" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-825"><sup>825</sup> <em>Bāla</em> обозначает отсутствие духовной зрелости — неспособность различать направление пути. Перечисленные состояния указывают на условия, при которых практика становится затруднённой — без указания на категоричность исключения возможности продвижения по пути.<a href="#ref-825" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-826"><sup>826</sup> Гатха фиксирует различие в понимании основания отречения. <em>Pravādin</em> — те, кто проповедует, не признавая указанного основания.<a href="#ref-826" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-827"><sup>827</sup> Перечислены фигуры различных традиций. Их объединение отражает циклическое понимание времени: имена указывают на повторяющиеся типы учителей. Включение <em>śākyanāyaka</em> в этот ряд показывает, что упоминаемые личности рассматриваются как проявления одного принципа учительства в разных циклах.<a href="#ref-827" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-828"><sup>828</sup> Перечисление эпических и исторических фигур носит символический характер и указывает на циклы проявления мира и учения.<a href="#ref-828" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-829"><sup>829</sup> <em>Na bhāvitaḥ</em> указывает, что Дхарма перестаёт культивироваться людьми. Сама Дхарма при этом не исчезает.<a href="#ref-829" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-830"><sup>830</sup> Описание космологического цикла: разрушение Мира Желаний открывает новый цикл развёртывания. Образ «колеса» подчёркивает цикличность, а не линейный прогресс или упадок.<a href="#ref-830" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-831"><sup>831</sup> После разрушения следует восстановление упорядоченного мира. Перечисление варн, правителей и риши обозначает возвращение структур, в рамках которых вновь возможна передача и поддержание Дхармы.<a href="#ref-831" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-832"><sup>832</sup> Гатха указывает на риск, возникающий при передаче учения через словесные жанры. Сказания, предания, проза и комментарии становятся самостоятельным предметом усвоения. При этом «услышанное» (<em>śruta</em>) — сам факт получения учения через слух и текст — может стать источником смятения, когда форма передачи заслоняет прямое постижение смысла.<a href="#ref-832" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-833"><sup>833</sup> Полотно традиционно окрашивается растительными материалами — корнями (например, куркума), стеблями или древесиной (популярна сердцевина джекфрута), корой дерева, листьями, цветами, плодами. Виная ограничивает использование грязи, навоза или глины из-за неприятного запаха и нестойкости цвета. В гатхе эти средства применяются для намеренного нарушения равномерности окраса: ткань покрывается разводами глины и навоза. Результат — потёртая, неравномерная, лишённая новизны ткань. Интересующимся этой темой подробнее лучше обратиться к изучении Винаи.</p>
    <p class="my-2">Ранее встречался образ ткани и грязи для описания чистоты ума (<em>prakṛti-prabhāsvara</em>) и омрачений. Возможно, эта технология работы с тканью служила напоминанием и скрытой передачей методов работы с умом.</p>
    <p class="my-2"><em>Tīrthya-liṅga</em> — отличительные знаки небуддийских аскетов. Необычность облика (<em>vicitra-aṅga</em>) — несвязанность ни с какой узнаваемой традицией по внешним признакам.<a href="#ref-833" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-834"><sup>834</sup> Перечисляются правила повседневной дисциплины, сохраняющие чистоту восприятия и поведения. Фильтрация воды, ношение пояса и своевременное принятие подаяния указывают на отказ от грубых привязанностей. Проповедь Учения выступает как завершающий акт реализации, объединяющий внутреннюю ясность с внешним выражением.<a href="#ref-834" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-835"><sup>835</sup> Гатха описывает определённый плод практики: три вида высокого рождения — одно небесное, два человеческих. Традиционно это указание на Чакравартина (вселенского правителя), наделённого семью драгоценностями (<em>sapta-ratna</em>) и тридцатью двумя признаками великого существа (<em>ratna-lakṣaṇa</em>).<a href="#ref-835" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-836"><sup>836</sup> Даже правление, согласованное с Дхармой, не устраняет обусловленность состояния. Долгое пребывание в высших мирах и владение континентами создают почву для возобновления привязанности. Указание на <em>tṛṣṇā</em> предупреждает о временном характере любых достижений, сохраняющих опору на жажду.<a href="#ref-836" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-837"><sup>837</sup> Говорящий (будущий Будда <em>Viraja</em>) относит себя и других Будд к Крита-юге, тогда как Шакьясимха (Будда Шакьямуни) — к Кали-юге. Это разграничение отражает различие эпох проявления. В <em>Ланкаватаре</em> Шакьямуни говорит о будущих циклах от первого лица — включая описание своего собственного будущего воплощения как Вираджи. Это возможно в рамках доктрины о надвременной природе речи Татхагаты: Будда видит все три времени непосредственно и говорит о них не как о внешних событиях, а как о прямо данном. Кроме того, в йогачарской традиции Татхагата рассматривается как принцип, проявляющийся в разных формах в разных циклах — и потому граница между «нынешним» и «будущим» Буддой условна.<a href="#ref-837" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-838"><sup>838</sup> В ряд <em>tīrthya</em> включён и Сиддхартха, сын Шакьев (Будда Шакьямуни). Тем самым указывается, что его учение в будущем будет восприниматься как одна из традиций среди других.<a href="#ref-838" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-839"><sup>839</sup> Формула <em>evaṃ mayā śrutam</em> («так мною было услышано») утратит функцию указания на живую передачу и станет частью историко-литературного жанра (<em>itihāsa</em>).<a href="#ref-839" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-840"><sup>840</sup> Описание соответствует традиционной схеме биографии Будды. <em>Viraja</em> — будущий Будда, «свободный от скверны».<a href="#ref-840" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-841"><sup>841</sup> Чампа — столица древнего царства Анга. <em>Soma-vaṃśa</em> (Лунная династия) — одна из двух великих царских линий индийской традиции.<a href="#ref-841" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-842"><sup>842</sup> <em>Naya —</em> «верный способ видения», ведущий к распознаванию природы ума. <em>Vyākṛtya</em> — технический термин пророчества о будущем пробуждении. Посвящение (<em>abhiṣeka</em>) Махамати устанавливает преемственность линии передачи.<a href="#ref-842" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-843"><sup>843</sup> Мати, Дхарма и Мекхала — имена учеников в линии передачи. Описывается её постепенное ослабление и разрушение в конце цикла.<a href="#ref-843" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-844"><sup>844</sup> Кашьяпа, Кракуччханда и Канака — будды прошлых эпох. Винайака здесь выступает как имя или эпитет в этом ряду.<a href="#ref-844" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-845"><sup>845</sup> <em>Mahāvīra —</em> эпитет Будды<em>.</em> «Пять познаваемых» (<em>pañca-jñeya</em>) скорее всего относятся к пяти дхармам (<em>nāma, lakṣaṇa, vikalpa, samyagjñāna, tathatā</em>), или к пяти объектам познания в йогачаре, или соотносимы с пятью <em>скандхами</em>.<a href="#ref-845" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-846"><sup>846</sup> Крита-юга рассматривается как эпоха полноты Дхармы, в которой возможно полное пробуждение Будд.<a href="#ref-846" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-847"><sup>847</sup> <em>Acchinna-daśaka</em> — технический термин, обозначающий «десятку непрерывных элементов» монашеского одеяния в традиции Винаи. Указание на <em>ahārya-lakṣaṇa</em> («неотъемлемые признаки») и эту структуру связывает внешний вид с установленной формой.<a href="#ref-847" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-848"><sup>848</sup> Размеры узора и промежутков задают меру, при которой украшение не становится объектом влечения. <em>Bāliśa</em> — тот, кто ориентируется на внешнюю привлекательность и не различает, как внешняя форма порождает влечение.<a href="#ref-848" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-849"><sup>849</sup> Три периода дня (<em>tri-sandhyā</em>) задают ритм практики. Образы «огня страсти» и «воды знания» указывают на два согласованных направления: прекращение омрачений и развитие понимания.<a href="#ref-849" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-850"><sup>850</sup> Стрела, трава и дерево подбрасываются одним движением, но движутся по-разному в силу собственной природы. Аналогия показывает, что последствия деяний определяются их качеством: благое направлено и устойчиво, неблагое лишено направленности и ведёт к падению. Одно и то же усилие даёт различные результаты.<a href="#ref-850" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-851"><sup>851</sup> Гатхи 809–812 образуют связанный аргумент против представления о превращении единой сущности (<em>eka</em>) во множество (<em>bahu</em>). Обсуждаемая позиция характерна прежде всего для Санкхьи с её теорией преобразования (<em>pariṇāma</em>), где мир понимается как последовательные видоизменения единой первоосновы (<em>prakṛti</em>). Близкую позицию занимает и адвайта-веданта, где многообразие явлений сводится к проявлениям единого Брахмана.</p>
    <p class="my-2">Доводы разворачиваются в четыре шага.</p>
    <p class="my-2 ml-4">Первый (809): различие признаков (<em>vailakṣaṇya</em>) само по себе исключает тождество. Если явления различаются по признакам, они не могут быть одной и той же сущностью в разных состояниях. Указание на ветер и сияние как на <em>grāhaka</em> («схватывающие» факторы) смещает объяснение с единой основы на условия: то, что принимается за действующую причину, выступает лишь как поле (<em>kṣetra</em>) проявления.</p>
    <p class="my-2 ml-4">Второй (810): позиция оппонента ведёт к внутреннему противоречию. Если единая основа сохраняется через все изменения, она должна быть несотворённой (<em>akṛtaka</em>). Но наблюдаемая изменчивость и разрушимость явлений опровергает это: сотворённое не может быть вечным.</p>
    <p class="my-2 ml-4">Третий (811): то, что принимается за тождество, есть лишь сходство (<em>sādṛśya</em>). Последовательность пламени светильника или стадий роста семени воспринимается как непрерывное «одно», хотя на деле речь идёт о цепи различающихся, но похожих состояний. Видимость тождества возникает в восприятии на основе последовательного сходства.</p>
    <p class="my-2 ml-4">Четвёртый (812): причинные связи своеобразны и не допускают взаимозаменяемости. Кунжут даёт кунжут, ячмень — ячмень. Если бы единая сущность становилась многим, такое своеобразие причинных линий было бы необъяснимо.</p>
    <p class="my-2">В итоге текст переопределяет саму постановку вопроса: множественность явлений объясняется через зависимое возникновение (<em>pratītyasamutpāda</em>) — через условия, сходство и своеобразие причинных связей раскрывается структура опыта. Представление о едином источнике всего сущего уступает место пониманию взаимообусловленных процессов.<a href="#ref-851" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-852"><sup>852</sup> Аргумент приписывается логикам (<em>tārkika</em>): если единая основа превращается во множество, она должна сохраняться во всех изменениях и тем самым быть несотворённой (<em>akṛtaka</em>). Наблюдаемая изменчивость и разрушимость явлений противоречит этому.<a href="#ref-852" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-853"><sup>853</sup> Примеры светильника и семени указывают на последовательность сходных состояний. Сходство (<em>sādṛśya</em>) создаёт видимость тождества, которое лежит в основе утверждения «одно становится многим».<a href="#ref-853" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-854"><sup>854</sup> Примеры с зерном подчёркивают особенность причинных связей: каждый результат возникает из соответствующих условий. Это исключает возможность того, что одна сущность становится различными явлениями.<a href="#ref-854" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-855"><sup>855</sup> Грамматически <em>lokāyata-praṇetāraḥ</em> стоит во множественном числе, что формально распространяет определение на всех перечисленных. Это, вероятно, указывает на общую категорию «учителей мирского знания». <em>Brahmā-garbha</em> («рождённый из Брахмы» / «зародыш Брахмы») не имеет однозначного определения и может отсылать к космогонической доктрине или к конкретной личности брахманической традиции.<a href="#ref-855" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-856"><sup>856</sup> <em>Bhuḍhuka</em> — фигура, не поддающаяся однозначному определению: возможно, имя автора или название текстуальной традиции. <em>Jyotiṣa</em> — одна из шести вспомогательных дисциплин Вед (<em>vedāṅga</em>), охватывающая астрономию и вычисление ритуальных сроков. Упоминание рядом с грамматиками и законодателями показывает, что Кали-юга понимается как эпоха расцвета специализированного знания при ослаблении прямой устной передачи.<a href="#ref-856" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-857"><sup>857</sup> <em>Puṇyakṛtām lokāt</em> («из мира совершивших заслуги») и <em>prajā-bhāgyāt</em> («по благу подданных») — задают двойную причинность явления царя Бали: его приход обусловлен собственными накоплениями и кармической зрелостью тех, кем он призван управлять. Бали в индийской традиции — царь-асура, известный щедростью и праведностью; его образ используется как пример правителя, чьё величие превосходит происхождение.<a href="#ref-857" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-858"><sup>858</sup> Перечисленные фигуры охватывают несколько жанров знания: Вальмики — автор «Рамаяны», Каутилья — «Артхашастры», Ашвалаяна — ведийских ритуальных сутр. Масуракша не имеет однозначного определения. Их объединение в категорию <em>mahābhāga ṛṣi</em> («великих риши») иллюстрирует понимание знания как единого потока, проявляющегося через различные традиции в разные эпохи.<a href="#ref-858" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-859"><sup>859</sup> Включение Сиддхартхи, сына Шакьев, в один ряд с малоизвестными фигурами продолжает линию, намеченную в гатхе 795: Будда Шакьямуни рассматривается как одно из проявлений учительства в определённую эпоху. <em>Bhūtānta</em> («предел явлений») и <em>pañcacūḍaka</em> («пятичубый») — возможно, эпитеты конкретных учителей или указания на доктринальные особенности; <em>vāgbali</em> («сильный речью») и <em>medhāvin</em> («одарённый разумением») — имена собственные с прозрачной этимологией.<a href="#ref-859" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-860"><sup>860</sup> Перечисленные предметы — традиционные атрибуты брахманического аскета: шкура антилопы служит подстилкой для сидения и медитации, посох указывает на странническую практику, пояс — элемент посвятительного одеяния. <em>Cakra-maṇḍala</em> в аскетическом контексте, предшествующем тантрической традиции, обозначает круговой предмет — деревянный диск или подставку, — а не ритуальный рисунок. Дарование этих предметов Брахмой и Махешварой закрепляет признание величия пути отречения со стороны божеств творения и разрушения.<a href="#ref-860" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-861"><sup>861</sup> Вираджа определяется исключительно через деяния: <em>mokṣa-deśaka</em> («проповедник освобождения») и <em>muni-dhvaja</em> («знамя мудрецов»). Образ знамени (<em>dhvaja</em>) — традиционный знак наивысшего достоинства, видимый издалека и указывающий направление. Отсутствие указаний на происхождение или внешние признаки подчёркивает практическую направленность пути.<a href="#ref-861" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-862"><sup>862</sup> <em>Vaśin</em> («обуздавший себя») — эпитет, подчёркивающий внутреннюю дисциплину как основание действия. Брахма удаляется сразу после совершения дара: он сопровождает явление Вираджи, не являясь его источником. <em>Brahma-śata</em> («сотни брахм») указывает на множественность небесных существ этого класса в индийской космологии, где существуют брахмы разных уровней мироздания.<a href="#ref-862" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-863"><sup>863</sup> <em>Virūḍhaka</em> — один из четырёх небесных царей (<em>lokapāla</em>), страж южной стороны света. Его появление вместе с Индрой, царём богов, указывает на охват обоих основных уровней небесной иерархии. Чаша для подаяния (<em>bhaikṣya-pātra</em>) и одеяния даруются будущему Вирадже как знаки статуса, воспроизводя мотив, известный из жизнеописаний: боги являются первыми, кто подносит дары носителю учения.<a href="#ref-863" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-864"><sup>864</sup> Гатха указывает на внутреннее противоречие: если «нерождённое» становится предметом доказательства (<em>sādhayiṣyati</em>), оно тем самым вводится в причинно-логическую структуру, которую это учение отрицает. <em>Vāṅmātra</em> («лишь слова») отмечает разрыв между речью и тем, на что она указывает. (Риторический вопрос <em>ajātaḥ jāyeta vā punaḥ</em> работает на двух уровнях одновременно — и как <em>reductio ad absurdum</em> позиции оппонента («если <em>anutpāda</em> доказуемо, то нерождённое должно было бы возникнуть»), и как указание на то, что сама структура вопрос/ответ неприменима к <em>ajāta</em>.)<a href="#ref-864" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-865"><sup>865</sup> Эти гатхи направлены против представления об уме как цепи строго отдельных мгновений.</p>
    <p class="my-2 ml-4">(823) ставит вопрос о «промежутке» (<em>antarā</em>): если момент ума определяется познанием формы, то до её распознавания неясно, в каком состоянии находится ум. Указание на <em>avidyā</em> как причину не снимает трудности, а усиливает её: между причиной и её проявлением остаётся неописанный разрыв.</p>
    <p class="my-2 ml-4">(824) обнажает проблему преемственности: если предшествующий момент полностью прекращён (<em>samanantara-pradhvasta</em>), а форма не сохраняется, следующему моменту не на что опереться (<em>ālambana</em>). Тогда сама связность потока оказывается необъяснимой.</p>
    <p class="my-2 ml-4">(825) завершает аргумент: если возникновение ума основано на «ложной причине» (<em>vitatha-hetu</em>) и не может быть установлено как действительное (<em>na prasiddha</em>), то утверждение о его мгновенном разрушении лишается основания. Нельзя говорить о распаде того, чьё возникновение не установлено.</p>
    <p class="my-2">Гатхи показывают, что попытка строго описать ум как цепь независимых мгновений сталкивается с тремя трудностями: неясен «промежуток» между мгновениями познания, не объясняется связь между моментами, нельзя последовательно обосновать ни возникновение, ни разрушение. Тем самым подрывается представление о мгновениях как самостоятельных единицах процесса.<a href="#ref-865" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-866"><sup>866</sup> <em>Samāpatti</em> — устойчивые состояния сосредоточения. <em>Suvarṇa-jina-dhātu</em> — реликвии Будды, понимаемые как не подверженные обычному распаду. <em>Ābhāsvara-vimāna</em> — «сияющие обители», связанные с высшими медитативными уровнями. Фраза <em>abhedyā lokakāraṇāt</em> означает: они неразрушимы для мирских причин, то есть обычные причинные силы не действуют на них.<a href="#ref-866" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-867"><sup>867</sup> Перечислены явления, предполагающие длительность и накопление: пребывание, обретение дхарм, знание Будд, монашество, обеты. Риторический вопрос указывает: если всё строго мгновенно, невозможно объяснить устойчивость практики и постепенность пути.<a href="#ref-867" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-868"><sup>868</sup> Город гандхарвов — классический пример иллюзорного, но воспринимаемого явления. Даже такие явления не переживаются как «одно мгновение». Игра слов <em>bhūta</em> / <em>abhūtika</em>: первоэлементы названы «лишёнными элементности». Это подрывает представление о них как о самостоятельных основаниях. Вопрос «откуда они приходят?» показывает, что сама идея возникновения предполагает уже некую форму существования, что ведёт к противоречию.<a href="#ref-868" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-869"><sup>869</sup> Перечисленные характеристики относятся к способу описания ума. Неведение и безначально накопленные умственные построения формируют представление о нём как связанном с возникновением и разрушением. Пассивная форма (<em>saṃprakalpyate</em>) указывает на условный статус этой схемы: она создаётся рассуждением и не совпадает с непосредственным переживанием. Текст смещает внимание к тому, как такие представления выстраиваются рассуждением.<a href="#ref-869" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-870"><sup>870</sup> Указание на «двоякость» (<em>dvividhaḥ</em>) остаётся нераскрытым в самой гатхе. В контексте Санкхьи это может относиться к различию между непроявленным (<em>pradhāna</em>) и проявленным состоянием, либо к различным аспектам учения о преобразовании. Далее формулируется базовый принцип <em>satkāryavāda</em>: следствие предсуществует в причине. Возникновение понимается как проявление уже наличного — появление нового при этом не требуется.<a href="#ref-870" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-871"><sup>871</sup> Доктрина гун объясняет множественность через различия их сочетаний в первооснове. Однако при признании предсуществования следствия в причине многообразие причин и следствий не находит опоры в самом процессе преобразования. Это указывает на напряжение между идеей изменения и сохранением исходной основы.<a href="#ref-871" class="text-blue-500 hover:underline ml-2">↩</a></p>
    <hr class="my-8 border-t-4 border-gray-500">
</div>

<div class="citations mt-4 text-lg">

    <p class="my-2" id="citation-872"><sup>872</sup> Образ ртути связан с индийской алхимической традицией (<em>rasāyana</em>): ртуть понималась как вещество, способное принимать примеси, сохраняя собственную чистоту. Глагол <em>lipyate</em> («прилипает», «загрязняется», «затрагивается») подчёркивает внешний и преходящий характер омрачений.</p>
    <p class="my-2"><em>Ālaya</em> здесь описывается как основание (<em>āśraya</em>) всех живых существ и одновременно как носитель скрытых отпечатков опыта. Омрачения могут временно покрывать это основание, однако его чистота (<em>śuddha</em>) сохраняется неизменной. Гатха использует образ ртути, чтобы показать: загрязнение касается уровня проявлений, не затрагивая глубинную основу.<a href="#ref-872" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-873"><sup>873</sup> <em>Hiṅgu-gandha</em> («запах асафетиды») и <em>palāṇḍu</em> («лук») — традиционные примеры скрытого следа или отпечатка (<em>vāsanā</em>). Даже после исчезновения самого предмета запах ещё долго сохраняется. Так описывается действие кармических следов: причина уже ушла, однако её воздействие продолжает проявляться.</p>
    <p class="my-2"><em>Garbhadarśanam</em> («плод во чреве беременной») указывает на скрытое присутствие того, что ещё не стало видимым. Плод уже существует, хотя остаётся недоступным внешнему взгляду. Этот образ применяется к <em>tathāgatagarbha</em> — природе Будды, присутствующей в существах до её раскрытия.</p>
    <p class="my-2"><em>Lāvaṇya</em> («солёность») показывает неотделимость свойства от носителя: солёность полностью пронизывает соль и не существует отдельно от неё. Так же и ясная природа ума присутствует во всех состояниях сознания, не выступая отдельным объектом.</p>
    <p class="my-2">Все примеры объединяются образом <em>bījavat</em> («подобно семени»): скрытое присутствует и действует, хотя ещё не проявлено внешне. Риторический вопрос гатхи предполагает утвердительный ответ: да, пребывает.<a href="#ref-873" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-874"><sup>874</sup> Гатха использует схему четырёх отрицаний (<em>catuṣkoṭi</em>): отвергаются различие, тождество, их сочетание и отрицание обоих. Тем самым показывается ограниченность рассудочных категорий при попытке описать основу опыта.</p>
    <p class="my-2">Термин <em>nirupādāna</em> буквально означает «без присвоения», «без схватывания». Речь идёт о присутствии, которое не становится объектом удержания или понятийного утверждения.</p>
    <p class="my-2">Фраза <em>na ca nāsti na saṃskṛtam</em> указывает, что это присутствие нельзя определить ни как полное отсутствие, ни как обусловленное явление среди других явлений. Гатха направляет внимание к способу восприятия, свободному от крайностей утверждения и отрицания.<a href="#ref-874" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-875"><sup>875</sup> Гатха воспроизводит позицию небуддийских школ, утверждающих реальное существование «я» как независимого начала. Образ лошади и коровы служит классическим логическим примером: два вида различаются по своей природе, не сливаясь друг с другом. По этой аналогии «я» мыслится как существующее отдельно от совокупностей (<em>скандх</em>). Перечисление взаимоисключающих характеристик показывает попытку описать этот постулат через предельные категории рассуждения, которые в буддийском анализе оказываются несовместимыми.<a href="#ref-875" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-876"><sup>876</sup> Гатха критикует попытку установить «я» посредством рассуждения, предания и логических построений. Такое «я» объявляется неопределимым (<em>anirdhārya</em>), поскольку его невозможно установить ни как тождественное присвоению <em>скандх</em>, ни как существующее отдельно от него.<a href="#ref-876" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-877"><sup>877</sup> Ошибка обнаруживается в самой попытке сопоставить «я» с отдельной скандхой. Этот метод неизбежно приводит к ложному выбору: признанию их полного тождества или абсолютного различия. Логики не осознают, что оба вывода ложны, поскольку сам метод такого рассмотрения исходит из допущения реальности «я».<a href="#ref-877" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-878"><sup>878</sup> Сравнение с отражением указывает на условный статус личности: она возникает зависимо от условий и не устанавливается как независимая сущность. Отражение нельзя назвать ни тождественным зеркалу, ни отдельным от него. Подобным образом личность обнаруживается в связи со <em>скандхами</em>, но не поддаётся определению через категории тождества или различия.</p>
    <p class="my-2">Три места отражения перечислены не случайно: зеркало — искусственный предмет, вода — природная поверхность, глаз — живое существо. В оптических представлениях того времени зрачок считался зеркалом: смотрящий видит своё отражение в глазу другого. Тем самым отражение возникает везде — в неживом, природном и живом. Личность подобна: она обнаруживается в любых условиях, не совпадая ни с одним из них.<a href="#ref-878" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-879"><sup>879</sup> Гатха описывает триаду созерцательной практики: созерцаемое (<em>bhāvya</em>), сам процесс созерцания (<em>vibhāvanā</em>) и созерцающий (<em>adhyātā</em>). Освоение этой триады составляет путь и непосредственное видение истины. Триада гатхи 839 соотносится с механизмом заблуждения, описанным в следующей гатхе: иллюзия непрерывности явлений порождает ложные понятия о постоянстве. Созерцание разрушает этот механизм через прямое видение мгновенной природы явлений.<a href="#ref-879" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-880"><sup>880</sup> Эти образы иллюстрируют мгновенность явлений. Молния, вспыхивающая и исчезающая в один миг, указывает на отсутствие устойчивого пребывания дхарм. Огненное колесо (<em>cakra</em>) в доме с прорехами — классический образ иллюзии непрерывности: вращаемая в темноте головня кажется цельным кругом, хотя в каждый миг горит лишь одна точка. Видимая связность явлений — лишь результат их мгновенной смены. Ошибка невежд заключается в выстраивании понятий о постоянстве или самостоятельной природе этих превращений.<a href="#ref-880" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-881"><sup>881</sup> Невежды впадают в заблуждение, пытаясь определить нирвану через категории бытия или небытия. Подобное понимание лишь укрепляет омрачённость ума, превращая нирвану в очередной объект умопостроения. Видение Благородных (<em>āryadarśana</em>) открывает нирвану иначе — через непосредственное постижение явлений в их истинном пребывании (<em>yathāvasthāna</em>), за пределами категорий наличия или отсутствия.<a href="#ref-881" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-882"><sup>882</sup> Гатхи 842 и 843 образуют единый блок, описывающий метод созерцания изменения (<em>pariṇāma</em>). Гатха 842 задаёт условия, при которых изменение созерцается вне возникновения и распада, вне категорий бытия и небытия, а также вне разделения на признак (<em>lakṣaṇa</em>) и обозначаемое (<em>lakṣya</em>). Гатха 843 дополняет это практическими условиями: созерцание должно быть очищено от учений тиртхиков, свободно от имён (<em>nāma</em>) и внешних форм (<em>saṃsthāna</em>) и опираться на внутреннее видение (<em>adhyātma-dṛṣṭi</em>), постигаемое лишь на собственном опыте. Вместе эти гатхи описывают созерцание изменения, полностью свободное от рассудочных наложений.<a href="#ref-882" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-883"><sup>883</sup> Состояния богов и обитателей адов разворачиваются через соприкосновение и страдание в самом сознании. Гатха переносит внимание с вопроса о самостоятельном статусе этих состояний на их развёртывание в сознании. <em>Antarābhavika</em> — термин для предполагаемого носителя, переходящего между смертью и новым рождением. По этому вопросу буддийские школы расходились: сарвастивада признавала такое существо, ряд других школ отрицал. Данная гатха отрицает его установленность: всё происходящее — включая переход между рождениями — есть развёртывание сознания (<em>vijñānena pravartitā</em>).<a href="#ref-883" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-884"><sup>884</sup> Стандартный буддийский список включает четыре вида рождения: живорождённых, рождённых из яйца, из влаги и рождённых чудесным образом. Гатха добавляет к ним существ промежуточного состояния, тем самым охватывая весь возможный диапазон форм воплощения. Все эти разнообразные тела лишены самостоятельной природы и подлежат созерцанию в их приходе и уходе — то есть в непрерывной смене рождений. Такое созерцание устраняет представление о неизменном существе, перемещающемся между жизнями, и открывает рождение как возникновение образов-форм в потоке сознания.<a href="#ref-884" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-885"><sup>885</sup> Воззрения тиртхиков отвергаются по двум основаниям: они лишены опоры на правильный метод (<em>yukti</em>) и свидетельства традиции (<em>āgama</em>), а их принятие истощает ту сторону сознания, что устремлена к свободе от омрачений (<em>niḥkleśa-pakṣa</em>). <em>Pralāpa</em> («пустословие») подчёркивает отсутствие содержательной связи между такими учениями и действительным путём. Мудрый (<em>matimān</em>) распознаёт это и не следует подобным воззрениям.<a href="#ref-885" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-886"><sup>886</sup> Логика утверждения признаков требует предварительного установления существования самого объекта. «Я» должно быть установлено прежде, чем его начнут отличать от присвоения. Попытка наделять отличиями неустановленный объект сравнивается с описанием качеств «сына бесплодной женщины» (<em>vandhyāputra</em>) — классическим примером слова без соответствия в действительности в индийской логике. <em>Vandhyāputra</em> наряду с «рогами зайца» (<em>śaśaviṣāṇa</em>) и «цветком в небе» (<em>ākāśapuṣpa</em>) входит в стандартный набор примеров для обозначения того, о чём говорят слова, не имеющие соответствия в действительности. Эти примеры иллюстрируют чисто умозрительные построения, лишённые опоры в действительности и не способные служить основанием рассуждения.<a href="#ref-886" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-887"><sup>887</sup> В индийской традиции различаются три вида глаза: плотской (<em>māṃsacakṣus</em>), глаз мудрости (<em>prajñācakṣus</em>) и божественный (<em>divyacakṣus</em>). Термин <em>prajñāmāṃsavivarjita</em> вызывает трудности интерпретации. Вероятно, речь идёт именно о божественном видении, не ограниченном ни плотским восприятием, ни рассудочным различением. Воплощённость всех обладающих телом (<em>mūrtimān sarvadehinām</em>), воспринимаемая этим оком, предстаёт свободной от <em>скандх</em> сансары. Это означает восприятие проявленных форм без выстроенной рассуждением картины обусловленного существования.<a href="#ref-887" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-888"><sup>888</sup> Образ золота разной степени очистки — традиционное сравнение (<em>upama</em>) для природы ума в учении о Татхагатагарбхе. Золото одинаково по природе в неочищенном и очищенном состоянии: устранение примесей оставляет саму природу металла неизменной. Природа существ в связанном и освобождённом состоянии тождественна изначально. Божественное (<em>divya</em>) пребывает в обусловленном (<em>saṃskārastha</em>) и одновременно свободно от него (<em>saṃskāravigata</em>) — оно созерцается именно внутри обусловленного мира.<a href="#ref-888" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-889"><sup>889</sup> <em>Gatisaṃdhi</em> — «стык между уделами существования» — момент перехода между смертью и новым рождением. Именно эта точка недоступна для понятийного мышления: она не фиксируется ни как объект восприятия, ни как предмет логического вывода. Воплощённость существа в этом переходе созерцается лишь тем, кто превзошёл человеческий удел (<em>atikrāntamānuṣyagati</em>). Термин «дурной логик» (<em>kutārkika</em>) означает носителя неверного метода рассуждения, чьё мышление движется в ложном направлении.<a href="#ref-889" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-890"><sup>890</sup> Гатха ставит вопрос о преемственности опыта в отсутствие «я»: если постоянного субъекта нет, откуда развёртывается ум? Три образа — река, светильник, семя — указывают на классические модели причинной передачи без носителя, где каждое последующее состояние обусловлено предыдущим. Река течёт без постоянной воды, пламя передаётся без переноса огня, семя прорастает без заранее существующего дерева. Термин <em>nirgama</em> («истечение») охватывает оба вопроса одновременно: откуда исходит ум и как он прекращается.<a href="#ref-890" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-891"><sup>891</sup> Гатха выстраивает аргумент двойной взаимозависимости (<em>anyonyāśraya</em>): сознание (<em>vijñāna</em>) не возникает без неведения (<em>ajñāna</em>) как условия, но и неведение не обнаруживается при невозникшем сознании. Каждое из двух требует другого как своего условия. При устранении любого из них преемственность опыта (<em>saṃtati</em>) теряет опору. Тем самым ставится вопрос: на чём держится поток сознания, если его условия взаимозависимы и ни одно не является самостоятельным началом?<a href="#ref-891" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-892"><sup>892</sup> Пятичленный перечень включает три времени (прошлое, настоящее, будущее), вневременное / необусловленное (<em>anadhva</em>) и неизрекаемое (<em>avaktavya</em>). Вневременное соотносится с необусловленным, не вовлечённым в поток становления. Неизрекаемое указывает на то, что принципиально не поддаётся понятийному описанию — оно выходит за пределы любой из четырёх предшествующих категорий. Для будд весь этот перечень открывается в прямом постижении; логики ограничиваются его рассудочным провозглашением (<em>saṃprakīrtyate</em>).<a href="#ref-892" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-893"><sup>893</sup> Гатха раскрывает, почему подлинная природа реальности остаётся неизрекаемой (<em>avaktavya</em>). Обыденное знание (<em>jñāna</em>) имеет своей причиной обусловленное (<em>saṃskāra</em>) и направлено на его же восприятие — оно полностью зависит от причинно-следственных связей и само обозначается как обусловленное. Сознание, занятое схватыванием обусловленного, не способно постичь то, что выходит за пределы этой зависимости. Именно поэтому неизрекаемое остаётся недоступным для такого знания.<a href="#ref-893" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-894"><sup>894</sup> Условия сами лишены независимой причины, выступая лишь как «обозначающие знаки» (<em>vyañjaka</em>), позволяющие описывать поток явлений. При этом сами условия не производят явлений как их независимая причина — они лишь указывают на взаимообусловленность. В отсутствие самостоятельных условий идея действующего лица (<em>kāraka</em>) теряет опору.<a href="#ref-894" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-895"><sup>895</sup> Ветер лишь побуждает (<em>preraṇa</em>) пламя к движению, но не порождает его как независимое явление. Побудив, он затихает — его роль исчерпана в самом акте побуждения. Так же и условия приводят в движение поток явлений, не создавая при этом неизменного «существа» (<em>sattva</em>). Побуждение само по себе преходяще — усматривать в нём основание для утверждения самостоятельной природы «существа» несостоятельно.<a href="#ref-895" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-896"><sup>896</sup> Обусловленное и необусловленное — лишь именования, лишённые самостоятельной опоры (<em>upādāna</em>). Они не могут служить основанием для установления какой-либо сущности. Образ огня, воображаемого глупцами, продолжает аргумент предыдущей гатхи: как ветер лишь поддерживает пламя, не порождая его, так и категории обусловленного и необусловленного остаются результатом различения (<em>vikalpa</em>) — за ними не стоят самостоятельно существующие явления. Глупцы принимают пламя за нечто отдельное, не видя зависимости его горения от условий, логики принимают слова за доказательства реальности «я».<a href="#ref-896" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-897"><sup>897</sup> Огонь возникает лишь при взаимном сочетании условий: трения, топлива, ветра, сухости, температуры. Если «существо» (<em>sattva</em>) признаётся подобным огню, вопрос о том, что именно приводит его в движение, обнажает несостоятельность рассудочного построения: за потоком обусловленных факторов нет самостоятельного источника движения. Представление о «существе» остаётся результатом различения (<em>vikalpa</em>), приписывающего единство и деятельность совокупности преходящих условий.<a href="#ref-897" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-898"><sup>898</sup> Отсутствие «я» (<em>nairātmya</em>) не является идеей, порождаемой <em>манасом</em> или иными условиями, — оно постоянно обнаруживается в самой совокупности <em>скандх</em> и <em>аятан</em>. Образ каравана (<em>sārtha</em>) указывает на единство без сущности: торговый союз состоит из множества участников, движущихся вместе, без единого неизменного «тела» каравана. Так и ум (<em>citta</em>) образует единство без постоянного субъекта. Отсутствие «я» и ум нераздельны — они пребывают вместе, как движение каравана неотделимо от его участников.<a href="#ref-898" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-899"><sup>899</sup> «Эти двое» в контексте предыдущей гатхи — ум (<em>citta</em>) и отсутствие «я» (<em>nairātmya</em>). Они описываются как непрерывно сияющие (<em>bhāsvara</em>), что указывает на их изначальную чистоту, не затронутую причинно-следственными связями. Образ огня, используемый логиками для объяснения возникновения существа, не может служить доказательством (<em>sādhaka</em>) их природы: огонь возникает и угасает в зависимости от внешних условий; сияющая природа ума и отсутствия «я» от таких условий не зависит. Это различие остаётся недоступным для рассудочного подхода логиков.<a href="#ref-899" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-900"><sup>900</sup> Гатхи 861–863 образуют единый блок.</p>
    <p class="my-2">Гатха 861 утверждает сущностное единство сияющей природы ума, всех существ и нирваны. Безначальные помехи (<em>doṣa</em>) лишь временно скрывают это сияние, не затрагивая его изначальной чистоты. Сравнение с пространством (<em>gagana</em>) указывает на нераздельность (<em>abhinna</em>): подобно тому как пространство не может быть расчленено или осквернено возникающими в нём объектами, так и природа ума остаётся единой и чистой, независимо от состояний заблуждения или освобождения.</p>
    <p class="my-2">Гатха 862 описывает механизм затемнения: воззрения тиртхиков и деятельность мановиджняны скрывают ясную природу, подобно теням. Очищение «огнём» символизирует устранение этих наслоений через прямое постижение, возвращающее уму чистоту и ясность видения.</p>
    <p class="my-2">Гатха 863 описывает результат: когда явления увидены такими, как они есть (<em>yathābhūta</em>), омрачения разрываются. «Дебри примеров» (<em>dṛṣṭāntagahana</em>) указывает на множественность рассудочных аналогий и построений, служащих лишь вспомогательным средством. Примечательно, что сама <em>Ланкаватара</em> на протяжении всего текста широко использует именно такие примеры — <em>māyā, svapna, gandharvanagara, bimba</em> и прочие. Гатха 863 тем самым указывает на предел самого этого метода: образы и аналогии служат средствами указания (<em>upāya</em>), которые в конечном счёте должны быть оставлены. Вступление в сферу Благородных (<em>āryagocara</em>) означает непосредственное видение, не опирающееся на рассудочные построения.<a href="#ref-900" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-901"><sup>901</sup> Гатха указывает на корень заблуждения: разделение на знание и познаваемое порождает представление об их взаимном отличии (<em>anyatva</em>). Пока такое различение принимается как самоочевидное, неизрекаемое (<em>avaktavya</em>) остаётся недоступным для рассудочного определения. Дурномыслящие слышат о неизрекаемом и даже говорят о нём, но продолжают воспринимать его через двойственное разделение субъекта и объекта.<a href="#ref-901" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-902"><sup>902</sup> Образ барабана из сандалового дерева указывает на неуместное использование ценного материала. Сандал и алоэ (<em>agaru</em>) традиционно связаны с чистотой и тонким ароматом — здесь они служат образом знания в его изначальной ясности. Дурные логики превращают его в инструмент словесного шума и рассудочных построений, не распознавая собственной природы знания.<a href="#ref-902" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-903"><sup>903</sup> Гатха работает на двух уровнях. Буквально — как наставление о внимательности и умеренности при получении и вкушении подаяния: согласно Винае, монах не должен выказывать ни удовольствия, ни отвращения к пище; мимические реакции (<em>mukha-vikāra</em>) рассматриваются как нарушение правильного поведения при принятии подаяния. После трапезы в сосуде остаются лишь следы пищи.</p>
    <p class="my-2">На другом уровне пища служит образом чистого знания, сосуд — его словесной или понятийной формой, а остатки — знаков и выражений, принимаемых за саму сущность знания. Искажения лица (<em>mukha-vikāra</em>) указывают на субъективные наслоения, затемняющие непосредственное восприятие. Призыв правильно обращаться с «чистой пищей» означает необходимость распознавать изначальную ясность знания за его внешними формами.</p>
    <p class="my-2">Гатха продолжает образный ряд предыдущей строфы: если в 865-й драгоценное знание превращалось в шумовой инструмент, то здесь внимание задерживается лишь на остатках и следах, упуская само содержание.<a href="#ref-903" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-904"><sup>904</sup> Здесь описываются качества практикующего как последовательный путь внутреннего преобразования. Рассуждение (<em>yukti</em>) служит первоначальным средством постижения метода (<em>naya</em>), однако не является конечной опорой. <em>Prasāda</em> («ясность», «прозрачность») указывает на ум, свободный от внутреннего помрачения, а практика йоги (<em>yoga-para</em>) — на направленность к непосредственной тренировке. <em>Akalpana</em> («свобода от различений») и <em>anāśrita</em> («неопирающийся») обозначают отказ от построения сети понятий и внешних оснований. <em>Artha-para</em> («устремлённый к смыслу») указывает на направленность к непосредственному постижению того, на что слова и знаки лишь указывают. Образ «золотого пути Дхармы» (<em>hiraṇmayī dharma-gati</em>), который такой практикующий «озаряет» (<em>pradīpayet</em>), подчёркивает живое раскрытие пути через собственную реализацию.<a href="#ref-904" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-905"><sup>905</sup> Гатха описывает результат очищения, намеченного в предыдущих строфах. Сеть дурных воззрений (<em>ku-dṛṣṭi-jāla</em>) возникает из понятийных построений, основанных на представлениях о бытии и небытии. Эти построения поддерживают <em>клеши</em> — влечение (<em>rāga</em>), неприязнь (<em>doṣa</em>) и отталкивание (<em>pratigha</em>), — которые удерживают сознание в двойственном восприятии. Когда они прекращаются, раскрывается состояние незапятнанности (<em>nirañjana</em>). Образ орошения лучами Будд (<em>buddha-kara</em>) указывает на проявление очищенного состояния, в котором присутствие Будд переживается как свет и благословение.<a href="#ref-905" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-906"><sup>906</sup> Перечисляются три искажения, удерживающих мышление в пределах крайностей. Первые тиртхики ищут внешнюю порождающую причину (<em>kāraṇa</em>), блуждая в её поиске. Вторые абсолютизируют обусловленность (<em>pratyaya</em>), превращая её в жёсткую зависимость. Третьи, исходя из признания беспричинности (<em>ahetu</em>), впадают в нигилизм (<em>uccheda</em>), ошибочно принимая это воззрение за путь Благородных (<em>ārya</em>). Все три позиции остаются внутри понятийных построений и не выходят за пределы двойственного мышления.<a href="#ref-906" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-907"><sup>907</sup> Блок гатх 870-874 представляет собой компактную йогачаринскую модель, описывающую развёртывание сансарного опыта: <em>ālaya</em> → <em>vāsanā</em> → <em>manas</em> → <em>vijñāna</em> → проекция вовне → <em>dṛṣṭi</em> → <em>saṃsāra</em>. (Здесь необходимо отметить, что в самой сутре и в этих гатхах употребление ума (<em>citta</em>) и сознания (<em>vijñāna</em>) зачастую синонимично).</p>
    <p class="my-2">Гатха 870 устанавливает иерархию: <em>Алая-виджняна</em> служит основой для <em>манаса</em>, <em>манас</em> — условием возникновения различающего сознания (<em>vijñāna</em>). Преобразование через созревание (<em>vipāka-pariṇāma</em>) кармических отпечатков движет этим процессом. Зависимость односторонняя: <em>Алая-виджняна</em> → <em>манас</em> → виджняна.</p>
    <p class="my-2">Гатха 871 вводит центральный образ блока: <em>Алая-виджняна</em> как океан, все сознания — волны (<em>taraṃga</em>). Каждое имеет своей причиной отпечатки (<em>vāsanā</em>) и возникает согласно условиям (<em>pratyaya</em>). Ни одно не обладает независимо существующим.</p>
    <p class="my-2">Гатха 872 описывает механизм схватывания: связанные последовательностью мгновенных различий, проявления ума возникают как формы, признаки и образы. Они схватывают собственные проявления ума как объекты (<em>svacittārtha-vigrāha</em>) — это почти прямое указание на <em>vijñaptimātra</em>.</p>
    <p class="my-2">Гатха 873 указывает на корень ошибки: сознание, связанное с безначальными помехами и поднявшееся из отпечатков отсутствия независимого объекта, проецируется вовне и воспринимается как внешний мир. <em>Artha-abhāva-vāsanā</em> можно понимать как укоренившуюся привычку воспринимать независимую объектность там, где независимый объект отсутствует. Осознание этого механизма устраняет воззрения тиртхиков, утверждающих самостоятельную внешнюю реальность.</p>
    <p class="my-2">Гатха 874 завершает блок: воззрение (<em>dṛṣṭi</em>) само является продуктом описанного механизма — и именно его возникновение приводит в движение сансару. Сансара не существует заранее — она запускается закреплением двойственного воззрения.<a href="#ref-907" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-908"><sup>908</sup> Гатха завершает блок 870-874: воззрение (<em>dṛṣṭi</em>) само является продуктом описанного механизма — и именно его возникновение приводит в движение сансару. Сансара не существует заранее — она запускается закреплением двойственного воззрения.<a href="#ref-908" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-909"><sup>909</sup> Пять классических образов йогачары описывают природу явлений:</p>
    <p class="my-2 ml-4">Иллюзия (<em>māyā</em>) — видимость без основы.</p>
    <p class="my-2 ml-4">Сновидение (<em>svapna</em>) — переживание без внешнего объекта.</p>
    <p class="my-2 ml-4">Город гандхарвов (<em>gandharva-nagara</em>) — то, что кажется существующим, но рассеивается при приближении.</p>
    <p class="my-2 ml-4">Мираж (<em>marīci</em>) — образ, возникающий из условий восприятия.</p>
    <p class="my-2 ml-4">Луна в воде (<em>udaka-candra</em>) — отражение, зависящее от основания и воспринимающего.</p>
    <p class="my-2">Все пять указывают, что явления обладают видимостью, но лишены независимой основы. Их следует созерцать как собственное различение (<em>sva-vikalpa</em>). Как уже говорилось: воззрение (<em>dṛṣṭi</em>) и сансара разворачиваются из различения; созерцание различения как различения прекращает этот механизм.<a href="#ref-909" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-910"><sup>910</sup> Прекращение обычной деятельности ума (<em>vṛtti-bheda</em>) обнажает Таковость как непосредственную основу восприятия. Совершенное знание (<em>samyag-jñāna</em>) описывается как опирающееся на эту основу. <em>Māyā-samādhi</em> и <em>Śūraṃgama-samādhi</em> — классические высшие <em>самадхи</em> Махаяны, указывающие на конкретные плоды этого прекращения.<a href="#ref-910" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-911"><sup>911</sup> Продвижение по ступеням (<em>bhūmi</em>) сопровождается обретением <em>сверхзнаний</em> (<em>abhijñā</em>) и <em>сил</em> (<em>vaśitā</em>). <em>Тело, подобное магическому знанию</em> (<em>jñāna-māyopama-kāya</em>) — классический термин для тела бодхисаттвы на высших ступенях, свободного от обычной кармической обусловленности. Посвящение (<em>abhiṣeka</em>) Сугатами указывает на передачу, подтверждающую достижение соответствующей ступени.<a href="#ref-911" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-912"><sup>912</sup> Затихание ума меняет способ видения: мир видится успокоенным для того, кто видит (<em>paśyataḥ jagat nivṛttam</em>). Обретение ступени «Радостная» (<em>muditā-bhūmi</em> — первая бхуми) и затем ступени Будды указывает на охват всего пути от начала до завершения.<a href="#ref-912" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-913"><sup>913</sup> <em>Āśraya</em> в йогачаре — технический термин, указывающий на основание сознания, претерпевающее <em>āśraya-parāvṛtti</em> (разворот основания). Когда это основание преобразовано, деятельность ради существ возникает спонтанно, без намеренного усилия. Образ драгоценного камня чинтамани, принимающего все формы, указывает на это спонтанное проявление. Образ отражения в воде — на его зависимый и безопорный характер.<a href="#ref-913" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-914"><sup>914</sup> Седьмая ступень (<em>Dūraṃgamā</em>) описывается через свободу от четырёх логических позиций (<em>catuṣkoṭi</em>): бытия, небытия, их сочетания и их отрицания. Это выводит практикующего за пределы путей пратьекабудд и шраваков, остающихся в тонких формах двойственного различения.<a href="#ref-914" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-915"><sup>915</sup> Махаяна определяется через три признака: постижение дхарм через непосредственное внутреннее видение (<em>pratyātma-dṛṣṭa-dharma</em>), очищение подлинных ступеней (<em>bhūta-bhūmi-viśodhana</em>) и свободу от воззрений тиртхиков. Эти три признака противопоставляются пути, опирающемуся на внешние авторитеты.<a href="#ref-915" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-916"><sup>916</sup> <em>Parāvṛtti</em> («разворот различения») описывается как лишённое упадка и уничтожения — это указание на то, что разворот не является простым прекращением. Образ <em>maṇi</em> («драгоценный камень») указывает на сияющую полноту освобождённого состояния.</p>
    <p class="my-2">Чтение <em>śaśaroma</em> («волос зайца») рукописной традиции ставится под сомнение рядом комментаторов: в буддийской логике стандартным примером несуществующего служат <em>śaśaviṣāṇa</em> («рога зайца»), и предлагается конъектура именно этого чтения. Если принять её, образ приобретает привычную двойственность: несуществующее (<em>śaśaviṣāṇa</em>) и существующее сияющее (<em>maṇi</em>) — что прямо перекликается с гатхой 880 о свободе от крайностей бытия и небытия.</p>
    <p class="my-2">Если же рукописное чтение <em>śaśaroma</em> верно, образ допускает иное толкование. Волос зайца существует, но настолько тонок и неуловим, что не поддаётся схватыванию как отдельный объект. Тогда пара <em>śaśaroma</em> / <em>maṇi</em> описывает две стороны <em>parāvṛtti</em>: то, что невозможно закрепить понятийно, и то, что сияет в своей полноте. Обе интерпретации согласуются с доктринальным контекстом гатхи. Метод провозглашается освобождённым (<em>mukta-naya</em>).<a href="#ref-916" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-917"><sup>917</sup> Гатха формулирует принцип внутренней согласованности: тексты проясняются текстами, рассуждение проверяется внутренне согласованным рассуждением. Верная логика (<em>yukti</em>) ведёт к устранению понятийных построений (<em>kalpanā</em>), а не к созданию новых.<a href="#ref-917" class="text-blue-500 hover:underline ml-2">↩</a></p>

    <p class="my-2" id="citation-918"><sup>918</sup> Гатха перечисляет компоненты обусловленного опыта: зрение (<em>cakṣus</em>), карму, жажду (<em>tṛṣṇā</em>), неведение (<em>avidyā</em>) как порождающее лоно, зримый образ (<em>rūpa</em>), <em>манас</em> (<em>manas</em>) и замутнённый ум (<em>āvila-manas</em>). Перечисление остаётся незавершённым — без сказуемого и без вывода. На этом десятая глава (<em>Сагатхакам</em>) завершена. Сутра завершается необычным образом: незамкнутым перечислением — что само по себе является указанием на предел словесного изложения. Но возможно последующие стихи не сохранились.<a href="#ref-918" class="text-blue-500 hover:underline ml-2">↩</a></p>

